window.QUIZ_LOCAL = (window.QUIZ_LOCAL||[]).concat([{"q":"대전광역시 중구 대사동 보문산(해발 406m) 정상 부분의 산세를 이용하여 쌓은 성으로, 둘레는 300m이다. 성벽은 자연지형에 따라 간단하게 다듬은 네모난 돌을 이용하여 쌓았으며, 성벽 바깥면은 조금씩 안쪽으로 둘러쌓아 쉽게 무너지지 않도록 하였다. 암반으로 형성된 동쪽과 북쪽의 급경사면에는 별도로 성벽을 쌓지 않았다. 발굴조사 결과 남문터가 확인되었고, 현재 통행로로 사용되는 북문을 통해 고려시대에는 성문폭을 좁혀서 사용한 것을 알 수 있다. 동쪽 성벽 아래에서는 청동기시대 후기의 주거지 유적과 민무늬토기, 덧띠무늬토기 등이 발견되었다.","a":"보문산성","c":"시도기념물","nc":"","r":"대전광역시","s":"중구","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1645787.jpg"},{"q":"삼산 유정원 선생의 종택으로 조선 영조 26년(1750)경에 지었다. 유정원(1702∼1761) 선생의 호는 삼산이며, 영조 때 이름난 신하로 형조참의, 대사간 등의 벼슬을 지낸 학자이다. 높은 인품과 학문으로 목민관으로서 높이 받들고 있는 분이다. 대문채, 안채, 사랑채 그리고 사당으로 구성되어 있는 집으로 안채와 사랑채가 전체적으로 ㅁ자형을 이루고 있다. 이 지방의 일반적인 주거형태를 갖추고 있는 건물이다.","a":"안동전주류씨삼산종택","c":"시도민속문화유산","nc":"","r":"경상북도","s":"안동시","i":"http://www.khs.go.kr/unisearch/images/folklore_material/thumb/1658557.jpg"},{"q":"임진왜란(1592) 때 의병장이었던 삼괴 ○○○ 장군의 뜻을 기리기 위하여 세운 ○○○ 및 ○○지이다. ○○○은 선조 23년(1590) 신립 장군의 부장이 되고, 이듬해 사헌부 감찰이 되었으나 곧 사직하고 고향으로 돌아왔다. 임진왜란이 일어나자 의병 2,000명을 모아 관군과 합세하여 ○○○에서 1만여 명의 왜적과 싸워 김천방면으로 물리쳤다. 그러나 곧 금산방면에서 공격해 온 왜군의 협공을 받아 사촌동생 호현과 함께 전사하였다. 장군의 높은 뜻과 애국충정을 기리기 위하여 이곳에 1978년 사당을 건립했다.","a":"영동 추풍령 전적 및 장지현 순절비","c":"시도기념물","nc":"","r":"충청북도","s":"영동군","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1650321.jpg"},{"q":"○○○○의 당산에 분포한 가야 무덤이다. 발굴조사를 통해 당산 주변이 청동기시대부터 가야에 이르는 각종 집자리 시설, 조개더미, 논 유적들이 골고루 형성된 대규모 복합 유적임이 밝혀졌다. 분포하고 있는 가야 무덤의 형태는 널무덤(토광묘), 돌널무덤(석관묘), 돌방무덤(석실묘), 독무덤(옹관묘)이 있다. ○○○○○무덤은 다양한 형태의 가야 무덤들이 밀집하여 분포하고 있어 무덤 변천 연구와 같은 가야사 연구에 좋은 자료가 되고 있다.","a":"창원 가음정동 고분군","c":"시도기념물","nc":"","r":"경상남도","s":"창원시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1655664.jpg"},{"q":"향교는 훌륭한 유학자를 제사하고 지방민의 유학교육과 교화를 위하여 나라에서 지은 교육기관이다 조선 성종 4년(1473) 현감 최영이 세웠으며, 정유재란 때 불에 타 없어진 것을 영조 12년(1736)에 다시 짓고 그 뒤 여러 차례 수리가 있었다. 건물은 출입문인 재천루, 공부하는 곳인 명륜당, 학생들의 거처였던 회우재·출숙재, 사당인 대성전 등이 있다. 건물의 배치는 명륜당이 앞에 있고 대성전이 뒤에 있는 전학후묘의 형태인데 이것은 평지에 세워진 향교의 일반적인 전묘후학 배치와는 어긋난다.","a":"안의향교","c":"시도유형문화유산","nc":"","r":"경상남도","s":"함양군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1641974.jpg"},{"q":"이 부도는 ○○○의 터에서 발견된 것이다. 보물 제382호 울주 ○○○○ 삼층석탑과 약 100m정도 떨어진 곳에 위치하고 있다. 주변에 부도 파변이 산재하고 있어, 이 일대가 일명 ‘부도골’로 불리기도 하였다. 모두 3기이며, 조선시대의 돌종 모양[石鐘形]부도이다. 부도는 이름난 스님들의 유골을 모시기 위해 세운 돌탑을 말한다. 오른편 부도는 높이 3m로 지대석, 기단석, 연꽃 좌대, 탑신(塔身)이 차례로 짜여져 있다. 기단석은 남북 면에는 인왕상을, 동서 면에는 연꽃무늬를 돋을새김 하였다.","a":"청송사지부도","c":"시도유형문화유산","nc":"","r":"울산광역시","s":"울주군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1637249.jpg"},{"q":"조선 중기의 문신이며 의병장이었던 ○○○ 선생의 ○○화이다. ○○○는 선조 24년(1591) 문과에 급제하고 이듬해 임진왜란이 일어나자 창녕에서 의병을 모집하여 곽재우 휘하에 들어가 활약했으며 그후 광주목사 등을 지내었다. ○○화는 두 손을 소매안에 모으고, 약간 왼쪽을 향한 채 서 있는 전신상으로, 녹색의 명주 바탕에 채색하여 그렸다. 머리에는 상투가 보이고 길게 늘어진 수염과 가늘게 올라간 눈이 인상적이다. 분홍색 겉옷의 옷자락 밑으로는 팔(八)자 모양으로 벌린 가죽신의 끝부분이 보인다.","a":"성안의 초상","c":"문화유산자료","nc":"","r":"경상남도","s":"창녕군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1664464.jpg"},{"q":"경상남도 ○○시 물금읍 물금리에 있는 산성으로, 임진왜란 때 왜장 다데마사무네가 쌓았다고 한다. 산의 정상을 깎고 큰 돌을 이용해 산성을 쌓아 근거지로 삼았다. 지형에 따라 동쪽과 서쪽의 2곳에 성을 쌓고, 양쪽으로 통할 수 있도록 한 것이 특이하다.","a":"양산 증산리 왜성","c":"문화유산자료","nc":"","r":"경상남도","s":"양산시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1664605.jpg"},{"q":"『東國史略』은 여러 종류의 문헌이 전해지고 있다. 태종대 권근의 『○○○○』, 이우(李堣 : 1469~1517)의 『○○○○』, 박상(朴祥 : 1474~1530)의 『○○○○』, 유희령(柳希齡 : 1480~1552)의 『○○○○』, 민제인(閔齊仁 : 1493~1549)의 『○○○○』 등이 있다. 이중에서 권근이 찬술한 『○○○○』은 단군에서 신라말까지만 서술한 것이다. 나머지 이본들은 단군에서 고려말까지 서술되어 있다. 그런데 본서는 6권 2책본으로 그 내용이 단군에서 고려말까지 서술된 내용이기 때문에 권근이 편찬한 『○○○○』이 아닌 것으로 보인다.","a":"동국사략","c":"문화유산자료","nc":"","r":"대전광역시","s":"유성구","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1659715.jpg"},{"q":"충청남도 천안시 성남면 해발 180m ○○○의 산정상을 둘러쌓은 테뫼식 성으로 돌로 쌓은 내성과 그 남쪽 기슭에 흙으로 쌓은 외성으로 이루어졌다. 내성의 둘레는 350m정도이며, 높이 3m정도로 경사가 급하고, 폭 2.8m의 동문터가 있다. 내성에서는 격자무늬, 민무늬 기와조각이나 토기조각들이 발견되고, 외성에서는 삼국시대 적갈색토기들이 발견되고 있다. 이 성에 관한 기록은 『신증동국여지승람』, 『대록지』, 『갑오동학혁명사』 등에 전하고 있다.","a":"천안세성산성","c":"시도기념물","nc":"","r":"충청남도","s":"천안시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1652867.jpg"},{"q":"지금은 폐교가 된 태자분교 왼쪽의 밭가에 자리하고 있는 비의 일부분으로, 이곳에 자리잡았던 옛 태자사의 유물일 것으로 짐작된다. 비는 통일신라 후기의 승려인 낭공대사의 것으로 전하고 있는데, 현재 비몸은 사라지고 받침돌과 머릿돌만 남아있다. 네모진 바닥돌 위로 엎드려 있는 비받침의 형상은 전체모습이 닳아 있어서 옛 모습을 확인할 수 없다. 받침 위에 놓아둔 머릿돌은 구름무늬가 가득 조각되어 있으며, 앞면 가운데에는 비명칭을 새기는 네모난 공간이 마련되어 있다. 제작된 시기는 조각수법과 형태로 보아 고려 전기인 것으로 보인다.","a":"태자사지 귀부 및 이수","c":"문화유산자료","nc":"","r":"경상북도","s":"안동시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1662483.jpg"},{"q":"○○○ 대웅보전(보물 제915호)의 전면 우측에 위치한 이 건물은 정확한 건축연대는 알 수 없으나 1765년경 조선 영조의 후궁인 영빈이씨(暎嬪李氏)의 위패를 봉안하였고 제사를 지내기 위해 ‘○○○○○’으로 조영되었다고 한다. 그 뒤 ○○○와 관련이 있는 역대 큰스님들의 초상을 모셔둔 ‘조사각(祖師閣)’으로 사용하다가 현재는 비워진 상태이다. ○○○에서는 ‘구(舊) 조사각(祖師閣)’으로 불리우고 있다.","a":"보은 법주사 선희궁 원당","c":"시도유형문화유산","nc":"","r":"충청북도","s":"보은군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1638850.jpg"},{"q":"이 영정(○○○○○영정)은 ○○○○○선사의 좌안 8분면 바닥가부좌상으로, 녹색상단벽면과 하단돗자리의 이단구도를 배경으로 옆으로 경전이 있는 서안을 두고 화면중앙에 앉아 왼손엔 주장자를 오른손엔 염주를 쥐고 앉아 있다. 화면 향우측엔 ‘선교양종정사○○○념일대화상지진(禪敎兩宗正事友溪堂念一大和尙之眞)'의 화제가, 화면외곽 좌측에는 찬이 있으며 하단에는 화기가 있어 1835년(도광십오년을/미사월, 道光十五年乙/未四月) 양공 우영과 화혜이 제작하였음을 알 수 있다. 화면크기는 가로 83.4cm, 세로 122.0cm이다.","a":"우계당 염일 진영","c":"시도유형문화유산","nc":"","r":"경상남도","s":"양산시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/0000000001642991.JPG"},{"q":"중국 명(明)나라 때 이천(李)이 지은 한의학 서적으로 총 19책이다. 이 책을 쓰게 된 동기는 저자가 병에 걸려 여러 의서를 살펴보았으나 책은 많은데 일목요연하게 요령을 삼을 만한 책이 없어 의학에 입문하기 어려움을 느낀 데서 시작되었다.","a":"의학입문","c":"시도유형문화유산","nc":"","r":"충청북도","s":"제천시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/2018101619414800.JPG"},{"q":"○○○은 1913년 7월 1일 영업을 개시한 호남선의 주요 역으로 1929년 ○○○○운동의 ○○○로서 역사적 가치를 지니고 있으며 역사(驛舍)건물은 초창당시의 규모와 외형등 대부분 원래의 모습을 유지하고 있으나 초창당시의 지붕기와를 골스레트로 바꾸고 개찰구 위치를 바꿔 관리하고 있다. ○○○○ 내에는 ○○○ 영업당시의 개찰모습, 역무원들의 근무 모습이 재현 되어 있다.","a":"광주학생독립운동진원지나주역사","c":"시도기념물","nc":"","r":"전남광주통합특별시","s":"나주시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1654338.jpg"},{"q":"○○○의 本貫은 南陽, 字는 敬夫, 諡號는 貞簡으로 1590년에 태어나서 14세가 되던 1603년(선조 36)년에 선조(宣祖)와 정빈민씨(靜嬪閔氏) 사이에서 태어난 정인옹주(貞仁翁主)와 결혼하여 순의대부당원위(順義大夫唐原尉)가 된 이후 관품이 봉헌대부(奉憲大夫)에 이르렀다. 1618년(광해군 10) 인목대비 폐모론이 일어나자 이이첨 등의 음모를 성토하다가 10간으로 몰려 유배당하였으며, 인조반정 이후 복관되었다. 1625년 6월 4일 36세의 일기로 사망하였으며 수록대부(綏綠大夫)에 추증되었다. 영정은 30여세 때의 진영(眞影)이다.","a":"홍우경 초상","c":"시도유형문화유산","nc":"","r":"충청북도","s":"진천군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1638866.jpg"},{"q":"○○○ 선생의 자는 한서(漢瑞), 호는 일수(一수), 본관은 성산(星山)이다. 일수 ○○○ 선생은 조선후기 실학자로서 한번도 정계에 진출하지 않고 산림에 묻혀 산 처사형 실학자이었기에 세상에 알려지지 않았다. 선생이 저술한 『심성록(心性錄)』은 조선 순조 15년(1815)에 완성되었으며, 『심성록』은 인간의 심성(心性)에 대하여 논술한 책으로 인륜(人倫)과 산업(産業)을 9도(道)·6사(事)의 역리(易理)로 풀이한 책으로 인간이 참다운 자유와 균형된 삶을 누리기 위해서 인간 자신이 도덕의 속박에서 벗어나야 함은 물론 물질적 얽매임에서도 자유로워야 한다는 뜻으로 인륜과…","a":"일수이원구저술및관련문서","c":"문화유산자료","nc":"","r":"경상남도","s":"합천군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1665042.jpg"},{"q":"경북지방에 처음 생긴 기독교회로, 선교사들이 이 지방을 개화시키기 위해 근대적 의료 및 교육을 전개했던 곳이다. 고종 32년(1895) 부산에 있었던 북장로교 선교본부가 대구로 옮겨지고, 광무 2년(1898)에 기와집 4동을 교회당으로 사용하였다. 계속해서 신도가 늘어 1908년에 재래양식과 서구 건축양식을 합작시킨 새로운 교회당을 지었다. 1933년 신도들의 헌금과 중앙교회의 성금으로 교회당을 새로 짓고 ○○○○로 이름을 바꾸었다.","a":"대구제일교회","c":"시도유형문화유산","nc":"","r":"대구광역시","s":"중구","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1636892.jpg"},{"q":"『○○○○』는 조선 중기의 문신이자 정유재란 때의 의병장인 수은 강항(姜沆,1567∼1618)이 중국의 역사서인『자치통감』과『통감강목』을 보완, 정리한 것이다. 숙종 28년(1702)에 새긴 것으로, 목판은 총 642매이다. 강항은 1593년 문과에 급제하여 교서관정자, 공조와 형조의 좌랑 등을 지냈다. 정유재란 때 왜적의 포로가 되어 일본으로 끌려갔다가 그곳에서 후지와라, 아카마쓰 등과 친분을 나누며 그들에게 학문적인 영향을 주었다. 그후 그들의 도움으로 포로생활에서 풀려나 귀국하였고, 여러 벼슬에 임명되었으나 스스로 죄인이라 하여 나아가지 않았다.","a":"영광내산서원강감회요목판","c":"시도유형문화유산","nc":"","r":"전남광주통합특별시","s":"영광군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1640138.jpg"},{"q":"원래 당간지주에서 동북쪽으로 약 60m 떨어진 지점의 사역 중심공간으로 추정되는 곳에 무너져 있었는데, 1960년 유유산업이 들어서면서 현재의 위치로 옮겨 세웠다. 기단은 단층으로 지대석은 판석형 석재를 여러 매 결구하여 마련하였다. 그 위에 각형 2단의 별석(別石) 받침을 높게 두었는데, 고려 시대 석탑에서 채용된 수법을 보인다. 면석(面石)은 4매의 석재를 결구하였고, 우주(隅柱)는 좁고 낮게 모각(模刻)하였다. 갑석(甲石)은 2매의 석재를 결구하였는데, 하부에 갑석 높이보다 낮은 부연을 마련하고, 상면에도 낮게 탑신받침을 두었다.","a":"안양중초사지삼층석탑","c":"시도유형문화유산","nc":"","r":"경기도","s":"안양시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1637695.jpg"},{"q":"○○○○○으로 보다 잘 알려진 석파(石坡) 이하응(1820∼1898)이 만 71세(1891년) 때에 유모(劉某)의 부탁을 받고 그린 12폭 석란도(石蘭圖)이다. 그림들은 2폭씩 대칭구도를 이루도록 배치되어 있는데, 각 폭에는 다양한 괴석과 난초가 어울려 있다. 난초잎은 뿌리에서 촘촘히 자라나 위로 한껏 기세를 뿜으며 부드럽게 퍼지게 표현되었는데, 전형적인 그의 후기 난초의 모습이 잘 나타나 있다.","a":"흥선대원군 이하응필 묵란도","c":"시도유형문화유산","nc":"","r":"서울특별시","s":"종로구","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1636335.jpg"},{"q":"이 곳은 절의 이름이나 유래가 전해지지 않는 백제의 절터로, 마을 이름인 ‘인갱’을 따서 임강사터라 하였다. 지금은 작은 마을이지만 조선시대까지만 해도 역이 설치될 정도로 중요한 곳이었다. 절터는 위와 아래로 구분되며, 앞면 5칸·옆면 4칸의 건물지도 발굴되었다. 출토된 유물로는 연꽃무늬 수막새 기와, 치미조각, 흙으로 만든 불상 조각, 탑의 머리장식 등이다. 주변에서 백제 기와를 굽던 가마터와 조선시대의 분청사기 가마터도 확인되었다.","a":"임강사지","c":"시도기념물","nc":"","r":"충청남도","s":"부여군","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1652687.jpg"},{"q":"◦ 통일신라 말기 ○○○ 창건시기에 세워진 신라양식의 석등으로 알려져 있음. ◦ 지붕돌에 비해 등불을 두는 화사석과 받침기둥이 가늘게 만들어 졌으며, 팔각형 지붕돌의 상륜부가 파손되었으며, 높이는 220cm이고 화강암으로 되었으며, 파괴되었던 것을 수습하여 지금에 이름.","a":"성주사지석등","c":"시도유형문화유산","nc":"","r":"충청남도","s":"보령시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1639052.jpg"},{"q":"중국 삼국시대의 이름난 장군인 관운장의 위패를 모시고 제를 올리던 곳이다. 임진왜란(1592) 당시 원정을 왔던 중국 명나라 장군이 자신들의 수호신인 관우를 모시기 위해 선조 31년(1598)에 ○○부 동문 밖에 세웠다. 지금 있는 자리는 영조 17년(1741)에 옮긴 것이고 해마다 봄·가을에 제사를 지냈다. 앞면 3칸·옆면 2칸 규모로, 지붕은 팔작지붕이다.","a":"남원 관왕묘","c":"시도유형문화유산","nc":"","r":"전북특별자치도","s":"남원시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1639389.jpg"},{"q":"○○○는 천등산 기슭에 있는 절로 신라 문무왕(재위 661∼681) 때 원효가 지었으며, 처음 이곳에 절을 지을 때 금탑이 있었다 하여 ○○○라 불렀다고 한다. 그 뒤 정유재란(1597) 때 불탄 것을 선조 37년(1604)에 다시 지었으며, 수 백인의 승려가 머물렀다고 한다. 그 후 헌종 11년(1845)에 천재지변에 의해 절이 기울어 그 다음해 절을 다시 지었거나 또는 고쳤다는 기록이 있다. ○○○○○은 모든 중생을 구제한다는 아미타불들 모시는 법당이다. 앞면 3칸·옆면 3칸의 규모로 1층이며, 옆면이 여덟 팔(八)자 모양으로 가장 화려한 팔작지붕이다.","a":"금탑사극락전","c":"시도유형문화유산","nc":"","r":"전남광주통합특별시","s":"고흥군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1639942.jpg"},{"q":"강진 ○○○ 창령조씨 문서는 주로 조명조(曺命肇, 1705∼1776)의 행적과 관련된 자료로서 연결된 문서를 중심으로 127건이다.(문집필사본 9책, 교지 2매, 시권 1매, 방목 1권, 호적문서 12매, 입안 1매, 간찰 82매, 향약문서 1권, 기행문 4건, 시문(시축) 20건, 서관일기 1책, 그림 3점) 이 문서는 원래 영암에 연고를 두고 강진에 입향한 성관의 내력을 알 수 있고 시문과 문집, 기행문, 서간문을 통하여 당시의 향촌 사회 동향과 문인 교류관계를 알 수 있다.","a":"강진선장리창녕조씨고문서일괄","c":"문화유산자료","nc":"","r":"전남광주통합특별시","s":"강진군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1662326.jpg"},{"q":"운곡 ○○○ 선생의 묘이다. ○○○ 선생은 어릴 때부터 학문에 밝아 목은 이색 등과 함께 성리학의 보급에 큰 역할을 했으며 조선 태종의 어릴적 스승이기도 하였다. 고려말에 정치가 문란해지자 이를 개탄하면서 치악산에 들어가 숨어 버렸다. 조선왕조가 들어서 선생에게 벼슬이 주어지자 고려에 대한 충절을 끝까지 지켜 나아가지 않았다. 선생의 묘역 내에는 봉분 앞에 묘비와 제사음식을 차려 놓을 수 있는 상석(床石)이 있고, 조금 떨어진 곳에 신도비가 있는 소박한 형태이다.","a":"원주운곡원천석묘역","c":"시도기념물","nc":"","r":"강원특별자치도","s":"원주시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1648526.jpg"},{"q":"조선시대 중기 사람인 ○○○ 선생의 묘비이다. ○○○ 선생은 그의 넷째 조부인 김홍욱이 효종의 격분을 산 탓에 그도 벼슬에 오르지 못하고 평생 학업에만 열중한 인물로, 사망 후에야 이조참판 관직을 받게 되었다. 비는 받침돌 위로 비몸을 세우고 지붕돌을 얹은 형태이다. 비받침은 높직하고 네모지며 4면에 구름모양조각을 하였고 윗면에는 연꽃모양을 새겨 넣었다. 비몸의 석재는 중국의 희귀한 바닷돌을 이용하여 세웠다. 비몸에는 각 면마다 윗부분에는 묘비명을, 아래부분에는 비문을 새겼는데 글씨와 조각솜씨가 매우 뛰어나다.","a":"서산김두징묘비","c":"시도유형문화유산","nc":"","r":"충청남도","s":"서산시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1639246.jpg"},{"q":"조선 후기 유학자인 이항로(李恒老, 1792년-1868년)가 세운 사당[노산사(蘆山祠)]이 있는 터를 말한다. 이항로는 생전에 중국 송나라 시대의 유학자 주희(朱熹)와 조선 후기 유학자 송시열(宋時烈)의 학문을 잇고자, 그가 태어난 집터에 두 사람의 위패와 초상화를 모신 사당[노산사(盧山祠)]을 지었다. 이후 이항로가 죽자 후손들이 그의 학문과 뜻을 길이 전하고자 사당 중앙에는 주희를, 동쪽으로는 송시열을, 서쪽에는 이항로를 각각 모셨다. 현재의 노산사는 한국 전쟁으로 불타 없어졌다.","a":"노산사지","c":"시도기념물","nc":"","r":"경기도","s":"양평군","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1646067.jpg"},{"q":"이 건물은 贈 嘉善大夫 副護軍인 徐承節의 묘소수호를 위해 조선후기에 건립된 재사이다. 각 부재에서 중수한 흔적이 많이 나타나고 있는데 이는 후대에 여러차례 중수하면서 규모를 눌렸던 것으로 보여진다. 건물배치는 \"一\"자형 4칸 아래채와 까치구멍집 안채가 나란히 배열되어 있고 안채 앞 양쪽으로 방안간채와 뒤주채가 마주보고 있다. 안채의 상부가구는 5량가이며 홑처마 팔작지붕이다. 정면4칸, 측면 2칸의 규모이다.","a":"영주용혈리달성서씨재사","c":"문화유산자료","nc":"","r":"경상북도","s":"영주시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1663544.jpg"},{"q":"충청도와 경기 남부를 중심으로 고려 시대에 유행한 불상 양식의 계보를 보여주는 ○○○○이다. 신체에 비해 큰 머리에는 원정모(圓頂帽 ; 챙이 둥글고 정상부가 봉긋한 형태의 모자로, 원나라 귀족들이 쓰던 모자였으나 원 간섭기 이후 고려의 관리와 승려들이 착용) 형식의 갓이 얹혀 있다. 양감이 없는 얼굴에는 가로로 긴 눈과 도톰한 코, 다물고 있는 작은 입이 표현되었고 두 귀는 어깨까지 늘어져 있다. 양 어깨를 덮고 내려오는 법의는 양쪽 팔뚝에서 굵은 띠 모양의 주름을 형성하고 있다. 오른손에 정병을 들고 왼손으로 이를 받치고 있는 특이한 자세를 보이고 있다.","a":"안성대농리석불입상","c":"문화유산자료","nc":"","r":"경기도","s":"안성시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1659994.jpg"},{"q":"조선 태조 4년(1395) ○○에 설치된 ○○○○은 강원감사의 집무처로 70여 칸의 규모였다. 임진왜란(1592) 때 부서져 다시 건물을 세웠으나 한국전쟁 때 큰 피해를 입어 현재는 관찰사 집무처였던 선화당과 정문인 문루만 남아있다. 문루에는 한국전쟁 이후부터 ‘○○○○문루’라는 현판이 달려있었으나 『여지도서』등의 문헌을 근거로 하여 1991년에 ‘○○○’로 고쳐 달았다. 앞면 3칸·옆면 2칸의 2층 누각건물로 지붕은 옆면이 여덟 팔(八)자 모양을 하고 있는 팔작지붕이다. 1층 가운데 칸에는 2짝의 널문을 달았다.","a":"원주 강원감영 포정루","c":"시도유형문화유산","nc":"","r":"강원특별자치도","s":"원주시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1637840.jpg"},{"q":"○○○는 중국 명나라에서 귀화한 사암 천만리(思庵 千萬里) 장군을 모시는 사당이다. 천만리 장군은 서쪽 중북산 천고봉 밑에 살았다 하여 성을 천씨로 하였다고 전해진다. 임진왜란이 일어나자 조선이 명나라에 원병을 요청하였는데, 이때 천만리 장군은 아들 상과 함께 이여송을 따라 조선에 왔다. 평양전투를 비롯하여 여러 전투에서 공을 세웠으며 정유재란 때에는 울산에서 공을 세웠다. 전쟁이 끝난 후에도 돌아가지 않고 조선에 머물러 살자, 선조는 그의 공을 생각하여 화산군*에 봉하고 전답 30결을 내려 주었으며 그의 아들 상도 한성부 좌윤에 봉하였다.","a":"고성 호암사","c":"문화유산자료","nc":"","r":"경상남도","s":"고성군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1663870.jpg"},{"q":"조선 선조~인조 연간 문신인 ○○○의 묘와 ○○○이다. 1617년(광해군 9) 인목 대비 폐모론에 이항복·정홍익과 함께 반대하여 남해에 유배되었다가 인조반정으로 복귀되었다. 묘역은 부인 경주 이씨(慶州李氏)와 합장한 단분(單墳; 하나의 봉분)의 형태이다. 봉분 정면 오른쪽에는 옛 묘표(墓 ; 무덤 주인공의 이름 등을 새긴 비석)와 최근에 건립한 묘표가 세워져 있다. 옛 묘표는 보편적인 원수방부형(圓首方趺形; 둥근 머릿돌과 사각 받침돌의 비석 형태)이다. 비문은 박세채가 짓고 증손인 김유(金濡)가 썼으며 건립 연대는 기록되지 않았으나, 17세기의 양식을 지니고 있다.","a":"김덕함묘및신도비","c":"시도기념물","nc":"","r":"경기도","s":"파주시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/2018010218500600.jpg"},{"q":"○○○○○는 조선시대 노비였던 삼월의 공을 기리기 위해, 1796년(정조 20) 김윤金潤의 후손들이 세운 비석이다. 오창읍 양지리쪽에서 목령산을 오르는 산중턱에 청풍김씨인 김윤의 묘소가 있는데, ○○○는 이 묘소의 향우측에 있다. 4각형의 받침돌 위에 비신을 얹은 모습이며, 앞면에 “忠婢三月之碑충비삼월지비”라고 새기고, 뒷면에는 삼월의 공적내용을 적어 놓았다. 화강암으로 조성된 이 비는 돌이끼가 끼어 고색이 창연하다.","a":"청주 삼월비","c":"문화유산자료","nc":"","r":"충청북도","s":"청주시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1660733.jpg"},{"q":"류수정(柳秀汀1484∼1534)선생의 자는 희순(希舜) 호는 만은(晩隱) 관향은 진주(晋州)이고 선생의 벼슬은 평해군사(平海郡事)겸 강릉진관 동첨절제사를 지냈다. 선생의 증조부 류백통(柳伯通)께서는 평해군사(平海郡事)를 지내시고 조부 류승적(柳升滴)께서는 부사정(副司正)을 지냈으며 부는 정난익대원종공신(定難翊戴原從功臣)에 녹훈(錄勳)되었다. ○○○는 1841년 신축(辛丑)3월28일 입주(立柱)하여 4월1일 축시(丑時)에 상량하였으며 상량기문은 홍문관 교리(弘文館 校理) 권봉희(權鳳熙)짓고 글씨는 후손 류종원(柳鍾源)쓰다.","a":"합천 가호리 동산재","c":"문화유산자료","nc":"","r":"경상남도","s":"합천군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1666808.jpg"},{"q":"이원조의 『탐라지초본』, 『대정군읍지』와 김약익의 『심재집』과 같은 문헌기록과 구전으로 전해지는 이야기를 통해 왕자의 무덤으로 추정되는 곳이다. 내부구조는 잘 다듬어진 석재로 4∼8단의 판돌과 깬돌로 축조된 네모형의 돌덧널무덤(석곽묘)이다. 자기편과 소옥·지석좌대·석재향료·문인석 등이 고려 후기에서 조선 전기에 축조되었음을 가르쳐 준다. ○○○○○ 무덤은 당시 고위층의 무덤으로 제주도 무덤 변천과정 연구에 높은 학술적·역사적 가치를 가지고 있는 곳이다.","a":"하원동탐라왕자묘","c":"시도기념물","nc":"","r":"제주특별자치도","s":"서귀포시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1657933.jpg"},{"q":"고려 후기의 문신이자 충정공 문숙선의 아들인 삼우당(三憂堂) ○○○ 선생의 묘소이다. 공민왕 9년(1390)에 문과에 급제하여 벼슬에 오르고 1363년 좌정언에 있을 때 이공수를 따라 원나라에 갔다. 때마침 이곳에 있던 최유가 충선왕의 셋째 아들 덕흥군을 왕으로 삼아 공민왕을 몰아내려 하였다. 원의 지원까지 받은 이 계획은 공민왕 13년(1364) 최영에게 패하면서 실패하였다. ○○○은 이 계획에 동참하였다는 혐의로 귀국과 동시에 중국 운남성으로 귀양을 갔다. 귀국할 때 목화씨를 숨겨와 장인 정천익과 함께 재배하여 의류면에 커다란 변화를 가져왔다.","a":"산청문익점묘","c":"시도기념물","nc":"","r":"경상남도","s":"산청군","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1655105.jpg"},{"q":"고려 때 절의를 지킨 포은 정몽주·목은 이색·야은 길재 등 삼은(三隱)의 위패를 모신 건물이다. 정몽주는 고려의 문신이자 학자로서 1360년 문과에 장원하여 1362년 예문관에 들어갔으며 이성계와 함께 여진토벌에 참여하기도 했다. 이색은 고려말의 문신이자 학자로서 충목왕 4년(1348)에 원나라에 가서 국자감 생원이 되었으며 성리학을 연구하였다. 그는 원·명 교체기 때 천명(天命)이 명나라로 돌아갔다고 보고 친명정책을 지지하였으며 유교의 입장에서 불교를 이해하고자 하였다.","a":"삼은각","c":"문화유산자료","nc":"","r":"충청남도","s":"공주시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1660967.jpg"},{"q":"개천면 ○○○○○은 죽포공 박영회(1827-1886)의 효행을 기리기 위하여 세운 것으로 각 내부에 붉은 색을 칠한 나무 기둥을 세워 먼 곳에서도 눈에 잘 띄고, 전면의 단청문양이 선명한 색채를 나타내고 있다 또한 경상남도 문화유산자료로 지정된 ○○○ 박진사고가(개천면 ○○○ 292-3)와 가까운 거리외 위치하고 있어 주위 주민들 뿐만 아니라 후세에 효에 대한 의식을 높이는데 도움이 됨","a":"고성 청광리 창효각","c":"문화유산자료","nc":"","r":"경상남도","s":"고성군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1666750.jpg"},{"q":"○○○는 통일신라 애장왕 5년(804)에 세운 절로 법당과 부속건물 및 여러 암자를 갖추고 있는 절이다. ○○○을 지은 시기는 알 수 없으나 1976년에 고쳐 세우고 1979년 보수를 거쳐 오늘에 이르고 있다. 앞면 1칸·옆면 1칸 규모이며, 지붕은 옆면에서 볼 때 사람 인(人)자 모양을 한 맞배지붕이다. 지붕 처마를 받치기 위해 장식하여 만든 공포는 기둥 윗부분에 새 날개 모양으로 짜올렸다. 건물 안팎으로는 단청을 하여 화려함을 더하고 옆면 외벽에도 그림을 그려 넣었다. 전통 민간신앙이 불교에 습합(習合)되어 나타난 전각 중 하나로 화려한 꾸밈을 엿볼 수 있다.","a":"파계사산령각","c":"문화유산자료","nc":"","r":"대구광역시","s":"동구","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1659462.jpg"},{"q":"『○○○○○』과 『불설예수시왕생칠경(佛說預修十王生七經)』이 합본된 1책이다. 이를 수생경(壽生經)이라 하며, 『수생경(壽生經)』은 12지(支) 60갑자(甲子)에 따라 저승의 관 속에 돈과 경전을 시납해야하는 수량을 설명해 놓았다. 『시왕경(十王生)』은 지옥의 고뇌를 면하기 위해 생전에 재공(齊供: 부처님께 공양을 바치는 일)을 할 것을 권한 책이다.","a":"불설수생경","c":"시도유형문화유산","nc":"","r":"충청북도","s":"단양군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1638890.jpg"},{"q":"수성구 상동 501번지 일대에 분포했던 ○○○○으로 현재는 상석 4개가 이동되어 임의로 배치되어 있다. 1998년 국립대구박물관에서 발굴조사한 바에 의하면 지상의 상석은 이동되어 원위치는 파악하기 어렵게 되어 있기는 하나 지하묘구는 15m×15m 구역내에서 30여기의 석관·석곽이 원상으로 분포되어 있음이 확인되었다. 묘구는 평면 장방형이였고, 대개 길이는 2m, 폭은 40㎝, 벽고는 30㎝ 정도의 규모였다. 묘구의 유형은 석관형과 석곽형의 두 종류가 있고, 석관은 네 벽을 판석으로 세워 구축했고, 석곽형은 천석 또는 천석과 판상석을 혼용해서 구축했다.","a":"상동지석묘군","c":"시도기념물","nc":"","r":"대구광역시","s":"수성구","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1645378.jpg"},{"q":"지석묘는 청동기시대의 대표적인 무덤으로 ○○○이라고도 부르며, 주로 경제력이 있거나 정치권력을 가진 지배층의 무덤으로 알려져 있다. 우리나라의 ○○○은 4개의 받침돌을 세워 돌방을 만들고 그 위에 거대하고 평평한 덮개돌을 올려 놓은 탁자식과, 땅속에 돌방을 만들고 작은 받침돌을 세운 뒤 그 위에 덮개돌을 올린 바둑판식으로 구분된다. 광주광역시 광산구에 있는 이 ○○○은 바둑판식으로 주변 200m 이내의 구릉 위에 모두 49기가 2개의 무리를 지어 분포하고 있다.","a":"삼거동고인돌군","c":"문화유산자료","nc":"","r":"전남광주통합특별시","s":"광산구","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1659671.jpg"},{"q":"임진왜란 뒤에 질병퇴치를 자치적으로 해결하고자 선조 35년(1602)에 김각(金覺), 성람(成濫), 이준(李埈)이 설립한 사설의료기관이다. ○○○이란 이름은 중국 송나라 학자 정자(程子)의 ‘존심애물’에서 따온 것이라 한다. ○○○은 의료시설이 아주 적었던 당시 많은 약재와 시설을 갖추어 주민과 가난한 사람들을 치료함으로써, 다른 지방에까지 큰 자랑거리였다. 특히 의료활동뿐만 아니라 지역민의 화합를 위한 각종 행사도 치렀는데, 1607년부터 1894년까지 백수회(白首會)라는 경로잔치를 개최한 것은 특기할 만한 일이다.","a":"존애원","c":"시도기념물","nc":"","r":"경상북도","s":"상주시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1654545.jpg"},{"q":"율곡 이이 선생의 향약을 기초로 하여 작성한 책이다. 내용을 보면, 정조 8년(1784) 면민의 각 호주를 계원으로 하고 임원인 공원 1인, 유사 1인, 상무 1인으로 규정하였으며, 매년 봄과 가을에 2회의 총회를 개최하여 미풍양속을 장려하고 풍습을 교정하는 것을 목적으로 하였다. 조선 후기 향촌사회사를 이해하는데 도움이 되는 ○○로 평가된다.","a":"남해 남면 향약계 관련 자료","c":"문화유산자료","nc":"","r":"경상남도","s":"남해군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1663885.jpg"},{"q":"황희 정승의 학문과 덕행을 기리기 위한 서원이다. 황희(1363∼1452)는 조선 전기 문신으로 성품이 어질고 청렴하며 충효가 깊어 조선왕조를 통하여 가장 명망있는 정승으로 칭송받고 있다. 조선 숙종 21년(1695)에 세운 ○○○○은 고종 5년(1868)에 흥선대원군의 서원철폐령으로 폐쇄되었다가, 1955년에 다시 세웠다. 현재 남아 있는 건물로 상현재가 있는데, 앞면 3칸·옆면 1칸 규모로 지붕은 옆면에서 볼 때 여덟 팔(八)자 모양인 팔작지붕이다.","a":"창계서원","c":"문화유산자료","nc":"","r":"전북특별자치도","s":"장수군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1661656.jpg"},{"q":"○○○은 가곡공 조예(1608~1661)가 1650년경 건축한 것으로 추정되며, 풍양조씨 검간공종파 자손들의 학문의 장소이자 영남유림의 인사들이 모여 시국을 논하고 시회를 열던 장소로 알려져 있다. 현재 ○○○에는 ○○○ 과 익암서당(益巖書堂) 두개의 편액이 있다. ○○○은 17세기 후반에 세워졌고, 19세기 후반에 중수된 것으로 조선 중기 정자건물의 특성을 갖추고 있고, 건립당시의 규모와 구성형식이 비교적 잘 유지되고 있어서 조선시대 정자건축 연구의 자료적 가치가 높은 것으로 판단된다.","a":"상주 청간정","c":"문화유산자료","nc":"","r":"경상북도","s":"상주시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1663655.jpg"},{"q":"○○○는 청동기시대의 대표적인 무덤으로 고인돌이라고도 부르며, 주로 경제력이 있거나 정치권력을 가진 지배층의 무덤으로 알려져 있다. 우리나라의 고인돌은 4개의 받침돌을 세워 돌방을 만들고 그 위에 거대하고 평평한 덮개돌을 올려 놓은 탁자식과, 땅 속에 돌방을 만들고 작은 받침돌을 세운 뒤 그 위에 덮개돌을 세운 바둑판식으로 구분된다. 전라남도 고흥군 ○○○에 있는 이 고인돌은 바둑판식으로 한 곳에 50여 기 이상이 무리지어 있다. 가장 큰 덮개돌의 길이 4∼5m이고 너비는 2.5∼3m이며, 작은 덮개돌의 길이는 0.6∼1.5m이다.","a":"고흥과역리민등지석묘군","c":"시도기념물","nc":"","r":"전남광주통합특별시","s":"고흥군","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1654317.jpg"},{"q":"○○○는 신라시대 때 창건하였으며 고려 충렬왕 10년(1284)에 평양부원군 조인규가 자신의 원당(願堂)으로 크게 다시 짓고 ○○○ 내에 자신을 위한 건물을 만들어 머물기도 하였다. 조선 세조 13년(1431)과 세조 30년(1448)에 조인규의 6세손인 조현(趙玹)이 다시 짓는 등 오랫동안 ○○○는 조인규 집안의 원찰(願刹)이 되었다. 연산군 9년(1503) 도성 내 사찰 폐쇄령이 떨어지게 되자 ○○○는 봉은사를 대신해 선종본찰(禪宗本刹)의 역할을 수행하였으나 임진왜란과 화재의 피해를 받았다.","a":"청계사","c":"문화유산자료","nc":"","r":"경기도","s":"의왕시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1659837.jpg"},{"q":"○○○○○은 현재까지 확인된 ○○ 지역에서 봉분이 가장 큰 고총고분으로 알려져 있다. ○○○ 3호 고분의 발굴조사 결과, 금관가야 후기(6세기 전반)의 대형 고분으로 확인되었으며, 내부주체 역시 ○○지역에서 드물게 발견되는 횡구식 석실로 밝혀졌다. 지금까지 금관가야의 전성기 ○○○은 다수 확인되었으나 가야 쇠퇴기인 금관가야 후기(6세기 전반)의 ○○○은 희소함 ○○○○○은 가야 쇠퇴기의 역사와 문화를 집약적으로 보여주는 귀중한 유적임.","a":"김해 원지리 고분군","c":"시도기념물","nc":"","r":"경상남도","s":"김해시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/2019042213160200.jpg"},{"q":"고종 광무 3년(1899)에 지은 석조건물이다. 일본인 니이노이에 다카마사가 설계한 건물로 모래, 자갈, 석회를 제외한 나머지의 모든 건축 재료를 일본에서 직접 가져와 만들었다. 현관은 반원의 곡선형으로 중앙에 만들었는데 그 위로 르네상스풍의 작은 돔을 올려서 좌우대칭으로 꾸몄다. 바깥벽은 화강암을 다듬어 쌓았고 지붕의 꼭대기 부분인 용마루에는 장식창이 있었으나 지금은 없다. 중앙 돔의 양옆에 있는 작은 탑은 나중에 첨가된 것으로 보이는데, 전체적으로 후기 르네상스 양식을 본떠서 단순화한 건물이다.","a":"인천 구 일본제1은행","c":"시도유형문화유산","nc":"","r":"인천광역시","s":"제물포구","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/2015122811073800.JPG"},{"q":"조선 후기 유학자인 대산 이상정(1710∼1781)의 학문과 덕행을 추모하기 위해 세운 서원이다. 이상정은 퇴계 이황의 학통을 계승한 분으로 여러 벼슬을 지내고 노년에는 후진양성에 전념하였다. 정조 13년(1789)에 세운 이 서원은 흥선대원군의 서원철폐령으로 고종 5년(1868)에 폐쇄되었고 1977년과 1984년, 1985년에 새롭게 복원하여 오늘에 이르고 있다. 경내에는 사당과 강당 등 주요 건물과 유물을 보관하는 백승각, 제관들의 숙소로 이용되는 동재, 서원 관리인이 생활하는 주소로 구성되어 있다.","a":"고산서원","c":"시도기념물","nc":"","r":"경상북도","s":"안동시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1654488.jpg"},{"q":"조선 숙종 때 문신 쌍백당(雙栢堂) ○○○ 선생의 묘소이다. ○○○는 인현 왕후(仁顯王后) 폐비설을 듣고 오두인(吳斗寅)과 함께 반대 상소를 올렸다. 정주로 유배를 가다가 풀려 파주로 은거했으며, 인현 왕후 복위도감제조(復位都監提調)로 다시 벼슬에 올랐다. 묘소는 높은 언덕 위에 위치하고 있으며, 부인 설씨(薛氏, 1627~1670)와 함께 묻혀있다. 봉분은 좌우 2기가 있으며, 두 봉분 사이에 묘표(墓表), 석상(石床), 향로석(香爐石) 등이 놓여 있다.","a":"이세화선생묘","c":"시도기념물","nc":"","r":"경기도","s":"파주시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1646129.jpg"},{"q":"○○○은 마을의 어느 한 방위에 불길한 징조가 보인다거나 어느 한 지형의 기가 허한 곳에 마을 공동으로 쌓아 올린 돌탑으로, 부정과 악의 출입을 막아 마을을 편안하게 하고자 하는 신앙 대상물이다. ○○○에서 단산으로 가는 길에는 ‘알뱅디’라 불리는 넓은 평지가 있는데, 이곳에 4기의 ○○○이 자리하고 있었다. 마을에 불이 자주 나고 가축이 병들어 죽는다 하여 쌓아 놓은 것인데, 1950년대 훈련소가 들어서면서 군인들이 허물어버려 2기만 남아 있다. 2기 중 서쪽에 있는 것이 이 탑으로, 동탑과는 100여m 떨어져 비교적 원형 그대로 보존되어 있다.","a":"인성리방사탑2호","c":"시도민속문화유산","nc":"","r":"제주특별자치도","s":"서귀포시","i":"http://www.khs.go.kr/unisearch/images/folklore_material/thumb/1659279.jpg"},{"q":"조선 세종 때의 문신 제정공 최용소 영정을 모신 곳으로, 이 영정은 명황제 숭조가 화공을 시켜 그려 보낸 것이라고 한다. 최용소는 고려말∼조선초의 문신으로 태조 3년(1394)에 회례사(回禮使)로 일본 구주(九州)에 파견되어 양국의 우호를 도모하자는 국서를 전하고, 피로인 570여 명을 대동하고 귀국하였다. 그는 성품이 청백하면서도 절개가 굳고 언행이 정중하였으며, 일찍이 명나라의 건축을 감독하고 명성을 얻기도 하였다. 시호는 제정(齊貞)이다.","a":"조치원 봉산영당","c":"문화유산자료","nc":"","r":"세종특별자치시","s":null,"i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1666860.jpg"},{"q":"○○○ 동치 3년 ○○○은 대칭 3단 구도로 최상단 가운데 8곡 병풍 앞에 범천 및 제석천과 그 뒤로 청동녀가 서 있고, 이 두 인물의 아래는 일궁천자, 월궁천자, 그 앞으로 두 천녀를 배치하였다. 중단에는 3면 6비의 예적금강을 중심으로 우측에 칼을 든 신장상과 좌측에 새 깃 모양의 날개가 달린 투구를 쓰고 갑옷을 입은 위태천을 도설 하였으며, 가운데는 날카로운 수염과 물갈퀴가 표현된 용과 머리에 새 모양의 관을 쓴 가루라가 나란히 서 있다. 범천과 제석천의 얼굴을 보면 옅은 갈색을 펴 바르고 붉은 선으로 윤곽선을 그렸다.","a":"남해 용문사 동치3년명 신중탱","c":"문화유산자료","nc":"","r":"경상남도","s":"남해군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1666095.jpg"},{"q":"조선 영조 11년(1735) 오류정 김두행(1705∼1785) 선생이 지은 살림집이다. 선생은 중국 진나라 도연명의 뜻을 따라 집 뒤뜰에 버드나무 다섯 그루를 심고 정자를 지어 오류정이라 하였다. 건물은 앞면 4칸·옆면 5칸 규모이며 ㅁ자형 평면구조를 이룬다. 사랑방 왼편으로는 2칸을 내어 마루를 깔고, 좁은 마루를 돌려 조각한 난간을 설치하였다. 안동지방을 중심으로 분포되어 있는 양반집의 대표적인 예로 귀중한 자료이다.","a":"오류정종택","c":"문화유산자료","nc":"","r":"경상북도","s":"영양군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1662523.jpg"},{"q":"이 ○○○○은 1686년(숙종 2)에 간행된 활자본이다. 법화경지험기(法華經持驗紀)의 말미에 강희25년 병인 사월에 전라도 낙안군 금화산 징광사에서 간행되었던 사실이 적혀 있고, 또한 역조화엄경지험기(歷朝華嚴經持驗紀)의 말미에 백암사문 성총(性聰)의 발문이 실려 있다. 사경지험기(四經持驗紀) 혹은 금강경관세음법화화엄등지험기(金剛經觀世音法華華嚴等持驗記)라고도 불리는데, 지험기(持驗記)라고 약칭한다.","a":"사경영험","c":"시도유형문화유산","nc":"","r":"충청북도","s":"단양군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1638952.jpg"},{"q":"조선 제10대 왕인 ○○○의 명령으로 세운 비이다. “○○○”는 본래 왕실에서 사냥과 군사 훈련 등의 목적으로 출입 금지 구역을 설정한 후 백성들에게 알리기 위해 세우던 비이다. 그러나 ○○○은 폭정을 휘두르며 금표 구역을 유흥과 향락 장소로 변질시켰다. ○○○는 1984년경 고양시 대자동에 위치한 금천군(錦川君) 이변(李抃)의 묘역을 재정비하다가 발굴되었지만 관련 학계에 처음 소개된 것은 1994년이다. 화강암으로 비신(碑身 ; 글씨를 새기는 부분)과 지붕돌을 만들었다. 지붕돌은 거의 파손되었지만 연잎 문양이 일부 확인된다.","a":"연산군시대금표비","c":"문화유산자료","nc":"","r":"경기도","s":"고양시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1660137.jpg"},{"q":"안채와 사랑채만 현존하며 안채는 5칸으로 부엌위에 다락방이 위치하고 있으며 사랑채는 누마루대청 양식을 갖추고 있다. 건물의 건립연대는 명확치 않으나 현 소유자는 약 450년전 건립한 것으로 알려져 내려오고 있다고 하며 임진왜란 당시 왜적을 퇴치하는데 의병모병, 군기비축 등의 근거지로 사용하였다 한다. ○○○ 선생(1556~1614)은 남하 양항 출신으로 호는 영호 본관은 파평(破平)이다.","a":"거창 윤경남 생가","c":"시도유형문화유산","nc":"","r":"경상남도","s":"거창군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1642252.jpg"},{"q":"<○○○○○>은 광무 3년(고종 16, 1879) 9월 11일에 조선과 청국 사이에 조인된 전문 15조의 통상협정이다. 그 전문은 총 15관(款)으로 정하되 한국, 청나라는 서로의 균등한 자격으로 거류민을 보호하며, 양국의 전권대신이 주도하여 상선은 양국이 지정한 통상지역 안에서만이 무역할 수 있다는 요지이다. 또한 중국인이 범법을 했을 경우 청나라 영사관을 통하여 조회하고 심판하며 양국 상선들이 서로 근해에서 폭풍우와 결량때에는 원조한다는 내용도 담겨 있다. 이는 한국측에서는 외부대신 박제순이, 청국측에서는 청국대신 서수붕이 국가대표로 서명하고 있다.","a":"대한국ㆍ대청국통상조약(한문)","c":"시도유형문화유산","nc":"","r":"서울특별시","s":"서초구","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/2587999.jpg"},{"q":"○○○[pinus densiflora sieb. & zucc.]는 우리나라 전역에 나는 상록성 침엽수이다. ○○○○○는 수관층이 반송형으로 나타난 전형적인 ○○○ 2주이다. 원식생의 ○○○들로 보이며 [○○○1]은 흉고둘레는 평균 410㎝(389㎝,39o㎝,410㎝,425㎝,427㎝), 수고는 평균 29m(상관에 의한 조사는 위치에 따라 27m, 26m, 27m, 29m, 32m)은 350여년(1650년 생)으로 보인다.","a":"담양 매산리 소나무","c":"시도기념물","nc":"","r":"전남광주통합특별시","s":"담양군","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1654395.jpg"},{"q":"청계 김진과 그의 아들 5형제의 뜻을 기리고 후학을 양성하기 위해 세운 서원이다. 김진(1500∼1580)은 조선 중기의 선비로 어려서부터 재능이 뛰어났고, 이름난 유학자를 찾아가 가르침을 받아 견문을 넓히기도 했다. 선생이 세상을 떠난 후에는 나라에서 이조판서 직함을 내렸다. ○○○○은 숙종 7년(1681)에 세웠고 그 뒤 흥선대원군의 서원철폐령으로 고종 8년(1871)에 폐쇄되었다가 고종 19년(1882)에 다시 세워 강당과 주사만 남아 있다.","a":"사빈서원","c":"문화유산자료","nc":"","r":"경상북도","s":"안동시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1662411.jpg"},{"q":"○○○는 청동기시대의 대표적인 무덤으로 고인돌이라고도 부르며, 주로 경제력이 있거나 정치권력을 가진 지배층의 무덤으로 알려져 있다. 우리나라의 고인돌은 4개의 받침돌을 세워서 돌방을 만들고 그 위에 거대하고 평평한 덮개돌을 올려놓은 탁자식과, 땅 속에 돌방을 만들고 작은 받침돌을 세운 뒤 뚜껑돌을 덮고 그 위에 거대한 덮개돌을 올린 바둑판식으로 구분된다. ○○시 서쪽 경운산 기슭의 마을 안에 있는데, 원래는 더 많은 고인돌이 있었던 것 같으나 주택개축과 개간 등으로 유실되어 현재는 1기만 남아 있다.","a":"김해 내동지석묘","c":"시도기념물","nc":"","r":"경상남도","s":"김해시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1655340.jpg"},{"q":"○○○은 고려 개국공신으로 ○○양씨 문중에서 시조로 삼고 있고, ○○는 형태가 팔각형의 죽절형(竹節形) 모서리 기둥을 새긴 호석(護石)을 두른 특이한 양식이다. 일부 풍화되고 결실된 부분을 보수한 흔적이 있으나, 고려시대 분묘 유적으로 그 유례가 희귀하다. ○○○의 15대손 ○○○은 조선시대 초기의 인물로 급제 후 예조정랑까지 오른 효자로 이름난 인물이다. ○○○과 ○○○은 ○○지역의 인물사에 중요한 부분을 차지하고 ○○가 원위치에 원형대로 보존되어 있어 하나로 묶어 보호할 필요가 있다.","a":"충주 양능길·양여공 묘소","c":"시도기념물","nc":"","r":"충청북도","s":"충주시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1651649.jpg"},{"q":"○○○○은 1864년에 안채를 짓고 이어서 사랑채(1871년)와 별채(1916년)를 짓고 광채, 행랑채, 부속사, 정암정, 문간채 등으로 구성되어 있다. 고택은 조선 중기 인물인 창주 하증의 후손이 세거해 온 곳으로 창주의 후손인 하우식(호 담산)의 호를 따서 ○○○○으로 하였다.","a":"진주 담산고택","c":"문화유산자료","nc":"","r":"경상남도","s":"진주시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/2023063022375200.jpg"},{"q":"○○○는 고려 예종 때 여진족 토벌에 큰 공을 세운 문양공 오연총 장군을 모신 사당으로, 1928년에 함경북도 경성의 정북사에서 오연총 장군의 영정을 이곳으로 옮겨와 사당을 세웠다. 오연총 장군을 모셨던 정북사는 조선 세종 19년(1437) 함경도 땅에서 여진족을 물리친 윤관, 오연총, 김종서, 오박 장군의 제사를 지내기 위해 세운 사당으로, 흥선 대원군 집권 당시 훼철되었다가 1904년에 다시 세워졌다. 그러나 오연총 장군의 제사는 후손들에 의해 곡성으로 옮겨져 1928년 ○○○ 건립 후 이곳에서 지내고 있다.","a":"덕산사","c":"문화유산자료","nc":"","r":"전남광주통합특별시","s":"곡성군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1662059.jpg"},{"q":"조선 중종의 후궁이며 선조의 할머니인 ○○○○의 신도비(神道碑:조선시대에 왕이나 고관 등의 평생 업적을 기리기 위해 무덤 근처 길가에 세운 비)와 묘소이다. ○○○○는 중종 2년(1507) 9살의 나이에 궁녀로 들어갔으며, 생김새가 단정하고 행동이 정숙하였다. 20세에 중종의 총애를 입게 되어 중종과의 사이에서 영양군과 덕흥대원군, 정신옹주를 두었다. 묘는 처음에 양주 장흥 땅에 있었으나 다음해에 현재의 자리인 동작동 국립묘지 안으로 옮겨졌다. 묘 왼쪽으로는 숙종 9년(1683)에 세운 신도비가 세워져 있다. 비문은 신정이 지었고 글씨는 이정영이 썼다.","a":"창빈 안씨 묘역","c":"시도유형문화유산","nc":"","r":"서울특별시","s":"동작구","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1636201.jpg"},{"q":"형태는 저지(楮紙)에 목판본(木版本) 선장(線裝)으로 정통(正統) 기미년, 즉 조선 세종 21년(1439)에 간행된 것이다. 제25권부터 제30권까지 6권 1책으로, 반곽의 크기는 26cm×19cm이다. 내용은 공자(孔子)가 편찬한 『춘추(春秋)』에 대하여 송나라 학자 호안국(胡安國)이 주석을 가한 책이다. 『좌씨전』과 『공양전』과 『곡량전』이 춘추삼전으로 13경에 들어 있는 것과는 달리, 송대에 이루어진 『○○○○○』은 당대의 시사(時事)를 『춘추』의 경문(經文)에 의탁하여 서술하고 있다는 데 그 특징이 있는 것이다.","a":"양산 대성암 춘추호씨전","c":"시도유형문화유산","nc":"","r":"경상남도","s":"양산시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1642392.jpg"},{"q":"이 불상은 우림정 뒤의 암벽 아래, 높이 약 3m의 타원형 석판에 선각되어 있는데, 석불의 크기는 높이 250㎝, 폭 110㎝ 정도이다. 석판은 두께가 20㎝ 정도로 아래쪽이 약간 두꺼운데, 윗부분은 보주형(寶珠形)으로 다듬어 몸광배 형태로 만들고, 편평한 앞면에는 원형 머리광배을 지닌 ○○○○ 1구를 선각하였다. 얼굴에서부터 신체 아래부분에 이르기까지 선각으로만 처리하여 마치 그림을 그린 듯이 보인다. 민머리 위에는 상투 모양의 육계가 큼직하게 솟아 있고, 얼굴은 마멸이 되어 확실치 않지만 갸름한 얼굴에 반달 모양의 눈썹, 넙적한 코 등이 얕게 선각되었다.","a":"암치리선각석불좌상","c":"문화유산자료","nc":"","r":"전북특별자치도","s":"고창군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1661871.jpg"},{"q":"암각화란 선사시대 사람들이 바위나 동굴벽에 기호나 물건, 동물 등의 그림을 새겨놓은 것을 말하는데, 주로 농사의 풍요와 생산을 기원하던 주술행위의 결과물로 보고 있다. 이 암각화는 ○○○ 해수욕장 서쪽의 곤륜산 계곡 옆에 툭 불거져 나온 바위면에 새긴 그림이다. 그림을 새긴 바위는 모두 세 군데인데, 원위치에 하나, 거기서 6m 떨어진 계곡에 하나, 그리고 20m 떨어진 곳에 또 하나가 있다. 원위치에 있는 암각화는 돌출부 앞쪽을 거칠게 쪼아서 평탄한 면을 만든 후 서쪽면 전체에 6개의 같은 모양의 그림을 꽉차게 새겨 넣었다.","a":"영일 칠포리 암각화군","c":"시도유형문화유산","nc":"","r":"경상북도","s":"포항시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1640786.jpg"},{"q":"도림마을 뒷산 중턱에 자리하고 있는 탑으로, 주변에서 ‘○○○ ’라 새겨진 기와조각이 발견되어 이 터가 ○○○의 옛 터임을 알게 되었다. ○○○는 고려시대 이전에 창건되어 조선 중기까지 계속되었던 사찰로 추측되고 있는데, 화재로 모두 불에 타고 현재는 터만 남아있다. 탑은 전체의 무게를 지탱하는 기단(基壇)을 2층으로 쌓고, 그 위로 3층의 탑신(塔身)을 올린 후 꼭대기에 머리장식을 얹은 모습이다. 위층 기단은 네 모서리와 면의 가운데에 기둥모양을 조각했는데 제법 뚜렷한 형상이다. 탑신부는 각 층의 몸돌이 적당히 줄어들고 있어 깔끔한 균형을 이룬다.","a":"도림사지삼층석탑","c":"시도유형문화유산","nc":"","r":"충청남도","s":"청양군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1639039.jpg"},{"q":"○○○는 통일신라 애장왕 5년(804)에 세운 절로 법당과 부속건물 및 여러 암자를 갖추고 있는 절이다. ○○○은 조선 광해군 12년(1620)에 지었다는 기록이 있으나 정확하지 않다. 숙종 21년(1695)에 고쳐 지은 후, 여러 차례 보수를 거쳐 오늘에 이르고 있다. 앞면 6칸·옆면 6칸 규모의 건물로 지붕은 옆면에서 볼 때 여덟 팔(八)자 모양을 한 팔작지붕이다. 간결한 조선 후기의 건축 양식을 보이는 좋은 예로서 소박한 옛 건축의 아름다움을 느끼게 한다.","a":"파계사적묵당","c":"문화유산자료","nc":"","r":"대구광역시","s":"동구","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1659464.jpg"},{"q":"○○○는 통일신라 헌안왕 3년(859)에 도선이 세운 절이다. 조선시대에도 여러 차례 고쳐 지었으나 1911년 화재로 소실되었다. 그 이듬해부터 3년에 걸쳐 다시 세웠는데 지금 있는 ○○○ 역시 이 때 세운 것이다. ○○○은 앞면 3칸·옆면 2칸 규모로 지붕은 옆면에서 볼 때 여덟 팔(八)자 모양인 팔작지붕으로 꾸몄다. 안쪽에는 목조석가여래좌상과 후불탱, 산신탱, 신중탱, 칠성탱, 독성탱 등 여러 점의 탱화와 소종(小鐘), 수번(繡幡)이 있다.","a":"청암사대웅전","c":"문화유산자료","nc":"","r":"경상북도","s":"김천시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1662630.jpg"},{"q":"운천 김용 선생과 그의 부인 이씨의 묘소를 보호하기 위하여 세운 재실이다. 운천 김용은 조선 선조와 광해군 때 문신이다. 선조 23년(1590)에 과거에 급제하였으며, 선조 25년(1592)에 임진왜란이 일어나자 안동에서 의병을 일으켜 안동수성장에 추대되었다. 1597년 정유재란 때에는 이원익(李元翼)의 종사관으로 많은 역할을 하였으며, 향교를 중수하는 등 문교에도 힘썼다. 1609년에는 『선조실록』편찬에 참여하기도 하였다. 조선 인조 17년(1639)에 세운 이 건물은 앞면 4칸·옆면 5칸 규모로, 지붕은 옆면에서 보았을 때 여덟 팔(八)자 모양을 한 팔작지붕이다.","a":"운천재사","c":"문화유산자료","nc":"","r":"경상북도","s":"안동시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1662437.jpg"},{"q":"삼척 심씨의 시조 심동로가 벼슬을 버리고 내려와 제자를 가르치며 생활할 때 지은 정자로 고려 공민왕 10년(1361)에 처음 짓고, 조선 중종 25년(1530)에 심언광이 다시 지었다. 심동로는 어려서부터 글을 잘하였는데, 고려말의 혼란한 상태를 바로잡으려 노력하다가 권력을 잡고있던 간신배들이 마음에 들지않아 고향으로 내려가려고 하였다. 왕은 그를 말렸으나 노인이 동쪽으로 간다는 뜻의 ‘동로(東老)’라는 이름을 내리면서 결국 허락하였다. 앞면 3칸·옆면 2칸 규모이며, 지붕 옆면이 여덟 팔(八)자 모양인 팔작지붕집이다.","a":"동해 해암정","c":"시도유형문화유산","nc":"","r":"강원특별자치도","s":"동해시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1638011.jpg"},{"q":"오산 회암지소가 저술하였으며 총 63페이지이다. 券尾 '至正十七年'은 고려 공민왕6년(1357)에 해당하며 이 판본은 이색(李穡)의 발문에 기록되어 있듯이 원나라에 세워진 '高麗大聖壽慶禪師'에서 선종의 고승인 五宗의 행적을 기록한 것으로 우리나라 晉城君 姜金剛이 중간한 판본을 조선시대 태조의 왕사였던 武學大師가 입수하여 檜巖寺에서 飜刻한 것으로 보여진다.","a":"인천안목 권상","c":"시도유형문화유산","nc":"","r":"충청북도","s":"충주시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1638900.jpg"},{"q":"이 문서들은 시권(試券)들을 제외하고는 ‘선적유편(先蹟類編)’과 ‘○○’이라는 책자의 형태로 묶여져 있던 것의 일부이다. ‘선적유편’은 1943년 하정근(河貞根 1889∼1973)이 조상이 남긴 유묵(遺墨), 만사(挽詞), 제문(祭文), 분재기(分財記), 호적(戶籍) 등 여러 문적을 종류별로 분류하여 4개의 책자로 묶고 명명한 것이고, ‘○○’은 1718년경의 ‘장석한(張錫漢) 무고사건’의 내력을 간략하게 기록해 놓은 여러 종류의 ○○ 및 일부 다른 문건을 묶어놓은 것이다.","a":"소록","c":"시도유형문화유산","nc":"","r":"경상남도","s":"진주시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/0000000001642950.JPG"},{"q":"조선 정조 15년(1791)에 송계 봉유례·풍애 봉즙·묵헌 봉여해 등을 추모하기 위해 단을 설치했던 곳이다. 그 뒤 정조 17년(1793)에 신당인 ○○○를 세워 봉여예만 모시다가 철종 13년(1862)에 봉유례·봉즙·봉단의를 추가로 모시게 되었다. 고종 5년(1868) 흥선대원군의 서원철폐령으로 훼철되었다가 1903년에 다시 세웠다. 건물로는 ○○○, 별묘, 숭절당, 고직사, 내삼문, 외삼문이 있다. 신당인 ○○○는 앞면 3칸·옆면 2칸 규모이며 지붕은 옆면에서 볼 때 사람 인(人)자 모양인 맞배지붕으로 꾸몄다. 강당인 숭절당은 앞면 4칸·옆면 2칸 규모이다.","a":"장성 만곡사","c":"문화유산자료","nc":"","r":"전남광주통합특별시","s":"장성군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1662034.jpg"},{"q":"고려시대의 문신인 회헌 안향(1243∼1306) 선생의 초상화이다. 안향은 원종 1년(1260) 문과에 급제하여 교서량을 시작으로 벼슬길에 나아갔다. 충렬왕 1년(1275) 상주 판관으로 재임할 때에는 미신을 타파하고 풍속을 쇄신하였으며, 이후 감찰사, 수국사 등의 벼슬에 올랐따. 우리나라 최초의 주자학자로, 원나라로부터 주자학을 들여오는데 큰 역할을 하였으며, 유교를 한층 발전시키기도 하였다. 그림은 붉은 홍포에 낮은 건을 쓴 모습을 가슴부분까지만 그린 반신상으로, 그 양식이 소수서원에 전해오는 안향상(국보 제111호)과 거의 비슷하다.","a":"회헌개모영정","c":"시도유형문화유산","nc":"","r":"경상북도","s":"영주시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1640765.jpg"},{"q":"조선 후기 문신이며 독립운동가인 동농 김가진(1846∼1922)선생이 조선 고종 23년(1886)에 지은 집이다. 고종 27년(1890) 죽헌 이현찬 공이 인수하여 현재 제사지내는 집으로 사용하고 있다. 전체적으로 가옥은 ㅁ자형 평면을 이루고 있으며 앞면 5칸·옆면 5칸 규모이다. 안채 지붕은 옆에서 볼 때 사람 인(人)자 모양의 맞배지붕으로 꾸몄다. 건물을 둘러싸고 있는 담은 외부의 침입을 막기 위하여 돌을 높이 쌓아 내부를 격리시킨 특이한 양식을 취하고 있다. 전형적인 조선 후기 ㅁ자형 민가의 특징을 보이는 건물이다.","a":"안동 죽헌고택","c":"시도민속문화유산","nc":"","r":"경상북도","s":"안동시","i":"http://www.khs.go.kr/unisearch/images/folklore_material/thumb/1658915.jpg"},{"q":"○○○ 석조 ○○○○○은 1936년 강릉시 연곡면 방내리의 방현사(方縣寺) 터에서 출토되었다고 한다. 몸체에 비해 하체가 커서 안정감이 있으나, 목이 짧아 움츠린 듯한 자세를 취하고 있다. 두상은 소라 모양의 머리카락과 상투 모양의 육계가 구분하기 어려울 정도로 완만한 곡선으로 이루어져 있으며, 둥근 얼굴은 눈과 입이 마모가 심하여 형태를 알 수 없다. 이마에는 백호공이 있는데 근래에 박아놓은 듯한 커다란 구슬이 있다. 양 어깨를 감싸고 있는 옷은 두터워 신체의 굴곡이 거의 드러나지 않으며, 굵고 단조로운 주름무늬와 왼쪽 어깨의 매듭 표현이 특징적이다.","a":"강릉송라사석조약사여래좌상","c":"시도유형문화유산","nc":"","r":"강원특별자치도","s":"강릉시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1638200.jpg"},{"q":"장륙사는 고려 공민왕(재위 1351∼1374) 때 나옹선사가 처음 세웠다고 전한다. 조선 세종(재위 1418∼1450) 때 산불로 인해 불에 타고 그 후 다시 절을 세웠으나 임진왜란(1592) 때 훼손되어 다시 절을 세웠다. 광무 4년(1900)에 수리하였다고 한다. 장륙사 ○○○은 태조 4년(1395)에 태조와 그의 부인 신덕왕후 강씨를 기리기 위하여 지방관리들이 중심이 되어 만들었고, 태종 7년(1407)에 다시 금을 입혔다. 또 숙종 3년(1677)에 수리하였다는 등 자세한 기록이 있어 유명하다.","a":"장육사대웅전","c":"시도유형문화유산","nc":"","r":"경상북도","s":"영덕군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1640537.jpg"},{"q":"'○○○○○'은 조선후기 학자 권순경(權舜經, 1676~1746)이 상례와 제례에 대하여 저술한『○○○○』의 책판이다. 전체 판수는 66판 132면이다. 책판의 제작은 저자 권순경의 5대손인 권주신(權周新)과 권호신(權虎新) 등이 1863년(철종 14)에 하였다. 판면의 목재는 배나무이며, 마구리는 소나무이다. 『○○○○』은 4권 2책으로 구성되었는데 처음 3권은 상례이고 마지막 1권은 제례이다.『○○○○』에는 1863년(철종 14)에 김대진이 쓴 ○○○○서(序), ○○○○ 목록(目錄), 그리고 1741년(영조 17)에 저자인 권순경이 쓴 자서(自序)가 있다.","a":"상제집략판목","c":"시도유형문화유산","nc":"","r":"대전광역시","s":"유성구","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1637209.jpg"},{"q":"사벌국은 경상북도 상주지방에 위치하였던 삼한 소국 중의 하나로, 일명 사량벌국이라고도 한다.『삼국사기』에 의하면 이 나라는 본래 신라에 속하여 있었으나 점해왕 때 갑자기 배반하여 백제에 귀속하였다 한다. 그러자 우로(于老)가 군대를 거느리고 이를 토벌하여 사벌주를 설치하였다. 그 뒤 신라 54대 경명왕의 여덟 왕자 중 다섯 번째 왕자인 언창이 사벌주의 대군으로 책봉되어 사벌국이라 칭하고 11년간 이 지역을 통치하였다. 그 뒤 후백제 견훤(甄萱)의 침공을 받아 929년 패망하였다.","a":"전사벌왕릉","c":"시도기념물","nc":"","r":"경상북도","s":"상주시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1654429.jpg"},{"q":"홍산 시가지 북쪽에 흐르던 홍산천에 ‘○○○’라는 돌다리를 놓은 후 그 기념으로 세운 비이다. 홍산 읍내로 들어가는 큰 관문이 되었던 ○○○의 건립연대는 알려지지 않고 있고, 비는 원래 다리 옆에 있었으나 다리가 없어진 뒤, 홍산초등학교로 옮겼다가 다시 지금의 자리인 홍산객사내로 옮겨온 것이다. 비는 비몸돌과 머릿돌을 하나의 돌로 만들어 세웠으며, 머릿돌에는 구름무늬를 새겼다. 조선 숙종 7년(1681)에 세운 것으로, 비문에는 객사 동쪽에 시내가 있으나 다리가 없어, 첨지 서덕해가 오랜 기간에 걸쳐 무지개모양의 이 다리를 놓았다고 적고 있다.","a":"홍산만덕교비","c":"시도기념물","nc":"","r":"충청남도","s":"부여군","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1651713.jpg"},{"q":"삼국시대의 백제 왕궁에서 이용하였다고 전해지는 우물이다. 우물이 있는 곳은 조선시대에 부여 현의 관청 건물이 있던 자리로, 발굴 결과 백제의 도로나 연못터 유적을 확인할 수 있어, 백제 때에 중요하게 쓰였던 장소일 것으로 추정된다. 우물의 바닥에는 길게 다듬어진 돌로 8각형의 우물을 짜고, 그 위에 깬돌을 차곡차곡 쌓아올렸다. 근처에서 건물에 쓰였던 주춧돌과, 집터를 만드는데 쓰였을 커다란 돌들이 많이 발견되고 있다. 우물의 주변에서 나오는 유물들이 백제의 문화를 반영하고 있어, 당시 왕궁터를 추정하는데 중요한 단서가 되고 있다.","a":"팔각정","c":"문화유산자료","nc":"","r":"충청남도","s":"부여군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1661056.jpg"},{"q":"이 석불은 석가여래의 서 있는 모습이다. 오랫 동안 머리 부분을 제외한 몸체가 땅에 묻혀 있었으나, 1970년대에 파내어, 1980년에 건립한 미륵암의 미륵당 안에 모셨다. 이 불상은 그 본 모습을 상당부분 잃었는데, 코와 손은 근래 새로 만들어 붙인 것이다. 두 어깨를 모두 가린 옷차림(통견)으로, 옷 주름은 양어깨에서 가슴과 두 팔에 곡선으로 흘러내려 다리까지 이어졌으며, 옷소매는 길게 드리워져 있다. 이 불상은 제작기법과 연꽃 무늬를 새긴 받침대 양식 등으로 미루어 보아 조선시대의 작품으로 보인다.","a":"서서학동석불입상","c":"문화유산자료","nc":"","r":"전북특별자치도","s":"전주시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1661618.jpg"},{"q":"인재를 가르치던 ○○향교 서쪽의 육영재를 철거하면서 회산 감씨 문중에서 인수받아 고종 14년(1877)에 옮겨 지은 것이다. 현재 ○○○은 내리동 반룡산 남동기슭의 군용지 안에 자리잡고 있다. 1936년에는 ○○○ 뒤편에 삼열사를 지어 임진왜란 때 선무원종공신에 오른 감경인·경륜 형제를 모시고 해마다 음력 4월에 유림제를 지내고 있다.","a":"창원 관술정","c":"문화유산자료","nc":"","r":"경상남도","s":"창원시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1664117.jpg"},{"q":"조선시대 직제학 설순 등이 임금의 명에 따라 우리나라와 중국의 서적에서 군신·부자·부부의 삼강에 모범이 될만한 충신, 효자, 열녀의 행실을 모아 만든 책이다. 조선 전기의 윤리와 의례에 관한 것을 기록한 것으로, 초판은 조선 세종 14년(1432)에 이루어졌지만, 본 책자는 재판인 것으로 보인다. 이 책은 조선 전기의 사회규범 연구에 좋은 자료로 평가된다.","a":"삼강행실도","c":"시도유형문화유산","nc":"","r":"경상남도","s":"양산시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1641756.jpg"},{"q":"세종특별자치시 ○○면 ○○○ 내판역 근처 얕은 구릉에 있는 마애불이다. 커다란 배(舟)모양의 광배(光背) 가운데에 돋을새김한 이 불상은 오른쪽 눈 윗부분이 파손되어 있으며, 무릎 아래는 땅에 묻혀 있다. 머리에는 상투 모양의 머리묶음이 큼직하게 표현되었으나 파손되어 일부만 남아있으며, 얼굴은 이목구비가 뚜렷하다. 가슴 앞에 올린 두 손은 손바닥을 가슴으로 향하고 있어 이 불상이 아미타여래를 표현한 것임을 알 수 있게 한다. 이 불상은 조각수법이 형식적이고 뛰어나지 못하나 전체적으로 육중하여 안정감을 준다.","a":"연동 송용리 마애여래입상","c":"문화유산자료","nc":"","r":"세종특별자치시","s":null,"i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1666857.jpg"},{"q":"이 석탑은 이중(二重) 기단 위에 3층의 몸돌을 올려 세웠다. 기단부의 구성, 지붕돌의 조성수법으로 신라 하대의 양식을 보여 주는 매우 세련된 탑으로서, 이 지방의 신라 석탑을 대표할 만한 것이다. 이 마을에서 전해 오는 말에 의하면 이 곳에 큰절과 3기의 탑이 있었다고 하나 확인할 문헌이 없다. 다만 이 석탑이 서 있는 주변에는 석탑의 부재와 기와조각을 볼 수 있고 이 밖에 순금불상, 청동불상 등이 발견되었다는 점으로 미루어 현존 탑 이 외에도 석탑이 더 있었던 절터임을 짐작할 수 있다.","a":"예천 간방리 삼층석탑","c":"시도유형문화유산","nc":"","r":"경상북도","s":"예천군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1640655.jpg"},{"q":"○○○는 서원 앞에 세워 서원의 건립취지와 그 서원의 주인·모시는 인물에 대한 문장 등을 기록해 두는 것으로, 이 비는 우암 송시열 선생을 모신 ○○○○의 자리에 놓여 있다. ○○○○은 조선 숙종 22년(1696) 송시열의 영정을 모시고 제향하기 위해 건립된 것으로, 창건되던 해에 현판을 하사받아 숙종 42년(1716) 어필로 현판을 달았다. 전국의 사액서원 중에서도 가장 이름있고 위세가 당당한 서원이었으나, 그릇된 세금징수로 심한 민폐를 끼쳐 철종 9년(1858)에 폐쇄되고, 논란 속에 고종 7년(1870) 건물이 헐리었다.","a":"괴산 화양서원 묘정비","c":"시도기념물","nc":"","r":"충청북도","s":"괴산군","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1650534.jpg"},{"q":"실상사 경내에 있는 높이 123㎝, 입 지름 83㎝의 종이다. 종을 매다는 고리는 용이 종머리를 딛고 있는 형상이며, 소리의 울림을 도와주는 용통은 간략화 된 용이 꼬리를 휘감은 모양을 하고있다. 몸통 위쪽은 원안에 범자를 양각한 문양을 12곳에 배치하였다. 그 아래 사각형을 이룬 유곽이 4면에 있으며, 사이사이에 두 손으로 꽃가지를 잡고 보관을 쓴 보살상이 1구씩 배치되었다. 유곽의 테두리는 덩굴무늬로 장식되었고, 안쪽으로는 꽃 모양의 유두 9개가 있다. 종에 새긴 글을 통해 조선 숙종 20년(1694)에 만들었음을 알 수 있다.","a":"실상사동종","c":"시도유형문화유산","nc":"","r":"전북특별자치도","s":"남원시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1639599.jpg"},{"q":"이 정자는 이 곳 출신 인물들이 간관(諫官)으로 많이 진출하여 여기서 나라 일을 의논하였다고 해서 ‘간원대(諫院臺)’라고도 한다. 세운 때는 정확히 알 수 없으나 ○○○○이라는 글씨는 송시열(宋時烈,1607~1689)이 쓴 것이다. ○○○○은 동약(洞約)이나 향약(鄕約)의 시행처로 활용되었기 때문에 동정(洞亭)이라는 이름을 썼으며, 정자 안에는 누정 시문과 <양과동적입의서(良瓜洞籍立議序)>나 <○○○○향약서(良瓜洞亭鄕約序)>와 같은 동약과 향약에 관련된 글들이 걸려 있다.","a":"양과동정","c":"문화유산자료","nc":"","r":"전남광주통합특별시","s":"남구","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1659606.jpg"},{"q":"화성면 기덕리는 평택임씨 집성촌으로 주변에는 재실이 있으며 지정건물과 맞대어 임찬○○○이 위치하고 있음. 건립년대는 정확하지 않으나 1900년대초 ○○○○ 지었다고 전해지며 그의 호가 ‘송운’으로 송운고택이라고도 불리움. 안채 등 건물구조, 양식은 물론 담장 등 전통양식이 비교적 원형유지⋅관리가 잘 되고 있어 도 민속자료로 지정","a":"청양임석주가옥","c":"시도민속문화유산","nc":"","r":"충청남도","s":"청양군","i":"http://www.khs.go.kr/unisearch/images/folklore_material/thumb/1658279.jpg"},{"q":"○○○은 석초 권두희가 금재 권습을 기리기 위해 1915년 수월산 아래 지은 정자이다. 일반적인 정자는 마루를 중심으로 한 구성이나 이 정자는 겨울에 추운 ○○의 지역 여건을 반영한 듯 온돌방을 중심으로 구성하였는데, 전반적으로는 좌우 대칭적인 구성을 취하되, 세부적으로는 비정형의 구성을 함으로써 기능성을 반영한 근대 한옥의 전형을 잘 보여주는 건축이다.","a":"산청 수월정","c":"문화유산자료","nc":"","r":"경상남도","s":"산청군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1666470.jpg"},{"q":"서남산 용장리(용장사지 입구)에서 삼릉 쪽으로 약 600m 가량 가면 “앞비파마을”이 있다. 이 마을을 뒤로하고 남산 정상을 향하여 약 800m 떨어진 지점, 삼각산의 능선이 내려와 계곡과 만나는 곳에 비파골 ○○○○가 있다. 이 절터 북쪽의 정상부에 자연 암반을 기단부로 삼은 ○○○○이 있다. 이 석탑의 가장 큰 특징은 위치 선정이라고 할 수 있다. 비록 작은 산봉우리이기는 하지만 정상부에 석탑을 세움으로써 주변 경관과 조화를 이룸은 물론 멀리서도 쉽게 인식될 만치 돌올하게 솟아 있어서 종교적 경외감을 불러일으킨다.","a":"경주남산 비파곡 제2사지 삼층석탑","c":"시도유형문화유산","nc":"","r":"경상북도","s":"경주시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1641257.jpg"},{"q":"○○○○은 비슬산 유가사 서쪽 해발 700미터 산 정상에 위치하여 북동에서 남서방향으로 길게 타원형으로 자리 잡은 성으로, 성의 둘레는 1,700미터이며 산성 내에 분포한 고분군으로 보아 삼국시대 축성된 산성으로 여겨진다. 성곽의 형태는 꼭대기가 평탄하며 절벽인 자연지형을 이용한 퇴뫼식 산성으로 성내부에는 성문, 망루 등의 흔적뿐만 아니라 기와, 우물, 고분군 등이 확인되어 달성군 현풍면, 유가면 일대의 중요한 유적으로 역사적 가치가 있다.","a":"초곡산성","c":"시도기념물","nc":"","r":"대구광역시","s":"달성군","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1645419.jpg"},{"q":"대사리 마을의 이름없는 절터에서 발견된 탑으로, 돌을 벽돌 모양으로 다듬어 쌓은 ○○○○이다. 자연석인 바닥돌 위에 기단(基壇)과 탑신(塔身)을 쌓아 올린 형식이며, 탑신의 1층 이상은 무너져 내려 정확한 탑의 규모를 알 수 없다. 건립연대는 알 수 없으나 탑의 양식으로 보아 통일신라시대의 것으로 추정된다.","a":"안동대사동모전석탑","c":"문화유산자료","nc":"","r":"경상북도","s":"안동시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1662488.jpg"},{"q":"○○○ 천황봉에 있는 ○○○으로, 이 산을 수호하는 민간신앙의 여신이었는데, 고대부터 국가적인 차원에서 숭상의 대상이 되어 왔다. 기록에 의하면 신라 박혁거세가 그의 어머니를 ○○○ 산신으로 봉하여 국가의 수호신으로 섬기면서 봄·가을에 제사를 지냈고, 고려태조 왕건 역시 그의 어머니 위숙왕후를 산신으로 모셨다고 한다. ○○○은 틀어 올린 머리를 하고 있고, 얼굴은 통통하다. 눈은 움푹 들어갔으며, 오똑하게 표현된 코밑으로 작은 입이 조각되어 있다. 상반신에는 저고리를 입고 있는 듯하며, 가슴께로 손을 모아 마주잡고 있는데 석상 전체가 청색을 띠고 있어 매우 특이하다.","a":"지리산성모상","c":"시도민속문화유산","nc":"","r":"경상남도","s":"산청군","i":"http://www.khs.go.kr/unisearch/images/folklore_material/thumb/1659052.jpg"},{"q":"이 ○○은 조선종의 특징인 음통을 갖추고 있는 1728년 주조된 조선후기의 ○○으로서 유곽과 보살상의 모습등이 생동감있는 양식을 보여주고 있으며 , 특히 꽃을 든 보살상의 모습은 조선후기 전라도지역의 대표적인 주성장인 사인 비구와 같은 승려장인의 계열에 속하는 장인이 주조한 것으로 추정된다. 현재 종의 표면에 검은 칠이 되어 있고 명문과 문양부분이 일부 마멸되기는 하였지만 초주년대(1623년)와 재주년대(1728년) 및 처음 봉안한 장소(龍頭山 龍壽寺)등이 정확하게 밝혀져 있는 조선후기 ○○의 귀한 자료이다","a":"옥천사 소장 범종","c":"문화유산자료","nc":"","r":"전북특별자치도","s":"정읍시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1661887.jpg"},{"q":"∙ 계하 강제가 건립한 주택으로 법전강씨 종택 전면에 위치하고 있다. ∙ 정침은 정면 6간 측면 6간반 규모의 “口“자형 건물로 사랑채는 중문칸 우측에 배치되어 있는데 좌측 2간은 전면에 퇴칸을 둔 2통간 사랑방을, 우측에는 마루방을 두었으며 사랑방 뒤에는 작은사랑을 두었다. ∙ 안채는 2통칸의 마루방을 중심으로 좌측에는 안방을, 우측에는 건너방과 상방을 두었으며, 안방의 전면에는 부엌을 연접시켰다.","a":"봉화 해은구택","c":"문화유산자료","nc":"","r":"경상북도","s":"봉화군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1663657.jpg"},{"q":"1907년에 편수 보암긍법(普庵肯法), 두흠(斗欽), 금어 봉감(奉鑑), 법연(法沿)범천(梵天) 등이 조성한 아미타후불화로, 대시주인 강문환ㆍ강재희가 황명을 받들어 황제, 황태자, 태자비, 귀비 엄씨, 의친왕과 비, 영친왕 등의 성수만세(聖壽萬歲)를 기원하며 제작한 것이다. 중앙의 커다란 광배 속에 석가모니 삼존을 배치하고 좌우의 화면을 3단의 격자형으로 분할한 뒤 16나한 각각을 그려 넣었다.","a":"수국사 십육나한도","c":"시도유형문화유산","nc":"","r":"서울특별시","s":"은평구","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1636434.jpg"},{"q":"성현의 위패를 모시고 제사를 지내며, 지방 백성의 교육을 담당하기 위해 국가에서 세운 지방 교육기관이다. 처음 지어진 연대는 알 수 없으나 태조 7년(1398)에 지금의 위치에 세워진 것으로 추정된다. 정종 2년(1400)에 불타 없어진 것을 다시 지었는데, 그 뒤 임진왜란(1592) 때 불에 탄 후 여러 차례 수리를 거쳐 오늘에 이르게 되었다. 현재 남아있는 건물은 ○○○·명륜당·동재·서재·내삼문 등이 있다. ○○○은 제사공간의 중심을 이루는 건물로 앞면 3칸·옆면 3칸이며, 지붕은 옆면이 사람 인(人)자 모양인 맞배지붕이다.","a":"고산향교대성전","c":"시도유형문화유산","nc":"","r":"전북특별자치도","s":"완주군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1639543.jpg"},{"q":"충재종택 우측편 계곡내에 자리하고 있는 추원재는 종택과도 그리 멀지 않는 곳에 자리하고 있다. 충재 권벌 선생은 외조부인 주부공 내외분과 선생의 부모 묘소를 관리하기 위해 자그마한 재실을 두었으나, 선생이 을사사화로 배소인 삭주(朔州)에서 돌아가시자 이곳에 유해를 모시고 재실을 지었다고 한다. 그후 1671 후손들이 중건하였다고 한다. 배산하여 남동향으로 자리하고 있는 본 재실은 북부지방에서 자주 볼 수 있는 재실의 형태와는 다소 차이가 있다.","a":"봉화추원재","c":"시도유형문화유산","nc":"","r":"경상북도","s":"봉화군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1641092.jpg"},{"q":"○○○란 한 인물의 옛 자취를 밝혀 후세에 알리고자 세우는 비석으로, 이 비는 고려 말 충신 포은 정몽주(圃隱 鄭夢周, 1337〜1392) 선생의 학덕을 기리고 있다. 포은 선생은 고려 우왕 1년(1375) 성균관 대사성의 벼슬에 있으면서 중국 명나라를 배척하고 원나라와 친하게 지내려는 친원배명(親元排明) 정책에 반대하다가 언양에서 1년 넘게 귀양살이를 하였다. 그동안 반구대에 올라 “중양절감회(重陽節感懷)”라는 시를 짓는 등 많은 자취를 남겼다. 그 후 지역인들은 선생을 추모하여 반구대를 ‘포은대’라 명명하기도 하였다.","a":"반고서원유허비","c":"시도유형문화유산","nc":"","r":"울산광역시","s":"울주군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1637273.jpg"},{"q":"고려 중기부터 조선 후기까지 이어져오던 역원공영제도에 의해 예안현에 속해있던 부라원의 2층 누각건물이다. 『영가지』에 의하면 안동지방에는 30여 개 정도의 원(院)이 있었다고 하는데, 그 당시의 누가 남아있는 것은 이곳이 유일하다. 원의 본래 건물은 없어지고 누각만이 남아 있으며, 안동댐의 건설로 인하여 1976년 지금의 위치로 옮겨졌다. 앞면 3칸·옆면 2칸 규모이며, 지붕 옆면이 여덟 팔(八)자 모양인 팔작지붕건물이다. 현판은 명필 한석봉이 썼다.","a":"부나원루","c":"시도유형문화유산","nc":"","r":"경상북도","s":"안동시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1640298.jpg"},{"q":"고종 11년(1874) 한상룡이 세운 집으로 압록강 흑송을 가져다 지었다고 전한다. 크게 행랑채, 안채, 사랑채로 구성되어 있는데 사랑채와 안채는 일반적인 서울지방 상류주택들과 달리 한 동으로 이어져 있다. 대문 좌우로 광과 부엌이 있고 사랑채에는 4칸의 방과 대청을 놓았으며 긴 툇마루가 안채와 연결되어 있다. 안채는 앞뒤로 퇴칸을 두었고 부엌·안방·대청·건넌방을 一자로 배치하였다. 별당은 뒤뜰 북서쪽에 자리잡고 있다. 조선 후기 주택으로 보존상태가 좋고 사랑마당으로 들어서는 대문과 안마당쪽 담의 꾸밈이 눈길을 끄는 집이다.","a":"가회동백인제가옥","c":"시도민속문화유산","nc":"","r":"서울특별시","s":"종로구","i":"http://www.khs.go.kr/unisearch/images/folklore_material/thumb/1658063.jpg"},{"q":"‘갓바위 부처’로 유명한 관봉석조여래좌상(보물 제431호)과 선본사 사이의 산 능선상에 자리한 탑으로, 2층 기단(基壇) 위에 3층의 탑신(塔身)을 올린 통일신라의 일반적인 양식을 따르고 있다. 아래·위층 기단의 각 면에는 모서리와 가운데에 기둥 모양을 새겼고, 탑신의 각 층 몸돌에도 모서리마다 기둥 모양을 가지런히 조각하였다. 지붕돌은 밑면에 5단씩의 받침을 두었고, 처마는 수평을 이루다 네 귀퉁이에서 살짝 올라갔다. 간결하면서도 장중한 멋을 지닌 탑으로, 지붕돌 받침이 5단이고, 네 귀퉁이가 살짝 올라간 점 등으로 보아 통일신라시대의 작품으로 추정된다.","a":"선본암삼층석탑","c":"시도유형문화유산","nc":"","r":"경상북도","s":"경산시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1640460.jpg"},{"q":"○○○○○은 북서쪽으로 뻗어 내린 국수봉의 나지막한 능선 자락에 위치하며 현재 ○○○ 숲안마을의 서쪽 편에 있다. 이 ○○○○은 바둑판식으로 추정되며, 3기(基)의 ○○○가 한 장소에 모여 있다. 제1호는 만화로 도로변에 위치하고 있으며, 제2․3호는 뒤쪽으로 40m쯤 떨어진 대밭 옆에 있다. 덮개돌의 규모가 제일 큰 제1호는 길이 270cm, 너비 220cm, 두께 50cm 정도이다. 이들 덮개 돌 위에는 작은 돌로 문질러서 둥글고 오목하게 파인 알[卵] 모양의 구멍들이 있는데, 이런 구멍을 성혈(性穴)이라고 한다.","a":"은편리지석묘군","c":"시도기념물","nc":"","r":"울산광역시","s":"울주군","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1645892.jpg"},{"q":"\"만회당 장경우(1581∼1656)가 후진을 양성하기 위해 효종 2년(1651)에 세운 건물이다. 장경우는 조선 중기 학자로 정묘호란 때 인동 의병장으로 활약하고 후진교육에 힘썼으며 『여헌문집』, 『만회당집』 등의 저서를 남긴 분이다. ○○○○은 원래 석적읍 성곡리에 있었으나, 사림의 여러 의견에 따라 헌종 6년(1840)에 석적읍 중리에 옮겨 세웠다.이 때 선현의 위패를 모시는 건물을 새로 세웠으나, 흥선대원군의 서원철폐령으로 고종 8년(1871) 해체되어 지금은 강당과 양예청만 남아 있다.","a":"화산서당","c":"문화유산자료","nc":"","r":"경상북도","s":"경산시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1662855.jpg"},{"q":"현재 ○○○ 나한전(羅漢殿)에는 석가삼존불상(釋迦三尊佛像) 좌우로 각각 8구(軀)씩 16구(軀)의 나한전(羅漢像)과 제석상(帝釋像) 1구(軀), 사자상(使者像) 1구(軀), 인왕상(仁王像) 2구(軀) 등 총 20구(軀)의 상이 봉안되어 있다. 모두 소조상(塑造像)으로 현재는 화려한 채색이 되어 있는데 각 상은 47cm에서 53cm에 이르는 그리 크지 않은 아담한 규모이다.","a":"진관사 소 십육나한상","c":"시도유형문화유산","nc":"","r":"서울특별시","s":"은평구","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1636350.jpg"},{"q":"충청도 감영에 체포된 천주교인들을 처형한 유적지이다. ○○ 감영 또는 우영(右營)에 체포된 교인들은 현 교동성당 인근에 있는 감옥에 수감되었다가 이곳에서 처형되었는데, 내포의 사도라 불리는 이존창(李存昌)도 이곳에서 참수되었으며, 치명일기에 기록된 순교자만 337인에 이른다. 1980년 ○○○○ 성역화사업 추진위원회가 결성된 이후 천주교단에서 부지를 매입하였고, 1985년 순교자 248명의 이름을 새긴 무덤경당 및 순교탑을 건립하였으며, 1984년 이후 성지 담당 신부도 부임하고 있다.","a":"공주 황새바위 천주교순교유적","c":"시도기념물","nc":"","r":"충청남도","s":"공주시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1653231.jpg"},{"q":"장승은 마을입구나 사찰입구에 세워 잡귀와 액운의 출입을 막고 사찰내의 재산과 경계를 표시하는 민간신앙물로, 마을에서는 수호신의 기능을 겸하기도 한다. ○○○ 입구에 서 있는 이 돌장승은 원래 남장동에 있었는데, 1968년 저수지 공사로 인해 현재의 자리로 옮겨놓은 것이다. 높이 186㎝의 크기로, 자연석을 그대로 살려 다듬었다. 한쪽으로 치우친 비뚤어진 얼굴에 눈꼬리가 치켜 올라간 왕방울 눈과 커다란 주먹코, 야무지게 다문 입술에 송곳니는 아래로 뻗어있다. 가슴에는 한가닥의 수염이 있으며 그 밑에 ‘하원주장군(下元周將軍)’이라는 글귀를 새겨 놓았다.","a":"남장사 석장승","c":"시도민속문화유산","nc":"","r":"경상북도","s":"상주시","i":"http://www.khs.go.kr/unisearch/images/folklore_material/thumb/1658543.jpg"},{"q":"조선 고종 8년(1871) 공자를 모시기 위해 세운 사당이다. 공자의 66대손인 가암 공혜종이 경남 하동에서 임진왜란의 화를 피하기 위해 이곳으로 이동했으며, 그의 9대손인 공인두가 고종 7년(1870)에 중국 산동성 곡부에 가서 공자 영정 1매를 가지고 와 오무산 남쪽에 사당을 세우게 되었다. 그 후 1924년 풍수지리설에 따라 현 소재지로 옮겨 지은 뒤 ○○○라 불렀다. 앞면 3칸·옆면 2칸 규모로, 지붕은 옆면에서 볼 때 사람 인(人)자 모양의 맞배지붕이다. 안쪽에는 중국 곡부에서 가져온 가로 64㎝·세로 90㎝ 영정이 있다.","a":"대성사","c":"문화유산자료","nc":"","r":"전남광주통합특별시","s":"고흥군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1661984.jpg"},{"q":"○○○ 선생의 묘역이다. ○○○ 선생은 독립운동가이며 교육자이자 언론인으로 황성신문을 창간하여 일제의 침략 야욕을 폭로하고 무궁화 보급운동과 국어·국사교육을 통해 민족정신을 고취시키는 등 일제시대의 대표적인 애국지사이다. 선생의 묘에는 둥글게 호석(護石)이 둘려져 있고, 봉분 앞에는 제사음식을 올려놓을 수 있는 상석(床石)이 있다. 상석의 오른쪽에는 묘비가 있고 그 앞쪽으로 망주석 1쌍이 배치되어 있으며 묘역의 입구에는 돌계단이 마련되어 있는데, 이는 모두 1977년에 조성한 것들이다.","a":"홍천한서남궁억묘역","c":"시도기념물","nc":"","r":"강원특별자치도","s":"홍천군","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1648613.jpg"},{"q":"충청남도 서천군의 ○○○○은 해발 90.1m의 후망산 남서쪽 끝에 있으며 산성이라기 보다는 평지에 있는 평지성에 가깝다. 성벽의 둘레는 640m이고 동·서 190m, 남·북 100m로 역사다리꼴에 가까운 형태로, 남쪽벽과 북쪽벽에 각각 1개씩의 문터가 있다. 동쪽벽에서 5∼7m 정도 떨어진 곳에 폭 4m, 깊이 1.2m 정도로 주변에 도랑을 돌린 해자가 있으며, 서쪽벽은 일제시대 때 거의 헐려 형태가 잘 남아있지 않다.","a":"서천장암진성","c":"시도기념물","nc":"","r":"충청남도","s":"서천군","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1652851.jpg"},{"q":"탱화란 불경에 관한 그림을 천이나 종이에 그림을 그려 액자나 족자 형태로 만드는 것으로, 일반적으로는 절 내의 ○○○에 모시는 본존의 뒷벽에 자리한다. ○○○○○ 내의 불상 뒤에 있는 이 그림은 당시 연풍현감이던 단원 김홍도(1745∼?)가 그렸다고 하나, 그림의 하단에 기록이 적혀있지 않고 양식을 보아도 김홍도의 화풍과 차이가 있어 그의 작품으로 단정하기는 어렵다. 그림은 길이 3.2m, 폭 2.7m 크기의 화면을 위아래 2단으로 나누어 그렸다. 상단은 중앙에 현재불인 석가모니불을 모시고, 왼측에 과거불인 약사불, 오른쪽에 미래불인 아미타불을 그려 놓았다.","a":"용주사대웅전후불탱화","c":"시도유형문화유산","nc":"","r":"경기도","s":"화성시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1637363.jpg"},{"q":"‘○○○’는 신라 말기에 창건되었다고 전하지만, 구체적인 내용은 알 수 없다. 글자가 새겨진 기와 등이 발견되어 1677년경에 중건된 것으로 확인되었다. ○○○는 한국전쟁 때 완전히 소실되었다고 한다. 현재 부도는 ○○○○의 서쪽 골짜기 사이로 형성된 개울 건너에 세워져 있다. 이 부도는 규모가 상당히 큰 대형으로 하나의 돌로 거칠게 다듬은 석종형 양식을 취하고 있다. 지대석은 모서리를 짧게나마 다듬은 부등변 팔각형의 대석을 마련하였다. 석종은 앞면과 뒷면이 납작한 형태로 되어 있는데, 조선 후기의 석종에서 많이 볼 수 있는 수법이다.","a":"오봉사지부도","c":"시도유형문화유산","nc":"","r":"경기도","s":"연천군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1637602.jpg"},{"q":"경상남도 함양군 함양읍의 보림사 법당에 모셔진 ○○○○○이다. 원래는 옛 ○○○ 절터 근처에서 발견되어 민가에서 모셨으나 1990년 초에 이곳 보림사로 옮겨왔다. 풍만한 얼굴에 목에는 3줄의 주름인 삼도(三道)가 뚜렷하고, 양 어깨에 걸친 옷자락은 아래까지 굵은 옷주름으로 표현하였다. 손모양은 땅속의 악귀를 물리친다는 의미의 항마촉지인(降魔觸地印)을 하고 있는데, 손가락을 힘주어 펼치고 있는 것이 주목된다. 전체적으로 풍만한 체구인데 반해 키가 작고 어깨가 좁으며 양 발은 어색하게 표현되어 있다.","a":"함양용산사지석조여래입상","c":"시도유형문화유산","nc":"","r":"경상남도","s":"함양군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1642235.jpg"},{"q":"경상남도 ○○에 있는 이 성은 자연돌을 이용하여 성벽을 쌓은 장성이다. 장성은 국경의 경계지대에 쌓아 적의 침입에 대비하고자 쌓은 것을 말한다. 축성 방법이 특이하여 전국에서 찾아보기 어려운 성의 형태이며 둘레 150m, 높이 1∼2m이다. 논과 밭 주변의 성벽은 거의 훼손되어 형체를 찾아보기 어려우나, 임야 속의 성벽은 보존상태가 양호하다. 이 성은 군사상의 목적으로 고려말이나 조선 초기에 쌓은 것으로 추정된다.","a":"남해 금산목장성","c":"시도기념물","nc":"","r":"경상남도","s":"남해군","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1655915.jpg"},{"q":"인천광역시 남구 문학산 정상부분에 있는 돌로 만든 산성으로, ‘미추홀 고성’, ‘남산성’이란 이름으로 불리고 있다.『동사강목』과『여지도서』에 의하면 문학산은 백제 미추왕(비류)의 도읍지로, 돌로 만든 산성의 터가 있고, 성안에 비류정이라는 우물이 있다고 기록되어 있다. 축조형식은 테뫼식으로 정상의 봉우리를 돌로 둘러싸며 성벽을 두른 산성으로, 내성과 외성으로 구성되어 있으며, 성내에는 봉수대가 있었다.","a":"문학산성","c":"시도기념물","nc":"","r":"인천광역시","s":"미추홀구","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/0000000001645423.JPG"},{"q":"임진왜란이 터진 가운데 전라도 영광군에 있었던 읍성을 지켜낸 사례와 향촌에 있던 사림들의 전란극복 의지가 소상히 기록된 문헌자료로, 총 1책 21장이다. 「임진왜란수성명첩서」, 「○○○○○」, 「수성명첩」, 「수성법」 등이 실려 있다. 내용에는 임진왜란이 발발한 1592년 10월 영광군수 남궁견이 상중에 있어 상복을 입고 있을 때, 수령이 부재한 상황에서 지역의 선비들이 읍성방위 및 행정업무를 자치적으로 수행했던 사실이 기록되어 있다. 책의 끝부분에 남겨진 글로 보아 영조 29년(1753)에 봉정사에서 인쇄하여 출간한 것이다.","a":"영광임진수성록","c":"문화유산자료","nc":"","r":"전남광주통합특별시","s":"영광군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1662229.jpg"},{"q":"조선시대의 관리가 한복이나 공복을 입을 때 두르던 띠이다. 겉에 물소뿔로 만든 장식이 달려있어 서대(犀帶)라 하는데, 조선시대 법전인『대전회통』에서는 정1품의 관리가 옷을 입을 때 사용하던 중요한 의장의 하나로 적고 있다. 외형을 살펴보면, 한지를 여러 겹 아교로 붙여 띠를 만들고, 밖에는 물소뿔을 얇게 다듬어 오려 붙인 후, 앞에는 착용할 때 필요한 금속구를 달아 놓았다. 태조 2년(1392) 삼척지방이 부(府)로 승격되면서 하사받은 것으로, 실직왕묘 안의 보대운한각(寶帶雲漢閣)에 ○○○와 서대기책이 함께 보관되어 있다.","a":"홍서대","c":"시도민속문화유산","nc":"","r":"강원특별자치도","s":"삼척시","i":"http://www.khs.go.kr/unisearch/images/folklore_material/thumb/1658179.jpg"},{"q":"○○○○는 사찰 입구에 설치하는 것으로, 절에 행사나 의식이 있을 때면 당이라는 깃발을 달아 두는데, 이 당을 꽂아두는 길다란 장대를 당간이라 하고, 당간의 양쪽에 서서 이를 지탱시켜주는 두 돌기둥을 ○○○○라 한다. 드물게 당간이 있으나 대부분 두 기둥만 남아있다. 이 ○○○○는 마을 입구의 민가 뒷돌담에 서 있다. 남아있는 상태가 그리 좋지 않아서 한쪽 기둥은 잘린 채 떨어져 있고, 다른 한쪽도 파손이 심하다. 기둥의 받침대는 여러 개의 돌로 조립되어 있으며, 옆면에 연꽃무늬를 새겨 놓았다. 마주보는 면에는 아래위 두 곳에 당간을 고정시키기 위한 홈을 파놓았다.","a":"공주상신리당간지주","c":"시도유형문화유산","nc":"","r":"충청남도","s":"공주시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1639157.jpg"},{"q":"선국사는 교룡산성 안에 자리하고 있는 사찰로서 통일신라 신문왕 5년(685)에 창건된 것으로 전하고 있다. 원래는 용천사라 하다가 유사시에 나라의 태평과 전승을 기원하는 도량의 역할을 담당하였기 때문에 사찰 이름을 바꾼 것으로 추정된다. 전성기에는 승려 수가 300여 명에 이르렀다고도 하며, 지금은 대웅전, 칠성각, 요사채, 보제루 등의 건물이 남아 있다. 선국사 내에 있는 이 북은 법고(法鼓), 홍고(弘鼓)라고도 한다. 불교의식에 사용되었으며 북둘레 260㎝, 북길이 102㎝ 정도의 큰 북이다. 몸통은 소나무로 만들고, 쳐서 소리를 내는 양면은 소가죽으로 만들었다.","a":"선국사대북","c":"시도민속문화유산","nc":"","r":"전북특별자치도","s":"남원시","i":"http://www.khs.go.kr/unisearch/images/folklore_material/thumb/1658292.jpg"},{"q":"이 영정은 ○○○○○선사의 좌안7분면 바닥가부좌상으로, 왼손엔 주장자를 오른손엔 염주를 쥐고 돗자리위에 가부좌하고 있다. 화면은 주색 상단벽면과 돗자리의 이단구도로 이루어져 있다. 화면 향좌측에 ‘국일도총섭대각등계○○○○○대사지진(國一都摠攝大覺登階虎惺堂奭鍾大師之眞)’ 의 화제가 있으며, 화면크기는 가로 75.2cm, 세로 114.5cm이다.","a":"호성당 석종 진영","c":"시도유형문화유산","nc":"","r":"경상남도","s":"양산시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/0000000001643029.JPG"},{"q":"○○○ 대웅전에 소장되어 있는 목 아미타○○○은 광배와 대좌가 없어졌지만 불신(佛身)은 완전한 형태로 남아있는 17세기 중엽의 대표적인 불상으로 평가된다. 머리는 둥근 복발형인데 육계(肉髻)가 표현되지 않았고 정상에 둥글고 낮은 정상계주(頂上髻珠)와 머리중심에 긴 반달형 중심계주(中心髻珠)가 있으며, 나발(螺髮)은 큼직한데 성글게 붙여져 있다. 얼굴은 전체적으로 궁글려 계란형에 가까운 모습이다. 눈썹 사이에 작은 백호(白毫)가 있고, 눈은 도톰하며 입이 작으면서 인중이 돌출하였고, 코는 눈썹 사이에서 돌출하여 17세기의 특징을 잘 보여주고 있다.","a":"환희사 목불좌상(아미타불)","c":"시도유형문화유산","nc":"","r":"서울특별시","s":"서대문구","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/2593343.png"},{"q":"울산시 울주군 범서면 구영리 중촌마을 ○○○○ 이채식의 12대 조상인 이충립의 무덤에서 나온 유품이다. 이충립은 조선 중기의 무인으로 임진왜란 때 많은 공을 세웠다. 1986년 공업단지 조성으로 무덤를 이장할 때 출토되었다. 17세기 전기의 것으로 추정되는 이 유물들은 350여년이 넘도록 땅 속에 있었지만 상한데 없이 그대로 출토되었다. 유물의 종류는 명정, 포의 띠, 구의, 지물, 얼레빗, 참빗, 단도, 칼꽂이, 붓의 호, 부채들이다. 당시 양반들의 복식과 장신구를 알 수 있는 중요한 자료이다.","a":"학성이씨현령공파절송공묘출토유물","c":"문화유산자료","nc":"","r":"울산광역시","s":"남구","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1659793.jpg"},{"q":"○○ 학동 ○○○는 전주 최씨 문중에서 후손들에게 강학을 하기 위해 세운 서당이다. 1723년(경종 3)에 전주 최씨 집성촌인 학동마을에 후손들의 교육을 위해 초가를 세웠으나 학생 수가 늘어 1845년(현종 11)에 지금의 자리로 옮겨 세웠다. ○○○는 곡저평야에 남향하여 자리 잡고 있다. 주된 건물인 ○○○를 중심으로 맞은편에 대문채가 있고, 좌우에 사랑채와 곳간채가 배치되어 있어 트인 “ㅁ”자형 구조이다. ○○○는 정면 6칸, 측면 1.5칸의 규모이다. 중앙에 마루 2칸, 좌우에 툇마루가 딸린 온돌방 2칸이 각각 배치되어 있다.","a":"고성 육영재","c":"문화유산자료","nc":"","r":"경상남도","s":"고성군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1664340.jpg"},{"q":"통일신라의 학자인 고운 ○○○ 선생의 초상화이다. ○○○은 6두품 출신으로, 12세 때 당나라에 유학을 가 18세 때 빈공과에 합격하였으며, 879년 당나라의 황소의 난 때 『토황소격문』을 지어 그의 문장력을 세상에 알리었다. 유교·불교·도교에 조예가 깊었고 문장력이 뛰어났으며, 이후 ‘문창공’에 봉해졌다. 선생의 초상화는 지리산 쌍계사본과 가야산 해인사본이 있는데, 이 그림은 조선 철종 11년(1860) 경에 해인사본을 옮겨 그린 것으로 추측된다. 신선세계를 배경으로 오른쪽을 바라보고 있는 모습이며, 비단 위에 9가지 색을 이용하여 짙게 채색하였다.","a":"문창후 최치원 영정","c":"문화유산자료","nc":"","r":"대구광역시","s":"동구","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1659483.jpg"},{"q":"이 영정은 ○○○○○의 좌안7분면 바닥가부좌상으로, 왼손에는 불자를 들고, 오른손은 염주를 쥔 채 불자의 술을 만지고 있다. 바닥에 화문석을 깔지 않았고 돗자리를 경계로 배경을 이분화하는 구도를 취하지 않았으므로 이단구도에 선행하는 형식임을 느끼게 한다. 그리고 배경에 문양이 없는 점, 인물이 안정된 삼각형 구도를 갖추지 않고 있는 점, 지물이나 법의의 표현이 도식화되지 않은 점 등으로 보아 통도사 소장의 바닥가부좌상 가운데 비교적 앞선 시기의 작품으로 추정된다. 화면 향우측으로 ‘○○○대선사○○진(花谷堂大禪師誡天眞)’의 화제만이 있을 뿐이다.","a":"화곡당 계천 진영","c":"시도유형문화유산","nc":"","r":"경상남도","s":"양산시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/0000000001643007.JPG"},{"q":"이 책판은 조선 중기의 유학자인 일신당 ○○○의 시문과 년보, 비명, 척록을 후손들이 편집하여 철종 6년(1855) 청곡서원에서 간행한 것이다. ○○○은 남명 조식의 문인으로, 효행으로 널리 알려지기도 했다. 이 문집의 내용에 특별한 역사적 기록은 없으나 년보, 스승과 친구 그리고 당대의 현인들을 기록한 사우제현록, 비명 등 당대의 사정을 보이는 자료가 있다. 서문은 재령 이씨인 이상의가 썼으며, 발문은 풍산 노광리와 이우가 썼으며, 권말에 ‘을묘맹추상한청곡서원개간’이라는 간행기록이 있다.","a":"이천경 일신당문집 및 필첩 목판","c":"시도유형문화유산","nc":"","r":"경상남도","s":"산청군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1642020.jpg"},{"q":"조선 후기 학자인 제산(霽山) 김성탁(金聖鐸, 1684~1747)이 18세기 초에 지어 거주한 살림집이며, 종택 오른편의 우곡초당(雨谷草堂)은 그가 1718년에 건립하여 후학을 양성한 곳이다. 김성탁은 조선후기의 문신이자 뛰어난 문장가로 성리학에 조예가 깊었을 뿐만 아니라 1728년(영조 4) 이인좌의 난 때는 의병을 일으키고 글을 지어 난의 진압에 공을 세우기도 하였다. 종택은 안채 지붕 기와에 새겨진 글(嘉慶 18, 1814)과 현존 건물의 건축양식으로 보아 1814년에 중건하여 지금에 이른 것으로 추정된다.","a":"안동제산종택","c":"시도민속문화유산","nc":"","r":"경상북도","s":"안동시","i":"http://www.khs.go.kr/unisearch/images/folklore_material/thumb/1658880.jpg"},{"q":"남해 ○○○에서 소장하고 있는 이 필사본 전적 2건 5책 (萬年通考 2책, 福田集 3책)은 그 내용으로 보아 18세기 초 (1704년, 肅宗 30년)부터 20세기(1956년) 후반까지 ○○○ 사찰 내의 주지와 간부 승려의 변동사항, 사찰 내의 각종 중요사항, 시주의 명단과 시주물목, 그 밖에 국내의 여러 가지 사건과 행사 등을 기록하고 있어서 1개 특정사찰의 사적(事蹟)기록물로서 뿐만 아니라 지방에서 작성된 역사기록물로서의 사료적 가치 또한 높다고 하겠다.","a":"남해용문사소장문헌","c":"문화유산자료","nc":"","r":"경상남도","s":"남해군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1665132.jpg"},{"q":"○○○○○은 비하동과 지동동의 경계를 이루며 솟아있는 ○○○ 정상을 에워쌓은 포곡식包谷式 석축산성과 그 주변으로 이어지는 능선 상에 3개의 작은 보루성堡壘城으로 구성되어 있다. 『신증동국여지승람』에 “부모성은 주州의 서쪽 15리에 있다. 석축으로 둘레가 2,427척이며, 성안에 큰 연못[大池]이 있는데 지금은 폐성되었다.”라고 기록되어 있으며, 후대의 지리지에는 이러한 내용을 거의 동일하게 기록하고 있다. 본성 성벽의 둘레 2,427척은 포백척(1척=46.73㎝) 준수遵守값으로 환산하면 1,134.1371m이다.","a":"청주 부모산성","c":"시도기념물","nc":"","r":"충청북도","s":"청주시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1650887.jpg"},{"q":"○○○○ 내 안국사 경내 남쪽 축대 아래에 있는 ○○○○에는 인조21년(1643) 이조판서겸 대제학인 이식(李植)이 왕명으로 사고를 순찰하고, 정축란 이후 문란해진 사고의 관리와 성내의 방비를 철저히 하기 위하여 왕에게 진상(秦上)하여 1645년 ○○○○를 창건하게 된 경위가 기록되어 있다. 고종 35년(1898) 간행된 적성지(赤城誌) 고적조(古迹條)에 비문의 전문이 게재되어 있다. 대리석으로 만든 비는 이면비(二面碑)로 전체 높이는 1.78m이다.","a":"적상산성 호국사비","c":"시도유형문화유산","nc":"","r":"전북특별자치도","s":"무주군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1639487.jpg"},{"q":"향교는 공자와 여러 성현께 제사를 지내고 지방민의 교육과 교화를 위해 나라에서 세운 국립교육기관이다. ○○○○는 조선 태종 5년(1405)에 처음 지은 뒤 여러 차례 고쳐 세웠다고 전한다. 현재 이곳에는 ○○○과 명륜당 동재와 서재 등의 건물이 있다. ○○○은 앞면 3칸·옆면 2칸 규모로, 지붕은 옆면에서 볼 때 사람 인(人)자 모양인 맞배지붕이다. 이곳에는 공자를 비롯하여 중국과 우리 나라 성현들의 위패를 모시고 있다. 조선시대에는 나라에서 토지와 노비·책 등을 지원받아 학생을 가르쳤으나, 지금은 교육 기능은 없어지고 제사 기능만 남아 있다.","a":"진잠향교대성전","c":"문화유산자료","nc":"","r":"대전광역시","s":"유성구","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1659697.jpg"},{"q":"이 건물은 전의이씨 다포공파의 입향조 이지화의 아들인 이윤이 1671년(현종 2)에 공부방으로 건립하였다. ○○○은 완만하게 경사를 이루는 지형을 그대로 두고 그 위에 평탄한 기단을 조성하였다. 건물의 전체적인 모습은 T자형으로 전체가 12칸인 기와집이다. 앞부분의 4칸은 마루로 사용하고, 본 건물인 4칸의 방과 측칸으로 이어진 1칸의 누마루가 뒤편에 붙어있다. 당호인 ○○○은 \"구장육지의 에서 따온 것으로 이윤이 후학양성을 위하여 벼슬을 마다하고 은둔하고 있는 모습을 상징적으로 나타낸 것이라고 한다.","a":"고령 장육당","c":"시도유형문화유산","nc":"","r":"경상북도","s":"고령군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/2018101510205700.jpg"},{"q":"한국전쟁 중 UN군에 포로가 되었던 공산군을 수용하던 장소이다. 1950년 11월부터 고현·상동·용산·양정·수월·해명·저산지구 등 360만평에 ○○○○○를 설치하여, 인민군 15만, 중공군 포로 2만, 여자포로와 의용군 3천명 등 최대 17만 3천명을 수용하였다. 이 곳에서 반공포로와 친공포로간의 유혈사태가 자주 발생하였으며, 1952년 5월 7일에는 ○○○ 소장인 돗드 준장이 납치되는 불미스런 사건까지 있었다. 1953년 7월 27일 휴전협정 후 폐쇄되었고, 친공포로들은 판문점을 통하여 북으로 보내졌다.","a":"거제포로수용소","c":"문화유산자료","nc":"","r":"경상남도","s":"거제시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1664043.jpg"},{"q":"대웅전 삼존불 사이 앞쪽에 있는 나무로 만든 3점의 패(牌)이다. 전체적인 만든 방법과 형태는 같으나 부분적으로는 차이를 보인다. 그중 하나는 높이 2.28m로 앞면에 임금의 만수무강을 기원하는 글씨가 있고, 뒷면에는 조선 16대 왕인 인조 때 조성된 것이란 제작연대가 있다. 다른 2점은 높이가 2.08m로 같으며, 뒷면에 정조 16년(1792)에 수리하였음을 검은 글씨로 기록하고 있다. 일반적으로 불·보살의 명칭을 적은 다른 위패들과는 달리 왕, 왕비, 세자로 조성한 2m가 넘는 대작이다. 여러 장의 목판을 엮어서 만든 것으로 구름과 용을 뚫어새긴 것이 특징이다.","a":"송광사목조삼전패","c":"시도유형문화유산","nc":"","r":"전북특별자치도","s":"완주군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1639649.jpg"},{"q":"모전석탑은 전탑(塼塔:흙으로 구운 벽돌로 쌓은 탑)의 양식을 모방한 것으로, 돌로 만든 벽돌을 이용하여 쌓아 올린 탑이다. 이 탑은 원래 교동사터에 남아 있던 것으로, 1946년 수봉초등학교로 옮겨 놓았다가 1995년 이곳 ○○ 향토자료박물관으로 다시 옮겨 세웠다. 1층 기단(基壇)에 5층의 탑신(塔身)을 올린 형태인데, 현재 탑신의 2층과 5층의 몸돌이 없다. 1층 탑신의 몸돌 네 면에는 중앙에 감실(龕室:불상을 모시는 방)을 새겼다. 지붕돌은 아래 ·윗면 모두 전탑에서와 같이 층단을 이루고, 네 귀퉁이에는 풍경을 달았던 구멍이 남아 있다.","a":"음성 읍내리 오층모전석탑","c":"시도유형문화유산","nc":"","r":"충청북도","s":"음성군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1638408.jpg"},{"q":"남해 ○○○○○은 현재 ○○○ 관음전(觀音殿) 법당에 도금되어진 양호한 상태로 봉안되어 있다. ○○○은 고려고찰(高麗古刹)로서 여러 차례 중건·중수되어 왔으며, 남해의 진산인 망운산(望雲山) 정상 아래에 위치한 관음기도도량이다. 여기에 봉안된 이 관음좌상은 정확한 기록은 없으나 8·15 해방을 전후한 시기에 ○○○에 왕래가 많았던 지역 고로(古老)들의 구전에 따르면, 옛적에 경주 옥돌로 조성된 영험 높은 부처님이라 전해왔다는 것이다. 머리에 보관을 쓰고, 양쪽 무릎 위에 두 손을 각각 나란히 두었으며, 오른쪽 발은 군의 바깥으로 노출된 반가부좌의 보살상이다.","a":"남해망운암석조보살좌상","c":"문화유산자료","nc":"","r":"경상남도","s":"남해군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1665023.jpg"},{"q":"고려 말∼조선 초의 인물 ○○○의 무덤으로, 묘 및 상석(床石) 1기, 문인석 2기, 묘비 1기 등이 남아 있다. ○○○는 고려 1372년 출생하였으며 1410년에 종4품 선략장군으로 두모포(豆毛浦)의 관군을 배수받았고, 1419년에는 대마도 정벌에 참가하기도 하였다. 이후 부친의 병환을 돌보기 위해 낙향하였으며, 일흔 일곱인 1448년에 사망하였다. 전체 묘역은 3단으로 구성되어 있다. 상단에는 묘와 상석, 중단의 동·서에는 문인석, 그리고 하단의 동쪽에는 묘비가 배치되어 있다.","a":"밀양 손유호 묘","c":"시도기념물","nc":"","r":"경상남도","s":"밀양시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1657034.jpg"},{"q":"○○○의 원통전에 봉안되어 있는 총높이 42Cm, 어께너비 20Cm, 무릎너비 26.7Cm의 소형불상이다. 큰 얼굴에 편편한 신체, 짧은 목 등 조선후기 불상의 특징을 보이고 있다. 보관은 별도로 만들어 얹었다. 보관은 가운데 화불을 중심에 두고 바탕에는 당초문을 양각하고 화염, 꽃, 새 등을 따로 만들어 끼워 화려하게 장식하였다.","a":"안동 석탑사 목조관세음보살좌상","c":"시도유형문화유산","nc":"","r":"경상북도","s":"안동시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1641139.jpg"},{"q":"조선 중기의 문신인 ○○○李基祚(1595~1653)과 부인 고령 신씨의 무덤이다. ○○○는 광해군 치세 때 문과에 급제하였고, 인조반정 이후에 관직에 본격적으로 나아갔다. 이괄의 난이 일어났을 때 난을 평정하여 국왕의 신임을 받았고, 이후 효종 연간에는 이조판서와 공조판서를 역임하였다. 그가 병으로 죽은 후에 숙종 24년(1698)에 조정에서 ‘충간忠簡’이라는 시호를 받았으며, 숙종 31년(1705)에 신도비를 설치하였다. ○○○ 신도비는 박세채朴世采가 글을 짓고 손자 이명필李命弼이 글씨를 썼으며, 상단의 전서체 글씨는 외손자 신완申琓이 글씨를 썼다.","a":"이기조선생묘","c":"시도기념물","nc":"","r":"경기도","s":"군포시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/2021102814462300.jpg"},{"q":"태조산에 있는 절로, 고려 태조(재위 918~943) 때 도선국사가 처음 세웠다는 설이 있으나 정확하지 않다. 고려 목종 5년(1002)에 담혜가, 1398년에는 조선 태조가 무학대사의 권유로 고쳐 세웠다고 하는데 이 또한 정확하지 않다. 경내의 건물로는 중심 건물인 대웅전을 비롯하여 산신각, 스님들이 생활하는 요사채가 있다. 대웅전에는 불상이 안치되어 있지 않고, 유리창을 통하여 뒷편 암벽에 조각이 완성되지 않은 서있는 모습의 불상을 모시고 있다. 앞면 3칸·옆면 2칸 규모이며, 지붕은 옆면에서 볼 때 여덟 팔(八)자 모양인 팔작지붕으로 꾸몄다.","a":"성불사","c":"문화유산자료","nc":"","r":"충청남도","s":"천안시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1660879.jpg"},{"q":"영동지방의 가뭄, 홍수, 폭풍, 풍작 등을 보살펴 주는 것으로 믿는 여러 신을 모신 곳이다. 서낭당은 이곳 출신이라고 알려진 범일국사(810∼889)를 모셨다고 한다. 범일국사는 통일신라시대 승려로 15세에 출가하였고 중국으로 건너가 제안과 유엄의 문하에 있으면서 깨달음을 얻었다. 그 뒤 귀국하여 후학들을 교육시켰으며 경문왕, 헌강왕, 정강왕이 차례로 국사(國師)로 받들어 모시고자 하였으나 사양하였다. ○○○은 기록에 따르면 장군 왕순식이 고려 태조를 모시고 후백제의 신검군을 정복코자 할 때 두 귀신이 꿈에 나타나 도움을 주어 싸움에 이겼다고 한다.","a":"대관령 성황사 및 산신각","c":"시도기념물","nc":"","r":"강원특별자치도","s":"평창군","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1648194.jpg"},{"q":"제주도의 고인돌은 한반도와는 달리 청동기시대가 아닌 탐라시대에 만들어진 거석문화유산으로 북방식․남방식․개석식(무지석식)으로 구분된다. ○○○고인돌 1호는 ○○○ 1741-1번지 도로변에 있다. 전형적인 남방식고인돌로서 앞쪽에 이중으로 고임돌을 고인 ‘들림형’ 고인돌이다. 뚜껑돌의 형태는 장타원형에 가까운 장방형이며 이중 고임으로 되어 있다. 고인돌의 크기는 장축 315cm, 단축 275cm, 두께 35～75cm이다. 이와 같은 고인돌 형식은 애월읍 광령리 고인돌 무리 중에서도 일부 확인된다. 이 고인돌의 축조시기는 탐라시대 전기(A.D 1～300)년 경이다.","a":"색달동지석묘1호","c":"시도기념물","nc":"","r":"제주특별자치도","s":"서귀포시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1657722.jpg"},{"q":"흥선대원군의 아버지인 남연군의 비이다. 남연군( ? ∼1822)은 조선 인조의 셋째 아들인 인평대군의 6대손 이병원의 아들로, 정조의 이복 동생인 은신군의 양자가 되어 남연군에 봉하여졌다. 죽은 뒤에는 충청도 예산의 덕산지역에 묻혔는데, 고종 5년(1868) 독일인 오페르트에 의해 도굴당하여 흥선대원군의 쇄국정책을 더욱 강화하게 된 계기가 되기도 하였다. 묘 앞에 자리하고 있는 비는 높직한 사각받침 위로 비몸을 세우고 지붕돌을 올린 모습으로, 비 앞면에는 ‘남연군충정’이라는 비의 명칭을 가로로 새겨 놓았다.","a":"남연군비","c":"문화유산자료","nc":"","r":"충청남도","s":"예산군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1661215.jpg"},{"q":"조선 전기 문신인 ○○○ 선생은 본관이 재령(載寧)으로 『동국통감(東國通鑑)』을 편수하는 데 참여했으며, 청백리에 녹선되었다. ○○○○○ 묘는 부인 파평윤씨(坡平尹氏)와 쌍분(雙墳)으로 조성되어 있다. 각 봉분 앞에는 묘표와 석상, 향로석 등이 놓여 있다. 두 봉분 사이에는 우의정(右議政) 허침(許琛, 1444~1505)이 지은 비문을 1956년에 후손들이 그대로 옮겨 세운 건립한 묘비가 있다. 각 봉분 앞의 묘표는 하엽수(荷葉首; 연잎 형태의 비석 머리)로 건립되었다. 봉분 좌우에는 문인석 1쌍이 건립되어 있다.","a":"이맹현선생묘","c":"시도기념물","nc":"","r":"경기도","s":"남양주시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1646484.jpg"},{"q":"현재 전북특별자치도 정읍시 칠보면 ○○○의 작은 암자 안의 법당에 모셔져 있는 불상이다. 무릎 아래는 땅에 묻혀 있으며 땅 위로 드러난 부분도 불단(佛壇)에 의해 상당 부분이 가려져 있다. 불상은 민머리이며 머리에 마치 두건을 쓴 것처럼 보인다. 얼굴은 긴 타원형이며 입은 불룩하게 튀어나오게 조각되었다. 귀는 길어 목부분까지 이어지며, 목은 짧게 표현되어 있다. 목에 있어야 할 3줄의 삼도(三道)는 가슴 부분에 표현되어 있으며, 양 어깨에 걸쳐진 옷자락은 U자형의 주름을 만든다.","a":"무성리석불입상","c":"시도유형문화유산","nc":"","r":"전북특별자치도","s":"정읍시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1639636.jpg"},{"q":"고흥 ○○○○ 해안 ○○○은 ○○○ 선정마을 해안에 위치해 있으며, 길이는 400여 m, 너비는 25m이다. 이 ○○○은 바닷바람으로부터 마을을 보호하기 위하여 마을 사람들이 심은 것이다. 해안 ○○○을 구성하고 있는 나무들로는 이팝나무 50그루, 팽나무 27그루, 검팽나무 24그루, 사철나무 21그루, 느티나무 4그루, 곰솔 5그루, 상수리나무 2그루, 쉬나무 2그루, 감나무 1그루, 멀구슬나무 1그루 등 모두 137그루가 있다. 마을 사람들은 큰 느티나무 주위에 단을 세우고 해마다 정월 대보름에 별신제(제사)를 지내면서 마을의 안녕과 평안을 기원한다고 한다.","a":"고흥월정리의해안방풍림","c":"시도기념물","nc":"","r":"전남광주통합특별시","s":"고흥군","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1654277.jpg"},{"q":"○○○○○은 올의 소격이 많이 벌어져 있는 폭 20.9cm의 비단과 42.4cm의 비단을 꿰매어 만든 비단 바탕 위에 제석천과 권속들을 묘사한 1폭의 탱화이다. 본래 ○○○에는 이 제석신중도와 함께 한 쌍으로 그려진 동진보살을 그린 ○○○ 1폭이 더 있었지만 지금은 이 ○○○ 1폭만 남아있다. 그리고 현재 이 ○○○은 틀의 가장자리 本地들은 절단된 채 화면만 잔존하고 있는 상태이며, 또한 조성연대의 오랜 경과로 색채가 약간 변색되어 있지만 보존상태는 대체로 양호한 편이다","a":"합천 연호사 신중탱","c":"시도유형문화유산","nc":"","r":"경상남도","s":"합천군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1643138.jpg"},{"q":"수릉(조선 헌종 부친인 익종의 묘)의 보호와 향탄(왕릉에 사용하는 목탄)의 생산을 위해 국가에서 지정한 일정구역의 출입을 금하고 있는 일종의 금지푯말이다. 표석은 높이가 낮고 옆으로 넓게 퍼진 자연석을 그대로 사용하였으며, 앞면에 세로로 두 글자씩 ‘○○○○○’라고 새겨 놓았다. 이러한 표석은 이곳 이외에 1기가 더 있는데, 이러한 점으로 보아 이 지역 일대가 봉산으로 지정되었었음을 알 수 있다. 봉산제도는 조선 숙종 때 시작된 것으로 산림훼손의 방지를 위해 구역을 지정한 후 표지석을 세워 출입을 막았던 제도이다.","a":"수릉향탄금계표석","c":"문화유산자료","nc":"","r":"대구광역시","s":"동구","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1659478.jpg"},{"q":"1917년에 세워진 살림집으로 안채와 사랑채, 행랑채보다 지붕을 한단 높여 만든 솟을대문이 남아 있다. ㅡ자형 평면의 안채는 자연석으로 쌓은 기단 위에 사각형의 주춧돌을 놓고 네모기둥을 세웠다. 지붕은 옆모습이 여덟 팔(八)자 모양인 팔작지붕으로 화려하다. 지붕 끝부분 기와에 ‘조선개국오백이십오년병진월십일수부귀남자’라고 새긴 글이 있어 건물의 연대를 알 수 있다. 지붕 네 귀퉁이의 끝에 있는 기와에는 태극의 4괘무늬를 새겨놓았다. 건물이 세워진 연도는 오래되지 않았지만 전통적 건축의 형태를 잘 간직하고 있다.","a":"영동 가곡리 고가","c":"시도유형문화유산","nc":"","r":"충청북도","s":"영동군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1638622.jpg"},{"q":"봉양사 입구에 세워져 있다. 조선 중종조 기묘명현인 신재 ○○○의 행적을 기록하여 놓은 이 비는 1775년(영조 51년)에 세워졌는데 비문은 순천부사였던 김약행(1774.6~1775.12, 재임)이 지었다. 비의 형태는 가첨석이 없으며, 비신과 대좌로 이루어져 있다.","a":"광양신재최산두선생유허비","c":"시도기념물","nc":"","r":"전남광주통합특별시","s":"광양시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1654380.jpg"},{"q":"○○○ 남쪽의 비탈진 소나무숲 속에 나란히 서 있는 2기의 비이다. ‘아○○○○○’는 ○○○○의 행적을 기록해 놓은 비로, 자연 암석을 받침 삼아 그 윗면에 홈을 파서 비를 세우고, 머릿돌을 얹었다. 머릿돌은 앞면에 이무기를, 뒷면에 네 마리의 용을 조각하고 그 사이마다 구름·용을 새겨 장식하였다. 비몸 앞면에는 위쪽에 가로로 전서체로 된 비의 이름을 새겨두고, 그 아래에 세로로 비문을 적었다. 뒷면에는 ‘자운비(慈雲碑)’라는 글씨를 새겼으며, 그 끝에 건립연대를 밝혀두어 조선 효종 6년(1655)에 세운 것임을 알게 되었다.","a":"아도화상사적비및도리사불량답시주질비","c":"시도유형문화유산","nc":"","r":"경상북도","s":"구미시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1640941.jpg"},{"q":"○○○○○의 구성은 상하 2단으로 상단에는 세보살상과 권속들을 배치하고, 하단에는 각종 신중상들을 배치하고 있다. 먼저 상단의 경우, 중앙에 천○○○과 그 좌우에 합장형의 진주·대진주보살을 두고, 그 좌측(향우측)에는 지지보살과 용수·다라니보살이 시립하고, 우측(향좌측)에는 정형의 지○○○상 좌우에 도명과 무독귀왕이 합장하고 있다. 그리고 화면 위쪽에는 천부중, 신중, 명부중 등 제권속들의 상반신만 묘사된 채 화면을 메우고 있다. 화면 하단에는 가운데 동자 2구외에 22구의 신장상이 상하 2열로 배치되어 있다.","a":"남해용문사삼장보살탱","c":"문화유산자료","nc":"","r":"경상남도","s":"남해군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1665135.jpg"},{"q":"(1) 비문의 주인공 ○○○. 자는 자함(子諴), 호는 송계(松溪), 본관은 평산이다. 송당(松堂) 박영(朴英)의 문인이며, 남명(南冥) 조식(曺植)과 매우 절친하였다. 남명과 함께 경상우도의 실천적 선비정신을 대표하는 인물이다. 점필재가 태어난 고을에서 태어나고 자람으로써 자연히 사림파의 학문 자세를 지닌 독행(篤行) 군자가 되었으며, 이로 인해 ○○의 예림서원(禮林書院)에도 배향되었고 김해의 신산서원(新山書院)에도 향사되었다.","a":"밀양 신계성 여표비","c":"문화유산자료","nc":"","r":"경상남도","s":"밀양시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1665778.jpg"},{"q":"경희궁 회상전 북쪽에 지어진 궁술연습을 하던 사정(활터에 있는 정자)이다. 고종 광무 2년(1898) 지어졌으며, 1922년에 지금의 위치로 옮겨졌다. 앞면 4칸·옆면 2칸 규모이며, 지붕 옆면이 여덟 팔(八)자 모양인 팔작지붕집이다. 원래 이 자리는 오사정의 하나인 등과정이 있던 자리이다. 오사정이란 도성 안 서쪽에 세워진 다섯 개의 활터에 세워진 정자로, 옥동의 등룡정·삼청동의 운룡정·사직동의 대송정·누상동의 풍소정·필운동의 등과정이 그것이다. 지금은 오사정이 모두 없어졌으나, 이곳에서는 가끔 궁술행사를 열어 옛 무인들의 기개를 보여주고 있다.","a":"황학정","c":"시도유형문화유산","nc":"","r":"서울특별시","s":"종로구","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1636102.jpg"},{"q":"전북특별자치도 고창군 ○○○의 ○○○ 안에 모셔진 목조금박(木造金箔)의 석가여래좌상과 아난·가섭 협시보살입상이다. 가운데 있는 여래좌상은 신체에 비하여 머리가 크며, 얼굴은 사각형에 가깝다. 목 아래에는 3개의 주름이 좁게 표현되었고, 옷은 양 어깨를 덮고 있으며 옷주름은 간략화되었다. 가슴은 넓으며 가슴 밑에 아랫도리 윗자락이 직선으로 표현되었다. 16각의 난간을 두른 나무로 된 연꽃무늬 대좌(臺座)에 모셔져 있다. 양쪽의 협시보살은 화려하게 장식된 관(冠)을 쓰고, 손에는 연꽃을 들고 있다. 목조이기 때문에 딱딱한 느낌을 주나 목조불로서는 희귀한 우수작이다.","a":"선운사영산전목조삼존불상","c":"시도유형문화유산","nc":"","r":"전북특별자치도","s":"고창군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1639397.jpg"},{"q":"○○○ 1527번지선 동남쪽 경계에 위치하도 있으며 남방식 ○○○형태를 취하고 있다. 뚜껑돌 형태는 장타원형으로 뚜껑돌 북서쪽이 73cm정도 들려있다. 북쪽과 남쪽 모서리에 지석이 고여 있으며, 동서측면에는 덜을 다듬은 치석 흔적이 있고, 뚜껑돌 아래에는 잡석으로 채워져 있다. 장축 290cm, 단축 170cm, 두께 70cm이며 축조시기는 탐라시대 전기 AD 1~300년경이다.","a":"상예동지석묘4호","c":"시도기념물","nc":"","r":"제주특별자치도","s":"서귀포시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1657720.jpg"},{"q":"○○○란 임금이나 고관의 평생업적을 기록하여 무덤가에 세워두는 것으로, 이 비는 조선 중기의 문신인 정황(1512∼1560)의 공적을 기리고 있다. 정황은 조선 중종 31년(1536) 친시(親試)에 합격하여 문원부정자(文院副正字)라는 관직에 올랐고 사간원정언(司諫院正言), 사헌부지평(司憲府持平), 병조형조정랑(兵曹刑曹正郞), 춘추관기주관(春秋館記注官)이 되었으며, 1560년 타계 후 숙종 34년(1708) 이조판서에 추증되었다.","a":"정황선생신도비","c":"시도유형문화유산","nc":"","r":"전북특별자치도","s":"장수군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1639751.jpg"},{"q":"이 집은 고려말의 큰 학자인 이문정(李文挺)이 고향에 내려와 노년을 보낸 곳이다. 공민왕 6년(1357)에 건립했으며, 임진왜란(1592) 때 불 타 없어진 것을 순조 24년(1824)에 후손들이 다시 세운 것으로, 중앙에 방을 두고 사방에 마루를 깐 정자이다. 벼슬을 그만 두고 내려온 이문정은 이곳에서 성리학을 가르치며 많은 제자와 인재를 양성하는 한편, 상소를 통해 잘못된 나라의 정책을 바로잡는 데도 많은 공을 세웠다. 그후 이문정의 학문과 공적을 기리기 위해 황강서원(黃岡書院)에 그의 위패를 모셔두고 제사 지내고 있다.","a":"문학대","c":"시도기념물","nc":"","r":"전북특별자치도","s":"전주시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1653378.jpg"},{"q":"대황사 절터에서 발견되어 구 광주농고터로 옮겼다가 다시 광주역사민속박물관으로 옮겨 보관하고 있다. 8각의 돌기둥 표면에 불상, 대좌(臺座) 등을 간략히 표현하였다. 민머리에는 구멍이 있어 보관(寶冠)을 썼던 것으로 보이며, 타원형의 평판적인 얼굴에서는 토속적인 수호신의 표정이 느껴진다. 돌기둥의 형태를 변형하지 않고 얼굴 너비와 거의 같은 너비로 어깨를 만들어 신체는 위축된 모습을 보여준다. 오른손은 가슴쪽으로 들어 보주(寶珠)같은 것을 쥐고 있으며, 왼손은 배에 대어 옷자락을 잡고 있는데 얼굴에 비해 경직된 모습이고 기법도 떨어져 보인다.","a":"광주십신사지석불","c":"시도유형문화유산","nc":"","r":"전남광주통합특별시","s":"북구","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1637137.jpg"},{"q":"○○○는 임금이나 고관 등의 평생업적을 기록하여 그의 무덤 남동쪽에 세워두는 것으로, 이 비는 고려시대의 문신인 순흥부사 하윤린의 공적을 기리고 있다. 하윤린은 고려 문정공 하시원의 아들이자 문충공 하륜의 아버지이다. 식목도감, 문하록사 등을 역임하였으며, 공민왕 대에는 홍건적의 침입을 당한 군졸과 백성들을 구제하였다고 한다. 비의 형태는 네모난 받침돌 위에 비몸을 세우고, 머릿돌을 얹었다. 특히 비몸 양 쪽에는 화강암 석재가 비몸을 감싸듯 설치되어 있고 머릿돌은 완만한 곡선을 이룬다. 받침과 머릿돌이 단순화되어 있어 당시 시대 양식을 잘 보여준다.","a":"진양 부원군 신도비","c":"시도유형문화유산","nc":"","r":"경상남도","s":"진주시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1641812.jpg"},{"q":"온달산성 건너편 골짜기, ○○군 영춘면과 강원특별자치도 영월군을 잇는 도로변에 있는 거대한 적석 구조물이다. 일명 ‘태조탑’ 또는 ‘태장이 묘’라고도 부른다. 그러나 ‘태장이 묘’라는 이름으로 더 많이 알려져 있다. ‘큰 장군’이라는 뜻을 가지고 있다. 축조 시기는 돌을 쌓은 기술이 신라의 산성 축성법과 같은 것으로 보아 대략 7세기경으로 추정된다. 유적의 정확한 용도는 알 수 없으나 온달 장군의 무덤으로 추정하는 경향도 있고, 고구려시대 무장의 적석총(돌무덤)으로 보는 견해도 있다.","a":"단양 사지원리 방단적석유구","c":"시도기념물","nc":"","r":"충청북도","s":"단양군","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1651373.jpg"},{"q":"고려 충신 양능양을 기리기 위한 서원이다. ○○○○은 조선 태종 2년(1402)에 세웠다고 하며, 고종 5년(1868) 흥선대원군의 서원철폐령으로 폐쇄되었다가 후에 다시 세웠으나 정확한 연대는 알 수 없다. 서원 건물로는 사당만 남아 있다. 사당 안쪽 중앙에 양능양을 모시고 그 외에 고려충신 양주운, 고려 후기 성리학자 김구용, 임진왜란 때 공신인 양대박의 위패를 모시고 있다.","a":"용장서원","c":"문화유산자료","nc":"","r":"전북특별자치도","s":"남원시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1661669.jpg"},{"q":"정국군 박위와 조선 전기 문신 박시를 기리기 위해 세운 건물이다. 박위는 이성계의 위화도회군 때 공을 세웠으며, 대마도를 정벌하는 등 많은 왜구를 물리친 장군이다.","a":"밀양 신남서원 경보당","c":"문화유산자료","nc":"","r":"경상남도","s":"밀양시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1664508.jpg"},{"q":"이 탑은 고려 시대에 유행한 ○○○○으로 3단의 화강암 기단위에 1층의 탑신이 남아 있고 그 위에 점판암으로 만든 옥개석이 다층으로 남아 있으며, 높이는 2.4m이다. 원래 ○○○ 경내에 있었으나 현재는 고령읍내 대가야박물관에 보관되어 있다. 우리나라 석탑은 대부분이 화강석으로 조성된 것이 주류를 이루고 있으나, 고려시대에 들어와서 점판암제(粘板岩制) 소형 석탑이 출현한다. 점판암제의 경우는 육각, 팔각 등 다양한 ○○○○이 나타난다. ○○○의 석탑도 점판암을 연마하여 조성한 소탑이다.","a":"반룡사다층석탑","c":"시도유형문화유산","nc":"","r":"경상북도","s":"고령군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1640463.jpg"},{"q":"작은 구릉의 남쪽 경사면에 있는 백제무덤이다. 1983년 국립부여박물관에서 실시한 발굴조사에 의하면 이 무덤의 구조는 풍화된 자연암반층을 판 후 그 안에 다듬은 화강암 판석으로 내부를 만들고 무덤의 뚜껑까지 완전히 묻히도록 한 굴식돌방무덤(횡혈식석실분)이다. 널길(연도)은 남벽면 가운데 있고 천정은 무덤의 횡단면이 윗면의 모서리를 죽인 6각이 되도록 동서 벽면의 윗부분을 안으로 꺾은 이른바 꺾임천정(평사천장)이다. 널길의 입구는 할석과 흑갈색 부식토로 막아 이중폐쇄하였다. 널방(현실) 바닥에는 크기가 일정하지 않은 납작한 잡돌을 정교하게 귀를 맞추어 깔았다.","a":"부여태양리백제석실고분","c":"시도기념물","nc":"","r":"충청남도","s":"부여군","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1652747.jpg"},{"q":"삼국시대 집단 무덤유적 중 가장 남쪽에 위치하고 있는 김해지역 무덤들이다. 구릉의 정상부와 남쪽사면에는 돌덧널무덤(석곽묘)이, 동·북쪽사면에는 덧널무덤(목곽묘)이 있으며 총 26기가 확인되었다. 대부분의 무덤이 도굴되었으나 비교적 많은 유물이 출토되었다. 철기류는 철도끼·철낫·철투갑창·철손칼·철화살촉이 출토되었다. 특히 15호 무덤에서 무구류와 함께 철제 낚시바늘과 작살이 나왔는데, 우리나라 삼국시대 유적에서 보기 드문 특이한 예이다.","a":"생곡동 가달고분군","c":"시도기념물","nc":"","r":"부산광역시","s":"강서구","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1645178.jpg"},{"q":"지정된 것은 먼저 전적류로 『남종통기』 2책이 있다. 수약당 남제명이 편집한 남종통기는 4권 2책을 배껴쓴 본으로, 이 책은 남씨 일가의 족보와 그 역사를 담은 『남씨세보』를 집대성환 기록이며 영락년간(1403∼1424)의 호적도 보인다. 특히 「보중취동성변문 풍기남두원」과 「신구보세계변의문 풍기남두원」은 같은 성씨간의 결혼문제에 대하여 남씨 뿐 아니라 다른 성씨까지 역사적으로 고찰한 중요한 문헌자료라 할 수 있다.","a":"영해난고종가문서","c":"시도유형문화유산","nc":"","r":"경상북도","s":"영덕군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1640565.jpg"},{"q":"이 유고는 초려 ○○○가 영변에 유배되어 있을 때 쓴 가훈이다. ○○○는 김장생, 김집의 문인으로 특히 예학에 뛰어나 김집과 함께「상례비요」,「의례문해」등을 교감했다. 그는 효종 때 학행(學行)으로 천거되어 벼슬살이를 시작하였고 1674년(현종 15) 갑인예송 때 남인 윤휴 등의 탄핵을 받아 다음 해 영변에 유배되었다가 1680년 경신대출척 이후 풀려났다. 서명(書名)은 우측 제첨에 『家庭遺訓 單』으로 되어 있고, 표지 중앙 붉은 색의 첨지에「草廬先生 手冩 戊午閏三月日」이라 되어 있으며, 총 책수 표시에는 '全'이라 되어 있고 표지는 푸른색이다.","a":"초려이유태유고","c":"시도유형문화유산","nc":"","r":"대전광역시","s":"유성구","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/2023031514320300.JPG"},{"q":"언제 지어졌는지 정확히 알 수는 없지만, 고운 최치원 선생이 함양태수로 있을 때 이 누각에 자주 올랐다 하여 학사루라 불리었고 통일신라시대에 지은 것으로 추정된다. 원래는 관아에 딸린 건물로 옆에 객사가 있었고, 동쪽에는 제운루, 서쪽에는 청상루, 남쪽에는 망악루가 있었다고 전한다. 지방관리가 피로한 마음을 풀기 위하여 이곳에 올라 시를 짓고 글을 쓰며 몸과 마음을 달래던 곳으로 알려져 있다. 조선 숙종 18년(1692)에 다시 지었다고 전하며, 1979년에 지금의 위치인 함양군청 정문 앞에 옮겨 지었다.","a":"함양학사루","c":"시도유형문화유산","nc":"","r":"경상남도","s":"함양군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1641549.jpg"},{"q":"○○○란 충신·효자·열녀 등의 언행과 정신을 기리기 위하여 그들이 살던 마을의 입구에 세우는 비로, 이 비는 임진왜란 때 활약한 ○○○의 충절을 기리고 있다. 임진왜란이 터지던 당시 사근도찰방을 맡고 있던 ○○○는 후퇴를 하는 도중 상주 지역 순변사 이일의 수하에 들어갔다. 그 후 상주판관 권길과 함께 왜군과 싸우다 상주 북천전투에서 장렬히 전사하였다. 숙종 1년(1675) 충신으로 임명되고, 정조 14년(1790) 이조참의, 고종 8년(1871) 이조판서에 증직되었다. 비는 비각 안에 보존되어 있으며 비문에는 ‘충신○○○지려’라 새겼다.","a":"김종무충신정려비","c":"시도기념물","nc":"","r":"경상북도","s":"구미시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1654628.jpg"},{"q":"충청남도 아산시 영인면 ○○○의 인적이 드문 산기슭에 있는 ○○○로, 넓고 판판한 화강암에 불상을 조각하였다. 높이 215㎝, 어깨 너비 106㎝이다. 머리에는 둥글고 큰 관(冠)을 쓰고 있는데, 일반적인 갓을 모방한 것 같다. 눈과 눈썹은 귀가 있는 부분까지 길게 조각되어 있으나 입은 이에 비해 작게 표현하여 엄숙한 인상을 풍긴다. 목에는 3줄의 삼도(三道)가 뚜렷하고, 옷은 양 어깨에 다 걸치고 있다. 목에 길게 걸려 있는 목걸이를 오른손이 가볍게 잡고 있다. 불상이라기보다는 스님의 형태에 가까우며, 민간 신앙의 측면에서 미륵정토를 기원하며 만든 것으로 보인다.","a":"영인신현리미륵불","c":"문화유산자료","nc":"","r":"충청남도","s":"아산시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1661289.jpg"},{"q":"임란 후에 간행된 경전 7책중 하나로, ○○○○○, 간집록, 대방광불화엄경소초 권34, 경덕전등록 권22~24, 대방광원각수다라요의경 권6, 묘법연화경 권1,2 이다. 각수를 적어놓은 형태나 어미 모양 등 지방 사찰에서 간행된 목판본의 형태와 판본류를 확인해 볼 수 있으며 조선후기 각 지방의 경전 간행의 경향을 알 수 있는 중요한 자료로 인정됨","a":"십지경론(하) 난승지 제5권 7~ 법운지 제10권 12","c":"시도유형문화유산","nc":"","r":"경상남도","s":"김해시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/0000000001643182.jpg"},{"q":"전교비는 왕의 명으로 이 지역 주민들의 세금을 면하게 해준 사실을 기념하기 위해 세운 비이다. 구 금구현의 일북면과 하서면·초처면 일대는 매년 비만 오면 인근지방의 물이 모두 이곳으로 흘러들어 다리가 떠내려가는 등 고통이 심했다. 또한 관가의 폐단으로 오히려 더 많은 세금이 거치자 이에 왕이 명을 내려 숙종 16년(1680) 이곳에 교지를 내려 세금을 면하게 하였다. 옆에 있는 또 하나의 비는 세금을 거두었던 사감을 내쫓고 폐단을 척결한 현령 이순익에 대한 감사의 뜻으로 주민들이 세운 것이라고 한다.","a":"김제전교비","c":"시도유형문화유산","nc":"","r":"전북특별자치도","s":"김제시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1639466.jpg"},{"q":"○○○는 경상남도 유형문화유산 300호로 지정되어 있는 옥계(玉溪) 노진(盧禛, 1518~1578)의 ○○○와 같은 영역(瑩域)의 상부에, 남향으로 안장된 ○○○ 노우명(盧友明, 1471~1523) ○○의 쌍분 묘체(墓砌) 바로 아래의 동쪽에 위치하고 있는데 서향으로 서 있으며, ○○는 각각의 분묘 정면에 남향으로 서 있다. ○○○의 두전(頭篆)은 증이조판서노공○○○명(贈吏曹判書盧公神道碑銘)이며, 비제(碑題)는 유명조선국 종사랑행현릉참봉 증자헌대부이조판서 겸지의금부사 노공○○○명병서(有明朝鮮國從仕郞行顯陵參奉贈資憲大夫吏曹判書兼知義禁府事盧公神道碑銘幷序)로 되어 있다.","a":"함양 평촌리 신고당 신도비 및 부부 묘표","c":"시도유형문화유산","nc":"","r":"경상남도","s":"함양군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1643231.jpg"},{"q":"○○○○○ 절터의 동쪽 암반 위에 동서로 서 있는 2기의 탑으로, 무너져 있던 것을 1997년에 복원해 놓았다. 서로 같은 양식을 하고 있어서, 2층 기단(基壇) 위에 3층을 이루는 탑신(塔身)을 올린 일반적인 모습이다. 위·아래층 기단에는 모두 기둥 모양을 새겼으며, 특히 아래층 기단에는 안상(眼象)을 얕게 새겨 놓았다. 탑신의 각 몸돌에도 기둥 모양의 조각을 두었다. 지붕돌은 네 귀퉁이가 경쾌하게 치켜올라 갔으며, 밑면에 4단의 받침을 두었다.","a":"보은 속리산 금강골 쌍탑","c":"시도유형문화유산","nc":"","r":"충청북도","s":"보은군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1638720.jpg"},{"q":"○○○○○는 1기로서 두동면 ○○○ 비조마을 회관 옆에 위치하고 있다. 덮개돌은 화강암으로 비스듬히 뉘어 있으며, 네모꼴에 가까운데 크기는 길이 260㎝, 너비 185㎝, 두께 120㎝정도이다. 덮개돌 아래에는 사람머리보다 조금 큰 받침돌이 확인되어, 바둑판식 ○○○로 추정된다. 덮개석의 상부에는 성혈과 같은 흔적은 발견되지 않았으며, ○○○ 부근에서 돌도끼 한점이 출토되었다고 주민들은 전하고 있다. 이 ○○○○○는 울산광역시 기념물인 은편리 ○○○군과 함께 청동기시대 두동 지역의 정치·사회·문화 등을 연구할 수 있는 중요한 자료가 된다.","a":"만화리지석묘","c":"시도기념물","nc":"","r":"울산광역시","s":"울주군","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1645901.jpg"},{"q":"○○○○○는 ○○○성(北漢山城) 내에 있는 누각(樓閣; 사방을 바라볼 수 있도록 지은 건물)인 ‘산영루(山映樓) 터’이다. 산영루가 언제 지어졌는지는 정확히 알 수 없으나, 1603년에 지어진 이정구(李廷龜)의 『유삼각산기(遊三角山記)』에 처음으로 ‘산영루 옛터’가 기록된 것으로 보아, 그 이전에 설립되었음을 추정해 볼 수 있다. 이후 산영루는 여러 차례 불타 없어졌다가 수리되었다. 1925년 대홍수 때 소실되어 초석만 남았다가, 2014년 ○○시에서 ‘○○ 600년 역사복원사업’을 진행하면서 복원되었다.","a":"고양 북한산 산영루지","c":"시도기념물","nc":"","r":"경기도","s":"고양시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/2536357.jpg"},{"q":"지석묘는 청동기시대의 대표적인 무덤으로 고인돌이라고도 부르며, 주로 경제력이 있거나 정치권력을 가진 지배층의 무덤으로 알려져 있다. 우리나라의 고인돌은 4개의 받침돌을 세워 돌방을 만들고 그 위에 거대하고 평평한 덮개돌을 올려놓은 탁자식과, 땅 속에 돌방을 만들고 작은 받침돌을 세운 뒤 그 위에 덮개돌을 올린 바둑판식으로 구분된다. 북으로는 해발 600m의 덕대산 기슭이 감싸고 남으로는 낙동강이 흐르고 있는 경상남도 ○○시 하남읍 ○○○에 40여 기의 고인돌 무리가 있다.","a":"밀양 남전리 지석묘군","c":"시도기념물","nc":"","r":"경상남도","s":"밀양시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1654971.jpg"},{"q":"충청남도 천안과 온양간의 국도 남쪽에 있는 해발 250m의 성재산 정상부를 테를 맨 모양으로 돌을 둘러쌓아 만든 산성이다. 성의 길이는 약 1500m이며, 성벽은 대부분 무너져 돌무지로 보이나 성의 남쪽에 15m 정도의 성벽이 남아 있다. 두께 12m, 길이 0.5m 정도의 자연할석을 이용하여 성벽을 쌓았고, 안쪽에 석재·잡석을 이용하여 너비 3∼4m를 길이모쌓기(돌의 길이가 표면에 나타나게 가로 쌓는 일)로 하였다. 하단에서 상단으로 갈수록 약간 안쪽으로 경사지게 쌓았는데, 복원한다면 높이는 5∼6m 정도로 추정된다.","a":"배방산성","c":"시도기념물","nc":"","r":"충청남도","s":"아산시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1652796.jpg"},{"q":"충청북도 ○○시 덕산면 와룡산의 ○○○ 응진전에 모셔진 관음보살상이다. 사찰에 1920년대에 제작한 중수 기록이 있는데, 이 기록에 의하면 신라말 고려초에 도선국사가 창건한 절로 나타난다. 그러나 절에서 발견되는 기와조각, 청자조각 등은 고려와 조선의 유물들이어서 확실하지 않다. 응진전에 모셔진 관음보살상은 조선 중기에 만든 것으로 추정된다. 머리에 매우 정제된 보관(寶冠)을 쓰고 있으며, 얼굴과 몸체의 각 부분도 균형미가 보인다. 다만 양 어깨가 위축되고 턱이 크게 숙여지는 등의 모습이 드러나는데, 이는 조선 후기의 불상 양식을 지닌 탓이다.","a":"제천 고산사 석조관음보살좌상","c":"시도유형문화유산","nc":"","r":"충청북도","s":"제천시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1638698.jpg"},{"q":"여타의 고승 진영 작품과 비교해 19세기 초반의 작품으로 추정된다. 배경의 산수 처리기법이 원형 화문으로 시문된 점은 독특하며 민화적인 요소가 엿보이는 작품으로 향후 고승 진영이나 민화, ○○○ 연구적 자료 가치가 있다. 이 ○○○은 일명 나반존자라고도 칭하며 미래에 사바세계에 출현할 미륵존불을 기다리며 천태산상에서 독수선정에 들어 있는 독성을 묘사한 불화이다. 화기에 연화질의 명기를 생략한 상태를 보아 지장시왕탱 조성과 동시에 조성된 것으로 추정되며, 이는 1855년(咸豊 5년)의 작품으로 보인다.","a":"남해 화방사 독성탱","c":"문화유산자료","nc":"","r":"경상남도","s":"남해군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1666676.jpg"},{"q":"○○○는 신라 선덕여왕 12년(643) 자장율사가 지었고 흥덕왕 때 진산조사가 다시 지었다. 임진왜란으로 불타버리기 전에는 경기도와 충청도 지방에서 가장 큰 절 중 하나였다고 한다. 임진왜란 후 대웅전과 ○○○을 다시 지었다고 하는데 지금 있는 ○○○은 옛 건물을 1975년에 완전히 해체하여 복원한 것이다. 앞면 5칸·옆면 3칸 규모로 지붕은 옆면에서 볼 때 여덟 팔(八)자 모양인 팔작지붕이다. 지붕 처마를 받치기 위해 장식하여 만든 공포는 기둥 위과 기둥 사이에도 있는 다포 양식으로 꾸몄다. 안쪽에는 목조비로자나불을 중심으로 좌우에 가섭과 아난존자를 모시고 있다.","a":"광덕사 천불전","c":"문화유산자료","nc":"","r":"충청남도","s":"천안시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1661306.jpg"},{"q":"경상북도 경주시 내남면 백운암(白雲庵) 동편의 침식골에 있는 이 불상은 현재 머리 부분이 없어졌으나 나머지 부분들은 대체로 잘 남아 있다. 불상의 목에는 3줄의 주름인 삼도(三道)가 선명하게 표현되어 있다. 오른쪽 어깨를 드러내고 왼쪽 어깨에만 걸친 옷에는 계단식의 옷주름이 새겨져 있다. 왼손은 손바닥을 보이며 배에 대고 있고, 오른손은 무릎 위에 얹었는데 손등이 보이면서 손끝은 땅을 향하게 하고 있다. 대좌는 상대·중대·하대의 세부분으로 이루어져 있다. 상대에는 위로 향한 연꽃잎이 새겨져 있고, 중대는 8각형으로 아무런 무늬가 없다.","a":"경주침식곡석불좌상","c":"시도유형문화유산","nc":"","r":"경상북도","s":"경주시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1640452.jpg"},{"q":"○○는 타악기의 일종으로 반자(飯子)나 금구(金口) 또는 정고(鉦鼓)라고도 부르며 용도는 불교의식에 사용되었으며 사찰의 종루나 당(堂) 앞 처마에 걸어두고 쳐서 울리는 불구(佛具)의 하나이다. <○○○○○ 청동○○>는 아산 신수리에서 출토되었다고 전해지고 있다. 명문은 없으며 앞면은 당좌구, 중구, 외구의 3부분으로 구획되어 있고, ○○의 규모는 36.7x9.2cm이다. ○○ 중앙 당좌구에 연꽃 열매가 있는 부분은 지름 8cm이고, 연꽃잎사귀는 4cm이다. 그 다음 중구는 4cm, 외구는 3cm이다.","a":"온양민속박물관 소장 금고","c":"시도유형문화유산","nc":"","r":"충청남도","s":"아산시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1639336.jpg"},{"q":"고려말 조선초의 무신 양정공(襄靖公) ○○○ 장군의 묘이다. 태종 2년(1402) 무과에 급제한 후 많은 관직을 역임하였는데, 특히 15년간이나 북방의 국경지대에 머물면서 오랑캐를 평정하여 변경 지방의 경비에 힘썼다. 성품이 너그럽고 활을 잘 쏘았으며, 군사정비를 위하여 많은 공을 세워 국가의 기틀을 견고하게 하는데 크게 기여하였다. 봉분 주위는 반달 모양으로 두둑하게 흙을 둘러 쌓았고, 봉분 아랫부분에는 긴 둘레석을 둘렀다. 조선 초기 묘의 특징을 잘 간직한 사각형의 묘이다.","a":"진주 하경복 묘","c":"시도기념물","nc":"","r":"경상남도","s":"진주시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1654996.jpg"},{"q":"천태산에 위치한 이 사찰(寺刹)은 통일신라 후기에 창건된 것으로 추정되며 고려 명종때인 12세기에 원각국사에 의해 중창이 있었던 것으로 추정된다. 고려(高麗) 고종(高宗)때에는 금당(金堂)을 건립하고 국청사(國淸寺)라 하였다고 전한다. 그 후 공민왕(재위1351∼1374) 때 홍건적의 침략을 피하여 이곳에서 나라의 안정과 국민의 평안을 기원하였으므로 이름을 ○○○라 고쳤다고 한다. ○○○은 석가모니불상을 모시는 법당으로, 앞면 3칸·옆면 2칸 규모이며，지붕 옆면이 사람 인(人)자 모양인 맞배지붕집이다.","a":"영동 영국사 대웅전","c":"시도유형문화유산","nc":"","r":"충청북도","s":"영동군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1638477.jpg"},{"q":"○○○는 청동기시대의 대표적인 무덤으로 고인돌이라고도 부르며, 주로 경제력이 있거나 정치권력을 가진 지배층의 무덤으로 알려져 있다. 우리나라의 고인돌은 4개의 받침돌을 세워 돌방을 만들고 그 위에 거대하고 평평한 덮개돌을 올려놓은 탁자식과, 땅 속에 돌방을 만들고 작은 받침돌을 세운 뒤 그 위에 덮개돌을 올린 바둑판식으로 구분된다. 충청남도 부여군 초촌면 ○○○의 ‘바우재’또는 ‘쇠울’이라 불리우는 구릉에 동서로 2기의 고인돌이 나란히 있다.","a":"부여산직리지석묘","c":"시도기념물","nc":"","r":"충청남도","s":"부여군","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1652731.jpg"},{"q":"○○○는 횃불과 연기를 이용하여 급한 소식을 전하던 옛날의 통신수단을 말하며, 높은 산에 올라가서 불을 피워 낮에는 연기로 밤에는 불빛으로 신호를 보냈다. 이 유적은 서생포 방면의 군사 정보를 중앙으로 알 리는 옛 통신시설의 하나로 낮에는 연기, 밤에는 불빛으로 신호하되 일정하게 조직된 봉수망을 따라 전달되었다. 불빛과 연기의 숫자에 따라 위급한 정도가 정해져 있었고 비나 궂은 날씨로 신호가 불가능하면 ○○○를 지키던 군사가 뛰어가서 다음 ○○○에 알렸다.","a":"기장 아이봉수대","c":"시도기념물","nc":"","r":"부산광역시","s":"기장군","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1645131.jpg"},{"q":"이 작품은 현왕을 중심으로 11존의 권속이 원형으로 둘러 서 있으며, 권속들은 좌우대칭 구도를 이룬다. 흰 바탕 위에 담묵으로 산수를 그린 4곡병 앞에 현왕은 의자 등받이에 흰색 천이 덮인 의자를 뒤로 하고 목리문이 그려진 넓은 탁자위에 반가좌의 자세로 앉아 있다. 오른손은 오른쪽 무릎 위에 두고 왼손은 가슴 위까지 들어 홀을 가볍게 쥐고 있는 모습으로 일반적으로 탁자가 놓인 의자에 앉아 권속들과 망자를 심판하는 광경을 묘사하고 있는 것과는 차이가 있다.","a":"남해용문사현왕탱","c":"문화유산자료","nc":"","r":"경상남도","s":"남해군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1666109.jpg"},{"q":"영조가 온양의 온궁에 행차하였을 때, 함께 따라온 장헌세자(사도세자)가 무술을 연마하던 곳이다. 세자는 이를 기념하고자 온양군수 윤염에게 세 그루의 느티나무를 심도록 하였고, 이후 아들인 정조가 왕위에 오른지 19년만인 1795년에 온양군수 변위진과 충청도 관찰사 이형원에게 명하여 이곳에 대를 만들도록 하였다. 대의 옆에 공사가 끝난 후 그 간의 과정을 기록한 비를 함께 세웠는데, 앞면에 새긴 ‘○○○비’라는 비의 명칭은 정조가 친히 써서 내려준 글씨이다.","a":"영괴대","c":"문화유산자료","nc":"","r":"충청남도","s":"아산시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1661271.jpg"},{"q":"○○○는 조선 중종(재위 1506∼1544) 때 병조판서를 지낸 금헌 이장곤 선생의 제사를 지내는 건물이다. 이장곤 선생은 조선 전기의 문신으로 죽은 뒤 ○○의 영암서원에서 제사를 모셨으나, 흥선대원군의 서원철폐령으로 영암서원도 사라지게 된다. 원래 ○○○는 용흥사의 부속건물이었던 것을 1966년 이곳으로 옮겨 지어 이장곤 선생의 제사건물로 삼은 것으로 보인다. 건물은 앞면 4칸·옆면 2칸 규모로 지붕은 옆에서 보면 여덟 팔(八)자 모양의 팔작지붕으로 대청과 온돌방시설이 갖추어져 있다. 방의 출입문은 기능적인 면과 장식적인 면 모두를 갖춰 아주 실용성이 돋보인다.","a":"창녕 금호재","c":"시도유형문화유산","nc":"","r":"경상남도","s":"창녕군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1642089.jpg"},{"q":"조선 명종 때의 문신인 ○○○을 기리기 위해 1560년(명종 15)에 건립한 비이다. 본관은 청송이고 호는 보암(保庵)이다. 1551년 영의정에 올랐으며 청천부원군(靑川府院君)에 진봉되었다. 명종의 묘정(廟廷)에 배향되었다. ○○○는 묘역의 아래에 위치하고 있으며 귀부이수(龜趺螭首) 양식을 갖추고 있다. 귀부(龜趺 ; 거북 모양의 받침돌)의 귀갑(龜甲 ; 거북 껍데기)과 그 위에 얹은 연잎 모양의 복련(覆蓮)은 볼륨 있게 조각한 반면, 귀두(龜頭 ; 거북 머리)는 간략히 표현하였다.","a":"심연원신도비","c":"시도유형문화유산","nc":"","r":"경기도","s":"김포시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1637640.jpg"},{"q":"본 작품은 아무런 손상 없이 완형으로 박물관내에 소장되어 있는데 복장물이 흩어져 없어졌다는 점은 다소 아쉬운 점이다. 그나마 1738년 불상중수기와 1796년 불사개금기의 기록 일부가 남아 있어 석조지장반가상은 적어도 18세기 전반이전에는 제작된 것으로 추정해 볼 수 있었다. 또한 양식적인 면에서 본다면, ○○○ 지장보살반가상은 바람에 날리는 듯한 천의자락이 딱딱하고 경직되어 있는데 반해 이와 같은 형태로서 연대가 이른 1666년 보은 법주사 관음상과 비교하면 천의 자락이 힘이 있으면서 유려하여 시기성을 반영한다고 할 수 있다.","a":"밀양 표충사 석조지장보살반가상","c":"시도유형문화유산","nc":"","r":"경상남도","s":"밀양시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1643069.jpg"},{"q":"○○○○○은 고려 초 ○○한씨 시조인 한란韓蘭이 농사를 권장하기 위하여 지은 정자이다. 창건 이후 오랜 세월이 지나 허물어져 옛터만 남아 있던 것을 1949년에 후손들이 중건하였으나, 한국전쟁 때 소실되었고 1988년에 다시 복원하였다. ○○ 시내에서 보은 쪽으로 가다 방서사거리의 왼쪽 언덕 위에 위치하고 있다. 현재 ○○○ 주변은 공원으로 조성되어 숲이 우거지고, 앞으로는 무심천과 용평뜰이 한눈에 들어오는 전망이 좋은 입지조건을 가지고 있다.","a":"청주 무농정","c":"시도기념물","nc":"","r":"충청북도","s":"청주시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1650159.jpg"},{"q":"전라남도 광양시 옥룡면에 있는 산성으로, 6개의 산봉우리를 아우르며 성 안으로 계곡을 품고 있다. 이곳은 백운산 중턱의 한재를 중심으로 구례·남원·하동·화개로 통하는 교통의 요충지이다. 산 전체가 천연적인 요새로 흙을 쌓아 만든 토성인데, 단순히 흙을 쌓아올린 것이 아니고, 일정한 두께로 흙을 다져 쌓았다. 외성은 길이가 약 4㎞ 정도로 매우 길며, 외성 안쪽에 약 240m에 이르는 내성을 흙으로 쌓았다. 중흥사 입구 세심정에 남문, 옥룡면 추산리로 넘어가는 오솔길에 북문터가 남아 있다.","a":"광양중흥산성","c":"시도기념물","nc":"","r":"전남광주통합특별시","s":"광양시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/2019052017560800.jpg"},{"q":"마이산 도립공원 남쪽 입구 좌측에는 ＇주필대(駐필臺)＇라는 각자가 새겨진 암벽과 그 윗부분에는 1907년 호남의병창의동맹단의 집결지로서 황단(皇壇)터가 있으며 그 하단부에는 ○○○라는 사당이 자리하고 있다. 주필대는 태조 이성계가 왜구를 무찌르고 개선하던 중에 머물렀던 곳으로 전하고 있으며, ○○○는 면암(勉菴) 최익현선생의 제자이자 고종의 스승인 연재(淵齋) 송병선의 제자들이 친친계(연재 제자모임), 현현계(면암 제자모임)를 구성한 후 건립한 곳으로서 회덕전(懷德殿), 영광사(永光祠), 영모사(永慕祠), 대한광복기념비 등이 위치하고 있다.","a":"이산묘","c":"시도기념물","nc":"","r":"전북특별자치도","s":"진안군","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1653831.jpg"},{"q":"○○○○○는 옛 나루터 마천(磨川, 득량면 해평리 일원)에 1674년(현종 15) 7월 완공한 돌다리의 건립을 기념한 비석으로 현재는 석교의 흔적을 찾을 수 없다. 석교 건립은 ○○ 개흥사 계수스님에 의해 주도되었다. 비석의 오른쪽 부분에는 건립 과정, 왼쪽 부분에는 건립에 참여한 사람의 명단을 기록하였다. 또한 건립 연대, 건립 주체, 건립 배경과 과정 등을 자세히 기록되어 있어 유례가 드문 17세기 교량 관련 기록 유산이다. ○○○○○는 오봉사 득량천 해평교 옆에서 두 동강이 난 채 발견되었으며 즉시 면사무소로 옮겨 비를 세우고 접합하여 보관하고 있다.","a":"보성 마천석교비","c":"시도유형문화유산","nc":"","r":"전남광주통합특별시","s":"보성군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/2019041914594800.jpg"},{"q":"괴암절벽 위의 아담한 정자가 있던 터이다. 고려 전객사령 김영이가 벼슬을 버리고 사위 한성판윤 장비와 함께 고향에 내려와 수석이 아름다운 경치를 시로 읊으며 여생을 즐겁게 하고 마음을 고결하게 하였던 곳이라 하여 자손이 그 곳에 정자를 세우고 ‘빙옥정(氷玉亭)’이라 하였다. 고려 후기 몽고군이 침입하여 국가의 기강이 무너지자, 국사를 바로잡을 길없는 뜻있는 선비들이 벼슬을 버리고 고향으로 내려와 숨어지내는 일들이 많았다.","a":"영동 김영이・장비 단소","c":"시도기념물","nc":"","r":"충청북도","s":"영동군","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1650232.jpg"},{"q":"부인사 한켠에 자리하고 있는 승려의 사리탑이다. 통일신라시대 이후 가장 많이 사용된 양식으로, 4각의 바닥돌 위에 올려진 각 부분이 모두 8각의 평면을 기본으로 삼고 있다. 상 ·중 ·하 세 부분으로 이루어진 기단(基壇)은 아래받침돌의 윗면에 연꽃을 두르고, 옆면에는 4마리의 사자상을 도드라지게 새겼다. 가운데받침돌은 4면에 꽃무늬를 장식하고, 나머지면에는 동물상과 동자상을 두었다. 윗면이 넓게 퍼진 윗받침돌은 연꽃을 새겨 둘러 놓았다.","a":"부인사부도","c":"시도유형문화유산","nc":"","r":"대구광역시","s":"동구","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1636888.jpg"},{"q":"○○○○○들은 울릉도를 순찰하는 수토사들의 접대를 위해 소요되는 각종 경비를 전담했던 구산동민들의 요청에 따라 부담을 경감할 수 있는 방책에 대해 관아(평해군)에서 결정해준 내용의 완문(完文)과 절목(節目)이다. 완문(完文)의 크기는 가로 27.5× 세로 29cm이다. 수토절목(搜討節目)의 크기는 가로 33× 세로 42.1cm이다. 완문과 수토절목의 내용을 살펴보면, 삼척진영 사또와 월송만호가 3년에 한 번씩 울릉도를 수토할 때 평해 구산리(구산항)에서 출발하는데 바람의 형편에 따라 머무는 기간이 길어지기도 하였다.","a":"울진 대풍헌 소장 문서","c":"문화유산자료","nc":"","r":"경상북도","s":"울진군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1663597.jpg"},{"q":"시종면 ○○○ 본촌마을 북쪽에 있는 구릉의 능선을 따라 분포되어 있는 3기의 고분으로, 각각 말무덤, 장수무덤, 마부무덤으로 불리고 있는데 일제강점기에 모두 도굴되었다. 1호분은 말무덤으로 불리는 것으로, 본촌마을에서 북쪽으로 250m 정도 떨어진 구릉의 정상부에 있다. 분구는 비교적 양호한 상태로 남아있지만 서남쪽에 풍산홍씨(豊山洪氏) 선산이 만들어지면서 다소 변형되었다. 분구의 평면형태는 원형이며 규모는 직경 15m, 높이 1.8m 이다. 2호분은 1호분에서 남쪽으로 150m 정도 떨어져 있는 것으로, 장수무덤으로 불리는 것이다.","a":"영암금지리본촌고분군","c":"문화유산자료","nc":"","r":"전남광주통합특별시","s":"영암군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1662258.jpg"},{"q":"○○○○○ 석탑은 삼릉계(三陵溪) 정상에서 서북쪽으로 약 1.3km를 이어져 내려와 ○○○ 본류와 합쳐지는 한 지류인 계곡 안에 절터가 있고 그 남쪽에 위치한다. 《東京雜記》에 “바둑바위는 금오산에 있다. 바둑판 모양으로 깎은 돌이다. 이곳은 옛날 신라 때 신선들이 모여서 바둑을 두면서 놀던 곳이다.”라는 기술이 있다. 이 골짜기 아래 마을 사람들은 이곳을 ‘장구터’라고 하였으나, 일제강점기 때 일본인들에 의하여 ‘○○○’이라 불리면서 지금까지 그렇게 불린다.","a":"경주남산 포석계 기암곡 제2사지 동삼층석탑","c":"문화유산자료","nc":"","r":"경상북도","s":"경주시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1663753.jpg"},{"q":"보백당 김계행(1431∼1517)이 말년에 독서와 사색을 위해 지은 정자이다. 김계행은 조선 전기의 청렴결백한 관리로 뽑혔던 분으로, ‘내 집에 보물이 있다면 오직 맑고 깨끗함 뿐이다.’라는 가르침을 남겼다. 규모는 앞면 3칸·옆면 2칸이며, 앞면을 마루 형식으로 개방하여 자연경관을 감상할 수 있도록 하였다. 양쪽에는 온돌방을 두어 학문의 공간으로 활용하였다. 16세기 초에 지은 이 정자는 자연과 조화를 이루는 아름다움을 보여주고 있으며, 특히 그 아래 떨어지는 폭포는 장관을 이룬다.","a":"만휴정","c":"문화유산자료","nc":"","r":"경상북도","s":"안동시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1662748.jpg"},{"q":"○○○○○은 ○○시와 순천시의 경계를 이루는 신대마을에 2개군, 순천에 1개군이 있다. 왕바위재에 있는 6기의 고인돌들 중 가장 큰 것은 덮개돌의 길이가 8.65m나 된다. 이곳에서 500m 떨어진 곳에 위치한 고인돌들은 율촌분교 앞 논 사이에 21기가 원형을 이루고 있다. ○○ 지역에서 집중적으로 출토되는 비파형 동검, 옥과 더불어 강력한 권력과 경제력이 존재했음을 증명하는 유적이다.","a":"여수 산수리 지석묘군","c":"시도기념물","nc":"","r":"전남광주통합특별시","s":"여수시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1654385.jpg"},{"q":"○○○○○는 선조 26년(1593) 6월 29일, 임진왜란 제2차 진주성 전투에서 진주성이 함락되고, 7만 민관군이 순절하자 나라의 원수를 갚기 위해 왜장을 끌어안고 순국한 논개의 사적을 기록한 비석이다. ○○○ 사민(士民)들은 명암 정식(明庵 鄭拭：1683∼1746)이 지은 비문으로 경종 2년(1722)에 세웠다. 영조 16년(1740) 병사 남덕하(南德夏：1688∼1742)는 의기정포(義妓旌褒)를 계청하여 의기사를 창건하였고, 「○○○○○」에는 비각을 건립하여 의기논개지문(義妓論介之門)이라는 현판을 게시하였다.","a":"진주의암사적비","c":"시도유형문화유산","nc":"","r":"경상남도","s":"진주시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1642314.jpg"},{"q":"○○○○○ 1호는 남방식 개석식 고인돌 형식이며 축조시기는 대략 기원전 1세기에서 기원 후 1세기경에 제작된 것으로 추정되며, 다른 2기의 고인돌과 10m정도의 간격을 두고 삼각형태로 놓여져 있다. 뚜껑돌 형태는 장타원형이며 뚜껑돌 남쪽은 65cm가 들려져 있고 그 아래에 지석이 둥그렇게 돌아가며 고여져 있다. 장축 310cm, 단축 235cm, 두께 105cm이고 뚜꺼돌 윗면에는 풍요와 다산을 상징하는 5~6개의 성혈이 있다. 고인돌 내부에서는 무문토기편이 수습되었다. 축조시기는 탐라시대전기(AD 1~300)년 경이다.","a":"상예동지석묘1호","c":"시도기념물","nc":"","r":"제주특별자치도","s":"서귀포시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1657707.jpg"},{"q":"향교는 공자와 여러 성현께 제사를 지내고 지방민의 교육과 교화를 위해 나라에서 세운 교육기관이다. ○○○○를 세운 시기는 정확하게 알 수 없으나, 조선 전기 전국적으로 많은 향교를 세운 시기에 지은 것으로 추정한다. 이후 여러 차례 보수한 기록이 있으며, 고종(재위 1863∼1906) 때 크게 고쳐 지었다. 건물 배치는 앞쪽에 학문을 배우는 공간인 명륜당이 있고 뒤쪽에 제사 공간인 대성전이 있는 전학후묘 형태를 따르고 있다. 대성전 좌우에 동무와 서무가 있고, 강당인 명륜당 좌우에 학생들의 기숙사였던 동재와 서재가 있다.","a":"서천향교","c":"시도기념물","nc":"","r":"충청남도","s":"서천군","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1652979.jpg"},{"q":"조선 인조 때의 문신인 ○○○ 선생의 충의를 추모하고 기리기 위해 세워놓은 비이다. 선원 ○○○ 선생은 선조 23년(1590) 문과에 급제하여 판동녕부사, 병조·예조·이조의 판서, 유도대장, 우의정 등을 역임하였다. 병자호란이 일어나자 종묘를 모시고 빈궁과 원손을 수행하여 강화도로 피란했으나 성이 함락되자 성의 남문루에 있던 화약에 불을 지른 후 순절하였다. 이러한 그의 충절을 기리고자 비를 세웠으며, 선원면에 자리한 충렬사에 그의 위패를 모시었다.","a":"김상용 순절비","c":"시도기념물","nc":"","r":"인천광역시","s":"강화군","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1645636.jpg"},{"q":"관음사 사찰 내 대웅전 앞에 자리하고 있는 석탑으로, 2층 기단(基壇) 위로 3층 탑신(塔身)을 올린 형태이다. 기단부는 탑신부에 비해 상대적으로 많이 파손되어 있으며, 위층 기단 위로 깎아둔 2단의 괴임돌 역시 모서리가 파손된 상태로 남아있다. 탑신부는 몸돌과 지붕돌을 각각 딴돌로 조성하였다. 몸돌은 위로 오를수록 높이가 줄고 있으나 1층 몸돌이 다소 높직한 느낌이다. 몸돌 각 모서리에는 가지런한 기둥 모양의 조각을 두었을 뿐 별다른 장식은 없다. 두꺼워 보이는 지붕돌은 완만한 경사를 이루다가 네 귀퉁이에서 약간 치켜올라 있다.","a":"관음사석탑","c":"문화유산자료","nc":"","r":"충청남도","s":"아산시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1661287.jpg"},{"q":"계룡면 양화리 ○○○○들은 중종반정의 주체인 박원종(1467-1510)의 집안으로서 박원종의 사촌인 순성군 박 이검의 후손들이다. 바로 이검의 아들인 인손(1498-1553)이 공주 계룡 양화리에 이거하면서 번성한 성씨였다. 인손의 아버지 이검은 청도군수로서 사촌 박원종과 함께 중종반정에 참여하여 정난공신에 봉해졌고 사후에 증직 공조판서와 순성군에 봉해졌고 시호는 양평이다. 아들 인손은 원종공신의 자제로서 진주정씨 정세규의 사위가 되어 양화리에 이거하여 터전을 마련하였으며 이후 ○○○○들은 계속 번성하여 오늘에 이르고 있다.","a":"공주순천박씨공신록권2책","c":"문화유산자료","nc":"","r":"충청남도","s":"공주시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1661539.jpg"},{"q":"주륵사터에 무너져 있는 석탑으로, 부재들이 많이 없어지고 땅 속에 묻혀있어 탑의 전체 규모는 알 수 없다. 땅 위에 드러나 부재들을 통해, 2층 기단(基壇) 위에 탑신(塔身)을 올렸을 것으로 추정된다. 기단에는 기둥 모양의 조각이 보인다. 지붕돌은 낙수면이 완만하고 네 귀퉁이가 살짝 치켜 올라갔으며 밑면에 5단의 받침을 두었다. 현재 남아있는 부재의 크기로 보아 그 크기가 웅장하여 불국사 석가탑 못지 않은 대규모의 석탑이었을 것으로 생각된다. 모든 양식으로 보아 통일신라시대 석탑의 전성기인 8∼9세기 경에 세운 것으로 추정된다.","a":"주륵사폐탑","c":"문화유산자료","nc":"","r":"경상북도","s":"구미시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1663080.jpg"},{"q":"조선 세조 대의 승려인 ○○○○의 초상화이다. 수미는 세조의 왕사(王師)이며 15세기 중엽에 ○○○를 크게 중창한 승려로서, 당시 선종판사가 되어 황폐한 불교를 부흥시켰다. 초상화에는 약간 왼쪽을 향한 자세에 불교용구인 불수를 들고 두 다리를 가부좌하여 의자에 앉아있는 모습을 담았으며, 화폭의 오른쪽 윗부분에 ‘○○○○○’이라는 그림제목을 써 놓았다. 조선 인조 11년(1633)에 제작된 것으로 전하는데 그의 비를 건립한 시기와 같다. 함께 보존되어 있는 도선국○○○과 인물의 표현법이나 의복의 음영처리 기법이 같다.","a":"도갑사수미왕사진영","c":"시도유형문화유산","nc":"","r":"전남광주통합특별시","s":"영암군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1640112.jpg"},{"q":"밀성박씨 문중에서 밀양주신(密陽主神)으로 섬겨오던 박욱(朴郁)의 모습을 나무로 깎아 만든 상이다. 박욱은 밀성대군 박언침의 아들이자 박혁거세 거서간의 31대손이다. 이 ○○은 붉은 바탕에 구름무늬가 새겨진 흉배가 있는 청색의 관복을 입고 있다. 빗살무늬가 교차하는 듯한 무늬가 있는 붉은색의 띠를 허리에 두르고 긴 칼을 두손으로 힘 있게 잡고 의자에 앉아있는 무인의 모습이다. 이 상은 추화산 추화사(推火祠)에 모셔져 있다가 1937년 밀양시 내일동 아북산 남쪽에 세워진 밀성박씨 재실에 옮겨 모셔졌으며 이후 새 사당을 익성사로 개칭하였다고 한다.","a":"삼한벽공도대장군 목상","c":"문화유산자료","nc":"","r":"경상남도","s":"밀양시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1664350.jpg"},{"q":"○○○는 안동김씨와 아주신씨 두 문중에서 함께 한 재사에서 하나의 산에 위치한 조상의 묘소를 수호하고 묘제를 올리고 있다는 점에서 민속적으로 독특한 사례이다. 16세기 초⋅중엽에 창건된 후, 현재에 이르기까지의 중수와 이건의 과정이 편액된 현판의 내용을 통해 자세하게 파악되며, 강당은 위치에 따른 위계의 표현하기 위하여 원기둥과 네모기둥을 구분하여 사용하고 있고 기둥 위치에 따라 장식적인 익공과 낮은 위계의 민도리 구조를 구분하여 사용하고 있어서 건축계획적인 의도를 분명히 확인할 수 있다.","a":"예천 직산재","c":"시도민속문화유산","nc":"","r":"경상북도","s":"예천군","i":"http://www.khs.go.kr/unisearch/images/folklore_material/thumb/2018101612081700.JPG"},{"q":"논산-대전간 1호 국도변 산등성이에 자리한 산성으로, 해발 118m지점의 산봉우리를 빙 둘러 흙으로 쌓았다. 성의 둘레는 400m이며, 성벽의 높이는 1.5m이고, 문터는 뚜렷하게 남아있지는 않지만, 외성리 마을쪽으로 올라오는 길목 쯤이라고 여겨진다. 백제 토기류가 발견되고 있어 산성을 만든 시기도 이때로 추정해볼 수 있다. 연산면 표정리에 있는 황산성의 외성으로, 서남 방향을 방어할 목적으로 만들어진 듯하다. 양촌면 모촌리, 부적면의 신풍리와 감곡리 및 논산에서 연산으로 통하는 길목의 중요한 위치에 세워진 성이다.","a":"외성산성","c":"문화유산자료","nc":"","r":"충청남도","s":"논산시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1661326.jpg"},{"q":"금옹 김학배(1628∼1673)와 적암 김태중(1649∼1711)의 학문과 덕행을 추모하고 이를 계승하고자 세운 서당이다. 김학배는 조선 후기 문신이다. 현종 4년(1663) 과거에 급제하고 벼슬이 예조좌랑에까지 이르렀다. 학문과 후학양성에도 정성을 다하였으며, 저서로는 『금옹문집』이 있다. 김태중은 김학배의 제자로 오로지 학문 연구와 후진양성에 힘썼다. 운곡은 김학배가 운계초당을 지어 김태중을 비롯한 문생들에게 학문을 전수한 유서깊은 곳이다. 그런데 초당을 지은지 3년 뒤에 김학배가 금양으로 이사하여 18년간 비어 있었다.","a":"운곡서당","c":"문화유산자료","nc":"","r":"경상북도","s":"안동시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1662757.jpg"},{"q":"조선 초기의 문신 식우(拭우) ○○○ 선생의 위패를 모신 사당이다. 세종 23년(1441) 문과에 급제한 후 세종의 특명으로 집현전 학사가 되어『치평요람』·『의방유취』등 각종 편찬사업에 참여하였다. 성종 2년(1471)에 4등공신이 되어 영산부원군에 봉해졌다. 학문과 문장이 뛰어나『명황계감』,『금강경』등을 한글로 풀이하였으며 저서로는『식우집』이 있다. ○○○는 번역과 간행에 많은 업적을 남긴 선생을 위하여 성종의 명으로 세운 사당인데, 종곡리에 있었던 것을 현종 5년(1664)에 우암 송시열이 지산리로 옮긴 것이다. 많이 무너지고 떨어져 1981년에 보수·정화하였다.","a":"보은 김수온 부조묘","c":"시도기념물","nc":"","r":"충청북도","s":"보은군","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1649828.jpg"},{"q":"○○군 남면 신남리의 암자에 있던 석탑과 ○○○○으로, 소양강댐을 만들면서 백련정사(白蓮精寺)로 옮겨왔다. 탑은 2층 기단(基壇) 위에 3층의 탑신(塔身)을 올린 모습인데, 현재 탑신은 2층까지만 남아있다. 아래층 기단은 없어진 부재가 많아 원래 모습을 정확히 알 수 없고, 위층 기단에는 각 면마다 기둥 모양을 조각하였다. 탑신은 1·2층 몸돌의 높이가 비슷하여 독특한 모습이고, 급한 경사를 보이는 지붕돌은 네 귀퉁이가 살짝 치켜올라 갔으며 밑면에는 3단의 받침을 두었다. 꼭대기에는 머리장식으로 보이는 둥근 모양의 돌이 놓여 있다.","a":"인제 상동리 삼층석탑 및 석불좌상","c":"문화유산자료","nc":"","r":"강원특별자치도","s":"인제군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1660383.jpg"},{"q":"송림이 우거진 낮은 야산을 배경으로 남향하여 자리하고 있다. 북으로ㅡ자형의 안채와 서측의 행랑채, 동측에는 안채와의 사잇담과 근래에 지은 주택이 안마당을 형성하고있다. 안채와 우측으로 ㄴ자형의 사랑채와 행랑채가 서로 마주보고있다. 원해 안채앞에 중문채가 있었던것을 1988년에 헐어내고 현재와 같이 누각형 대문채를 건립하였다. 사랑마당과 안마당은 담장으로 구분되어 있는데, 특히 후면담장은 급한 경사지를 따라 둥글게 감싸고 있으며 상부에 연목을 놓고 기와를 얹은 토담이다. 토담을 축조할때 사용했던 귀틀이 현재도 남아있다","a":"서산유기방가옥","c":"시도민속문화유산","nc":"","r":"충청남도","s":"서산시","i":"http://www.khs.go.kr/unisearch/images/folklore_material/thumb/1658277.jpg"},{"q":"이 영정(○○○○○영정)은 좌안7분면의 바닥가부좌상으로, 화문석위에 결가부좌를 한 채 왼손에 주장자를 들고 오른손은 염주를 쥔 채 무릎위에 둔 상태이다. 안면부묘사는 백색을 바르고 먹선으로 윤곽선을 잡았다. 상검선은 농묵세선, 하검선은 담묵세선으로 그린 후 눈동자는 중묵으로 처리하였고 동공은 농묵점으로 찍었다. 눈머리와 눈꼬리는 담묵으로 바림하여 부드럽고 자연스런 느낌을 표현하였다. 두부의 모발과 수염묘사가 다른 초상화에 비해 특징적인데 담묵으로 바림한 후 백색점과 먹점을 무수히 찍었다.","a":"해송당 관준 진영","c":"시도유형문화유산","nc":"","r":"경상남도","s":"양산시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/0000000001642986.JPG"},{"q":"○○○는 통일신라 경덕왕 원년(742)에 이름모를 스님 세 분이 세웠다고 전한다. 고려시대에는 광자대사가 크게 늘려 지었는데 이 때 절의 규모는 총 40여 동에 110칸이었고, 법당에는 높이 1.4m되는 약사여래철불좌상을 모셨던 듯하다. 고려 고종 10년(1223)에는 당시 집권자인 최우가 고쳐 지었으며, 조선시대에는 숙종 10년(1684)에 주지 각현이 창고를 새로 지었다는 기록이 보이고 있다. 특히 조선초에 태종의 둘째 아들 효령대군이 이곳에 머물렀던 인연이 있는 곳이다. 한국전쟁때 많은 피해를 입어서 지금 있는 건물은 대부분이 복원된 것이다.","a":"태안사","c":"문화유산자료","nc":"","r":"전남광주통합특별시","s":"곡성군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1661941.jpg"},{"q":"파은 박수기·눌재 박상·충암 김정·안재 박지견·사암 박정·육유정, 박지효 선생 등의 절의와 충정을 받들고 이를 후손에게 전하고자 세운 재실이다. 눌재 박상 선생은 조선 중기 문신으로 연산군 2년(1496)에 진사가 되었고, 1505년 전라도사를 지냈다. 중종 6년(1511)에는 담양부사가 되었으며, 1515년에는 중종반정으로 폐위된 단경왕후 신씨의 복위를 주장하기도 하였다. 1526년에는 문과중시에 장원하였으며 1529년에는 병으로 관직을 사직하고 고향으로 돌아왔다. 저서로는 『눌재집』이 있고 시호는 문간(文簡)이다. 충암 김정 선생은 조선 전기 문신이며 학자이다.","a":"화산사","c":"문화유산자료","nc":"","r":"전북특별자치도","s":"장수군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1661648.jpg"},{"q":"조선 초기에 유학자의 위패를 모시고 제사지내며 지방민의 교육과 교화를 위해 나라에서 지은 교육기관이다. 처음 지은 정확한 연대는 알지 못하나, 원래 웅진동 송산 기슭에 있던 것을 인조 원년(1623)에 지금의 위치로 옮겨지었다고 전한다. 그 뒤 여러 차례의 보수가 있었고, 1954년 문묘·명륜당·동재·존경각 등을 보수하여 현재에 이르고 있다. 외삼문을 들어서면 강당인 명륜당이 있고 그 양쪽에 동재와 존경각이 있다. 뒤쪽 한층 높은 곳에 있는 내삼문을 들어서면 정면에 사당인 대성전이 있으며, 그 양쪽에 동무와 서무가 있다.","a":"공주향교","c":"시도유형문화유산","nc":"","r":"충청남도","s":"공주시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1639121.jpg"},{"q":"○○○○은 해발 380m의 산꼭대기에 가파른 경사를 이용하여 쌓은 성으로, 안심과 하양으로 이어지는 통로상에 있어, 지형상 중요한 군사적 요충지였던 것으로 짐작된다. 성벽의 둘레는 약 1㎞이며, 성의 서쪽과 남쪽의 산기슭에서 능선으로 이어지는 완만한 경사지에는, 인공적으로 절벽을 만들어 적의 침입에 대비하였다. 절벽 앞에는 문터로 보이는 입구가 있으며, 성 안의 동북쪽에는 우물터가 있다. 성 안에서 신라 토기조각들이 발견되는 점으로 미루어, 삼국시대에 만들어진 성으로 추측된다.","a":"용암산성","c":"시도기념물","nc":"","r":"대구광역시","s":"동구","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/2387590.jpg"},{"q":"○○○ 한켠에 지어진 비각 안에 놓여 있는 비로, 고려시대 승려인 ○○○○ 결응을 기리고 있다. 결응은 12세에 출가하여 복흥사에서 승려가 지켜야 할 계율을 받았으며, 28세에 대덕(大德:덕이 높은 승려를 가리킴)이 되었다. 고려 정종 7년(1041) ○○○로 들어와 화엄종의 법통을 이어받았고, 문종 7년(1053) 4월 이 절에서 입적하였다. 왕은 그의 시호를 ‘원융’이라 내리었다. 비는 바닥돌 위에 거북받침을 마련하여, 비몸을 세운 후 머릿돌을 얹은 구조로, 거북받침은 원래의 것이 아니며, 비몸은 깨어지고 갈라져 있는 것을 이어 붙인 것이다.","a":"부석사원융국사비","c":"시도유형문화유산","nc":"","r":"경상북도","s":"영주시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1640491.jpg"},{"q":"○○○○는 사찰 입구에 설치하는 것으로, 절에 행사나 의식이 있을 때면 이곳에 당이라는 깃발을 걸게 되는데, 이 깃발을 매달아 두는 길쭉한 장대를 당간이라 하고, 당간을 양쪽에서 지탱해주는 두 돌기둥을 ○○○○라 한다. 이 당간은 원래 높이가 12m나 되는 거대한 것이었다고 전한다. 1945년 태풍으로 윗부분이 부러져 쇠고리로 붙였으나, 부러진 부분이 없어지고 지금은 붙였던 흔적만 남아있다. ○○○○는 간결한 형태로 기둥 맨 윗부분은 모서리를 깍아 둥글게 처리하였다.","a":"영광단주리당간지주","c":"시도유형문화유산","nc":"","r":"전남광주통합특별시","s":"영광군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1640050.jpg"},{"q":"향로란 절에서 마음의 때를 씻어준다는 의미를 가진 향을 피우는데 사용하는 도구를 말한다. 이 향로의 전체 높이는 110㎝이고 몸체 높이 80㎝, 뚜껑 높이 30㎝, 다리 높이 25㎝이다. 조선시대에 만들어진 것으로 추정되며, 뚜껑 중앙부에 사자가 웅크리고 앉은 모양을 만들어 붙였다. 이 사자상이 꼭지 겸 손잡이이며, 옆구리에도 사자 머리 모양의 손잡이를 만들어 붙였다. 표면에는 덩굴 무늬와 모란꽃 무늬를 은상감 하였으며, 그 원형이 잘 보존되어 있다.","a":"청동은입인동문향로","c":"시도유형문화유산","nc":"","r":"전북특별자치도","s":"익산시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1639468.jpg"},{"q":"율곡 이이가 쓰던 벼루와 토지 양여서이다. 벼루는 가운데가 타원형으로 오목하게 패여 있고, 위쪽과 아래쪽에 나뭇가지와 잎사귀를 양각하였다. 벼루의 뒷면에는 글씨가 새겨 있는데, 정조 12년(1788)에 정조가 율곡 이이의 유품이 강릉에 있다는 말을 듣고 직접 보시고, 쓰신 것을 그대로 새긴 것이다. 보신 후 율곡의 유품을 소중히 보존하기 위해 어제각이라는 건물을 지어 보관하도록 하였다. 토지 양여서는 율곡이 그의 소유의 토지를 이종 권처균(權處均)에게 양여 한다는 증서로, 계약서나 각서와 같은 성질의 문서이다.","a":"율곡유품(벼루,토지양여서)","c":"시도유형문화유산","nc":"","r":"강원특별자치도","s":"강릉시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1637865.jpg"},{"q":"이곳은 이름이나 유래가 정확하지 않으나, 출토유물로 보아 백제의 절터로 추정된다. 가람의 배치방식을 살펴보면, 남·북 일직선을 중심으로 하여 중문, 금당, 강당이 있고, 회랑이 중문에서 강당으로 이어졌다. 이 절터에서 납석제 불상편, 기와로 만든 광배조각, 동제 금구편, 동제 불상편과 다양한 토기·기와가 출토되었다. 동남리절터는 탑과 건축이 확인되지 않은 특이한 가람배치를 보이고 있는 절터로, 백제의 불교사원 건축 연구에 중요한 자료가 되고 있다.","a":"동남리사지","c":"시도기념물","nc":"","r":"충청남도","s":"부여군","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1652763.jpg"},{"q":"공처럼 둥글게 팽배하였으면서도 약간 갸름한 몸통과 적당한 굵기와 길이의 목, 그리고 밖으로 말린 입술 부분을 가진 백자병이다. 이러한 모양의 몸통은 주로 18세기 백자병에서 볼 수 있는 특징이다. 몸통의 중앙부 앞․뒷면에는 가는 줄기의 대나무와 아직 잎이 나지 않은 채 꽃만 피어 있는 한 그루의 매화나무를 청화(靑畵)로 그려 넣고 그 사이 면에는 우리나라 자기에 많이 시문되는 시구(詩句)가 능숙한 서체로 쓰여 있다. 유태색(釉胎色)은 18세기의 전형적인 유백색(乳白色)이다. 대나무 아래 지표면을 시문하고 정갈한 서체의 시구(詩句)를 적어놓은 수작이다.","a":"백자청화매죽문시명병","c":"시도유형문화유산","nc":"","r":"서울특별시","s":"관악구","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/2593106.jpg"},{"q":"조선시대 만들어진 높이 111㎝, 입 지름 84㎝의 종이다. 종은 정조 7년(1783)에 제작된 것으로 소리울림을 도와주는 음통은 없으며, 종을 매다는 고리는 2마리의 용으로 되어 있다. 몸체 가운데에 4개의 유곽이 독립적으로 배치되어 있고, 유곽 사이의 빈 공간에는 보살상이 새겨 있다. 문양의 조각기법이 조잡하고 표면은 거친 편이나, 조선시대 ○○ 연구에 중요한 자료가 된다.","a":"창원 성주사 동종","c":"문화유산자료","nc":"","r":"경상남도","s":"창원시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1664572.jpg"},{"q":"소나무가 우거진 낮은 언덕을 배경으로 세운 집이다. 한국전쟁 때 임시 학교로도 사용될 만큼 규모가 크고 웅장한 집으로 조선 정조 때 세도가였던 홍국영이 유배되었던 곳으로 알려져 있다. 안채, 사랑채로 구성된 본채와 바깥 행랑채가 ㅁ자형을 이루고, 본채 동쪽에 1714년경 지은 것으로 추정되는 문간채가 있다. 안채 왼쪽은 참방이 있고 오른쪽은 사랑채가 있으며 맞은편에는 행랑채가 있다. 안채는 마루를 사이에 두고 좌우에 방들을 배치하였다. 방 앞에는 대청마루와 이어진 마루를 두어 각 방의 통로 구실을 하고 있다.","a":"강릉김윤기가옥","c":"문화유산자료","nc":"","r":"강원특별자치도","s":"강릉시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1660438.jpg"},{"q":"안동권씨 현감공파 재사로 1484년 현감공의 장례후 건립한 재사로 강희 23년(1693)에 1차 중수하였으며 함품 11년(1861)에 2차 중수하였다. 정면 3칸,측면5칸의 ㅁ 자형 가옥으로 삼량가 구조이다. 재사 중수기록에 의하면 고승의 암자였을 것으로 추정되고 현감 권경행을 암자뒤에 장사지낸 후 이곳에 재사를 검립하였을 것으로 추정된다. 건립당시의 평면구조를 잘 간직하고 있어 재사 건축양식을 파악하는데 중요한 자료로 평가되고 있다.","a":"단운재사","c":"문화유산자료","nc":"","r":"경상북도","s":"영주시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1663533.jpg"},{"q":"○○○은 흥성 장씨의 선조인 장창우가 학문을 가르쳤던 옛 터에 후손들이 그의 덕을 기리고자 지은 정자이다． 1934년에 세웠으며 1945년에 고쳐 지은 건물로 앞면 2칸·옆면 2칸 규모를 갖추고 있다. 지붕은 옆면에서 볼 때 여덟 팔(八)자 모양인 팔작지붕이다. ○○○ 안에는 많은 시문과 현판들이 걸려 있다. ○○○은 큰 연못 가운데에 세운 정자로 다리를 사이에 두고 다른 정자들과 한 줄로 늘어서 있다.","a":"만귀정","c":"문화유산자료","nc":"","r":"전남광주통합특별시","s":"서구","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1659597.jpg"},{"q":"구한말 둔헌 ○○○ 선생이 일본의 침략으로부터 나라를 구하고자 의병들을 모아 훈련시켰던 곳이다. ○○○ 선생은 불법적인 을사조약이 체결된 이듬해인 1906년 면암 최익현 선생과 무성서원에서 의병을 일으켰으며, 순창전투에서 일본군과 싸우다 최익현과 함께 붙잡혀 대마도로 유배되었다. 1914년 독립의군부를 전국 조직으로 확대하여 대한독립의군부로 만들었으며, 의병활동을 하다 체포되어 거문도에서 유배생활을 하던중 병으로 세상을 떠났다.","a":"임병찬창의유적지","c":"시도기념물","nc":"","r":"전북특별자치도","s":"정읍시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1653651.jpg"},{"q":"○○○는 천개산에 있는 절로 기록에 의하며 통일신라말 애장왕 6년(805)에 도선국사가 세웠다고 한다. 세울 당시에는 계곡을 중심으로 양쪽에 묘덕사와 쌍계사 두 절이 있었는데 후에 쌍계사는 수정사라 이름을 바꾸었다. 한동안 폐허가 되었던 것을 중종 19년(1524)다시 지으면서 ○○○라 이름을 바꾸었고, 이후 여러 차례 다시 짓거나 수리를 하였다. ○○○○○은 절의 중심에 있는 법당으로 석가모니를 모시고 있으며 4번에 걸쳐 수리한 기록이 있다. 앞면 3칸·옆면 2칸의 겹처마로 가장 단순한 맞배집이다.","a":"정수사대웅전","c":"시도유형문화유산","nc":"","r":"전남광주통합특별시","s":"강진군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1639941.jpg"},{"q":"이 고택은 임진왜란과 병자호란에서 공을 세워 자헌대부(資憲大夫) 지중추부사(知中樞府事)를 역임한 사월(沙月) 조임(趙任, 1576-1644)의 손자인 시벽(是壁, 1670-1753)이 1710년 경 건립하였다고 하며, 조선 후기의 학자인 하담(荷潭) 조언관(趙彦觀, 1805-1870)이 태어난 곳이다. 시벽의 아들이 심은 회나무가 있다하여 쌍괴당(雙槐堂)이라고도 한다. 고택은 ㅁ자형 건물로 정면 좌측에 팔작지붕의 사랑채가 높게 솟아있고 그 뒤편에 안채가 다른 집과는 달리 지붕이 독립된 구조로 길게 놓여 있다.","a":"영양하담고택","c":"문화유산자료","nc":"","r":"경상북도","s":"영양군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1663466.jpg"},{"q":"창주 하증(1563~1624)이 지은 글을 모아 책으로 간행하기 위해 만든 책판은 1897년 12월에 ○○의 오방재에서 목활자로 \"창주선생유사(滄洲先生遺事)\"로 간행되었다가 1939년에 \"창주선생문집\"이란 제목으로 ○○을 제작하여 간행하였다. 전체 63판 107면이 남아 있으며 간재(艮齋) 전우(田愚 : 1841~1922)의 서문과 송종오(宋鍾五 : 1828~1904)의 발문이 새겨져 있다. ○○을 사용하여 만든 책은 많지만 현전하는 ○○은 많지 않아 전통출판문화를 알 수 있는 좋은 자료이다.","a":"진주 담산고택 창주집 목판","c":"문화유산자료","nc":"","r":"경상남도","s":"진주시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1665120.jpg"},{"q":"○○○는 고려 공민왕(재위 1352∼1374)때 나옹대사가 지은 절이다. 주변 경치가 아름답고 산속에서 흘러내리는 샘물과 계곡에 흩어진 돌이 수정과 같이 깨끗하다 하여 ○○○라 불렀다고 한다. 경내에는 ○○○을 비롯하여 산신각과 요사채가 있다. ○○○은 앞면 3칸·옆면 2칸 규모로, 지붕은 맞배지붕이다. 지붕 처마를 받치기 위해 장식하여 만든 공포는 기둥 위와 기둥 사이에도 있는 다포 양식으로 꾸몄으며, 단정하고 아담한 건물이다.","a":"수정사대웅전","c":"문화유산자료","nc":"","r":"경상북도","s":"청송군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1662497.jpg"},{"q":"○○○ 극락전 옆 마당에 세워져 있는 이 석탑은 3매의 옥개석으로만 구성되어 있는 규모가 작은 석탑이다. 석탑 부재의 크기 및 형태와 전각 체감율을 고려할 때 1층, 2층, 3층의 동일한 ○○○○ 옥개석으로 판단된다. 1층 옥개석은 지면과 맞닿은 아랫부분이 흙속에 많이 파묻혀 있지만 옥개받침이 4단이며, 낙수면과 옥개받침 등의 치석이 대체로 좋은 편이다. 이 석탑은 조각수법으로 미루어 보아 고려시대 특히 고려 후기에 조성된 것으로 파악된다.","a":"선암사 삼층석탑","c":"문화유산자료","nc":"","r":"부산광역시","s":"부산진구","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1659413.jpg"},{"q":"춘향고개 하단도로변에 자리잡고 있는 ○○○은 1953년에 세웠다. 우리나라 고대소설 춘향전의 성춘향과 이몽룡이 이별의 정을 나눈 곳이라 한다. 건물은 2층으로 된 목조기와집으로 대청으로만 구성되어 있다.","a":"오리정","c":"문화유산자료","nc":"","r":"전북특별자치도","s":"남원시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1661674.jpg"},{"q":"조선 숙종 36년(1710)에 여주 이씨 시조인 태사공 이인덕의 20대손 이지섬과 21대손 이식이 후손들을 가르치기 위해 세운 서당이다. 이 서당은 앞면 4칸·옆면 2칸으로 지붕 옆면이 여덟 팔(八)자 모양인 팔작지붕으로 되어있다. 앞면 4칸 중 가운데 2칸은 우물 정(井)자 모양의 마루를 깐 대청이고, 양 끝칸은 온돌방이다. 서당 뒤편에는 16대손인 이윤수(1545∼1594) 선생을 제사지내는 사당이 있다.","a":"무이서당","c":"시도유형문화유산","nc":"","r":"경상북도","s":"예천군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1640754.jpg"},{"q":"고려 후기의 무신으로 홍건적을 격퇴하는 데 큰 공을 세운 ○○○ 장군의 무덤이다. 장군은 충목왕이 원나라에 있을 때 모신 공을 인정받아, 왕이 즉위하자 무관의 벼슬인 중랑장에 오르게 되었다. 1359년(공민왕 8)에 4만 여명의 홍건적이 침입해오자 철주·철화·함종 등에서 관군들과 적을 무찌르는 큰 공을 세워 왕명의 출납과 군기를 맡는 추밀원 부사가 되었다. 1361년(공민왕 10)에 20여 만명의 홍건적이 다시 침입하여 개경까지 오자 정세운·최영 등 장군들과 합심하여 적을 완전히 물리치고 개경을 수복하였다.","a":"이방실장군묘","c":"시도기념물","nc":"","r":"경기도","s":"가평군","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1646099.jpg"},{"q":"용인시 남사읍 아곡리에 있다. 형제봉에서 동쪽으로 능선이 이어지며 돌출된 해발 70.9m의 자연 구릉이다. 용인에서 진위로 가는 길목이자 수원-오산-안성으로 연결되는 교통의 요충지에 해당한다. ○○○의 평면 형태는 사다리꼴이며 전체 둘레는 351m다. 작은 규모지만 성 내부가 평탄하여 공간효율성은 좋은 편이다. 성벽은 남서쪽이 높고 북동쪽이 낮은 형태다. 성문은 개거식(開据式)이었으며 북동 성벽에 2개가 있었던 것으로 보인다. 성벽은 자연지형을 활용하여 낮은 지점은 판축공법으로 성토하는 방법으로 구축했다.","a":"처인성","c":"시도기념물","nc":"","r":"경기도","s":"용인시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1646070.jpg"},{"q":"이 영정은 ○○○○○선사의 바닥가부좌상으로 8분 좌안면이며, 돗자리위에 방석을 깔고 양손에 각각 주장자와 염주를 쥐고 측면을 향해 앉아 있으며 그 옆으로는 서안과 서책이 보인다. 화면은 녹색바탕에 운보문의 충진구도인 상단벽면과 돗자리의 이단구도로 이루어져 있으며 화면상단에는 풍대가 묘사되어 있어 장식적이다. 표현기법에 있어서는 의습선, 가사연부의 연화문, 불자의 장식부분, 풍대의 술, 서책의 제목 등에 금색세선으로 처리하여 화려함을 더하고 있다. 화면 향우측에 ‘○○○○○대사진(慶坡堂敬審大師眞)’의 화제가 있다. 화면 크기는 가로 65.9cm, 세로 98.7cm이다.","a":"경파당 경심 진영","c":"시도유형문화유산","nc":"","r":"경상남도","s":"양산시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/0000000001643015.JPG"},{"q":"『○○○○』은 청음 김상헌(淸陰 金尙憲, 1570~1652)이 병자호란 이후 청나라 심양(瀋陽)에 볼모로 잡혀가 4년여를 지내는 동안에 지은 시를 함께 끌려갔던 조한영(曺漢英, 1608~1670)이 기록하여 한 질의 책으로 묶은 것이다.","a":"설교시첩","c":"시도유형문화유산","nc":"","r":"대전광역시","s":"유성구","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1637219.jpg"},{"q":"1988년 2월초에 ○○시(당시 제원군) 한수면 ○○○에서 덕주골까지 도로확장공사중 월광사지(月光寺址) 입구인 ○○○ 답(沓) 147번지 논둑에서 발견되었다. 당시 월악산국립공원관리사무소장 李相哲씨에 의해 관리사무소로 옮겨 졌다. 현재는 下德周寺 경내로 옮겨 비각을 세웠다. 碑文은 첫줄에만 漢字로 『大佛頂呪』라 刻字하고, 다음 줄부터는 ?梵字文?으로 鐫刻하였는데 모두 11行이다. 각 행의 字數도 고르지 않고 梵字로 새긴 부분은 글자의 크기도 일정하지 않다. 4行까지는 8자, 5～6행은 7자, 7～11행은 12～13자로 글자의 크기도 일정하지 않은 것이 특징이다.","a":"제천 송계리 대불정주범자비","c":"시도유형문화유산","nc":"","r":"충청북도","s":"제천시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1638847.jpg"},{"q":"고려 말기의 충신으로 우리나라 성리학의 기초를 닦은 포은(圃隱) ○○○ 선생의 묘소이다. 공민왕 9년(1360)에 문과에 장원급제 후 예문관검열·대사성 등의 여러 벼슬을 거쳤다. 고려 당시 풍속이 모든 상제(喪祭)에 불교의식을 숭상했는데, 『가례(家禮)』에 의해 사당을 세우고 신주를 만들어 제사를 받들게 하도록 해 예속이 다시 일어날 수 있도록 힘썼다. 서울에는 오부학당(五部學堂)을 세우고 지방에는 향교를 두어 교육의 진흥을 꾀했고 기강을 정비하였으며 의창(義倉)을 다시 세워 궁핍한 사람을 구제하는 등 기울어져가는 국운을 바로잡고자 노력하였다.","a":"정몽주선생묘","c":"시도기념물","nc":"","r":"경기도","s":"용인시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1645933.jpg"},{"q":"서원의 규모는 정면 5칸, 측면 2칸의 규모로 전·후 툇집 형식이며 정면의 기둥은 배흘림을 둔 두리기둥으로 단면의 크기도 크고 훤칠하다. 가구는 5량 구조로 장식이 잘 되어 있다. 양 툇간에는 툇보를 걸었으며 홑처마에 팔작지붕 형식이다. 서원으로서 전체적인 배치가 무난하며 부재의 사용이나 적절한 비례의 적용, 그리고 동재의 여러 가지 기술적인 수법 등 조선 후기 건축의 여러 기법들을 볼 수 있어 학술적 가치가 있다.","a":"진주 대각서원","c":"문화유산자료","nc":"","r":"경상남도","s":"진주시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1665106.jpg"},{"q":"현재 ○○○○○ 향좌측에 모셔져 있는 ○○○로 화기(畵記)에 의하면 1936년 안병문(安秉文), 김일차(金日叉) 등에 의하여 제작된 작품이다. 구도면에서는 상․하단의 2단 도상을 취하여 상단에는 제석천(帝釋天)과 범천(梵天), 하단에는 위태천(韋駄天)을 중심으로 50여 명에 달하는 신중(神衆)들을 빽빽하게 그려 넣었다. 상단의 제석과 범천 주위로는 일궁천자와 월궁천자를 비롯한 신중들과 악기를 연주하는 동자와 동녀 등이 서로 대칭되게 에워싸고 있다. 하단에는 위태천을 갑옷 입은 무장 신중들 18위(位)가 둘러싸고 있다.","a":"안양암 천오백불전 신중도","c":"문화유산자료","nc":"","r":"서울특별시","s":"종로구","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/2018102313553600.jpg"},{"q":"임진왜란(1592) 때 조선 중앙군과 왜병의 선봉주력부대가 최초로 싸운 장소로 800여 명이 순국한 호국성지이다. 선조 25년(1592) 일본군 주력 부대인 소서행장(小西行長)이 이끄는17,000명이 조총으로 무장하고 침공해 왔다. 이에 싸움도 하기 전에 순변사 이일은 성을 버리고 도주하였으나, ○○ 판관 권길과 호장 박걸, 종사관인 윤섬, 이경류, 박호 등의 경군과 사근도 찰방 김종무, 의병장 김준신 등은 800여 사병과 함께 죽기로 맹세하고 역전분투하였으나 호국의 영령으로 산화되었다.","a":"상주 임란북천전적지","c":"시도기념물","nc":"","r":"경상북도","s":"상주시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1654524.jpg"},{"q":"이 삼응○○은 육십갑자 중 십이간지를 네 묶음으로 분류하여, 한 묶음의 띠에 해당하는 나이가 삼재에 해당하는 해가 되면 이 삼재 소멸을 위해 기도하며, 그 비보용으로 이 삼응판을 인출 탁삼재라는 제호를 낙관하여 액자를 만들어 출입문 위에 걸었던 것이다. 흔하지 않은 자료라 보존가치가 높다.","a":"남해 화방사 삼재부 목판","c":"문화유산자료","nc":"","r":"경상남도","s":"남해군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1666695.jpg"},{"q":"조선의 문신인 ○○○ 선생의 ○○화 1폭과 그림을 옮겨 그리는 과정에 따르는 여러 사항들을 기록한 1권의 책이다. ○○○은 세종 32년(1450) 문과에 급제한 후, 세조의 왕위등극을 도와 공신의 반열에 올랐으며, 이후 벼슬이 좌찬성에까지 올랐다. 이 ○○화는 선생이 공신에 올랐을 때 왕명에 의해 그렸던 공신상을 1856년에 옮겨 그린 것으로, 신숙주·이숭원 선생의 ○○화와 같은 양식을 보인다. 검은 사모에 연붉은 바탕의 홍포를 입고 앉아 얼굴은 약간 오른쪽을 향하고 있으며, 두 손은 앞으로 모아 옷소매 안에 넣은 전신좌상이다.","a":"정수충 초상 및 중모기","c":"시도유형문화유산","nc":"","r":"충청북도","s":"청주시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1638644.jpg"},{"q":"충청북도에서 처음으로 지은 성당으로 1896년 프랑스 신부 임가밀로가 세웠다. 원래 이곳은 명성황후의 6촌 오빠 민응식의 집이 있던 곳으로, 1895년 명성황후가 시해되고 민응식이 서울로 압송되면서 의병들이 사용하게 되자 일본군들이 불태워 버렸다고 한다. 설계는 프랑스 신부 시잘레가 하였고 중국인이 공사를 맡았는데 명동성당의 축소판 같은 인상을 준다. 안쪽 천장은 원형돔으로 꾸몄다. 학교를 설립해 문맹퇴치에 힘쓰고 우리말을 가르쳐 일제 식민지 아래에서도 민족의 뿌리가 마르지 않도록 공헌하였다. 역사의 고난과 함께 뜻 깊은 민족정신의 흔적을 간직하고 있는 곳이다.","a":"음성 감곡성당","c":"시도유형문화유산","nc":"","r":"충청북도","s":"음성군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1638687.jpg"},{"q":"영남학파의 거두인 존재 이휘일(1619∼1672)의 유업을 기리기 위하여 세운 서당이다. 이휘일은 조선 후기의 학자이다. 일찍부터 성리학을 깊이 연구하여 사리를 깨달아 독립된 성리학의 한 유파를 이루었다. 또한 예를 존중하여 상제대요와 절목을 정리하여 예로부터 생활화된 폐단을 시정하였다. 저서로는 『존재집』, 『구인략』, 『홍범연의』가 있다. ○○○○은 영조 33년(1757) 지방 유림들이 세웠다. 세월이 흐르는 동안 여러 차례에 걸쳐 수리·보수하였으며, 최근에는 임하댐 건설로 1989년 지금 있는 자리에 옮겨 세웠다.","a":"백호서당","c":"문화유산자료","nc":"","r":"경상북도","s":"청송군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1662775.jpg"},{"q":"전남 장흥군 유치면 봉덕리에 위치한 ○○○의 ○○○○에 들어 있던 유물이다. 고려 중기 지눌이 조계산에 수선사를 세우고 선(禪)사상을 일으켰을 때 처음 불교에 입문한 사람과 수선사의 기강을 위해 저술한 것이다. 불교 수행에 있어 핵심내용을 뽑아 우리나라에 맞게 저술한 것으로, 불교 전문강원의 교재로 채택되었으며 승려는 물론 일반 신도까지 배워야 할 기본서가 되었다. 이 책 뒤에 『몽산화상법어약록』과 『훈몽요초』가 함께 묶여 있는데, 한자구결이 본문에 있어 학술적 가치가 크다. 『훈몽요초』는 지금까지 알려진 것보다 시기가 상당히 앞서 간행된 것으로 밝혀져 주목된다.","a":"보림사사천왕상복장계초심학인문","c":"시도유형문화유산","nc":"","r":"전남광주통합특별시","s":"장흥군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/2020022811420800.jpg"},{"q":"신라의 옛 절터에 있는 석탑으로, 1층 기단(基壇) 위에 3층의 탑신(塔身)을 쌓고, 머리장식을 얹은 모습이다. 기단의 네 모서리에는 기둥 모양을 새겼고, 윗면에 높직한 괴임을 두어 탑신의 1층 몸돌을 받치도록 하였다. 탑신부의 각 몸돌에도 기둥 모양이 조각되어 있는데, 일부 파손된 모습이다. 두꺼워 보이는 지붕돌은 네 귀퉁이가 위로 들려 있어 경쾌하며, 밑면에는 3단의 받침을 두었다. 꼭대기에는 노반(露盤:머리장식 받침)과 보륜(寶輪:바퀴모양장식)만이 남아 머리장식을 하고 있다.","a":"보은 원정리 삼층석탑","c":"시도유형문화유산","nc":"","r":"충청북도","s":"보은군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1638578.jpg"},{"q":"별립산(해발 340m) 북쪽 구릉에 11기의 고인돌무덤이 분포하고 있다. 고인돌무덤은 굄돌과 덮개돌의 일부만 훼손되었을 뿐 대체로 보존상태가 양호하다. 굄돌과 마감돌 및 덮개돌을 갖춘 북방식 고인돌무덤이 있으며 간혹 크기가 3∼4m나 되는 덮개돌을 갖춘 남방식 계통의 고인돌무덤도 있는데 이들은 굄돌 없이 땅위에 덮개돌만 놓은 이른바 개석식 고인돌무덤이다.","a":"강화 교산리 고인돌군","c":"시도기념물","nc":"","r":"인천광역시","s":"강화군","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/2018112115262300.jpg"},{"q":"○○ 대승시 ○○○○○은 기단부의 복련 장식, 기단부 상층 기단면석에 3개 연속의 탱주 모각, 1층 탑신석 남면에 조각된 문비 등이 특징이고, 이를 현존 탑과 비교하면, 건립 시기는 고려시대로 추정된다. 추후 마당에 묻힌 기단부를 노출시켜 확인하면 보다 정확한 기단 구조를 파악할 수 있을 것으로 보인다. 또 2층 탑신석이 멸실된 상태이나 잔존 1층 옥개석 상면의 탑신받침 규격을 고려하면 전체적으로 3층 석탑으로 추정된다.","a":"문경 윤필암 삼층석탑","c":"문화유산자료","nc":"","r":"경상북도","s":"문경시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1663743.jpg"},{"q":"조선 중기의 유학자 신독재(愼獨齋) 김집(1574∼1656)의 묘이다. 18세에 진사에 합격하고 광해군 2년(1610)에 참봉이 되었으나 광해군의 문란한 정치로 은퇴하였다가 인조반정 후 다시 벼슬길에 올랐지만 곧 사직하였다. 효종이 즉위한 후 대사헌을 거쳐 이조판서가 되어 북벌을 계획하기도 하였고 판중추부사의 자리에까지 올랐다. 죽은 후 고종 20년(1883)에 영의정으로 벼슬이 높여졌다. 그는 초야에 묻혀 아버지의 학문을 이어받고자 노력하였으며 이이의 학문을 계승하여 송시열에게 그 학문을 전해주어 기호학파 형성에 크게 공헌하였다.","a":"김집선생묘","c":"문화유산자료","nc":"","r":"충청남도","s":"논산시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1661364.jpg"},{"q":"권장(1802∼1874)이 셋째 아들 권숙의 살림집으로 지은 집이다. 조선 철종 1년(1850)에 세웠고 권숙의 호를 따라 ‘○○○○’이라고 부른다. 앞면 6칸·옆면 6칸 규모의 기와집으로 튼 ㅁ자형 구조이다. 안채에는 벽장이 있어 19세기 전통 주택의 변화과정을 보여 주고 있으며, 사랑채는 후학양성을 위한 서당 기능을 갖고 있어 특이하다.","a":"남천고택","c":"문화유산자료","nc":"","r":"경상북도","s":"안동시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1663144.jpg"},{"q":"○○○이 사용한 거문고(현금)와 거문고의 옛날 악보인 『○○○』로 그의 후손이 소장하고 있다. ○○○은 조선 숙종 때 양양부사와 순천부사를 지낸 유경시의 손자이다. 이 거문고는 1726년에 만들어진 것으로, 앞판은 오동나무로 만들었고, 앞판과 뒷판이 서로 떨어져 있다. 앞판의 뒷면에 명문이 있어, 재료의 출처와 만든시기를 알 수 있다. 밤나무로 만든 뒷판은 옆 귀퉁이가 약간 갈라져 있으나, ○○○ 문집의 시를 적어 놓아 이 거문고의 오랜 내력을 증명하고 있다. 전체길이 160㎝로 안족 2개와 괘 16개가 원형대로 남아 있고, 돌괘 1개가 있다.","a":"강포유홍원의현금및어은보","c":"시도유형문화유산","nc":"","r":"경상북도","s":"안동시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1641011.jpg"},{"q":"○○○○지는 조선 고종 16년(1879) 일본측이 서해안을 측량하면서 개항지를 탐색하는 것을 보고 인천을 개항 후보지로 요구할 것을 대비하여 어영대장 신정희와 강화유수 이경하가 인천과 부평 연안에 화도진을 설치하고 포대를 만들 때 함께 만들어진 것으로서 1999년 \"화도진도\" 원본 확인을 통해 이곳에 3혈(穴)의 포대를 설치했다는 사실이 밝혀졌다. 현재는 포대의 모습을 찾아볼 수 없고 문헌에는 포좌 3기가 설치되어 있었던 것으로 기록되어 있다.","a":"장도포대 터","c":"문화유산자료","nc":"","r":"인천광역시","s":"남동구","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1659582.jpg"},{"q":"물암 김융(1549∼1594)이 후진을 양성하기 위해 세운 건물이다. 김융은 퇴계 이황의 가르침을 받고 여러 벼슬을 두루 거쳤다. 임진왜란 때에는 왜적을 물리치고 백성을 구할 수 있는 방책을 유성룡에게 건의하기도 하였으며, 죽은 뒤에 승정원 좌승지에 임명되었다. 선조 2년(1569)에 세운 이 서당은 앞면 4칸·옆면 2칸 규모의 건물로, 지붕은 옆면에서 볼 때 여덟 팔(八)자 모양을 한 팔작지붕이다. 가운데 2칸은 마루, 양 옆으로는 온돌방을 배치하였으며, 현판은 퇴계 이황의 친필이다.","a":"두릉서당","c":"문화유산자료","nc":"","r":"경상북도","s":"봉화군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1662967.jpg"},{"q":"○○○는 알[卵] 모양의 구멍들이 있는 바위라는 뜻이다. 이 구멍들은 돌 표면을 쪼아서 형태를 잡은 다음 회전 마찰을 통해 다듬은 것으로, 성혈(性穴)이라고도 한다. 주로 고인돌의 덮개돌이나 자연암반에 새겨지며, 흔히 ‘알구멍’, ‘○○○’ 등으로 불린다. 성혈은 주로 태양, 여성의 성기 등을 상징하며, 이는 풍요와 다산의 의미로 해석된다. 청동기시대 농경의 발달은 인구 증가와 동시에 많은 생산량을 필요로 하게 되었으며, 이것이 다산과 풍요를 기원하는 신앙적 의식의 표현으로 이어졌을 것으로 추정된다.","a":"방기리알바위","c":"시도기념물","nc":"","r":"울산광역시","s":"울주군","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1645875.jpg"},{"q":"인천에 있던 외국인들의 사교모임인 ○○○○○의 사교장으로 쓰기 위해 광무 5년(1901)에 지은 것이다. 1913년 일본제국 재향군인회 인천연합회 소속의 정방각으로 불리다가, 1934년 일본부인회, 광복직후에는 미군 장교 클럽, 1947년부터는 대한부인회 인천지회가 각각 활용하였으며, 1952년 시의회, 교육청, 박물관이 함께 사용하다가, 1953년 의회와 교육청이 이전한 후 1990년 인천시립박물관도 이전하였다. 2007년 6월 리모델링 작업을 거쳐 구)○○○○○의 모습을 복원하여 스토리텔링박물관으로 운영되고 있다.","a":"구 제물포구락부","c":"시도유형문화유산","nc":"","r":"인천광역시","s":"제물포구","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1637028.jpg"},{"q":"조선시대 무과에 급제한 사람의 이름을 기록한 명부이다. 숙종 46년(1720)에 김여강, 김우천, 양유성 등에 의하여 처음으로 만들어졌다. 내용은 서문, 절목, 명단의 순으로 기록되어 있다. 서문은 효종 9년(1658)에 무술방(戊戌榜:과거 합격자로서 아직 임관되지 않은 사람)출신인 이기발이 썼고, 명단은 명종 13년(1558) 무오방부터 총 338명의 급제한 사람의 이름과 급제한 해의 간지(干支)가 기록되어 있다. 또한 명단은 후대로 가면서 여러 사람이 계속하여 추가로 기록한 것으로 보인다.","a":"급제선생안","c":"시도유형문화유산","nc":"","r":"제주특별자치도","s":"제주시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1643286.jpg"},{"q":"향교는 훌륭한 유학자를 제사하고 지방민의 유학교육과 교화를 위하여 나라에서 지은 교육기관이다 세워진 시기는 정확히 알 수 없으나 조선 영조12년(1736)에 부사 민진기가 횡천으로부터 옮겨지었다. 그 뒤 헌종13년(1847)과 1920년에 고쳐지었고, 근래에도 보수하였다. 출입문이자 휴식공간이었던 풍화루를 들어가면 유생들이 공부하는 명륜당이 있고 그 앞쪽에는 유생들의 거처인 동·서재가 비대칭으로 위치하고 있다. 명륜당 뒤로는 내삼문이 있고, 그 안에 사당인 대성전과 동·서무가 있어서 공자를 비롯한 여러 성현들을 모시고 있다.","a":"하동향교","c":"시도유형문화유산","nc":"","r":"경상남도","s":"하동군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1641946.jpg"},{"q":"○○○○○는 임진왜란 의병장인 이달(李達) 장군의 묘하에 건립한 재실이다. 1880년(고종 7)에 중건된 목조와가(木造瓦家) 건물이며 1940년에 한차례의 보수가 있었다. 정사는 철마산의 남사면부 끝자락에 남향하여 자리잡고 있는데 장좌천의 상류부이다. 강당과 대문채가 서로 마주 보고 있으며 대문의 남동쪽에는 고직사가 있다. 정사는 정면 4칸, 측면 1.5칸의 홑처마 팔작지붕이다. 평면은 좌측부터 툇마루가 딸린 온돌방 2칸, 마루 1칸, 툇마루가 딸린 온돌방 1칸으로 구성되어 있다. 공포양식은 장여수장집이며 상부가구는 도리가 세 개인 3량가이다.","a":"고성 철산정사","c":"문화유산자료","nc":"","r":"경상남도","s":"고성군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1665507.jpg"},{"q":"화면을 상하로 이분한 뒤 상단에는 향우측부터 청진당, 청하당, 청운당, 락서당을, 하단에는 향우측부터 봉성당, 우진당, 용암당, 은암당을 그린 후 오른쪽 위에 각각 명칭을 기입하였다. 이들은 생략된 배경을 뒤로 무늬 없는 돗자리위에 좌안7분면의 결가부좌상으로 염주나 주장자를 들고 있는 모습이다. 8명의 스님 가운데 행적이 확인되는 분은 별로 없지만 그 중 낙서당은 삼천포 운흥사 낙서암에 주석하였던 것으로 알려져 있다. 그리고 시도유형문화유산으로 지정된 ○○○ 소재 부도군 9기 가운데 ○○○ 중 청하당과 은암당의 부도가 포함되어 있다.","a":"남해 용문사 팔화상 진영","c":"문화유산자료","nc":"","r":"경상남도","s":"남해군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/0000000001666203.jpg"},{"q":"○○○은 백양사에 소속된 암자로 고려 충정왕 2년(1350)에 각엄왕사가 세웠다. 이곳 ○○○은 마음을 청청한 맑은 물에 비유하여 맑고 깨끗한 심성으로 선(禪)에 든다고 하여 ○○○이라 하였다고 한다. 백양사 경내에 들어서 왼쪽 계곡을 건너 가파른 산길을 2㎞가량 오르면 ○○○에 이른다. ○○○ 안에는 ○○○과 요사채가 있다. ○○○은 기단 위에 커다란 주춧돌을 놓고 두툼한 원형기둥을 세웠다. 지붕 처마를 받치기 위해 장식하여 만든 공포는 새 날개 모양으로 짠 익공 양식으로 꾸몄다, 공포의 뻗쳐 나온 부재 끝부분에는 연꽃봉오리를 얹었다.","a":"장성 청류암 관음전","c":"문화유산자료","nc":"","r":"전남광주통합특별시","s":"장성군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1662172.jpg"},{"q":"대천천 하류에 있었던 다리로, 예전에는 남포와 보령을 이어주는 중요한 교통로였다고 한다. 세월이 흐르면서 물살에 쓸려 떠내려 가거나, 하천 제방공사를 하면서 파손되어 얼마남지 않은 것을, 1978년 수습하여 옮겨 두었다가, 1992년에 대천천 강변에 옮겨 일부만 복원해 놓았다. 거대한 화강암으로 만들었는데, 근처에 있는 왕대산의 돌을 깎아내어 뗏목으로 운반해온 것으로 보인다. 다리의 몸체를 받치는 기둥은 거칠게 손질한 2∼3개의 돌을 쌓아 이루게 하여, 모두 6개의 기둥이 불규칙하게 배치되어 있다.","a":"대천한내돌다리","c":"시도유형문화유산","nc":"","r":"충청남도","s":"보령시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1639236.jpg"},{"q":"마을 중심부에 자리잡고 있으며 마을 통과도로에 인접해 있다. 집앞 솟을대문에는 상량문이 남아 있는데 「숭정기원후오회갑기축삼월초칠일임자무신시주립십구일갑자기사시상량」이라 기록되어 있어 1949년에 지어졌음을 알 수 있다. 그러나 안채나 사랑채는 연대가 훨씬 올라가 20세기 초로 추정된다. 집앞에는 두 그루의 노거수가 서있고 그 뒤에 몇단의 계단을 오르면 솟을대문이 서향하여 자리하며 대문 좌측으로 사랑채를 배치하였다. 안채로 들어가는 입구는 대문에서 상당히 많은 계단을 오르도록 하였고 문 없이 담사이를 비워 놓아 통행하도록 계획하였다.","a":"장흥 죽헌 고택","c":"시도민속문화유산","nc":"","r":"전남광주통합특별시","s":"장흥군","i":"http://www.khs.go.kr/unisearch/images/folklore_material/thumb/1658349.jpg"},{"q":"척화비란 조선 고종 때 병인양요와 신미양요를 승리로 이끈 흥선대원군이 서양사람들을 배척하고, 그들의 침략을 국민에게 경고하고자 서울 및 전국의 중요한 도로변에 세우도록 한 비로, 이 비도 그 중의 하나이다. 긴 돌을 이어 붙인 네모난 구역안에 서 있는 비는 머릿돌은 얹지 않은 간결한 구조이다. 비문에는 “서양오랑캐가 침략하는데 싸우지 않으면 화해할 수 밖에 없으나 화해를 주장하는 것은 나라를 파는 것이니 자손만대에 경고하노라”라는 강한 경고문구가 적혀 있다.","a":"청도척화비","c":"문화유산자료","nc":"","r":"경상북도","s":"청도군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1662588.jpg"},{"q":"경상남도 ○○군 북천면 직전리에 있는 불상으로, 암벽을 다듬어 불상이 들어 앉을 공간을 만들고 그 안에 조각하였다. 머리 부분은 도드라지게 새겼고 목 이하는 간단하게 윤곽선만을 묘사했다. 얼굴은 둥근 편이고, 세세한 부분은 닳아 없어져 분명하지 않지만 가늘게 뜬 눈, 꾹 다문 입 등에서 근엄한 표정이 나타난다. 오른손은 들어 올리고 왼손은 팔을 구부려 무릎 위에 올려 놓았으며, 옷주름은 신체 전반에 걸쳐 얕은 선으로 새겼다. 만든 양식으로 보아 통일신라시대 작품으로 추정된다.","a":"하동 이명산 마애여래좌상","c":"시도유형문화유산","nc":"","r":"경상남도","s":"하동군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1641696.jpg"},{"q":"향교는 공자와 여러 성현들께 제사를 지내고, 지방민의 교육과 교화를 위해 나라에서 세운 교육기관이다. ○○○○는 조선 중종 26년(1531)에 세웠다고 전하지만 근거가 있는 것은 아니며, 이후 몇 차례 자리가 바뀌었다가 인조 13년(1635)에 지금 있는 자리로 옮겼다고 한다. 현재 남아 있는 건물로는 대성전, 명륜당, 동재, 서재, 관리소 등 5개동의 건물과 문루인 석회루와 내삼문 등이다. 지금의 건물은 한국전쟁 중 파손된 것을 다시 짓거나 고쳐 옛 모습을 갖춘 것이다.","a":"홍천향교","c":"문화유산자료","nc":"","r":"강원특별자치도","s":"홍천군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/2304344.jpg"},{"q":"경상남도 사천시 사천읍 선진항의 북방에 있는 이 성은 삼면이 바다에 접하고 동쪽만 육지에 닿아 있는 반도 지형에 세워졌다. 조선시대에는 항구로 유명했으며 선진이 설치되기도 하였는데, 선진은 싸움터에서 앞장서는 군대를 뜻한다. 『읍지』와 『대동지지』의 기록을 보면 이 선진에는 전함이 1척, 병선이 1척, 하후선이 2척 있었다고 하여, 삼천진이라 불렸다. 선조 30년(1597)에 왜의 석만자가 이곳에서 지내면서 울산의 도산, 순천의 왜교와 더불어 3굴이라 불렀다고 한다.","a":"사천선진리성","c":"문화유산자료","nc":"","r":"경상남도","s":"사천시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1664592.jpg"},{"q":"연대는 횃불과 연기를 이용하여 정치 ·군사적으로 급한 소식을 전하던 통신수단을 말한다. 봉수대와는 기능면에서 차이가 없으나 연대는 주로 구릉이나 해변지역에 설치되었다. 낮에는 연기로 밤에는 횃불을 피워 신호를 보냈다. ○○○○○는 제주대 안 38개의 연대 가운데 원래의 모습이 잘 남아 있는 곳이다. 모서리마다 큰 판돌로 쌓아올려 연대를 만드는 제주도만의 특이한 방식을 잘 볼 수 있으며, 높이는 3.6m이다.","a":"말등포연대","c":"시도기념물","nc":"","r":"제주특별자치도","s":"서귀포시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1657798.jpg"},{"q":"일명 ‘절골’이라고 불리는 경상남도 ○○시 소탑동 ○○○에 있던 불상으로, 현재는 성산패총(城山貝塚) 경내로 옮겨 놓았다. 불신·광배·대좌를 모두 갖추고 있으며, 불상의 머리 부분은 시멘트로 보수하였다. 얼굴은 눈·코·입이 단아하게 표현되어 세련된 인상을 주며, 목에는 3개의 주름인 삼도(三道)가 뚜렷하다. 어깨는 떡 벌어졌으나 가슴의 탄력성이 사라지고 허리는 너무 잘록하게 처리되었다. 오른쪽 어깨를 드러내고 입은 옷은 ㄴ자에 가까운 평행한 옷주름을 이루고 있는데 도식적으로 표현되었다.","a":"창원 용화전 석조여래좌상","c":"시도유형문화유산","nc":"","r":"경상남도","s":"창원시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1641440.jpg"},{"q":"충청남도 홍성군 홍성읍 ○○○에 있는 불상으로 광경사지 미륵불이라고도 불린다. 머리에는 작은 소라 모양의 머리칼을 붙여 놓았고, 얼굴은 눈·코·입을 낮게 돋을새김하였다. 주먹코와 두툼한 입술, 길다란 눈 등이 매우 익살스러운 표정을 만들고 있다. 신체의 윤곽은 선으로 표현했으며, 앞면에만 조각을 하였다. 양 어깨를 감싼 옷을 걸치고 있으며, 가슴에서 발까지 U자형의 옷주름을 새겼다. 오른손은 가슴에 붙이고 왼손은 손바닥이 보이게 들고 있다. 조각수법이 거칠고 비례감각이 없는 점으로 보아 조선시대에 민간신앙의 대상으로 만들어진 듯하다.","a":"대교리석불입상","c":"문화유산자료","nc":"","r":"충청남도","s":"홍성군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1661155.jpg"},{"q":"○○○ 대적광전 아래쪽의 3층 석탑 앞에 자리하고 있는 ○○으로, 불교의식을 행할 때 불을 밝혀두는 기구이다. 등불을 밝혀두는 화사석(火舍石)을 중심으로, 아래에 3단의 받침을 두었고, 위로는 지붕돌과 머리장식을 얹었다. 높직한 4각 바닥돌은 한 면에 2개씩의 안상(眼象)을 새겼다. 그 위의 아래받침돌은 6㎝가량 층을 둔 다음 8잎의 연꽃무늬를 두었다. 가운데기둥은 후대에 와서 새로 만든 것으로 옛 모습을 찾을 수 없음이 안타깝다. 윗받침돌은 아래와 대칭되는 모습의 연꽃무늬를 새겼다.","a":"합천 해인사 석등","c":"시도유형문화유산","nc":"","r":"경상남도","s":"합천군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1642064.jpg"},{"q":"조선시대 우계 이시형이 살던 살림집이다. 이시형은 운악 이함의 아들로 학문과 재능이 뛰어났다. 선조 40년(1607)에 세운 이 가옥을 이함이 의령현감에 부임하면서 차남인 이시형이 관리하였다고 한다. 그러나 이시형이 27세 되던 해인 광해군 4년(1612) 과거에 응시하고 돌아오던 길에 외가에서 별세하였다. 그 뒤 약 400년간 보존하여 오늘에 이르고 있다.","a":"영덕 우계종택","c":"시도민속문화유산","nc":"","r":"경상북도","s":"영덕군","i":"http://www.khs.go.kr/unisearch/images/folklore_material/thumb/1659018.jpg"},{"q":"정무공 최진립(1568∼1636)이 살았던 곳으로 가옥의 사랑채에 해당된다. 처음에는 당호를 흠흠당이라 했는데 1760년경 건물을 수리한 후 ○○○으로 이름을 바꿨다. 건물은 앞면 4칸·옆면 2칸이며 지붕은 옆면이 여덟 팔(八)자 모양인 팔작지붕이다. 집의 구성은 정면의 ○○○을 중심으로 뒷면에 정침과 광채 그리고 흠흠당이 ㅁ자형으로 배치되어 있다. 오른쪽에는 제향공간이 있어 조선시대 상류주택의 전형적인 배치방법을 지니고 있다. 인근에는 선생을 추모하여 정려비각을 세우고 용산서원에 배향하였다.","a":"충의당","c":"시도민속문화유산","nc":"","r":"경상북도","s":"경주시","i":"http://www.khs.go.kr/unisearch/images/folklore_material/thumb/1658810.jpg"},{"q":"충암(冲菴) ○○은 ○○ 성족에서 출생하여 1507년 문과에 장원급제하여 정언(正言)ㆍ순창군수 등을 지냈으며, 폐비신씨 복위상소와 관련하여 파직되었다 복직하여 부제학(副提學)ㆍ동부승지(同副承旨)·도승지(都承旨)·이조참판(吏曹參判)·대사헌(大司憲)·형조판서(刑曹判書) 등을 역임하였다. 1519년 기묘 사화(己卯士禍) 때 제주도에 안치되었다 사사(賜死)되었고 후에 복권된 뒤 영의정으로 추증되는 등 충북을 대표하는 유학자이다.","a":"보은 김정 유허비","c":"문화유산자료","nc":"","r":"충청북도","s":"보은군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/2020032316224700.JPG"},{"q":"○○○란 임금이나 고관 등의 평생업적을 기록하여 그의 무덤 남동쪽에 세워두는 것으로, 이 비는 조선 중기의 문신인 ○○ 선생의 행적을 기리고 있다. ○○ 선생은 명종 1년(1548) 문과에 급제하여 승문원의 박사로 관직에 나아가 예조·이조판서를 지내었다. 공적인 것과 사적인 것을 분명히 하고, 효성이 지극하여 청백리(淸白吏)에 뽑혔으며, 저서로는『옥계문집』이 있다. 비의 형태는 거북받침돌 위에 비몸을 세우고, 용을 새긴 머릿돌을 얹은 모습이다.","a":"함양 노진 신도비","c":"시도유형문화유산","nc":"","r":"경상남도","s":"함양군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1642196.jpg"},{"q":"삼일중학교의 ○○○○○은 1923년에 건립된 학교 건물이다. 미국 매사추세츠 노스 ○○○교회의 도움을 받아 건립되었기 때문에 ○○○○○이라고 불린다. ○○○○○은 윌리엄 노블(W. Noble) 목사의 주선으로 미국 노스○○○교회의 기부와 수원시민 및 종로교회 교인들의 성금으로 지어졌다. 공사는 설립자이자 독립운동가로 평양감옥에서 병보석으로 풀려난 임면수의 총괄 지휘로 지어졌다. 지상2층 지하1층의 벽돌조 건물이다. 당시로는 드물게 주출입구가 중앙에서 오른편으로 치우쳐 지어졌는데, 이는 내부공간의 구성을 반영한 결과다.","a":"아담스기념관","c":"시도기념물","nc":"","r":"경기도","s":"수원시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1647094.jpg"},{"q":"○○○은 조선시대 「東國新續三綱行實圖」에 기록된 효자로서 국가로부터 정려를 받은 인물이다. ○○○○○는 17세기 전반부터 20세기 중엽에 이르기까지 전주이씨 임영대군 효자공파 6세손인 ○○○ 묘부터 13세손인 이명규 묘까지 조성되어 있다. 墓域은 구릉의 능선을 따라 李時振 墓, 李晩栽(○○○의 장자) 墓, 李世彦(이만재의 장자) 墓, 李億齡(이세언의 장자) 墓, 李顯昌(이억령의 장자) 墓, 5대에 걸친 직계 장손들의 ○○가 차례로 조성되어 있다.","a":"충주 이시진 묘소","c":"시도기념물","nc":"","r":"충청북도","s":"충주시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1651549.jpg"},{"q":"이 건물은 교동마을 東村(동촌) 중앙부에 자리 잡고 있는 근대한옥이다. 이 건물 주위에는 문화유산으로 기 지정된 ○○○○와 손정규가옥, 손대식 고가(문자 175호)가 위치하고 있다. 교동○○○○는 대문채, 중문간채(중사랑채), 안채, 아랫채 등 4동의 건물로 구성되어 있다. 당초에는 사랑채가 있었으나 30여 년전 다른 문중에서 재실로 사용하기 위해 매입하여 뜯어갔다고 한다. 안채는 1910년경에 건축된 정면 7칸 측면 1칸 반의 ‘역ㄱ자형’ 건물로, 건너방 앞으로 5칸 규모의 아랫채가 증축되어 있다.","a":"밀양교동밀성손씨고가","c":"문화유산자료","nc":"","r":"경상남도","s":"밀양시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1665891.jpg"},{"q":"○○○는 이애와 그의 아내 진성 백씨의 묘 근처에 세운 재실 건물이다. 이애(1480∼1561)는 황해도 관찰사를 지낸 근재공의 아들로 중종 10년(1515) 과거에 급제한 후 선전관, 사헌부 감찰, 경주 판관 등을 지냈다. 20여년간 병으로 벼슬에 오르지 못하다가 명종 15년(1560) 통정의 벼슬을 받았으나 이듬해에 죽었다. 명종 20년(1565) 처음 지은 ○○○는 효종 10년(1659) 고쳐 지은 뒤, 몇 차례의 보수공사를 하였는데 당시 건축의 원형이 잘 남아 있다.","a":"사암재","c":"문화유산자료","nc":"","r":"경상북도","s":"영덕군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1663111.jpg"},{"q":"임진왜란 때 진주성 싸움에서 순절한 ○○○ 장군의 유적지이다. ○○○ 장군은 고려 후기 문인 이규보의 8대손으로 조선 선조 16년(1583)에 무과에 급제하였다. 임진왜란이 일어나자 의병을 모집하여 선조 26년(1593)에 진주성 싸움에 참여하였다가 성이 함락되자 김천일, 최경회 장군과 더불어 석강에 투신, 순국하였다. 묘소는 장군이 살던 뒷산 남향 기슭에 있으며, 장군은 진주 충열사에 위패를 모셨다. 정문은 ○○○ 장군의 충절을 기리기 위하여 세운 것이며, 신도비는 정조 20년(1796) 송환기가 지어 강택중이 새긴 것을 순조 원년(1801)에 세웠다.","a":"영동 이의정 유적","c":"문화유산자료","nc":"","r":"충청북도","s":"영동군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1660721.jpg"},{"q":"이 석탑은 탑불이라 불리는 마을로부터 약 200m쯤 떨어진 옛 절터에 위치하고 있다. 현재 절터가 대부분 경작지로 변해 절의 규모를 파악하기 힘들뿐만 아니라 절의 내력을 전해주는 자료도 없어 이 탑이 어느 절의 것이었는지조차 알 수 없다. 이 석탑은 사각형으로 된 이중의 받침대를 두고 있어 통일신라시대의 일반 석탑 양식을 계승하고 있다. 그러나 전체적으로 간략화 된 조성 기법이 고려시대 이후의 변화 양상을 잘 보여주고 있다. 받침대 부분은 위 아래 받침 모두 모서리 기둥과 함께 중앙에 받침기둥을 새겼다.","a":"거창 갈계리 삼층석탑","c":"시도유형문화유산","nc":"","r":"경상남도","s":"거창군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1641508.jpg"},{"q":"○○○는 19세기 후반 1880년경에 창건된 사찰이라 한다. 극락보전에는 문화유산자료로 지정된 ○○ 2기가 모셔져 있다. 「석조여래좌상石造如來坐像」과 「목조보살입상木造菩薩立像」이 그것이다. 석조여래좌상(제주특별자치도 문화유산자료) 이 ○○은 돌로 만들어진 것으로, 높이가 59cm에 달한다. 몸체에 비해 큰 머리를 갖고 있으며, 상체가 낮으면서도 안정감을 주는 등 조선후기 특징이 보이는 ○○이다. 머리는 곱슬곱슬한 나발螺髮이며, 머리 위로는 상투와 같이 우뚝 튀어난, 즉 육계肉髻가 높이 솟아 있다. 머리와 육계 사이에는 반달모양의 계주髻珠, 즉 장식물이 있다.","a":"월정사 소장 불상(목조보살입상)","c":"문화유산자료","nc":"","r":"제주특별자치도","s":"제주시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1666839.jpg"},{"q":"공민왕의 부인인 노국공주를 모셨던 청주 양씨 시조, 양기 선생의 영정을 모신 사당이다. 이 지방에는 관청을 제외하고는 둥근기둥을 사용하지 않았는데, 사당에 둥근기둥을 사용한 점이 주목할 만하며, 약 200여년 전에 세운 건물로 보인다.","a":"창녕 경모당","c":"문화유산자료","nc":"","r":"경상남도","s":"창녕군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1663968.jpg"},{"q":"부도란 승려의 무덤을 상징하여 그 유골이나 사리를 모셔둔다. 이 부도는 ○○○ 내에 있는 7기의 부도 중 하나로, 절 북쪽의 화왕산으로 오르는 길 옆에 자리하고 있다. 2단의 바닥돌 위로, 아래·가운데·위의 세 받침돌로 이루어진 기단(基壇)을 쌓고, 공모양의 탑몸돌을 올린 후 사각 지붕돌을 올린 모습으로, 아래에 비해 윗부분의 몸집이 더 커 보인다. 아래 받침돌은 옆면마다 두 개의 공간을 만들어 무늬를 넣고, 윗면에는 연꽃무늬를 둘러 새겼다. 가운데 받침돌 역시 조각을 두었으나 무늬가 뚜렷치 않고, 윗받침돌 밑면에 새긴 연꽃무늬 역시 많이 닳아있는 상태이다.","a":"창녕 관룡사 승탑","c":"문화유산자료","nc":"","r":"경상남도","s":"창녕군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1663821.jpg"},{"q":"『금강경』의 내용을 요약하여 그림으로 해설한 책으로, 선조 3년(1570) 안동 광흥사에서 간행한 것이다. ‘금강경’은 ○○○○○밀경을 줄여서 부르는 것으로, 우리나라에서는 조계종의 근본경전으로 『반야심경』 다음으로 가장 많이 읽히는 불교경전이다. 변상도는 경전 속에 삽화 형식으로 배치되거나 책머리에 배치되는 두 가지 형식이 있는데 고려시대에는 삽화 형식으로, 조선시대에는 책머리에 붙여 두는 것이 일반적이었다. 이 책은 상단에는 그림, 하단에는 경문이 있는 상하 2단으로 구성되어 있어 조선 전기까지는 삽화 형식의『금강경』이 간행되었음을 알 수 있다.","a":"범어사 금강반야바라밀경변상","c":"시도유형문화유산","nc":"","r":"부산광역시","s":"금정구","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1636671.jpg"},{"q":"○○○ 하윤 선생 위패를 모신 재실로 세워졌으나 근래 담장의 우측으로 사당인 경인사를 짓고 위패는 사당에 모시고 있다. ○○○은 남북방향의 길이가 약간 더 긴 직사각형의 대지에, 대지의 우측으로 약간 벗어나서 ○○○과 대문채를 마주보게 배치하고 두 건물 사이의 좌측에 ○○○과 직각되도록 망추정을 앉혔다. ○○○은 정면 3칸, 측면 2칸의 건물로 3칸 모두 방을 들이고 있는데, 좌, 우 협칸은 방 1칸, 마루 1칸으로 구성한데 비하여 어칸은 방을 1칸 반으로 하고 반칸만 마루로 쓰도록 시설하여 가운데 방이 반 칸 돌출된 형상이다.","a":"진주 운수당","c":"문화유산자료","nc":"","r":"경상남도","s":"진주시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1665948.jpg"},{"q":"향교는 공자와 여러 성현께 제사를 지내고 지방민의 교육과 교화를 위해 나라에서 세운 지방 교육기관이다. 양민(良民) 이상이면 향교에 입학할 수 있었고 시나 문장을 짓는 사장학(詞章學)과 유교의 경전 및 역사를 공부하는 경학(經學)이 주요 교육내용이었다. 향교는 고을 크기에 따라 학생 수를 조정하였는데 대체로 군에서는 50명, 현에서는 30명의 학생을 수용하도록 하였다. 동국여지승람에 따르면 ○○○○는 1486년 이전에 건립된 것으로 추정되나 그 시기를 정확히 알 수 없다.","a":"안성향교","c":"문화유산자료","nc":"","r":"경기도","s":"안성시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1659945.jpg"},{"q":"전라남도 광양시 옥룡면 운평리 ○○○에 있는 보살상으로, 왼발을 올리고 오른발을 내린 ○○○이다. 두건을 쓰고 있어서 ○○○○을 표현한 것으로 간주되기도 한다. 이런 모습은 조선초까지 더러 보이는데 전라남도 강진 무위사의 아미타불상협시○○○○상이 그 대표적인 예이다. 얼굴은 네모 반듯한 모습에서 형식화가 엿보이지만 풍만하고, 체구도 다소 둔중하지만 친근함이 느껴진다. 옷은 스님들이 입던 장삼(長衫)을 걸치고 있어 독특한 모습이다. 대좌(臺座)는 맨 밑에만 보이는데 겹겹으로 된 연꽃무늬를 새겼고 발받침대도 있다.","a":"중흥사석조지장보살반가상","c":"시도유형문화유산","nc":"","r":"전남광주통합특별시","s":"광양시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1640018.jpg"},{"q":"전동제 저수지의 물길 위에 가로 놓여진 다리와 그 주변에 서 있는 2기의 비이다. 다리는 ‘도매다리’라고도 불리우며, 가까이 있는 부용산이 ‘약마부정(躍馬浮定:도약하려는 말의 자세) ’의 형태를 하고 있어 이 다리를 ‘○○○’라 부르게 되었다고 한다. 다리에 사용된 돌은 화강암으로, 이를 각이지게 다듬어 아래에 기둥을 세우고, 각 기둥 위로 넓적한 돌을 가로로 걸쳐 다리를 완성하였다. 본래는 지금의 길이보다 훨씬 더 길었다 하나, 1989년 여름 홍수 때 일부가 떠내려가 그 절반만이 남아있다.","a":"벌교도마교및석비","c":"시도유형문화유산","nc":"","r":"전남광주통합특별시","s":"보성군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1640107.jpg"},{"q":"만치당 김수남(1576∼1636)의 충절을 기리기 위해 세운 서원이다. 김수남은 조선 중기 문신으로 임진왜란 때 조정을 따라 강화도로 피난하였으나 그곳에 적군이 침입하자 순절하였다. 이 서원은 숙종 13년(1687) 가야곡면 조정리에 송시열, 송준길이 세웠는데 숙종 16년(1690)에 지금 있는 자리로 옮겼다. 정조 5년(1781)에는 매죽헌 성삼문과 송재 조계명의 위패를 추가로 모셨다. 그 뒤 고종 5년(1868)에 흥선대원군의 서원철폐령으로 서원이 철거되자 제단을 마련해 모시다가 1977년 사우를 세워 오늘에 이르고 있다.","a":"금곡서원","c":"문화유산자료","nc":"","r":"충청남도","s":"논산시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1661010.jpg"},{"q":"○○○는 신라 때에 처음 세운 사찰이라고 하며, 고려 말에 무학·나옹·지공대사 등이 거쳐간 곳이기도 하다. ○○○ 상량문에는 영조 12년(1736)년과 광무 3년(1899)년에 고쳐 지은 기록이 있다. ○○○○○은 석가모니를 모시는 건물로 앞면 3칸·옆면 2칸의 1층으로 되어 있다. 지붕 옆모습이 여덟 팔(八)자 모양인 팔작지붕으로, 지붕을 받치기 위해 장식하여 만든 공포가 기둥과 기둥 사이에도 있는 다포식이다. 기둥은 약간의 배흘림이 들어갔다.","a":"진주 응석사 대웅전","c":"시도유형문화유산","nc":"","r":"경상남도","s":"진주시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1641707.jpg"},{"q":"조선 인조 14년(1636) 병자호란이 일어났을 때 나라를 구하기 위해 목숨을 바쳐 싸우다 죽은 ○○○와 그의 충성스런 노비 억부의 충절을 기리기 위해 세운 비이다. ○○○는 광해군 10년(1618) 무과에 급제하여 남포현감을 지낸 분으로 병자호란 때 이천의 쌍령전투에서 그의 노비인 억부와 함께 전사하였는데, 시체를 찾지 못하여 옷과 관으로 제사를 지냈다. 정조 7년(1783) 왕의 명을 받아 세워 놓은 비로, 비문은 우승지 이정규가 짓고 정충필이 글씨를 썼다.","a":"손종로정충비각","c":"문화유산자료","nc":"","r":"경상북도","s":"경주시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1662983.jpg"},{"q":"장수읍의 향교 앞에 자리하고 있는 비로, 조선시대 중기 사람인 정경손의 의로운 뜻을 기리고 있다. 정경손의 호는 충복으로, 임진왜란 당시 향교내의 문묘(文廟)를 지키고 있었는데, 왜적의 한 부대가 이곳 장수지역에 침입하여 문묘에까지 이르자, 문을 굳게 닫고 무릎을 꿇고 앉아서 말하기를, “만약 문에 들려거든 나의 목을 베고 들라”하였다. 이러한 그의 늠름하고 당당한 태도에 감복한 왜적들은 ‘본성역물범(本聖域勿犯 : 이곳은 성스러운 곳이니 침범하지 말라)’이라 쓴 쪽지를 남기고 스스로 물러났다.","a":"정충복비","c":"문화유산자료","nc":"","r":"전북특별자치도","s":"장수군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1661657.jpg"},{"q":"경상북도 고령군 개진면 ○○○에 있는 고려시대의 석불로, 배모양의 평평한 돌에 새겼다. 전체적인 윤곽은 돋을새김하고 옷주름이나 연꽃무늬 등은 선으로 긋는 도식적인 수법을 사용하고 있다. 머리에 쓴 관(冠)에 작은 부처가 새겨져 있고 손에 연꽃가지를 쥐고 있는 것으로 보아 ○○○○상임을 알 수 있다. 머리에 쓴 관은 보통의 것과는 달리 丁자 모양을 하고 있어 완전히 토속화된 모습을 보이고 있다. 얼굴은 둥글 넓적한 모습이고 좁은 코, 작은 입 등에서 토속적인 느낌이 강하게 풍긴다.","a":"고령개포동석조관음보살좌상","c":"시도유형문화유산","nc":"","r":"경상북도","s":"고령군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1640466.jpg"},{"q":"○○○란 왕이나 고관 등의 평생업적을 기리어 그의 묘 남동쪽에 세워두는 것으로, 이 비는 안동 권씨의 시조(始祖)인 태사 권행(權幸)을 기리고 있다. 비는 받침돌 위로 비몸을 세우고 머릿돌을 올린 모습으로, 조선 현종 2년(1621) 권행의 24세손인 군수 권성원이 세웠다. 비문은 이후 우의정을 지내기도 한 허목선생의 글씨로 새겼다. 1971년에 비각을 세워 비를 보호하고 있다.","a":"권태사신도비","c":"문화유산자료","nc":"","r":"경상북도","s":"안동시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1662471.jpg"},{"q":"○○○는 청동기시대의 대표적인 무덤으로 고인돌이라고도 부르며, 주로 경제력이 있거나 정치권력을 가진 지배층의 무덤으로 알려져 있다. 우리나라의 고인돌은 4개의 받침돌을 세워 돌방을 만들고 그 위에 거대하고 평평한 덮개돌을 올려놓은 탁자식과, 땅 속에 돌방을 만들고 작은 받침돌을 세운 뒤 그 위에 덮개돌을 올린 바둑판식으로 구분된다. 남제주군 안덕면 창천리의 고인돌은 경사진 곳에 자리한 두 개의 밭 경계에 있다. 길이 2.5m, 너비 2.35m의 덮개돌은 4각형에 가까운 모양인데, 수평을 유지하기 위해 3군데에 높은 받침돌을 고였다.","a":"창천지석묘 1호","c":"시도기념물","nc":"","r":"제주특별자치도","s":"서귀포시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1657686.jpg"},{"q":"충청남도 일대에서 유행한 돌기둥 모양의 조각상으로 높이는 3.2m이다. 대체적으로 머리 부분과 몸체에 약간의 모양만 내어 단순함과 육중함만을 나타내었다. 머리에는 보관(寶冠)을 쓴 것으로 보이며 네모난 얼굴은 도식적이다. 이목구비는 돌이 많이 닳아 명확하지 않지만 얼굴의 크기에 비해 유난히 작게 표현하여 밋밋한 돌기둥 형식으로 보인다. 오른손은 배에 대고 왼팔은 가슴에 붙였는데 신체에 비해 팔이 작은 편이다. 원통형의 신체는 양감이나 조각형태가 거의 없고 옷주름을 판별하기 어려울 정도이다.","a":"석남동석불입상","c":"문화유산자료","nc":"","r":"충청남도","s":"서산시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1661250.jpg"},{"q":"이곳에서 지표채집된 유물을 통해 조선시대 전기의 분청사기와 조선시대 후기(17-18세기)의 백자와 옹기를 생산하였던 지방요로 추정되고 있다. 사남면 우천마을의 구룡못가에 위치하고 있는데, 일부는 구룡못 물속에 잠겨 있다. 가마터는 구릉면을 따라 길이 200여m, 폭 약 30m로 구룡못의 물속에 잠겨 있는 부분까지 한다면 그 면적이 꽤 넓은 것으로 여겨진다. 주변에는 가마 벽체의 일부분과 분청사기, 자기, 옹기 조각 등이 발견되고 있어 이 지역의 도자기 역사연구에 중요한 자료이다.","a":"사천우천리도요지","c":"시도기념물","nc":"","r":"경상남도","s":"사천시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1656998.jpg"},{"q":"조선 영조 28년(1752)에 현령 홍석이 지은 정자이다. 1911년 조선총독부에서는 ○○○을 국가에 헌납케 한 후 국고 수입을 올린다는 구실로 공개 처분한다. 이 때 수천리 송림마을의 임소환이 250원에 ○○○을 사서 용담현의 공동 소유물로 기증하여 오늘에 이르고 있다. 현재는 용담댐 건설로 망향의 동산에 새로 옮겨 지었다. 건물은 앞면 3칸·옆면 2칸 규모로, 지붕은 옆면에서 볼 때 여덟 팔(八)자 모양인 팔작지붕이다.","a":"태고정","c":"문화유산자료","nc":"","r":"전북특별자치도","s":"진안군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1661715.jpg"},{"q":"○○○란 옛 선현의 자취를 살피어 후세에 전하고 그를 기리기 위해 세우는 비로, 이 두기의 비들은 고려 후기의 문신인 ○○과 그의 동생 ○○의 공적을 기리고 있다. ○○의 호는 행촌으로 고려 충선왕 5년(1313) 과거에 급제하여 비성교감에 임명된 후 여러 관직을 거쳐 도관정랑이 되었다. 이후 충혜왕∼충목왕 대까지는 유배와 복직을 거듭하다가 공민왕 때에 수문하 시중이 되었다. 홍건적이 침략하여 개경을 핍박하자 왕을 모시고 안동으로 피난갔던 공이 인정되어 1등 공신이 되고 철성부원군에 봉하여졌다.","a":"고성 이암·이교 유허비","c":"문화유산자료","nc":"","r":"경상남도","s":"고성군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1664360.jpg"},{"q":"팔상(八=捌相)은 법화경의 주존불인 석가여래의 일생을 크게 8가지로 구분해서 설명한 것이다. ○○○은 법화신앙이 행해졌던 사찰에 많이 지어졌는데, 석가모니불을 주존으로 모시고 그가 살아가신 일생의 모습을 8폭의 탱화로 그려 모신 곳이다. ○○○○○은 조선후기(17세기경)에 건립되어 중수한 다포계 3칸 팔작지붕으로 대웅전에 버금가는 부속건물이다. 어간문은 4합, 양옆은 3합문으로 빗살문과 정(井)자 문을 하였다. 기둥에 배흘림과 안쏠림, 귀솟음이 나타나 전통적인 형식을 띄고 있으며, 불단 위에는 ‘亞’자형 닫집이 있어 매우 호화롭게 하였다.","a":"여수 흥국사팔상전","c":"문화유산자료","nc":"","r":"전남광주통합특별시","s":"여수시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1662301.jpg"},{"q":"향교는 공자와 여러 성현께 제사를 지내고 지방민의 교육과 교화를 위해 나라에서 세운 교육기관이다. ○○○○의 원래 자리는 알 수 없으나, 조선 태종 13년(1413) 지금 있는 자리에 옮겨 지은 후 여러 차례 수리하였다. 현재 남아 있는 건물로는 ○○○을 비롯하여 명륜당과 동재·서재가 있으며，출입구로 내삼문·외삼문·홍살문 등이 있다. ○○○은 공자를 비롯한 여러 성현의 위패를 모시고 제사를 지내는 곳이다．앞면 3칸·옆면 4칸의 규모이며, 지붕은 옆면에서 볼 때 사람 인(人)자 모양인 맞배지붕이다.","a":"임실향교대성전","c":"문화유산자료","nc":"","r":"전북특별자치도","s":"임실군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1661641.jpg"},{"q":"송파 박전과 그의 부인 신안 주씨의 유덕을 추모하기 위하여 후손들이 세웠다. 박전(1514∼1558)은 조선 명종 1년(1546)에 문과에 급제하여 호조정랑, 북평사를 역임하였고 명종 13년(1558)에 죽었다. 그 뒤 부인 주씨는 3년상을 치른 후 어린 아들과 함께 친정인 울진으로 갔다. 그리고 순흥 땅 화천리로 이사하여 아들 박선장을 남삼송에게 가르침을 받게 해 문과에 급제하여 크게 이루니, 후세 사람들이 주씨 부인의 행적을 추모하여 정자를 세웠다.","a":"몽화각","c":"문화유산자료","nc":"","r":"경상북도","s":"봉화군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1662708.jpg"},{"q":"임진왜란 때 활약한 무신 ○○○의 가문에 내려오는 ○○○들이다. ○○○은 아버지 이선경이 왜적과 싸우다 전사하자 18세 때 이충무공 휘하에 들어가 명량해전에서 공을 세워 9품직을 제수 받았으며, 명나라 구원병으로 원병을 청하자 우영장으로 들어가 공을 세우고 전사하였다. 이러한 공로로 순조때 증직되었으며, ‘충의’라는 시호까지 부여받았다. 또한 용정사에 이충무공과 함께 배향되고 있다.","a":"연안이씨 이유길 가전 고문서","c":"시도유형문화유산","nc":"","r":"전북특별자치도","s":"무주군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1639577.jpg"},{"q":"현재 ○○○ 대웅전 석가불상의 후불도로 봉안된 ○○○○○로서, 화기에 의하면 1899년(광무 3년)에 조성하여 삼각산 청룡암 칠성각에 봉안하였으며, 화사로는 윤감(允鑑), 재겸(在謙) 등이 참여하였다. 이 불화는 ○○○○상을 중심으로 좌·우 3열 층단식 구도를 이루며 시왕 및 권속들이 배치되어 있다. 가로로 긴 화폭 중앙에 ○○○○상과 도명존자·무독귀왕이 삼각형 구도를 이루고 있으며, 다시 2열 횡대를 이루며 시왕상들이 그려져 있다. 상단에는 두루마리를 든 사자와 동녀, 장군과 옥졸, 판관과 팔부신중 등의 인물상들이 배치되어 있다.","a":"지장암 지장보살도","c":"시도유형문화유산","nc":"","r":"서울특별시","s":"종로구","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1636488.jpg"},{"q":"영도와 부산을 잇는 연육교인 ○○○○는 1932년 3월에 착공하여 1934년 11월에 개통된 길이 214.7m, 폭 18.3m의 우리나라 최초의 연육교이다. 하루 총 6회씩 도개하여 부산의 명물로 자리하였고 1966년 9월 증가하는 차량 통행으로 인하여 도개 기능이 멈추게 되었으나, 2013년 11월 27일에 기존 4차선을 6차선으로 복원․개통하여 매일 오후 2시에 도개를 하고 있으며, 부산의 명소로 옛 명성을 다시 찾고 있다.","a":"영도대교","c":"시도기념물","nc":"","r":"부산광역시","s":"영도구","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/2307932.jpg"},{"q":"‘○○○’는 중부 내륙의 명산인 보개산에 있다. 환희봉(지장봉)의 서남쪽 골짜기에 3단의 석축을 쌓아 대지를 조성했다. 『유점사 본말사지』에 따르면 ○○○는 신라 진덕여왕 원년(647) 영원 조사가 창건하여 흥림사라 하였다고 한다. 859년(신라 헌안왕3)에 범일 국사가 재창했으며, 1393년(조선 태조2)에 화재로 소실되었다. 1396년(태조 5)에 무학 대사가 개건하면서 사명을 ○○○로 바꾸었다고 한다. 내산리 계곡 깊은 곳에 있는 ○○○는 구한말 의병들의 주요 근거지였다. 당시에 의병장 허위가 이끄는 800여 명의 의병들이 ○○○에 주둔하고 있었다.","a":"연천심원사지","c":"시도기념물","nc":"","r":"경기도","s":"연천군","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1647480.jpg"},{"q":"남이웅(1575∼1648) 선생의 영정을 모신 사당으로 광무 10년(1906) 유림들이 세웠다. 조선 선조, 광해군, 인조 때 정치가였던 선생은 평소 법을 준수하고 사치를 하지 않은 인물이었다. 광해군 5년(1613) 문과에 급제하여 예조좌랑, 병조좌당 등 여러 벼슬을 하였으며, 병자호란 때는 소현세자가 중국 심양으로 잡혀갈 때 극진히 모시고 따가갔다와 후에 춘성부원군에 봉해졌다. 인조 16년(1638) 대사헌이 된 후 법을 철저하게 집행하였으며, 미신을 없애려고 무당을 박해하기도 하였다. 사당 뒤쪽으로 선생의 묘소와 묘비가 있다.","a":"금남 남산영당","c":"문화유산자료","nc":"","r":"세종특별자치시","s":null,"i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1666861.jpg"},{"q":"○○○은 청동기 시대의 대표적인 무덤으로 주로 경제력이 있거나 정치권력을 가진 지배층의 무덤으로 알려져 있다. 거대한 덮개돌[上石]이 지상에 드러나 있고 그 밑에 고임돌[支石], 묘역시설(墓域施設), 무덤방 등이 있는 구조를 가지고 있다. 하지만 지역과 시기에 따라 그 형태는 매우 다양하다. 일반적으로는 무덤방이 지상에 위치한 탁자식(卓子式)과 지하에 위치한 기반식(碁盤式) 또는 바둑판식으로 분류하고 있으며, 지하에 무덤방이 위치하지만, 거대한 덮개돌 아래에 고임돌을 두지 않는 형식을 별도로 개석식(蓋石式), 또는 무지석식(無支石式)이라 칭한다.","a":"연천학곡리고인돌","c":"시도기념물","nc":"","r":"경기도","s":"연천군","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1646840.jpg"},{"q":"송안군 이자수 선생의 덕을 기리기 위해 조선 성종 11년(1480)에 세운 것으로 후학들이 공부를 하던 강당과 선생께 제사를 올리는 주사로 구성되어 있다. 강당은 앞면 5칸·옆면 2칸 크기로 왼쪽 높은 터에 자리잡고 있다. 옆면에서 볼 때 지붕선이 여덟 팔(八)자 모양과 비슷한 팔작지붕 건물로 가운데 3칸은 대청, 양쪽 끝칸은 온돌방으로 꾸몄다. 주사는 ㅁ자 평면을 가지고 있는 건물이다. 덕 깊은 선생의 전통과 함께 일반적인 이 지방 주택형태와 소박함을 느낄 수 있는 곳이다.","a":"작산구강당및주사","c":"시도민속문화유산","nc":"","r":"경상북도","s":"안동시","i":"http://www.khs.go.kr/unisearch/images/folklore_material/thumb/1658500.jpg"},{"q":"○○○○○은 치성광여래(熾盛光如來)를 위시한 칠성여래(七星如來)와 일광·월광보살 및 칠원성군(七元星君)과 8권속을 비단 바탕 위에 먹과 채색안료를 사용하여 제작한 불화이다. 전체적인 구도는 화면을 크게 양분하여 상단 중앙에는 청연화좌(靑蓮花座)에 결가부좌한 치성광여래를 일광· 월광 두 협시보살과 함께 삼각형의 구도로 배치하고 있다. 협시보살 측면에는 좌우 각각 4구씩 8권속을 묘사하고 있으며, 주존 광배 후면 양 측면에는 6여래를 각각 3위씩 나누어 배치하고 있다.","a":"함안 능가사 칠성탱","c":"문화유산자료","nc":"","r":"경상남도","s":"함안군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1665854.jpg"},{"q":"부도는 승려의 무덤을 상징하여 그 유골이나 사리를 모셔두는 곳이다. 이 부도밭은 ○○○에서 상원사로 가는 길의 전나무 숲속에 자리하고 있는데, 모두 22기에 이르는 부도들이 흩어져 있다. 운공성관(雲空性觀)·금성당(金聖堂) 등의 호를 가진 승려들의 사리를 모시고 있는 이 부도들은 낮은 받침위로 종모양의 탑몸돌을 올린 모습들이 대부분이나, 2층 기단(基壇)과 지붕돌을 갖춘 부도의 모습도 간혹 눈에 띈다. 크기는 1∼2m 내외의 그리 높지않은 체구로, 조선시대 중기 이후에 세웠을 것으로 추측된다.","a":"월정사부도군","c":"문화유산자료","nc":"","r":"강원특별자치도","s":"평창군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1660404.jpg"},{"q":"봉석주(1418∼1465)의 위패를 모신 사당으로 일명 강성사 또는 하음사라고 한다. 봉석주는 조선 단종 1년(1453)에 세조를 도와 김종서 등 단종추대 세력을 타도하기 위한 계유정란에서 공을 세워 정난 2등 공신이 된 인물이다. 이 사당은 숙종 20년(1694)에 지었고 1926년에 고쳐 지었으며 1970년에 보수한 것이다. 앞면 3칸·옆면 1칸 반 규모로, 지붕은 옆면에서 볼 때 사람 인(人)자 모양을 한 맞배지붕이다.","a":"청주 모충사","c":"문화유산자료","nc":"","r":"충청북도","s":"청주시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1660726.jpg"},{"q":"백제 장군인 계백과 박팽년·성삼문·이개·유성원·하위지·유응부 등 사육신을 추모하기 위해 세운 서원이다. 계백은 백제 장군으로 신라의 김유신과 당나라의 소정방을 중심으로 구성된 나·당연합군이 쳐들어오자 황산벌에서 용감히 싸우다 전사하였다. 사육신은 수양대군이 단종의 왕위를 빼앗자 단종의 복위를 꾀하다가 발각되어 죽은 6명의 신하를 말한다. 숙종 6년(1680)에 세운 이 서원은 흥선대원군의 서원철폐령으로 고종 5년(1868)에 폐쇄되었고 1933년 복원하였다.","a":"충곡서원지","c":"시도기념물","nc":"","r":"충청남도","s":"논산시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1651849.jpg"},{"q":"만운 ○○○의 영정을 모신 곳이다. ○○○은 조선 중기의 무신으로 미천한 집에서 태어났다. 병조판서 이항복에게 사서를 배웠으며 머리가 총명하였다. 임진왜란이 일어나자 권율 장군 아래에서 종군하였고 키가 작으면서도 씩씩하여 덕장이라는 칭송을 들었다. 이괄의 난이 일어나자 이를 평정하여 1등 공신으로 책정되고 ○○○에 봉해졌다. 천문·지리·복서·의술 등 다방면에 걸쳐 뛰어났으며 청렴하기로 이름이 높았다. 시호는 충무(忠武)이다.","a":"금남군정충신영정각","c":"문화유산자료","nc":"","r":"전북특별자치도","s":"장수군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1661647.jpg"},{"q":"현 소유자의 조부가 이곳으로 이주하면서 처음 지었으나, 한국전쟁 때 폭격으로 무너지고, 1953년 조규팔 씨가 새로 지어 오늘에 이르고 있다. 가옥은 대문간채가 없는 ㄷ자형 구조로 안채와 사랑채로 구성되어 있다. 곳간 뒷면과 사랑채 툇마루는 외부로 노출되어 있다. 안채는 앞면 3칸·옆면 2칸 규모로 부엌·건넌방·안방으로 구성되어 있다. 안방은 원래 방 중간에 미닫이문이 있고, 옆면에 툇마루가 이어져 있었으나, 모두 헐고 안방 공간으로 넓혔다. 사랑채는 행랑채·작은사랑·큰사랑으로 구성되며, 사랑방 앞에는 툇마루를 두어 사용하기 편리하게 하였다.","a":"강릉조철현가옥","c":"문화유산자료","nc":"","r":"강원특별자치도","s":"강릉시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1660490.jpg"},{"q":"○○○의 여러 부처와 보살을 모시고 종교의식을 치르는 건물인 불전 중에서 가장 중심이 되는 건축물이다. ○○○○○은 임진왜란으로 불에 타 없어져 1684년에 다시 짓고, 1725년에 크게 수리한 것이다. 건물의 생김새를 보면 별도의 축대는 없이 거칠게 다듬은 자연석 기단만 한 단을 두고, 자연석 주초와 둥근 기둥을 사용하여 몸통을 구성하고, 지붕은 옆면이 수직으로 마감되는 맞배지붕을 하고 있다. 지붕 아래쪽 처마와 기둥 사이에는 건물의 무게를 지탱하고, 화려하게 돋보이도록 하는 장치인 공포를 앞뒤에만 두고, 옆면에는 두지 않았다.","a":"석남사대웅전","c":"시도유형문화유산","nc":"","r":"경기도","s":"안성시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1637541.jpg"},{"q":"퇴계 이황의 학문을 계승한 정재 유치명(1777∼1861)의 종가이다. 증조부인 유관현이 조선 영조 11년(1735)에 세운 이 집은 원래 임동면에 있었으나 임하댐 건설로 1987년 지금 있는 자리에 옮겨 세운 것이다. 대문채, 정침, 사당으로 구성되었는데, 정침은 안채와 사랑채를 포함한 건물로 ㅁ자형 평면을 갖추고 있다. 앞쪽에는 사랑채를 구성하고 뒤쪽에는 안채를 두었으나 앞·뒤 공간이 안쪽에서 연결되지 않고 분리되어 있다. 사랑채에서 안채로 들어가려면 건물 오른쪽에 있는 중문을 통해서만 출입할 수 있게 하였다.","a":"안동 정재종택","c":"시도기념물","nc":"","r":"경상북도","s":"안동시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1654729.jpg"},{"q":"○○○ 대웅전 앞에 서 있는 탑으로, 다른 곳에 있던 것을 이곳으로 옮겨온 것이다. 원래는 2층 기단(基壇) 위에 5층의 탑신(塔身)을 올리고 있었으나 현재는 4층까지만 남아 있다. 탑신의 몸돌은 이 탑에서 가장 주목되는 부분으로, 평면이 모두 사다리꼴이 되도록 윗면의 폭을 좁혔다. 이는 층수가 올라감에 따른 시각적 안정감을 주기 위한 것으로 생각된다. 지붕돌은 밑면의 받침을 1·2층은 3단, 그 이상은 모두 2단을 두었고, 수평을 이루던 처마는 네 귀퉁이에서 살짝 들려 있다. 꼭대기에는 머리장식을 받치던 네모난 받침돌만 남아 있다.","a":"함안 장춘사 오층석탑","c":"시도유형문화유산","nc":"","r":"경상남도","s":"함안군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1641492.jpg"},{"q":"2층 기단(基壇) 위에 5층의 탑신(塔身)을 올린 모습이다. 아래층 기단은 편편한 4매의 돌로 짜맞추고, 위층 기단은 모서리마다 기둥 모양을 조각하였다. 기단 맨윗돌 위에는 높은 괴임을 두었는데, 이곳에 난간모양을 새겨놓아 독특한 특징이 되고 있다. 탑신의 1층 몸돌 4면에는 중앙을 직사각형모양으로 얕게 파내었다. 지붕돌은 밑면에 5단씩의 받침을 두었다. 꼭대기에는 노반(露盤:머리장식 받침)과 복발(覆鉢:엎어놓은 그릇모양의 장식)이 남아 머리장식을 하고 있다.","a":"남복리오층석탑","c":"시도유형문화유산","nc":"","r":"전북특별자치도","s":"정읍시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1639508.jpg"},{"q":"○○군 관산읍 방촌의 내동마을 안쪽 깊숙한 곳에 자리한 ○○위씨 종가댁이다. 방촌마을은 ○○위씨 집성촌으로 임진왜란이 지난 뒤 17세기 초엽에 동족적 기반을 마련하기 시작하고 위덕화(1551∼1598)의 장남 위정철(1583∼1657)이 방촌으로 옮겨오면서 자리를 마련한 곳이 현재의 위성렬 가옥이다. 이 자리는 고려시대 ○○부의 동헌이 있던 터로 알려지고 있다. 위성렬 가옥은 서향으로 안채와 사랑채 등이 자리하고 있는데 현재 사당, 안채, 사랑채, 그리고 헛간채로 구성되어 있다.","a":"장흥 죽암 고택","c":"시도민속문화유산","nc":"","r":"전남광주통합특별시","s":"장흥군","i":"http://www.khs.go.kr/unisearch/images/folklore_material/thumb/1658414.jpg"},{"q":"○○시 무안면 내진리에 자리잡고 있는 ○○○○은 조선 순조 13년(1813)에 별사를 창건하여 문안공 산화 이견간(李堅幹)과 성산군 이식(李軾)을 봉안한 서원이다. 순조 18년(1818)에 장소와 건물이 협소하여 현재의 위치로 옮기고 용안사라고 편액하였다. 1870년에 훼철된 후 용안재(龍安齋)로 개액(改額)하였으며, 1922년부터 설단(設壇)하여 여은 이사지(李思之)와 대호군 이중림(李中林)을 추가로 봉안하고 향사하였다. 1983년에 용안사 옛터에 사우를 중건하고 재사를 중수하여 위패를 봉안하였으며 매년 9월에 향사를 지내고 있다.","a":"밀양 용안서원","c":"문화유산자료","nc":"","r":"경상남도","s":"밀양시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1664730.jpg"},{"q":"이 ○○은 ○○에 약 500여년간 세거해 온 안동권씨 사용공파의 대표적인 건물이다. 경북 북부지역의 뜰집이 튼 ‘ㅁ’ 자형에서 ‘ㅁ’ 자형으로 발전하는 과정의 배치형태, 중부형 살림채의 평면구성, 살림채에 정자까지 갖춘 상류주택이다. 일부 수리가 있긴 했으나 건립시의 입체적인 벽면 구성과 구조·형태는 잘 간직하고 있어 당시의 가옥구조 및 주생활 연구에 좋은 자료가 된다.","a":"영주 원리 도율종중 고택","c":"문화유산자료","nc":"","r":"경상북도","s":"영주시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/2018101510263500.jpg"},{"q":"무안지서 바로 옆에 자리하고 있는 비로, 현재는 돌담이 둘러진 비각안에 보존되어 있다. 사명대사의 충절을 기리고 있는 비로, 일명 ‘사명대사비’라고도 불리운다. 비는 네모난 받침돌 위로 비몸을 세우고, 맨 위에 머릿돌을 얹은 구조로, 특이하게도 비몸은 까만 대리석을 사용하였다.","a":"밀양 표충비","c":"시도유형문화유산","nc":"","r":"경상남도","s":"밀양시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1641364.jpg"},{"q":"○○시 상당구 가덕면 백족산 정상부 남쪽 기슭에 있는 ○○○ 대웅전 안에 봉안된 ○○○○○이다. ○○○의 연혁을 알려주는 문헌기록은 없으나 경내에 고려시대에 조성된 석탑과 조선시대의 석물들이 남아 있어 이 사찰이 고려시대에 창건되어 조선 전기까지 법통法統이 이어졌던 것으로 추정된다. 본래 ‘심진암尋眞庵’이라는 암자였다가 산 명칭에 따라 절 이름을 바꾸었다고 한다. 현재의 ○○○는 옛 절터에 1930년 대웅전을 다시 세우고 중창한 것으로 대웅전과 삼성각, 요사채가 있다.","a":"청주 백족사 석조여래좌상","c":"문화유산자료","nc":"","r":"충청북도","s":"청주시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/2019042311510000.jpg"},{"q":"불규칙한 모양의 자연석을 쌓아 만든 고려시대의 석탑이다. 탑에 대한 기록은 물론 주변에 관한 기록도 전하지 않는다. 탑은 건물터 만큼 넓게 낮은 단을 마련하여 그 위에 계단모양의 층단을 만들었다. 1, 2단에 걸쳐 네 면에 목탑에서처럼 감실(龕室)을 파서 불상을 모셔두었다. 현재 윗부분이 무너져 원래 몇층이었는지 알 수 없고, 기단과 탑신의 구분도 애매한 독특한 형식의 탑이다.","a":"의성석탑리방단형적석탑","c":"시도유형문화유산","nc":"","r":"경상북도","s":"의성군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1640974.jpg"},{"q":"이 자료는 운고 김재윤(1808~1893)의 문집 ○○으로 현재 한국국학진흥원에 보관되어 있다. 김재윤은 류치명, 이종상 등과 교류하면서 평생 학문과 후진교육에 힘썼다. 80세에 증직으로 가선대부 동지중추부사 겸 오위장을 제수받았다. 비록 널리 알려진 인물은 아니지만 결판이 없고 조선시대 말 지방에서의 서적간행을 보여주므로 자료적 가치가 높다.","a":"포항 김해김씨 유수공파 소동문중 소장 판목","c":"문화유산자료","nc":"","r":"경상북도","s":"포항시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/2017122210414000.jpg"},{"q":"이 영정은 근암당선사의 좌안7분면 바닥가부좌상으로, 왼손에 주장자를, 오른손엔 염주를 쥐고 측면을 향해 앉아있다. 선사 뒤 편으로는 녹색바탕에 연화문이 그려진 상단벽면과 하단돗자리의 이단구도를 배경으로 하여 도식화된 등받이 장식을 배치하였다. 화면 향좌측엔 ‘선교양종근암당대사영(禪敎兩宗勤岩堂大師影)’의 화제가 있으며 향우측에는 영찬(무하명주당천랑월내형내상기성 기심영칙비진진칙비영○○□ 간합소유신 문족덕민근찬 ,無瑕明珠當天朗月乃形乃像其性 其心影則非眞眞則非影眞影□ 間合所留神 門足德旻謹讚) 이 있다. 화면 크기는 가로 79.0cm, 세로 111.8cm이다.","a":"금암당 진영","c":"시도유형문화유산","nc":"","r":"경상남도","s":"양산시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/0000000001643024.JPG"},{"q":"1946년에 지은 집으로 안채, 문간채 등과 축사를 갖추고 있다. 안채는 앞면 6칸·옆면 1칸 규모의 건물로 왼쪽에서부터 방·부엌·큰방·대청마루·건넌방 순으로 되어 있다. 큰방과 대청마루, 건넌방 위에는 대청 다락방을 설치하였는데 3칸 규모로 넓고 높이도 높아 특이하다. 문간채는 앞면 5칸·옆면 2칸 규모이며 지붕은 서양식 기와를 얹었다. 외양간·대문·방·헛간·뒷간으로 구성되어 있다.","a":"김봉호가옥","c":"문화유산자료","nc":"","r":"전남광주통합특별시","s":"광산구","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1659682.jpg"},{"q":"조선시대 능주지방에 파견된 지방관이 업무를 보던 건물인 녹의당의 정문이다. 선조 32년(1599)에 문을 수리했다는 기록으로 보아, 능주목사로 부임한 정윤이 녹의당을 지을 때 함께 지은 것으로 보인다. 앞면 3칸·옆면 2칸 규모이며, 지붕은 옆면에서 볼 때 여덟 팔(八)자 모양인 팔작지붕이다．지붕 처마를 받치기 위해 장식하여 만든 공포는 간결하게 짜여 있다. 건물에는 당대의 문필가인 정이(1568∼1625)가 쓴 현판이 걸려 있다. ○○○○○은 전라남도에서 보기 드문 구조를 가진 간결하고 아름다운 건물이다.","a":"죽수절제아문","c":"문화유산자료","nc":"","r":"전남광주통합특별시","s":"화순군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1661993.jpg"},{"q":"○○○은 전면 3칸 측면 2칸의 소로수장 주두집으로 5량 가구구조의 팔작지붕의 재실용도의 한옥이다. ○○○의 평면은 대청마루가 3칸의 ㄱ자형으로 구성되고 온돌방도 3칸의 ㄴ자형으로 구성되어 서로 마주보는 마루와 온돌방의 구성을 취하고 있어 조형적이면서 기능적으로 영역의 조화로운 안배를 이루고 있는 것으로 파악된다.","a":"합천 임강정","c":"문화유산자료","nc":"","r":"경상남도","s":"합천군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1666607.jpg"},{"q":"이 불화는 1887년에 혜산 축연과 허곡 긍순이 함께 조성한 ○○○로서 상궁들의 시주로 조성되었다. 천부중과 천룡팔부를 한 폭에 묘사한 형식이라든가 산신과 조왕신이 위태천의 협시로 등장하는 점, 주악천녀의 등장 등은 전형적인 19세기 신중탱화의 전형적인 특징을 보여주고 있으면서도 다양한 존상의 세밀한 표현과 균형을 이루는 구성과 더불어 화사(畵師)의 필력이 돋보이는 작품이다.","a":"경국사 신중도","c":"시도유형문화유산","nc":"","r":"서울특별시","s":"성북구","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/2594874.jpg"},{"q":"읍성이란 군이나 현의 주민을 보호하고, 군사적·행정적인 기능을 함께하는 성을 말한다. 충청남도 당진군 면천면 소재지의 거의 전역을 둘러싸고 있는 읍성으로 조선 초기에 쌓은 것이다. 성의 둘레는 약 1,200m이고 성벽은 자연석을 다듬어 축조하였는데, 저수지 공사 등의 사업에서 이곳의 돌을 빼다 써서 현재는 유실된 부분이 많다. 서쪽 성벽과 남쪽 성벽이 비교적 잘 남아 있는데, 서벽의 경우 높이가 3.6m정도이다. 서벽의 안쪽 부분은 사다리꼴 모양으로 비탈지게 쌓았으며 바닥의 폭이 6.8m, 윗면의 너비가 2.4m이다.","a":"당진면천읍성","c":"시도기념물","nc":"","r":"충청남도","s":"당진시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1652838.jpg"},{"q":"헌종 10년(1844)에 지은 건물이며, 1975년 안동댐 건설로 인한 수몰때문에 현재의 위치로 옮긴 것이다. 원래는 평산 신씨가 지은 건물인데 1940년에 현재의 소유자가 집을 사서 자기의 아버지 호를 따 ‘○○○’라 하였다. ㅁ자형의 안채와 一자형의 사랑채로 구성되어 있다. 안채는 이 지방의 전형적인 살림채 모습을 잘 간직하고 있으며, 사랑채는 一자형으로 안채와 분리하여 따로 세웠다. 앞면 3칸·옆면 2칸으로 지붕은 옆면이 여덟 팔(八)자 모양의 화려한 팔작기와지붕으로 꾸몄다.","a":"안동예안동간재고택","c":"시도민속문화유산","nc":"","r":"경상북도","s":"안동시","i":"http://www.khs.go.kr/unisearch/images/folklore_material/thumb/1658448.jpg"},{"q":"○○○은 고려 공민왕 원년(1352)에 해경대사와 월산대사가 세운 절이다. 절 이름은 이 두 스님의 이름에서 따와 ‘○○○’이라 하였다. 조선 명종 11년(1556)에 남원부사가 고쳐 세웠고 영조 23년(1747)에는 거사 양정봉이 고쳐 지었으며, 철종 9년(1858)과 1915년에 다시 고쳐 지어 오늘에 이르고 있다. 현존하는 건물로는 인법당(因法堂)인 본전을 비롯하여 산식각, 요사채 등이 있다. 본전은 ㄱ자형으로 한쪽 지붕은 옆면에서 볼 때 여덟 팔(八)자 모양인 팔작지붕이고, 다른 한쪽은 앞면이 사다리꼴인 우진각지붕으로 꾸몄다.","a":"해월암","c":"문화유산자료","nc":"","r":"전북특별자치도","s":"임실군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1661639.jpg"},{"q":"광주 ○○○은 1990년대 초반에 중창된 사찰이다. 중창 당시 이곳에 출토된 것과 다른 곳에서 이곳으로 옮겨진 ○○의 부도가 전하고 있다. 첫 번째 부도는 관음전 건립 시 출토된 것으로 전한다. 기단부의 하대석과 중대석은 팔각형이며, 탑신석은 원구형으로 마련하였다, 옥개석(석탑이나 석등 따위의 위에 지붕처럼 덮는 돌)은 사각형의 우진각지붕 형태로 구성하였는데, 낙수면에 기왓등이 표현되었고, 마루부를 높게 하여 그 끝에 높게 돌출된 용머리를 조각하였다.","a":"우리절 석조부도 2기","c":"문화유산자료","nc":"","r":"경기도","s":"광주시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1660299.jpg"},{"q":"고려 후기의 문신인 ○○ 이제현(1287∼1367) 선생의 초상화이다. 선생은 원나라의 만권당에서 조맹부 등과의 교류를 통해 고려에 신학문과 사상 등을 소개하고 성리학의 전파와 발전에도 중요한 역할을 했다. 조맹부 글씨를 도입했으며『국사』,『역옹패설』등을 저술하였다. 선생의 초상화는 모두 4점이 전하는데 그 중 1점으로, 고려 충숙왕 6년(1319) 선생이 왕을 따라 중국에 갔을 때 진감여가 그렸던 원본(국립중앙박물관 ○○)을 18세기 후반에 옮겨 그린 것이다. 왼쪽을 바라보며 의자에 앉은 전신상으로, 두 손은 소매 안에서 마주잡고 있다.","a":"장성 가산사 소장 익재 영정","c":"문화유산자료","nc":"","r":"전남광주통합특별시","s":"장성군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1662147.jpg"},{"q":"○○○○○은 지금은 폐사(廢寺)되고 그 터만 남아 있는 용기사(龍起寺)에서 생활했던 승려들이 음식을 만들 때 사용했던 석조(石槽)와 맷돌이다. 석조는 가로 160㎝, 세로 120㎝에 높이 73㎝, 깊이 52㎝정도의 크기로 길쭉하게 모를 죽인 직사각형 형태를 하고 있으며 완형으로 남아 있다. 속이 깊고 안쪽 바닥 한켠에 구멍을 뚫어 놓아 배수가 되도록 하였으며, 안쪽 구멍은 매끈하게 다듬었는데 비하여 바깥쪽은 적당히 다듬었다. 전체적으로 둔중한 편이나 소박한 멋이 있다.","a":"성주 용기사지 석조유물","c":"문화유산자료","nc":"","r":"경상북도","s":"성주군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/2018103021001700.jpg"},{"q":"조계종 사찰의 거제 본산으로 약 300년 전에 고성군 하이면의 옛 절터에서 옮겨온 향나무 조립식 ○○○상을 봉안하고 있으며, 머리, 몸, 팔, 다리 등으로 구분 조각하여 조립식으로 되어 있고, 불신(佛身)내부의 복장품 중 발원문에는“康熙四十二年癸未五月日華功安干臥龍山深寂菴”이라고 쓰여 있어 이 불상이 1703년(숙종 29년)에 와룡산 심적암에서 제작되었음을 알 수 있다. 지금은 ○○○의 중건시기는 약 100여년전이라고 하며, 일본의 자료에 의하면“대한제국때 거제면에 고찰이 있었다”고 적고 있어 ○○○을 가리키는 것으로 생각된다.","a":"거제세진암목조여래삼존불좌상","c":"문화유산자료","nc":"","r":"경상남도","s":"거제시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1664961.jpg"},{"q":"옥천 조씨 절민공파의 종가로 조선 숙종 2년(1676)에 조치형(1642∼1754)이 지었다고 한다. 이 마을은 약 550여년 전에 옥천 조씨 조지곤이 처음으로 살기 시작하여 형성되었다. 마을에는 친족간에 화목과 우애를 돈독히 하는 감락재가 남아 있으며, 귀두정과 경운각이 있었다고 하나 지금은 남아 있지 않다. 안채, 사랑채, 문간채, 곳간, 제실, 아래채, 중문간 등으로 구성되어 있으며, 솟을대문이 있던 곳에는 주춧돌만 남아 있다.","a":"승주조승훈가옥","c":"문화유산자료","nc":"","r":"전남광주통합특별시","s":"순천시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1662170.jpg"},{"q":"조선 후기 실학의 대가인 석정 이정직(1842∼1910)의 생가이다. 사학과 실학, 서화에 통달한 석정은 28세 때 중국에 가는 사신을 수행하여 중국에 머물면서 동서양의 학문을 두루 섭렵하였다. 그 뒤 이들을 종합하여 그의 학문과 사상을 집대성한 『연석산방미정고』라는 유고를 남겼다. 가옥은 우리나라 전형적인 농가의 모습으로 20㎝의 축대 위에 초가로 세웠으며, 120년 전에 지었다.","a":"이석정선생생가","c":"시도기념물","nc":"","r":"전북특별자치도","s":"김제시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1653369.jpg"},{"q":"○○○에 있는 옛집으로 곱은자 모양의 안채와 一자 모양의 곡간채 및 문간채로 구성되어 있다. 안채 뒤에 사랑채가 있었지만 지금은 흔적만 있으며, 건넌방이 사랑채의 기능을 대신하고 있다. 부엌 앞에는 고방을 두어 식료품을 저장하는데, 부엌과 고방 사이에는 판자벽을 둘렀다. 이러한 기법은 오래된 집에서만 볼 수 있는 양식이다. 문간채 주위에는 담장을 둘러 바깥마당과 구분하고, 대문간에도 담을 설치하여 밖에서 집안을 들여다보지 못하도록 하였다. 특히 안채와 곡간채 사이에도 담장을 둘러 사랑채 역할을 하고 있는 건넌방의 독립성과 아늑한 분위기를 조성한 점이 특이하다.","a":"제천 지곡리 고가","c":"시도유형문화유산","nc":"","r":"충청북도","s":"제천시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1638525.jpg"},{"q":"기면(器面) 전체에 백유(白釉)가 시유되어 있으나 전체적으로는 회색빛이 약간 감도는 모습의 이 대병(大甁)은 도톰하게 말린 채 밖으로 벌려진 구연부와 긴 목, 비교적 양감이 적은 동체(胴體) 등으로 구성되어 있다. 18세기 전반기의 전형적인 병형(甁形)이면서도 전체 높이가 46.4㎝에 이르는 흔치 않은 크기에 길게 과장되어 표현된 목, 말려서 외반(外反)된 구연부 등에서 그 특징을 찾아 볼 수 있다.","a":"백자대병","c":"시도유형문화유산","nc":"","r":"서울특별시","s":"종로구","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/2590229.jpg"},{"q":"이 괘불은 봉은○○○과 같은 삼존도 형식으로, 경기도 내의 남양주 ○○○○○, 불암○○○과도 유사하다. 도상은 순·고종 시대에 유행한 삼존불의 간략하고 소형화된 구도이다. 아미타불을 중심으로 좌우 협시보살인 관음보살과 대세지보살, 아난, 가섭과 문수동자, 보현동자가 배치되었다. 본존의 형태는 키형의 광배를 지고 있다. 원만한 얼굴에 큼직한 중앙 계주와 긴 두 귀, 늘여진 팔 등 비현실적이다. 본존과는 달리 보살상·제자상·동자상은 비교적 섬세하게 표현하고 있다. 하지만 본존불 앞으로 선 협시들은 어색한 원근법을 표현하고 있다.","a":"고양흥국사괘불","c":"시도유형문화유산","nc":"","r":"경기도","s":"고양시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/2020031015232100.jpg"},{"q":"○○○의 법당인 불이정사(不二精舍)에 모셔져 있는 ○○○ 가운데 ○○○○좌상과 보현보살상이다. 불이정사의 ○○○은 ○○○○좌상을 가운데 두고 양옆에 보현보살과 문수보살이 자리하고 있는데, 문수보살은 잃어버려 최근에 만들어 놓은 것이다. 가운데 자리하고 있는 ○○○○좌상은 작은 소라모양의 머리칼을 붙여 놓은 머리형태를 하고 있으며 정수리 부분에 상투모양의 육계가 뚜렷하게 표현되어 있다. 두텁게 표현된 옷자락은 양어깨를 모두 감싸고 흘러 내려 무릎까지 덮고 있다.","a":"혜봉원목조석가여래삼존상","c":"시도유형문화유산","nc":"","r":"전북특별자치도","s":"익산시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1639686.jpg"},{"q":"임진왜란 때 금산으로 쳐들어 오는 왜적을 막다 장렬히 순절한 금산 군수 권종의 충의를 기리기 위해 고종 15년(1878)에 세워졌다. 권종(?∼1592)은 개티강가에 진을 치고, 강을 건너려는 왜구를 막아내고자 200여 명도 못되는 병사를 거느리고 싸움에 나갔다. 이 싸움에서 왜적을 무수히 무찌르고 용감히 싸웠으나, 그의 아들 권준과 함께 전사하고 말았다. ○○○는 높이 176cm, 너비 51cm, 폭 40cm이며, 홍문관대제학 이승보(李承輔)가 비문을 지었고, 그 11대손인 정호(鼎鎬)가 글씨를 썼다.","a":"권충민공순절비","c":"문화유산자료","nc":"","r":"충청남도","s":"금산군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1660906.jpg"},{"q":"고려말 조선초의 문신인 문숙공 ○○○의 묘소이다. ○○○의 자는 이행(而行), 본관은 문화(文化), 시호는 문숙(文肅). 유식(柳湜)의 증손으로, 할아버지는 유안택(柳安澤)이고, 아버지는 전농정(典農正) 유임(柳臨)이며, 어머니는 권숙(權肅)의 딸이다. 조선조 초기 16세 때 생원시에 합격하였으며, 18세 때인 태조 2년(1393년) 식년 문과에 동진사(同進士)로 합격해 좌정언, 이조·병조정랑 등을 역임하고 태종 7년 (1407)에 문과 중시에 병과로 급제하여 사헌부 장령이 되었다.","a":"류사눌 묘","c":"시도기념물","nc":"","r":"인천광역시","s":"서해구","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1645505.jpg"},{"q":"조선 후기 승려인 ○○○○ 태흘(泰屹, 1710~1793)의 일대기를 기록한 탑비이다. 의정부시 호원동 ○○○ 경내의 남서쪽에 세워져 있다. 탑비 옆에는 그의 사리를 모신 부도가 함께 세워져 있다. 태흘 스님은 속성이 김씨이고, 자는 무등(無等)이다. 호는 천봉(天峯)이고, 본관은 서흥(瑞興)이다. 16세에 유덕사 명탁(名琢) 스님을 스승으로 출가하였고, 도원(道圓) 스님을 은사로 모시며 구족계를 받았다. 영조 5년(1729)에 은월우점(隱月雨霑) 스님으로부터 학문을 배운 뒤 선지식을 찾아 전국을 두루 섭렵했다.","a":"망월사천봉선사탑비","c":"문화유산자료","nc":"","r":"경기도","s":"의정부시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1660065.jpg"},{"q":"조선 중엽 최응숙 선생이 임진왜란 이후 이곳에 낙향하여 지은 정자이다. 성균진사 최응숙은 본관은 전주, 호는 양요, 시호는 충현이다. 문충공 최군옥을 시조로 하며, 위정공 최칠석을 중시조로 한다. 최칠석의 아들 최운이 전주에서 남원부 수지방(水旨坊)으로 이거해 8대를 세거했는데, 최칠석의 9세손인 양요당 최응숙이 임실 운암으로 처음 입향한 것으로 보인다. 최응숙은 임진왜란 당시 성균진사로서 임금을 호종한 공로로 호성공신 3등에 책봉되었고, 후에 운암으로 낙향해 ○○○을 짓고 소요했다.","a":"양요정","c":"문화유산자료","nc":"","r":"전북특별자치도","s":"임실군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1661775.jpg"},{"q":"이 영정은 ○○○○○ 선사의 좌안8분면 바닥가부좌상으로, 왼손엔 주장자를 들고 오른손엔 염주를 쥐고 앉아 있다. 인물의 뒤편은 갈색 상단부와 돗자리가 그려진 하단부로 이루어진 이단구도를 배경으로 호형의 등받이를 배치하였다. 의자 끝부분은 금박의 원심문으로 마감하였고, 가장자리가 주색으로 마감된 녹색의 법피를 의자처럼 표현하였다. 안면부는 세필의 선묘로 뚜렷한 눈, 깊게 패인 주름과 강조된 인중 등 이목구비를 묘사하면서 당당한 상호를 드러낸 반면 의습선의 표현에서는 선염 효과없이 동일한 선묘로 처리하여 평면적이고 도식적인 느낌이 강하다.","a":"응허당 도흡 진영","c":"시도유형문화유산","nc":"","r":"경상남도","s":"양산시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/0000000001643033.JPG"},{"q":"이 영정은 17세기 밀양 표충사 · 청도 운문사 · 통도사에 주석하신 ○○○○○선사의 영정으로 좌안7분면의 전신교의좌상이다. ○○선사는 1676년(숙종 2) 5월 1일 경북 자인현(현 경산시)에서 태어났다. 1688년 13세에 청도 운문사로 출가하여 처음에는 석제를 스승으로 섬기고, 뒤에 환성지안에게 참학했다. 이 두 스승의 법을 함께 전해 받고, 청허휴정 이후 갈라졌던 2파를 하나로 통합한 분이다. 내전을 널리 보아 공부가 깊었는데, 만년에는 학인들을 사절하고 참선만하다 1750년(영조26) 세수 75세, 법랍 62년으로 입적하셨다.","a":"설송당 연초 진영","c":"시도유형문화유산","nc":"","r":"경상남도","s":"양산시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/0000000001642995.JPG"},{"q":"○○○는 충남지방의 모든 사찰을 통괄했던 큰 사찰로 신라 때 자장율사가 창건하고 고려시대 보조국사가 재건하였다고 기록되어 있다. 조선시대에는 세조(재위 1455∼1468)가 이곳에 와서 ｀영산전´이라는 편액을 직접 써서 내렸고 잡역을 면제하는 교지를 내렸는데 모두 임진왜란(1592) 때 불에 타 없어졌다. 효종 1년(1650)년부터 주지스님인 주순의 노력으로 절이 어느 정도 회복되었는데, 정조 6년(1782)년에 다시 큰 불이 일어나 대광보전을 비롯한 1,050칸이 모두 불에 탔다.","a":"마곡사심검당및고방","c":"시도유형문화유산","nc":"","r":"충청남도","s":"공주시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1639230.jpg"},{"q":"○○는 승려의 무덤을 상징하여 그 유골이나 사리를 모시는 곳이다. 이 ○○는 ○○○ 적멸보궁 뒤쪽에 놓여 있는 것으로, 모신 사리의 주인공은 아직 밝혀 지지 않았다. 형태는 아래·가운데·윗받침돌로 이루어진 기단부(基壇部) 위에 탑신(塔身)을 올리고 머리장식을 갖추었으며, 각 부분이 8각을 이루고 있다. 넓고 네모진 바닥돌 위에 놓인 아래받침돌은 각 면마다 안상(眼象)을 새겼다. 가운데받침돌은 여덟 모서리마다 기둥 모양의 조각을 두었다. 윗받침돌에는 연꽃무늬를 둘렀다.","a":"영월 법흥사 부도","c":"시도유형문화유산","nc":"","r":"강원특별자치도","s":"영월군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1638044.jpg"},{"q":"미륵전에 본존으로 안치되어 있는 불상으로서 무릎 이하 아래부분이 땅 속에 묻혀있어 전체높이는 알 수 없지만 현 높이는 약 185㎝ 정도이다. 불상은 두툼한 돌을 이용하여 뒷부분은 원형 그대로 다듬지 않고 두었으며 앞 부분은 조각을 기하였지만 전체적으로 평면적인 느낌을 준다. 그러나 측면에서 보면 상당한 중량감이 느껴지는 불상이다. 머리에는 지붕돌 모양의 커다란 보관(寶冠)을 쓰고 있는데 윗부분을 구슬 모양으로 처리하였다. 정수리에 있는 상투 모양의 육계는 분명치 않지만 그 부분이 높게 솟아 보관을 받고 있다.","a":"용화사미륵불상","c":"문화유산자료","nc":"","r":"전북특별자치도","s":"고창군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1661877.jpg"},{"q":"‘탑골(塔谷)’이라 불리는 마을에 서 있는 3층 석탑이다. 절터의 이름이나 역사에 관해 알려진 바는 없으며, 마을에 전해오는 이야기에 따르면, 신라시대에 세운 절이 있었으나 언젠가 불에 타 사라졌다고 한다. 탑은 2층 기단(基壇)을 쌓아 3층의 탑신(塔身)을 올린 모습이나, 탑신의 3층 몸돌은 없어졌다. 아래층 기단은 한돌로 간단하게 만들고, 위층 기단은 여러 장의 편평한 돌을 짜 맞춘 후 각 면의 모서리와 가운데에 기둥 모양을 조각 하였다. 기단에 비해 폭이 크게 줄은 탑신부는 각층 몸돌마다 모서리에 기둥 모양을 새겼다.","a":"의령 성황리 삼층석탑","c":"시도유형문화유산","nc":"","r":"경상남도","s":"의령군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1641599.jpg"},{"q":"임진왜란 때 의병으로 활약하여 영천·경주 전투에서 큰 공을 세운 정수번의 셋째아들인 호신이 결혼하여 살던 집이다. 조선 광해군 12년(1620)경에 지었으며, 효종 6년(1655)에는 사당을 세웠다. 1977년 영천댐 건설공사로 인해 지금의 위치로 옮겨졌다. 앞면 5칸·옆면 1칸 규모로, 지붕 옆면이 여덟 팔(八)자 모양인 팔작지붕집이다. 사당은 앞면 3칸·옆면 1칸 규모이며，지붕 옆면이 사람 인(人)자 모양인 맞배지붕집이다.","a":"오회공종택","c":"시도유형문화유산","nc":"","r":"경상북도","s":"영천시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1640367.jpg"},{"q":"○○○○○은 조선말기 조성된 별서형 정자이며, 영역의 구성방식이나 정자건물의 균제미 등이 우수하고 특히 자연샘물과 물길을 이어 조성된 방지원도형 연지 등은 정자 원림의 우수한 기법을 보여주므로 역사적, 예술적, 기능적 가치가 우수함","a":"밀양 삼은정","c":"문화유산자료","nc":"","r":"경상남도","s":"밀양시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/2023053016510700.jpg"},{"q":"정문은 국가에서 풍속을 권장하기 위해 충신·효자·열녀가 사는 마을 입구나 집 문 앞에 세우는 붉은 문을 일컫는다. 조선 세조 때 단종 복위 운동에 가담했던 이조판서 김문기와 아들 현석에 대한 충신정문과 효자정문 등 5대에 걸친 정문을 한 곳에 모셔놓은 곳이다. 지금 있는 건물은 조선 고종 7년(1870)에 세웠다고 하며, 1968년 보수하였고 1976년 단청을 거쳐 1981년에 시흥군에서 정화사업을 실시하여 오늘에 이르고 있다.","a":"오정각","c":"문화유산자료","nc":"","r":"경기도","s":"안산시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1659838.jpg"},{"q":"○○○은 고려시대 문신인 정서가 유배생활을 할 때 정자를 짓고 오이밭을 일구며 임금을 그리워하는 고려가요인 ○○○곡(鄭瓜亭曲)을 지은 곳으로, <동국여지승람(東國輿地勝覽)>, <동래부지(東萊府誌)> 등에 의하면 과정(瓜亭)은 '동래부(東萊府) 남쪽 10리에 위치하고 있으며, 정자는 없으나 그 터는 남아 있다'고 기록되어 있다. 이 기록을 토대로 추정해 보면 ○○○의 현재 위치는 수영강변을 따라 수영하수처리장에서 고려제강에 이르는 지역으로 추정된다.","a":"정과정유적지","c":"시도기념물","nc":"","r":"부산광역시","s":"수영구","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1645248.jpg"},{"q":"삼거리 공원안에 자리하고 있는 탑으로, 지금은 밭으로 변해 버린 안서동의 유려왕사(留麗王寺)터에 있던 것을 이곳으로 옮겨 놓았다. 형태는 전체의 무게를 지탱하는 기단(基壇)을 2층으로 쌓고, 3층의 탑신(塔身)을 올린 모습이다. 아래층 기단에는 한면에 2개씩 안상(眼象)을 옅게 새겨 놓았고, 탑신의 세 지붕돌은 밑면에 2단씩의 받침을 두었다. 고려시대에 세운 것으로 추측되나, 탑신의 2층 몸돌 이상이 원래의 것이 아닌 후대에 새로 만들어 놓은 것이어서 아쉬움을 주고 있다.","a":"삼룡동 삼층석탑","c":"문화유산자료","nc":"","r":"충청남도","s":"천안시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1660881.jpg"},{"q":"○○○○의 바닷가 정면에 남북으로 서 있는 2기의 ○○○ 중 북쪽에 서 있는 탑이다. ○○○은 마을의 어느 한 방위에 불길한 징조가 보인다거나 어느 한 지형의 기가 허한 곳에 마을 공동으로 쌓아 올린 돌탑으로 부정과 악의 출입을 막아 마을을 편안하게 하고자 하는 신앙 대상물이다. 이 마을의 ○○○은 바다 방향의 허한 기를 보강해주기 위해 세운 것으로, 2기 모두 탑 위에 새 부리 모양과 비슷한 돌이 놓여 있어 ‘매주제기’라 부르기도 한다. 특히 이 탑은 ‘새원’이라는 암반 위에 세웠다하여 ‘새원탑’이라고도 하는데, 돌탑 위에 놓인 새의 석상이 서쪽을 향하고 있다.","a":"용수마을방사탑1호","c":"시도민속문화유산","nc":"","r":"제주특별자치도","s":"제주시","i":"http://www.khs.go.kr/unisearch/images/folklore_material/thumb/1659265.jpg"},{"q":"부도는 승려의 무덤을 상징하여 그 유골이나 사리를 모시는 곳이다. 이 부도는 ○○○ 대웅전에서 왼쪽으로 약 150m 떨어진 숲속에 자리하고 있는데, 이 절에 전하고 있는 몇 안되는 유물 가운데 하나이다. 네모난 바닥돌 위에 3개의 받침돌로 이루어진 기단(基壇)을 마련한 후, 탑신(塔身)을 올려 놓은 모습으로, 바닥돌과 기단의 일부를 제외한 각 부분이 8각을 이루고 있다. 기단은 아래받침돌 윗면에 연꽃조각을 두르고, 옆면의 네 모서리에 숫사자와 암사자를 교대로 배치하였다.","a":"원효사동부도","c":"시도유형문화유산","nc":"","r":"전남광주통합특별시","s":"북구","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1637143.jpg"},{"q":"○○○○○군은 초기철기~원삼국시대의 주변 마을을 조성했던 당시 주민들이 축조한 무덤유적으로 ○○○ 고인돌은 서귀포시 서남부 지역에 위치하고 있으며 행정구역상으로는 제주특별자치도 서귀포시 대정읍 ○○○ 1614번지, 1628번지 외 3필지[○○○○○ 1호], 1607번지[○○○○○ 2호], 1619번지[○○○○○ 3호], 1619번지[○○○○○ 4호]에 각각 축조되어 있다. 가시악(加時岳)[106.5m 오름] 하단의 구릉상에 위치하고 있다. ○○○○○ 3호는 덮개돌의 형태가 타원형에 가깝게 이루어져 있다. 긴 쪽의 방향은 북에서 동쪽으로 35° 정도 기울어져 있다.","a":"동일리지석묘3호","c":"시도기념물","nc":"","r":"제주특별자치도","s":"서귀포시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1657736.jpg"},{"q":"○○○은 두문동 72현 중 한 분인 덕곡 조승숙이 인재를 양성하기 위해 태조 7년(1398)에 지은 정자이다. 조승숙은 고려 우왕 7년(1381) 문과에 급제하고 명나라 사신으로 중국에서도 명성이 알려진 분이었으나, 조선 태조가 즉위하자 벼슬을 버리고 세상에 나오지 않았다. 성종(1469∼1494)은 선생의 충절을 가상히 여겨 사제문을 내렸는데, ‘수양명월율리청풍(首陽明月栗里淸風)’이라는 여덟자를 자연 암반 위에 새겨 거북 머리를 조각하고 비를 세웠다. 비의 높이는 320㎝·폭 90㎝·두께 39㎝이다.","a":"함양 교수정","c":"문화유산자료","nc":"","r":"경상남도","s":"함양군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1663984.jpg"},{"q":"정암(靜菴) ○○○는 조선 전기 대사헌 등을 역임한 문신이다. 『소학』·『근사록(近思錄)』 등을 토대로 성리학 연구에 힘써 이후 김종직(金宗直)의 학통을 이은 사림파(士林派)의 영수가 되었다. 그는 유교로써 정치와 교화의 근본을 삼아야 한다는 지치주의(至治主義)에 입각한 왕도정치의 실현을 역설하였다. 1519년에 훈구파 중 홍경주(洪景舟)·남곤(南袞)·심정(沈貞)이 일으킨 기묘사화(己卯士禍)로 죽음을 맞이했다. ○○○의 묘는 부인 이씨와 합장(合葬)된 단분(單墳)으로 조성되어 있다. 봉분 앞에는 묘표, 석상, 향로석, 망주석, 문인석이 설치되어 있다.","a":"문정공조광조묘및신도비","c":"시도기념물","nc":"","r":"경기도","s":"용인시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1646980.jpg"},{"q":"○○○은 융복(戎服)의 일종으로 철릭을 간소화하여 소매를 좁혀 까치동으로 하고 허리 부분의 주름을 없애고 양쪽 겨드랑이와 등솔의 아래를 터서 민첩하게 움직일 수 있도록 한 동시에 그 위에 다시 반비형(半臂型) 전복(戰服)을 덧입어 위엄을 갖추게 한 것이다. 줄여서 군복(軍服)이라고도 하며, 구성은 전립(戰笠), 이엄(耳掩), 동다리, 전복(戰服), 목화(木靴)에 전대(戰帶)를 띠고 병부(兵符)를 차고 환도(環刀), 통개(筒箇), 등책(藤策)을 갖춘다.","a":"동래영구군복","c":"시도민속문화유산","nc":"","r":"부산광역시","s":"동래구","i":"http://www.khs.go.kr/unisearch/images/folklore_material/thumb/1658095.jpg"},{"q":"경상남도 ○○시 호계동의 큰 바위에 새겨진 마애불로, 바위 밑의 동굴에는 온돌을 설치했던 흔적이 있다. 이 동굴은 원효대사가 수도했던 ‘반고굴(磻高窟)’이라고 전해지지만 아직 확실한 근거는 없다. 머리에는 마애불로는 드물게 작은 소라 모양의 머리칼을 붙여 놓았으며, 정수리에는 상투 모양의 작은 머리묶음이 있다. 몸에 비해 큰 얼굴, 길게 감은 눈, 큰 코, 다문 입 등은 투박한 인상을 준다. 신체는 풍화가 심해 뚜렷하지 않은데, 양 어깨에 걸친 옷이 두툼하게 선각되었고, 손·발 역시 투박하게 표현되었다.","a":"양산 호계리 마애여래좌상","c":"시도유형문화유산","nc":"","r":"경상남도","s":"양산시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1641565.jpg"},{"q":"선조 30년(1597) ○○○○ 때 전라도 부안지방의 의병들이 왜군을 맞아 싸운 싸움터이다. ○○○란 지명은 7세기 당나라 장군 소정방이 이곳에 상륙하여 유진치와 주류성 일대에 통수부를 설치하였던 사실에서 비롯되었다고 전한다. 선조 25년(1592)에 일어난 임진왜란 때와는 달리 왜군은 주력부대를 전라도에 투입하여 곳곳을 짓밟았는데, 이 때 왜병들은 해로를 이용해 줄포에 상륙하여 부안으로 진격하여 왔다.","a":"정유재란호벌치전적지","c":"시도기념물","nc":"","r":"전북특별자치도","s":"부안군","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1653402.jpg"},{"q":"○○○○ 일가 4대의 충, 효, 열 행정적을 기리기 위해 세운 정려이다. 임진왜란 시 의병으로 활동한 조언수의 충, 그의 손자 조순악과 증손자 조후건의 효, 며느리 문화유씨의 열을 기리는 정려이다.","a":"창녕조씨 삼강정려","c":"문화유산자료","nc":"","r":"전남광주통합특별시","s":"광산구","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1659685.jpg"},{"q":"○○○은 조선 명종 1년(1546)에 박원순이 지은 정자로, 오랜 세월이 흘러 낡은 것을 13대손인 박정현이 고쳐 지었다. 박원순은 김인후의 제자로 성리학을 공부하고 진사시에 합격하였으나 벼슬길에는 나아가지 않고 이곳에 정자를 짓고 제자들을 가르치며 지냈다. 정자 안에는 은행나무를 심고 연못을 파서 구곡수를 끌어 들이는 등 그윽한 분위기를 만들어 냈다. 박원순이 죽자 은행나무와 샘물이 모두 말랐다가 삼년 후에 다시 살아났다는 전설도 있다. 건물은 앞면 2칸·옆면 2칸 규모이며, 지붕은 옆면에서 볼 때 여덟 팔(八)자 모양인 팔작지붕으로 꾸몄다.","a":"장성 청계정","c":"문화유산자료","nc":"","r":"전남광주통합특별시","s":"장성군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1662033.jpg"},{"q":"정려비는 충신·효자·열녀 등의 언행과 정신을 기리기 위하여 그들이 살던 마을의 입구에 세워두는 것으로, 이 비는 조선시대 중기에 이 지방에서 대장간을 하던 배순 선생을 위하여 세운 것이다. 배순 선생은 천성이 유순하고 효성이 지극하며, 학문에도 뜻이 있어 퇴계 이황의 제자가 되었다. 유일한 평민 제자였던 그는 퇴계 선생이 세상을 떠나자 삼년복(三年服)을 입고, 철을 이용해 스승의 상을 만들어 기리는 등 제자의 예를 다하였다. 광해군 7년(1615) 충신으로 표창되었다. 비는 소박한 받침돌 위에 비몸을 세웠으며, 윗쪽으로 갈수록 조금씩 넓어졌다.","a":"배순정려비","c":"시도유형문화유산","nc":"","r":"경상북도","s":"영주시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1640869.jpg"},{"q":"○○도 전통가옥의 형태를 간직하고 있는 집으로 1940년대에 지은 것이다. ○○○이라고도 불리는 귀틀집은 통나무를 井자형으로 귀를 맞추어 쌓아 올려 벽을 만들고, 그 위에 너와·굴피·화피 따위로 지붕을 이은 집을 가리킨다. 3칸 규모의 一자형 집으로 귀틀로 벽을 짠 머릿방과 큰방, 수숫대로 만든 부엌이 각각 1칸씩 구성되어 있다. 통나무 사이에는 흙을 채우지 않아 바람이 잘 통하게 하였으며 부엌은 바닥을 낮게 하여 부뚜막을 설치하고 구들을 놓았다.","a":"울릉 나리동 투막집","c":"시도민속문화유산","nc":"","r":"경상북도","s":"울릉군","i":"http://www.khs.go.kr/unisearch/images/folklore_material/thumb/1659011.jpg"},{"q":"통도사 소장 고승영정은 18세기에서 19세기 말에 조성된 작품들로서 당시의 화풍을 다양하게 보여줄 뿐만 아니라 경상도 지역에서 활동한 화승들의 이력과 양식적 특징을 파악할 수 있어 조선후기 고승 영정에 관한 시대 및 지역 연구에 중요한 자료임.","a":"동파당 탄학 진영","c":"시도유형문화유산","nc":"","r":"경상남도","s":"양산시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/0000000001643027.jpg"},{"q":"일본 오사카에 본점을 둔 제58은행의 ○○지점이다. 후에 여러 은행들과 합쳐져 야스다 은행으로 바뀌었다. 광복 후 조흥은행이 ○○지점으로 사용하기도 하였으나 1958년 새로 건물을 짓고 옮겨가자 대한적십자사 경기도지사로 사용되다가 현재는 ○○ 중구 요식업조합에서 사용하고 있다. 2층에는 보기 드문 발코니와 지붕창이 특징이며 지붕이 2중으로 경사를 이루고 있어, 프랑스 분위기를 자아내는 르네상스 양식의 건물이다.","a":"인천 구 일본제58은행","c":"시도유형문화유산","nc":"","r":"인천광역시","s":"제물포구","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1637035.jpg"},{"q":"부도는 승려의 무덤을 상징하여 그 유골이나 사리를 모셔두는 곳이다. 상이암의 뒷마당에 자리하고 있는 이 2기의 부도는 각각 ‘해월당’, ‘두곡당’이라는 호를 가진 두 승려의 사리를 모시고 있다. 해월당 부도는 하나의 돌로 이루어진 3단의 받침 위로, 항아리 모양을 한 탑신(塔身)의 몸돌을 두고, 지붕돌을 얹었다. 받침돌에는 세련되지 못한 연꽃무늬가 있고, 지붕돌은 여덟 귀퉁이가 위로 살짝 들려 있다. 꼭대기에는 밑부분이 깨진 꽃봉오리 모양의 돌이 놓여 머리장식을 하고 있다.","a":"상이암부도","c":"문화유산자료","nc":"","r":"전북특별자치도","s":"임실군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1661751.jpg"},{"q":"○○한씨의 시조인 한란韓蘭이 살던 마을에 있던 우물이다. 무농정에서 약 200m 떨어진 ○○한씨 종중회관이 있는 골목 안쪽에 있다. 한란이 이곳에 살면서 음료와 용수로 사용했다고 전해진다. 전설에 의하면 어느 해 심한 가뭄이 들어 농사를 지을 수 없게 되자 한란이 제수를 마련하여 사흘 동안 기도를 드리다 쓰러져 의식을 잃었는데 이때 북쪽에서 장수가 나타나 창끝으로 땅을 찌르니 맑은 물이 콸콸 흘러 나왔다. 너무 기뻐 소리치다 깨어난 후 꿈속에 보이던 곳을 파보니 땅속에서 많은 양의 물이 쏟아져 나왔다고 한다.","a":"청주 방정","c":"시도기념물","nc":"","r":"충청북도","s":"청주시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1650135.jpg"},{"q":"동래부사 이문원의 기부금과 동래부 유지들의 모금을 바탕으로 동래부의 남문 밖에 있던 네 곳의 나무다리를 돌다리(石橋)로 바꾼 것을 기념하여 세운 비석이다. 원래 동래고등학교 앞 길가에 있던 것을 도로확장공사로 인하여 금강공원 안의 임진동래의총 입구에 옮겼다가 그후 지금의 자리로 다시 옮긴 것이다. 나무다리는 1∼2년마다 다시 고쳐 쌓게 되는데 그때마다 백성에게 그 비용을 거두었으므로 백성들의 고통이 심하였다.","a":"사처석교비","c":"시도기념물","nc":"","r":"부산광역시","s":"남구","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/2328903.jpg"},{"q":"불자는 삼이나 짐승의 털을 묶어서 자루 끝에 맨 것으로 원래는 모기 등의 벌레를 쫓는데 쓰는 생활용구이나, 불가에서는 수행자가 마음의 티끌과 번뇌를 털어내는 상징적 의미의 불교 용구이다. 불교식으로는 불(拂) 또는 불진(拂塵)으로 불린다. 불가에서는 흰 말의 꼬리털로 만든 백불(白拂)을 귀하게 여기며 조사(祖師) 영정에 지물로 그리는 경우가 많다. 자루에는 장식으로 흔히 용의 문양을 새기기도 한다. 불자를 지물로 삼는 뜻은 신상의 악한 장애나 환란을 없애기 위해서라고 한다.","a":"묘관음사불자","c":"문화유산자료","nc":"","r":"부산광역시","s":"기장군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1659400.jpg"},{"q":"조선 중기의 학자인 곤재 정개청(1529∼1590)의 문집을 널리 간행하기 위해 숙종 15년(1689)에 왕의 특명으로 시작되어 숙종 18년(1692)에 완성된 목판이다. 정개청은 어린 시절 보성의 영주산사에서 성리학을 비롯하여 천문, 지리, 의약 등의 학문을 열심히 익혔다. 그후 서경덕을 스승으로 박순과 교류하며 학문의 깊이를 더하였으며, 명종 20년(1565)에 함평군 엄다면 제동 마을로 귀향하여 향리에서 학생들을 양성하였다. 그후 선조 22년(1589) 정여립의 모반사건에 연루되어 20여년간 이곳에서 유배생활을 하였다.","a":"곤재우득록목판","c":"시도유형문화유산","nc":"","r":"전남광주통합특별시","s":"함평군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1640027.jpg"},{"q":"이 석비는 광무 10년(1906)에 세워졌으며, 조선 후기 대일외교의 실무관청이었던 유원각(柔遠閣)과 관련된 유일한 금석문 자료이다. 비석에는 비의 건립배경과 목적, 비석을 세운 사람들의 이름 등이 새겨져 있어, 약조제찰비(시도기념물)와 함께 왜관(倭館) 및 조선 후기∼근대의 부산역사와 대일관계사를 연구하는데 중요한 사료적 가치를 지니고 있다.","a":"유원각선생 매안감고비 및 비각","c":"시도유형문화유산","nc":"","r":"부산광역시","s":"남구","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/2327407.jpg"},{"q":"덕유산 내의 ○○○ 뒷쪽에 마련되어 있는 ○○으로, 불교의 계(戒:승려가 지켜야 할 계율)의식을 행하는 곳이다. 이 산에서 흔히 볼 수 있는 화강암질의 암석으로 이루어진 단은 절 뒷쪽의 등성이에 바닥을 널찍하게 마련하여 고르게 만든 후 자연석을 깔고 그 중앙에 종 모양의 탑을 세워두었다. 낮은 바닥돌 위에 올려진 탑은 꼭대기에 구슬무늬를 둔 두툼한 받침을 조각한 후, 그 위로 꽃봉오리 모양의 머리장식을 올려놓았다. 탑의 서쪽으로는 동·서·남·북의 방위를 장식한 듯한 3각점의 홈이 파여 있고, 그 안에 동그란 무늬를 새긴 받침대가 놓여 있다.","a":"백련사 계단","c":"시도기념물","nc":"","r":"전북특별자치도","s":"무주군","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1653457.jpg"},{"q":"조선 전기 문신인 신말주(1439∼?)선생의 위패를 중앙에 두고 양 옆으로 조윤옥, 장조평 선생을 배향하며 그 좌우에 7분의 위패를 모시고 있는 사당이다. 신말주 선생은 단종 2년(1454) 과거에 합격하고 벼슬이 대사간에 이르렀으나 단종이 폐위되자 벼슬을 버리고 순창에서 여생을 보냈다. ○○○는 순조 18년(1818)에 세웠으나 현재 건물은 1917년 이후에 고쳐 지은 것이다. 앞면 3칸·옆면 2칸 규모이며, 건물 앞쪽에는 앞면 3칸·옆면 2칸 크기의 솟을대문인 내삼문이 있다.","a":"덕천사","c":"문화유산자료","nc":"","r":"전북특별자치도","s":"고창군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1661823.jpg"},{"q":"○○○ 미륵전 안에 모시고 있는 이 ○○○○은 미륵불상으로 알려지고 있으나, 손모습으로 보아 석가여래가 책상다리를 하고 앉아있는 모습으로 보인다. 광배 윗 부분은 잘려나갔으며, 얼굴의 눈과 코 부위 등은 심하게 닳았고, 채색의 흔적이 일부 남아있다. 이 불상은 몸체에 비해 얼굴부위가 크게 묘사되어 있으며, 오른쪽 어깨를 완전히 드러낸 옷차림을 하고 있다. 큼직하게 표현된 두 손은 부처가 모든 악마를 굴복시켜 없앤다는 손 모양새를 취하고 있다. ○○○는 고려 초에 원광스님이 세웠다고 전해지는데, 이 불상은 제작 기법 등으로 보아 고려말에 지방에서 만든 작품으로 보인다.","a":"천고사석불좌상","c":"문화유산자료","nc":"","r":"전북특별자치도","s":"전주시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1661798.jpg"},{"q":"○○○○○는 전주시 금상동 법사산에 위치한다. 묘의 형태는 조선시대의 일반적 형태와 달리, 태인의 정극인 묘처럼 부부묘가 세로로 되어 있는데, 아래의 묘가 부인의 묘이며, 위의 묘가 회안대군 이방간의 묘이다. 이 묘자리가 군왕지지(君王之地)라 하여 지기가 흐르는 곳에 뜸을 떠버렸다는 것은 유명한 이야기다. 지금도 뜸을 뜬 자리가 남아 있다. 회안대군은 태조 이성계의 넷째아들로 그 동생 태종 방원과 함께 자웅을 겨루었던 조선초 인물이다.","a":"회안대군묘","c":"시도기념물","nc":"","r":"전북특별자치도","s":"전주시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1653870.jpg"},{"q":"청하군수를 지낸 해와 김희택(1742∼1818)의 손자인 김중수(1791∼1868)가 지은 집이다. 김중수는 할아버지의 유언에 따라 집을 짓고 ‘○○○○’이라 부르게 되었다. 건물은 이 지방의 양반집 배치방법인 ㅁ자형과는 달리 안채와 전면 사랑채 및 중문채가 2개의 ㄱ자형으로 나누어져 튼 ㅁ자형을 이루고 있다. 사랑채는 앞면 3칸·옆면 4칸 반으로 큰사랑방과 마루로 구성되어 있다. 안채는 앞면 4칸·옆면 3칸으로 대청을 중심으로 좌우에 온돌방을 배치하였다. 중문채는 사랑채 왼쪽에 연결되어 있으며 앞면 3칸·옆면 1칸으로 이루어져 있다.","a":"해와고택","c":"문화유산자료","nc":"","r":"경상북도","s":"봉화군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/2019111514321600.jpg"},{"q":"○○○○는 통일신라 신문왕 4년(684)에 양개조사가 세운 절이라고 전한다. 조선시대에 고승 무학대사가 수도한 곳이기도 하며, 사명대사가 임진왜란 때 승병들의 훈련장으로 사용하기도 하였다. 그 뒤 임진왜란 때 불탔던 것을 효종 4년(1653) 인혜대사가 ○○○과 함께 다시 세웠으나, 순조 6년(1806)에 또 화재를 2년 뒤 다시 세웠다고 한다. ○○○은 법당과 생활공간의 기능을 겸한 특이한 평면을 가진 건물로, 앞면 3칸·옆면 2칸 규모이다. 그러나 실제로 법당의 기능보다 강당의 기능을 가진 건물로 ‘인법당’으로도 부르고 있다.","a":"남지장사 청련암","c":"시도유형문화유산","nc":"","r":"대구광역시","s":"달성군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1636903.jpg"},{"q":"은진 송씨 문중의 송종만이 조선 고종 3년(1866)에 지은 가옥이다. 처음에는 유전리에 있던 것을 1986년에 지금 있는 자리로 옮겨 지었다. 본채는 앞면 5칸·옆면 2칸의 규모이며, 건넌방·마루·큰방·부엌 순으로 배치하였다. 지붕은 옆면에서 볼 때 사람 인(人)자 모양인 맞배지붕이다. 사랑채는 앞면 4칸·옆면 2칸 규모의 맞배지붕 건물로 모방·작은방·큰방·마루·부엌 순으로 배치하였으며, 마루에는 조각한 난간을 설치하였다.","a":"합천 역평리 송씨종가","c":"문화유산자료","nc":"","r":"경상남도","s":"합천군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1664063.jpg"},{"q":"○○○는 청동기시대의 대표적인 무덤으로 고인돌이라고도 부르며, 주로 경제력이 있거나 정치권력을 가진 지배층의 무덤으로 알려져 있다. 우리나라의 고인돌은 4개의 받침을 세워 돌방을 만들고 그 위에 거대하고 평평한 덮개돌을 올려 놓은 탁자식과, 땅 속에 돌방을 만들고 작은 받침돌을 세운 뒤 그 위에 덮개돌을 올린 바둑판식으로 구분된다. 경상남도 ○○군 하이면 ○○○는 서쪽으로는 봉현천이 흐르고 있고 동쪽으로는 해발 142m의 야산이 있는 곳에 자리잡고 있다. 마을 앞의 들판에는 5기의 고인돌이 사방 10m 이내에 모여 있는데 지금은 논으로 경작되고 있다.","a":"고성 석지리 지석묘","c":"시도기념물","nc":"","r":"경상남도","s":"고성군","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1654915.jpg"},{"q":"경상남도 ○○시 산양읍 삼덕리의 야산 정상부와 구릉의 경사면을 이용하여 돌로 쌓은 산성이다. 이 성은 고려 공민왕 23년(1374) 왜구의 침략을 막기 위해, 최영 장군이 병사와 많은 백성을 이끌고 성을 쌓고 왜구를 물리친 곳이라 전한다. 선조 25년(1592) 임진왜란 때 왜구들에 의해 ○○○이 점령당하였으나 이순신 장군에 의해 다시 탈환되었는데, 이것이 당포승첩이다. 성은 2중 기단을 형성하고 있는 고려·조선시대 전형적인 석축진성(국경·해안지대 등 국방상 중요한 곳에 대부분 돌을 쌓아 만든 성)이다.","a":"통영 당포성","c":"시도기념물","nc":"","r":"경상남도","s":"통영시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1655076.jpg"},{"q":"돈대는 해안가나 접경 지역에 쌓은 소규모 관측·방어시설이다. 병사들이 돈대 안에서 경계근무를 서며 외적의 척후 활동을 비롯한 각종 수상한 정황을 살피고 대처한다. 적이 침략할 때는 돈대 안에 비치된 무기로 방어전을 펼친다. 망월리에 있는 이 돈대는 40∼120㎝의 돌을 직사각형으로 쌓아 올린 것으로, 성곽 위로는 흙벽돌로 낮게 쌓은 담장이 둘러져 있었으나 지금은 그 흔적만 남아 있다. ○○○○는 1679년(숙종 5)에 쌓은 48돈대 가운데 하나로 진무영에서 직접 관할하는 영문 소속 돈대였다. 방형구조로 둘레 124m, 석벽의 높이는 180~300㎝이다.","a":"강화 망월돈대","c":"문화유산자료","nc":"","r":"인천광역시","s":"강화군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1659549.jpg"},{"q":"○○○는 성수산에 있는 절로 신라 흥덕왕 5년(830)에 무염국사가 지었으나 그 뒤의 역사는 전해지지 않으며, 조선 헌종 6년(1840)에 수리하였다는 기록만이 전한다. ○○○○○은 석가모니를 모시는 법당으로 절의 중심에 위치한다. 앞면 3칸·옆면 3칸으로 지붕 옆면이 사람 인(人)자 모양인 맞배지붕이다. 지붕 위에는 흔히 볼 수 없는 형태로 얇고 넓적한 돌을 깔았으며, 지붕의 맨 윗부분만 기와를 얹었다. 건물의 양 끝이 처져보이는 것을 방지하기 위해서 지붕의 끝을 약간 올렸다. 기둥 위에서 지붕 처마를 받치는 공포는 기둥 위에만 있는 주심포 양식이다.","a":"신광사대웅전","c":"시도유형문화유산","nc":"","r":"전북특별자치도","s":"장수군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1639540.jpg"},{"q":"현감 박수근이 그의 아우들과 학문을 논하던 곳이다. 조선 숙종 36년(1710)에 세워졌다. 앞면 3칸·옆면 2칸의 규모에 지붕은 옆모습이 여덟 팔(八)자 모양인 팔작지붕이다. 땅에서 1.2m 높이 위에 마루가 설치된 건물로 앞면 3칸 중 왼쪽 끝 1칸과 오른쪽 모퉁이를 온돌방으로 꾸미고 나머지를 대청마루로 하였다. 2단의 받침대 위에 주춧돌을 놓고 둥근 기둥을 세웠다. 사방에 간결한 난간이 둘러져 있고 온돌방의 창호가 알맞게 짜여져 있다. ○○○은 마루가 높게 설치된 건물의 특징을 갖춘 전형적인 별당건축이다.","a":"영동 사로당","c":"시도유형문화유산","nc":"","r":"충청북도","s":"영동군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1638631.jpg"},{"q":"명종의 장인이었던 심강(沈鋼, 1514~1567)의 공적을 기리기 위해 1596년(선조 29)에 건립한 비이다. 본관은 청송이다. 명종이 대군으로 있을 때 심강의 큰딸과 혼인하였다. 1546년에 명종이 즉위하자 영돈녕부사에 임명되고 청릉부원군(靑陵府院君)에 봉해졌다. 신도비는 묘역의 아래에 위치하고 있으며 귀부이수(龜趺螭首) 양식을 갖추고 있다. 용머리처럼 생긴 귀두(龜頭 ; 거북 머리)의 얼굴은 우측으로 고개를 길게 빼서 뒤를 돌아보며 있다. 앞발은 땅을 헤치고 곧장 뛰쳐나갈 것처럼 역동적이다.","a":"심강신도비","c":"시도유형문화유산","nc":"","r":"경기도","s":"김포시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1637646.jpg"},{"q":"○○○○○은 금왕읍 무극리 탑골사지라는 옛 절터에 세워진 ○○○에 봉안되어 있는 불상으로, 금왕읍 오선리 오선초등학교 교정에서 출토되어 1970년경에 이곳으로 옮겨놓았다. ○○○○○은 1매의 화강석을 주형거신광 형태로 다듬어좌불상과 광배를 정교하게 조각하였으며, 불상의 현존 상태는 오른쪽 무릎 부분이 일부 파손이 되었지만 대체로 양호한 편이다. 불상의 조성시기는 대략 고려중기에서 조선 초기로 추정하고 있다. 불상의 머리에는 육계의 형태가 낮게 남아 있고 보발은 양옆으로 땋아 귀 뒤로 돌려졌으며 오른쪽은 귀밑까지 내려 어깨에 닿았다.","a":"음성 보현암 석조아미타여래좌상","c":"시도유형문화유산","nc":"","r":"충청북도","s":"음성군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1638919.jpg"},{"q":"이 ○○은 금강산에 대한 상세한 지리 표현과 화려한 색채효과로 그림지도 역할과 함께 장식화로서 제작된 지본담채의 12폭 ○○이다. 현재 전하는 ○○○○는 대부분 조선 중엽 이후 것으로 대체로 정통화법채, 민화채, 판화채의 세 종류로 나누는데, 이 그림은 민화채를 많이 원용하고 있으면서 청록산수화의 심원한 멋을 보여준다. <동국세시기>에 의하면 단오 때 금강산 일만이천봉을 부채에 그리는 풍습이 있었다 하는데, 이는 정초에 세화가 유행했듯이 단오 때는 단오화로서 유행했던 것이다.","a":"금강전도 12첩 병풍","c":"시도유형문화유산","nc":"","r":"부산광역시","s":"서구","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1636717.jpg"},{"q":"○○○○○은 파평 윤씨의 집성촌이었던 윤촌마을(○○○) 초입에 남수산을 뒤로하여 남동향으로 자리 잡고 있다. 1750년(조선 영조 26)경 건립되었다고 하며, 1960년경 중수하였다. 이 집은 정면 4칸× 측면 4칸 규모의 뜰집으로 사랑채와 안채가 연이어져 □자형을 이루고 있다. 구조는 자연석 기단위에 막돌초석을 놓고 그 위에 네모기둥을 세웠다. 상부구조는 사랑채와 안채 모두 삼량가로 대량위에 동자주를 얹어 종도리를 받게 한 간략한 구성이다.","a":"울진 매화리 윤광수 가옥","c":"문화유산자료","nc":"","r":"경상북도","s":"울진군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1663555.jpg"},{"q":"○○○는 언양현 사람으로 아버지인 김부는 예부시랑(禮部侍郞)을 지냈다. 그는 1216년(고려 고종 3)부터 1219년(고종 6)까지 거란군의 여러 차례 공격을 물리쳐 나라를 어려움에서 구하였다. 당시 13세기 동아시아의 정세는 몽골이 크게 흥기하고 있었으며, 거란 역시 몽골의 공격을 받아 1216년 압록강을 건너 고려의 북방지역으로 밀려오게 되었다. 이때 ○○○는 대장군으로 조양진(평안남도 개천시 조양)에서 거란군을 물리쳤고, 연주(평안북도 영변군)에서도 거란군의 포위를 돌파하였다. 이에 거란군은 청새진(淸塞鎭: 평안북도 희천)을 넘어 퇴거하였다.","a":"위열공김취려의묘","c":"시도기념물","nc":"","r":"울산광역시","s":"울주군","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1645868.jpg"},{"q":"1805년(純祖 5) 건립한 ○○○○○는 비각을 건립하여 보관하고 있다. 비는 조선시대 일반적인 형태인 팔각지붕형 갓석과 비신, 비대석으로 되어 있다. 비문은 金祖淳이 썼으며, 글씨는 申緯가 썼고, 篆字는 徐邁修가 썼다. 신위는 조선시대 4대 명필가였으며, 서매수는 당시 좌의정이었다. 비의 규모는 비신의 높이 228cm, 폭 106cm, 두께 39cm이다.","a":"춘천 장절공 신숭겸 신도비","c":"시도유형문화유산","nc":"","r":"강원특별자치도","s":"춘천시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1638337.jpg"},{"q":"○○○는 성주산문(聖住山門)과 밀접한 관계에 있었던 낭혜화상(朗慧和尙)의 제자였던 원랑선사(圓朗禪師, 816~883)가 머무르면서 이 지역 선종의 보급과 발전에 중요한 역할을 수 행하였던 곳으로 보물 ○○○○○ 원랑선사탑비와 도 유형문화유산인 ○○ 송계리 대불정주범자비와 관련된 역사 문화 환경 유존지역이다. 충북지역의 수많은 사찰과 폐사지들 중에서도 절대연대를 가름할 수 있는 신라 하대의 사찰로 중요한 학술적 의미를 갖는다.","a":"제천 월광사지","c":"시도기념물","nc":"","r":"충청북도","s":"제천시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/2020030310363100.jpg"},{"q":"조선 인조(재위 1623∼1649) 때 선비 채명보(1574∼1644)가 학문을 강론하던 곳이다. 그 뒤 후손들이 선생의 덕행을 널리 기리고자 새로 짓고 ‘○○○○’이라 이름을 고쳤다. 채명보의 휘는 선견, 자는 명보, 호는 양전헌이며 본관은 인천이다. 광해군 9년(1617) 생원시에 합격하였고, 서궁유폐사건이 일어나자 선비들과 함께 상소를 올려 잘못된 점을 지적하였다. 인조 2년(1624) 이괄의 난 때에는 향병을 모집하기도 하였으며, 인조 4년에 희릉참봉에 제수되었으나 받지 않았다. 고향으로 돌아와 성재정을 짓고 선비들과 학문을 논하면서 만년을 보냈다.","a":"성재서당","c":"시도유형문화유산","nc":"","r":"대구광역시","s":"동구","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1636857.jpg"},{"q":"신라 말기의 학자인 최치원 선생이 이곳 합포만에 머물면서 제자들을 가르친 곳이다. 최치원은 자가 해운이며, 시호는 문창후이다. 최치원(857∼?)은 가족과 더불어 이곳에 살다가 신라의 멸망을 미리 알고 합천 해인사로 망명하였다. 선생이 돌아가시고 ○○○는 그의 학문과 인격을 존경한 고려·조선시대의 문장가·선비들의 순례지가 되었다. ○○○는 보호축대로 둘러싸여 있으며 그 안에 최치원 선생 추모비가 있다. 추모비를 보호하기 위해 세운 비각은 앞면 3칸·옆면 2칸 규모로, 지붕은 옆면에서 볼 때 여덟 팔(八)자 모양인 팔작지붕이다.","a":"창원 월영대","c":"시도기념물","nc":"","r":"경상남도","s":"창원시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1655659.jpg"},{"q":"이 책은 조선 후기 ○○○ 적멸보궁의 중창사실과 이를 재정적으로 후원한 일반 시주자 및 인근 사찰의 시주스님을 기록한 책으로, ○○○ 적멸보궁(중대)에서 보관용으로 기록한 것이다. 각 장 8행(行)에 글자 수는 16∼25자로 불규칙하며, 모두 20장으로 이루어져 있다. 책에는 재물을 출연하여 시주하는 공덕을 찬양하는 내용의 발문, 일반 대시주자의 이름과 소원문이 보이며, 이어서 본사 비구를 비롯하여 인근의 사찰 및 경상도 은해사 스님들의 시주명이 차례로 기재되어 있으며, 권말에는 이를 증명하는 각 사찰명이 지역별로 기재되어 있다.","a":"오대산중대불량문","c":"문화유산자료","nc":"","r":"강원특별자치도","s":"평창군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1660630.jpg"},{"q":"금산읍 아인리에 위치해 있는 석탑으로, 원래 1층 기단(基壇) 위에 3층의 탑신(塔身)을 올린 모습이었을 것이나, 현재는 탑신의 2층 몸돌과 꼭대기의 머리장식이 없어진 상태이다. 기단은 최근에 조립된 것으로, 네 장의 판판한 돌을 세워 4면을 만들고, 판돌을 덮어 마무리하였다. 탑신의 1층 몸돌 남쪽면에는 선으로 새긴 부처 모습의 조각이 있으며, 한 돌로 이루어진 2층 지붕돌과 3층 몸돌은 그 위에 놓여 있는 3층 지붕돌의 크기가 잘 맞지 않아 불안정한 비례를 보인다. 지붕돌은 밑면의 받침이 1층은 4단, 2·3층은 3단이며, 네 귀퉁이에서 크게 치켜올라갔다.","a":"아인리석탑","c":"문화유산자료","nc":"","r":"충청남도","s":"금산군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1661446.jpg"},{"q":"높이 2.5m로, 이천 설성면 연화정사 대웅전 좌측 노천에 위치한 ○○○○이다. 목의 삼도(三道; 불상의 목에 표현된 세 줄의 주름으로 지혜를 상징) 외에는, 신체에 법의의 주름이나 팔 다리 등의 표현이 보이지 않는다.. 옷주름은 마모된 것이 아니라 애초에 표현하지 않은 것으로, 편평한 신체 표현과 함께 고려 시대 작품에서 볼 수 있는 특징이다. 불상은 가슴 부분에서 상하로 나누어지는 2매의 돌로 이루어졌다. 머리에는 원형의 보개(寶蓋 ; 인도에서 귀인의 외출시에 사용하던 양산을 불상의 머리 위에 갓처럼 씌운 것)를 쓰고 있다.","a":"이천자석리석불입상","c":"문화유산자료","nc":"","r":"경기도","s":"이천시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/2019051613524100.jpg"},{"q":"○○○○○은 ○○군 장계면 ○○○ 백화산 자락에 자리한 가야 수장층의 묘역으로 직경 20~30m 내외의 대형고분 20여기가 분포되어 있다. ○○○ 고분군에 대한 2차례 발굴조사를 통해 무덤내부에서 다양한 가야토기를 비롯하여 철제마구, 꺽쇠, 교구, 환두대도 등 피장자의 위상이 매우 높았었음을 짐작케 하는 최상급 가야유물이 출토 되었다. 또한, 한 봉토 내에 주곽과 부곽이 배치된 다곽식의 형태도 파악되었으며, 주곽과 부곽 모두 가야계 수혈식 석곽묘로 확인되었다.","a":"장수 삼봉리 가야고분군","c":"시도기념물","nc":"","r":"전북특별자치도","s":"장수군","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1653891.jpg"},{"q":"‘○○○○○’는 서운산 ○○○의 중수를 기념하기 위해 조선 경종 원년(1721)에 세운 비로 부도군(浮屠群)이 있는 사찰 입구에 위치한다. 직사각형 비좌(碑座) 위에 세운 비신과 그 위에 올린 이수(螭首)로 구성되었다. 비신은 화강암인데 비문이 마멸되어 판독할 수 없는 곳이 여러 곳이다. 비명과 서문은 나준(羅浚)이 짓고, 황하민(黃夏民)이 썼으며, 전액(篆額)은 김진상(金鎭商)이 썼다.","a":"청룡사사적비","c":"시도유형문화유산","nc":"","r":"경기도","s":"안성시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1637580.jpg"},{"q":"○○○는 치악산 중턱에 위치한 ○○○의 불이문 역할을 하는 건물이다. ○○○의 진입은 사천왕문을 통과하여 ○○○ 밑을 지나 대웅전 앞으로 나아가게 되어 있다. 앞면 5칸, 옆면 2칸의 익공집으로 맞배지붕의 형태를 하고 있다. 기단은 자연석이며 배흘림이 있는 둥근기둥을 세운 뒤에 그 위로 누각형 건물을 올렸다. 누각층은 대웅전 앞의 마당을 향해 개방시킨 형태이며, 기둥은 1층보다 빈약한 배흘림이 없는 원형기둥을 사용하였다. 천장은 우물반자이며, 누마루는 우물마루인데, 한때 마루에는 우리나라에서 제일 큰 멍석이 깔려 있었다고 한다.","a":"원주구룡사보광루","c":"시도유형문화유산","nc":"","r":"강원특별자치도","s":"원주시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1638289.jpg"},{"q":"조선시대의 문신 황파 김종걸이 효종 1년(1650) 무렵에 세운 정자로 당대 유림들의 교유, 토론, 풍류를 위해 지었다고 한다. 앞면 3칸·옆면 2칸 크기이며 지붕은 옆면이 여덟 팔(八)자 모양과 비슷한 팔작지붕이다. 간결하게 꾸민 건물로 가운데 칸은 마루를 놓았고 양쪽에 온돌방을 두었다. 누마루 주변에는 난간을 설치하였다. 정자 앞의 연못, 인공섬, 큰 바위들과 노송 등 주변 경관과 정자가 잘 어우러져 당시 양반들의 안목을 엿볼 수 있는 곳이다.","a":"도암정","c":"시도민속문화유산","nc":"","r":"경상북도","s":"봉화군","i":"http://www.khs.go.kr/unisearch/images/folklore_material/thumb/1658681.jpg"},{"q":"향교는 훌륭한 유학자를 제사하고 지방민의 유학교육과 교화를 위하여 나라에서 지은 교육기관이다. ○○○○는 처음 세워진 연대는 알 수 없으며, 1530년에 지금의 자리로 옮겼다. 1587년에 다시 짓고 그 후에 여러 번의 수리를 하였으나 비교적 원래의 형태를 잘 간직하고 있다. 현재 남아있는 건물은 대성전과 동무·서무, 명륜당과 동재·서재 등이 있다. 대성전은 공자를 비롯하여 여러 성현들의 위패를 모시고 제사 지내는 곳으로 동무·서무와 함께 제사공간을 이룬다. 명륜당은 학생들이 공부하던 곳으로 학생들의 거처인 동재·서재와 함께 배움의 공간을 형성한다.","a":"괴산향교","c":"시도유형문화유산","nc":"","r":"충청북도","s":"괴산군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1638548.jpg"},{"q":"충숙공 문극겸(1122∼1189)을 기리기 위해 세운 서원이다. 문극겸은 고려시대 무신들이 집권한 시기의 문신으로, 재상이 되었을 때에도 상장군을 겸하고 무신들의 자문에 응하는 등 문무를 겸비한 독특한 인물이었다. ○○○○은 정조 1년(1777) 대병면 역평리에 세웠다. 그 뒤 고종 7년(1871) 흥선대원군의 서원철폐령으로 철거되었다가 1957년에 사우 등을 복원하였다. 지금 있는 건물은 ○○댐 건설로 1985년에 옮겨 복원한 것이다.","a":"합천 송호서원","c":"문화유산자료","nc":"","r":"경상남도","s":"합천군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1664051.jpg"},{"q":"○○○ 이장형(李長亨, 1597­1671)의 고택이다. 건물의 정확한 건립 연대는 알 수 없으나 대체로 약 200년 전에 건립된 것으로 추정되고 있으며, 약 100년 전에 중수가 있었다고 한다. 정면 5칸, 측면 2칸의 ㄷ자형 안채와 정면 6칸, 측면 1칸의 一자형 문간채로 구성되어 있다. 20세기 초 중수 시에 일부 변경이 되었다고는 하나 전체적인 평면구성과 구조양식, 수납공간과 편의를 도모하기 위한 곳곳의 쪽마루, 그리고 환기창 등은 19세기 주택의 모습을 잘 나타내고 있다.","a":"안동칩와당고택","c":"문화유산자료","nc":"","r":"경상북도","s":"안동시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1663459.jpg"},{"q":"○○○○○는 1891년에 금어비구(金魚比丘)인 완송(玩松) 종친과 창림(昌林), 능오(能悟) 등이 함께 그린 것으로, 원래는 칠성각 내에 봉안되었다가 칠성각 철거 후 1973년 독성상과 함께 산령각으로 이안, 봉안되었다. 그림의 중앙에는 구름이 떠가고 폭포가 흘러내리는 산수를 배경으로 머리가 하얗게 세고 흰 수염이 무성한 늙은 비구형의 독성이 왼쪽 다리를 편안히 세우고 앉아 있는데, 독성의 뒤로는 잔잔한 격자문이 그려진 장자가 그려져 있다.","a":"청룡사독성도","c":"문화유산자료","nc":"","r":"서울특별시","s":"종로구","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/2018102314324100.jpg"},{"q":"○○○○는 살아 있는 화석이라 할 만큼 오래된 나무로 우리나라, 일본, 중국 등지에 분포하고 있다. 우리나라에는 중국에서 유교와 불교가 전해질 때 같이 들어온 것으로 전해지고 있다. 가을 단풍이 매우 아름답고 병충해가 없으며 넓고 짙은 그늘을 제공한다는 장점이 있어 정자나무 또는 가로수로도 많이 심는다. 벌교 ○○○의 ○○○○는 나이가 500년 정도로 추정되며, 높이는 40m, 둘레가 10m였으나, 원줄기가 불타고 밑에서 새로 난 싹이 자라 원줄기와 가지를 구별하기 어렵다. 또한 가지에서 발달한 혹 같이 생긴 유주(乳柱)가 특색이다.","a":"벌교고읍리은행나무","c":"시도기념물","nc":"","r":"전남광주통합특별시","s":"보성군","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1654308.jpg"},{"q":"이 영정은 ○○○○○선사의 좌안7분면 바닥가부좌상으로, 돗자리위에 방석을 깔고 왼손엔 목리문이 그려진 주장자를 쥐고, 오른손은 염주를 가볍게 쥐고 앉아 있다. 화면은 주색의 연속당초화문이 그려진 상단벽면과 돗자리의 이단구도로 이루어져 있다. 장삼과 가사의 의습선 주변으로는 가볍게 농담을 주어 음영을 자연스럽게 표현하고 있다. 화면 향좌측에 ‘○○○○○대선사진(喚應堂敏悅大禪師眞)’의 화제가 있으며, 화면 크기는 가로 75.2cm, 세로 121.0cm이다.","a":"환응당 민열 진영","c":"시도유형문화유산","nc":"","r":"경상남도","s":"양산시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/0000000001643025.JPG"},{"q":"창주(滄洲) 하증(1563~1624)은 남명학파의 중요인물로 창주가문의 후손들이 대를 이어 세거하면서 소장되어 전해지는 ○○○로 희귀한 준호구와 분재기에서도 별급문기, 유언, 증여문기 등 다양하게 전해지며, 산송이나 창주관련 위토를 둘러싼 상서, 전령, 완문 등의 문서도 양이 적지 않다. 또한 간찰의 양도 많고 작성기간도 오래된 것이 많아 조선시대 다양한 문서를 한눈에 볼 수 있으며 지방에 소재한 선비가문이 세거하면서 인근 유림들과의 유대관계를 살필 수 있고, 살아 온 과정들을 한눈에 알 수 있어 중요한 자료이다.","a":"진주 담산고택 고문서","c":"시도유형문화유산","nc":"","r":"경상남도","s":"진주시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1642421.jpg"},{"q":"백련사는 명승지 구천동을 대표하는 절로 신라 신문왕 때 백련선사가 숨어 살던 곳이다. 전해 내려오는 말에 의하면 여기서 백련이 솟아 나와서 절을 지었다고 한다. 이 절터에서는 광무 4년(1900)에 이하섭이 고쳐 지으면서 기념비를 세운 흔적을 찾아볼 수 있다. 한국전쟁 때 건물들은 불에 타 없어졌으나, 경종 3년(1723)에 만들어진 것으로 전하는 백련사의 종은 자리를 옮겨 두어 남아 있다. 지금의 건물은 1962년에 새로 지은 것이다. 대웅전은 앞면 5칸·옆면 3칸의 규모이며, 지붕은 옆면에서 볼 때 여덟 팔(八)자 모양과 비슷한 팔작지붕이다.","a":"백련사지","c":"시도기념물","nc":"","r":"전북특별자치도","s":"무주군","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1653529.jpg"},{"q":"이 불화는 상대에 결가부좌한 석가불을 중심으로 권속이 좌우로 둘러선 구도로서 이러한 형태는 희귀한 예에 속하며 특이한 법의문양, 문수보살을 장식한 금채 등 장식적으로도 독특한 면이 보인다. 당시 ○○○○○ 연구에 귀중한 자료로 판단되므로 유형문화유산으로 지정한다.","a":"정수사영산회상도","c":"시도유형문화유산","nc":"","r":"경상북도","s":"의성군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1641146.jpg"},{"q":"○○○에 보존되어 있는 ○○○○○인데, 탱화란 천이나 종이에 그림을 그려 액자나 족자 형태로 만들어지는 불화를 말한다. 비단 바탕에 채색하여 그린 이 탱화는, 주색바탕에 황색선묘로 도상을 표현하였으나, 황색선묘가 현재 칙칙하게 변색된 상태이다. 화면 상단 중앙에 본존인 석가여래좌상을 중심으로 가장 아래쪽에 협시보살상과 사천왕상이 좌우에 배치되어 있다. 그리고 그 바로 위쪽에는 8대보살상이 좌우 4구씩, 가장 위쪽에는 16나한상과 신장상이 좌우로 배치되어 있다.","a":"양산 통도사 백련암 석가모니후불탱","c":"문화유산자료","nc":"","r":"경상남도","s":"양산시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1664859.jpg"},{"q":"설매리 큰마을에 자리잡은 민가로 건축연대는 정확하지 않지만 약 150년 전에 지은 것으로 보인다. 지붕은 원래 초가였으나 1970년대에 슬레트로 고쳤다. 앞면 4칸·옆면 2칸 규모로 내부의 공간이 2줄로 배치된 겹집이다. 왼쪽부터 앞줄은 마구간·봉당·부엌이고, 뒤줄에는 방·마루·고방을 두었다. 봉당과 외양간의 바깥벽·봉당마루의 뒷벽은 널벽으로 하고 나머지는 심을 박은 흙벽으로 지었다. 일반적인 까치구멍집 요소를 일부 가지고 있으나 전체적으로 독특한 구성을 보이고 있는 민가주택이다.","a":"설매리겹집","c":"시도민속문화유산","nc":"","r":"경상북도","s":"봉화군","i":"http://www.khs.go.kr/unisearch/images/folklore_material/thumb/1658830.jpg"},{"q":"박진(朴晉, 1560~1597) 장군은 본관이 밀양(密陽)이며, 임진왜란 때 큰 업적을 세웠다. 임진왜란이 일어나자 작원(鵲院)에서 적을 맞아 싸우다 패해 포위되자, 밀양부(密陽府)를 소각하고 후퇴하였다. 이후 경상좌도병마절도사로 임명되어 경주성(慶州城)을 탈환했다. 이후 1593년에는 독포사(督捕使)로 밀양·울산 등지에서 전과를 올렸다. 1594년 2월에 경상우도병마절도사, 같은 해 10월 순천부사, 이어서 전라도병마절도사, 1596년 11월 황해도병마절도사 겸 황주목사를 지냈으며, 뒤에 참판에 올랐다.","a":"박진장군묘","c":"시도기념물","nc":"","r":"경기도","s":"연천군","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1646438.jpg"},{"q":"장대는 지휘하는 사람이 올라서서 명령하는 대를 가리킨다. 진주시 남성동에 있는 이 장대는 ○○○ 서북쪽의 높은 언덕에 있으며, 이곳은 서쪽과 북쪽 일대를 한 눈에 내다볼 수 있는 요충지대이다. 이곳은 내성 북쪽 끝 제일 높은 곳에 있어서, 낭떠러지 밑의 성밖은 물론 성안과 외성에 주둔한 병사까지도 지휘할 수 있었다. 현판의 이름도 이와 연관하여 진남루, 혹은 공북루라 하였다. ○○○는 임진왜란 때 손상된 것을 병마절도사 남이흥이 새롭게 고쳐 지은 건물이며, 이후에도 여러 차례의 보수를 거쳐 오늘에까지 이르렀다.","a":"진주성 북장대","c":"문화유산자료","nc":"","r":"경상남도","s":"진주시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1663789.jpg"},{"q":"1778년(정조2년)에 증이조참의 안기종의 5세손 설산재(雪山齋) 안여석(安如石)공이 주도하여 창건하였으며, 수파, 송은, 백산 선생 등 애국지사를 많이 배출한 유서 깊은 건물로서 수많은 인재가 ○○○에서 수학 연마하여 문과와 무과에 급제하고 현달한 유학자를 양성하였던 곳이다. 조선시대 후기의 건축물로서 한적한 공간에서 학문을 정진하며 후학을 양성하던 곳으로서 소박하면서도 단아한 공간을 구성하되 격식을 차려 누마루의 풍류를 살리면서도 사치하지는 않은 건물이다.","a":"의령 고산재","c":"문화유산자료","nc":"","r":"경상남도","s":"의령군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1666714.jpg"},{"q":"○○○란 임금이나 고관의 평생업적을 기록하여 그의 무덤 남동쪽에 세워두는 것으로, 이 비는 조선 선조 때의 문신인 ○○○의 행적을 기리고 있다. ○○○은 일찍이 부모를 여의고 계모와 동생을 효와 성실로써 극진하게 받들어 그 효행이 널리 알려졌다. 벼슬길에 올라서도 군민들을 어질게 다스렸고, 임진왜란 때에는 군량미가 부족하여 어려움을 겪는 것을 보고, 자신의 식량으로 이를 조달하는 등 나랏일에도 노력을 다하였다. 이에 조정에서는 첨지중추부사에 임명하였고, 팔순에 이르니 더욱 벼슬을 올리어 가선대부동지중추부사를 맡기었다.","a":"청주 신중엄 신도비","c":"시도유형문화유산","nc":"","r":"충청북도","s":"청주시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1638648.jpg"},{"q":"신도비란 왕이나 고관 등의 평생업적을 기록하여 후세에 전하고자 그의 묘 남동쪽에 세워두는 것으로, 이 비는 조선 선조 때의 문신인 김용(1557∼1620) 선생의 행적을 기리고 있다. 선생의 호는 운천으로, 34세에 문과에 급제하여 벼슬길에 올랐다. 예문관 검열·병조참의 등의 관직을 거쳤으며, 임진왜란이 일어났을 때에는 안동수성장이 되어 많은 공을 세웠다. 그 후 편수관이 되어『선조실록』의 편집과 편찬에 참여하기도 하였다. 비각안에 있는 비는 낮은 사각받침돌 위로 비몸을 세우고, 반달모양의 머릿돌을 올린 모습이다.","a":"운천신도비","c":"문화유산자료","nc":"","r":"경상북도","s":"안동시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1662463.jpg"},{"q":"이 유적은 1992년 10월부터 1993년 5월까지 약 7개월에 걸쳐 발굴조사가 실시된 경남 ○○시 의창구 동읍 육군종합정비창 내에 있는 청동기시대 유적이다. 이곳에서는 지석묘 23기, 수혈2기, 환호를 비롯하여 묘역으로 판단되는 길이 62.3m, 너비 21m의 대규모 석축시설이 확인되었다. 유물은 무문토기, 동검, 석검, 석촉 등 무기류와 관옥이 출토되어 청동기시대 지배계층의 위상이 어느 정도인지를 짐작하게 해준다.","a":"창원 덕천리 유적","c":"문화유산자료","nc":"","r":"경상남도","s":"창원시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1664336.jpg"},{"q":"만사(晩沙) ○○○은 본관이 청송(靑松)이다. 청요직(淸要職)을 두루 거치고 영의정에 이르렀으며, 효종 승하 후 원상(院相)으로 국정을 맡았다. ○○○ 묘는 사적으로 지정되어 있는 ‘윤관장군 묘’와 앞뒤로 인접해 있었다. 이로 인해 청송 심씨와 파평 윤씨 두 문중 간의 400년 산송(山訟; 묘지에 관한 다툼)은 유명하다. 이 다툼은 2007년 ○○○ 묘 등 청송 심씨 묘소를 동쪽으로 120여 미터 떨어진 곳으로 옮기는 대신, 파평 윤씨 문중이 이장할 땅을 청송심씨 문중에 제공했다.","a":"심지원묘및신도비","c":"시도기념물","nc":"","r":"경기도","s":"파주시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/2018010218475700.JPG"},{"q":"충청남도 아산시 온양관광호텔에 있는 것으로 1927년 신창면에 파손되어 흩어져 있던 것을 모아서 옮긴 것이다. 전체 높이는 84㎝이며 둥근 얼굴에 양 어깨를 감싼 옷을 입고 있다. 두 손은 무언가를 들어 마주 쥐고 가슴 위까지 올리고 있어 스님의 모습으로 보이기도 한다. 전반적인 불상의 형태로 보아 보아 조선 후기의 작품으로 추정된다.","a":"온천리석불","c":"문화유산자료","nc":"","r":"충청남도","s":"아산시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1661270.jpg"},{"q":"○○○ 대웅전으로 오르는 계단 양쪽에 놓여 있는 2기의 돌사자상이다. 받침돌을 따로 두지 않고 한돌로 조각하였는데, 하늘을 바라 보는 얼굴은 거의 수평으로 되어 있으며 사람 얼굴 모양을 하고 있다. 머리털은 구름무늬를 이루고 있고, 입은 약간 벌린 모습으로, 그 안에 이빨도 표현하였는데, 사실성은 떨어진다.","a":"광덕사 석사자","c":"문화유산자료","nc":"","r":"충청남도","s":"천안시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1661309.jpg"},{"q":"중국 삼국시대의 이름난 장군인 관우 운장의 영정을 모신 관왕묘로 서울의 옛성 동·서·남·북 4곳에 있던 관왕묘 중 하나이다. 규모는 앞면 3칸·옆면 1칸이며 지붕은 옆면에서 볼 때 사람 인(人)자 모양을 한 맞배지붕이다. 4쪽 여닫이문을 달았고 안쪽에 관우 부부상을 모시고 있다. ○○○는 조선시대의 민속신앙과 의식구조를 알 수 있는 자료가 되고 있다.","a":"성제묘","c":"시도유형문화유산","nc":"","r":"서울특별시","s":"중구","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1636051.jpg"},{"q":"林軒 鄭世弼(1494~1566)은 포은선생의 5대손으로 莊陵의 유신 설곡공 保의 증손이다. 1534년에 무과에 급제하고 여러 州郡의 守令을 거쳐 경상좌도 병마절도사를 역임하였다. 公은 관직의 재임 시에는 淸白吏로도 유명하였고, 퇴계 李滉 · 덕계 吳健과 교류하여 道義의 벗을 삼았으며, 영일정씨 초간본 족보인 「嘉靖癸丑譜」(1553)를 발행하였는데, 이 족보는 안동권씨 「成化譜」에 이어 두 번째로 오래된 족보이다.","a":"합천 정세필 묘비","c":"문화유산자료","nc":"","r":"경상남도","s":"합천군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1666681.jpg"},{"q":"조선 인종 때의 학자인 하서 김인후(1510∼1560) ○○을 새긴 ○○이다. 김인후는 1540년 문과에 급제하여 문원부정자를 시작으로 홍문관의 박사와 부수찬, 옥과현감 등의 벼슬을 지냈다. 시문에 뛰어나 10여 권의 ○○을 남겼으나 도학(道學)에 관해 쓴 책은 많지 않다. 천문, 지리, 의약, 산수에도 정통하였으며, 제자로는 정철, 조희문 등이 있다. 그가 죽은 후 ○○의 ○○○○, 옥과의 영귀서원 등에 모셔졌고, 시호는 ‘문정’이다.","a":"장성 필암서원 하서선생 문집 목판","c":"시도유형문화유산","nc":"","r":"전남광주통합특별시","s":"장성군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/2018112114430400.jpg"},{"q":"백야 ○○○ 장군이 살았던 곳이다. 선생은 충청남도 홍성 출신으로 대한제국 후기의 독립운동가이다. 1905년 을사보호조약이 체결된 후 청년학우회 등의 간부를 지냈고, 1913년에 대한제국 광복단에 가입하여 자금을 모으다가 체포되어 3년간 복역한 후 1917년 만주로 망명하였는데, 이후 13년간 평생을 항일전투에 몸바쳤다. 1920년 10월 청산리전투에서 일본군을 섬멸하였는데 이것이 독립 전투상 승리의 금자탑을 세운 일로 기록되는 청산리전투이다. 1929년 정신, 이붕해 등과 함께 한족총연합회를 조직하여 주석에 취임하고, 만주에 거주하는 동포의 교육과 민생에 주력했다.","a":"김좌진장군생가지","c":"시도기념물","nc":"","r":"충청남도","s":"홍성군","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1652811.jpg"},{"q":"전라남도 담양군 고서면 금현리 ○○○에 있는 불상으로, 불신과 광배(光背)를 하나의 돌에 새겼다. 머리에는 상투 모양의 머리묶음이 솟아 있고, 둥근 얼굴에 이목구비가 다소 형식화되어 있다. 체구는 평판적이며 왼쪽 어깨를 감싼 옷을 입고 있는데 U자형의 특징적인 옷주름을 도드라지게 새겼다. 몸 뒤쪽에 있는 배(舟)모양의 커다란 광배(光背)는 머리광배를 한 줄의 선으로 두르고 바깥부분에 불꽃무늬를 새겨 넣었다. 이 불상은 전라남도 영암의 도갑사 ○○○○○과 비슷한 양식으로 신라말 고려초에 유행한 지방적인 유파의 흐름을 잘 보여준다.","a":"영은사석조여래좌상","c":"시도유형문화유산","nc":"","r":"전남광주통합특별시","s":"담양군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1640019.jpg"},{"q":"○○읍의 남산 정상부 서쪽 경사면에 일렬로 늘어선 4기의 큰 무덤이다. 오래전에 모두 도굴되어 돌방 안쪽이 노출되고, 봉토의 외형도 크게 무너져 있었던 것을 1993년에 발굴 조사하였다. 그 결과 1호분 안쪽은 구덩식돌덧널무덤(수혈식석곽묘)이고, 4호분은 굴식돌방무덤(횡혈식석실묘)임을 밝혀냈다. ○○○○○무덤들은 이 지역 고대사를 밝혀 역사를 다시 조명할 자료로 매우 중요한 가치를 가진 유적이다.","a":"의령 중동리 고분군","c":"시도기념물","nc":"","r":"경상남도","s":"의령군","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1656392.jpg"},{"q":"○○○터 입구 양옆에 나란히 서 있는 2기의 돌장승으로, 절의 영역표시 기능과 더불어 경내에서의 수렵·어로 등의 금지를 알리며 잡귀의 출입을 막는 수호신상의 구실을 하였던 것이다. 거대한 화강석을 최대한 자연스럽게 살려 아무런 조각이 없는 민둥머리와 이마, 커다란 왕방울 눈, 우뚝 솟은 주먹코와 작은 입이 조각되어 있다. 두 장승의 모습이 거의 비슷하나, 남장승은 외수염을 하나 더 조각해 두었다. 장승의 앞에는 각각 넓직한 판돌의 제단이 놓여 있으나, 장승과 관련된 의례는 전하지 않고, 다만 할머니들이 때를 가리지 않고 소원을 비는 곳이라 한다.","a":"총지사지석장승","c":"시도민속문화유산","nc":"","r":"전남광주통합특별시","s":"무안군","i":"http://www.khs.go.kr/unisearch/images/folklore_material/thumb/1658383.jpg"},{"q":"○○군 정곡면 죽전리에 있는 ○○○의 정상부에 약 200m 가량의 흙으로 쌓아 올린 성의 흔적이 남아 있다. 이 산성을 쌓은 시기는 정확히 알 수가 없으나, ○○읍 하리 벽화산에 있는 벽화산성(碧華山城)과 비슷한 시기에 쌓은 것으로 추정된다. 이 산성은 임진왜란 때의 의병장인 망우당 곽재우(1552∼1617) 장군의 전적지 가운데 하나이며, ○○○은 산의 형태가 호랑이 꼬리를 닮았다 해서 얻은 이름이다.","a":"의령 호미산성","c":"시도기념물","nc":"","r":"경상남도","s":"의령군","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1655442.jpg"},{"q":"월천 조목(1524∼1606)이 후진을 양성하기 위해 세운 서당이다. 조목은 퇴계 이황에게서 가르침을 받고 명종 7년(1552) 생원시에 합격하였으나 여러 벼슬을 사양하고 이황을 가까이 모시면서 학문 연구에만 주력한 분이다. 임진왜란 때에는 동생 및 두 아들과 더불어 의병을 모집하여 활동하였고 이황의 제자 가운데 유일하게 도산서원 상덕사에 모셨다. 중종 34년(1539)에 세운 이 서당은 앞면 4칸·옆면 2칸 규모로, 지붕은 옆면에서 볼 때 여덟 팔(八)자 모양인 팔작지붕으로 꾸몄다. 가운데 2칸에는 마루를 구성하고 양 옆으로 온돌방을 배치하였다.","a":"월천서당","c":"시도기념물","nc":"","r":"경상북도","s":"안동시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1654453.jpg"},{"q":"미산 김이도의 덕을 추모하고 후진을 양성하기 위해 세운 사설 학원이다. 김이도는 경당 장흥효의 문인으로 학문이 뛰어나 사림들의 존경을 받았다. 선생은 ‘학사가 없으면 뜻을 펼 수 없다.’는 홍학 이념으로 후진을 양성하였다. ○○○○는 현종 11년(1670)에 세웠다. 규모는 앞면 3칸·옆면 2칸으로, 지붕은 옆면에서 볼 때 여덟 팔(八)자 모양인 화려한 팔작지붕이다. 건물은 평범한 평면구성이나 앞쪽 큰마루는 난간을 돌려 다락집으로 꾸며 매우 단아한 모양을 지니고 있다. 큰마루 위에는 ‘○○○○’와 ‘삼경당’이라고 쓴 현판이 걸려 있다.","a":"미산학사","c":"문화유산자료","nc":"","r":"경상북도","s":"예천군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1662674.jpg"},{"q":"범어사 북쪽 금정산 정상 부분의 화강암 절벽 위에 새긴 높이 12m의 거대한 불상이다. 가는 선으로 불상을 새겼는데 지금은 오랜 비바람으로 손상이 심하게 된 상태이다. 머리 위에는 상투 모양의 머리묶음이 둥글게 솟아 있으며, 귀는 어깨까지 길게 늘어져 있다. 얼굴은 네모진 형태이고 활 모양의 가는 눈, 큰 코 등이 토속적인 인상을 준다. 옷은 오른쪽 어깨를 드러낸 채 입고 있으나, 가슴 아래부분은 많이 닳아서 자세히 살펴보기 어렵다. 토속적인 지방색이 느껴지는 모습, 가는 선으로 불상을 만든 점 등에서 고려시대에 만들어진 작품으로 보인다.","a":"양산 가산리 마애여래입상","c":"시도유형문화유산","nc":"","r":"경상남도","s":"양산시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1641452.jpg"},{"q":"조선 선조 때 문신인 ○○○의 공적을 기리기 위해 1640년(인조 18)에 건립한 비이다. 본관은 동래(東萊)이고 호는 사암(思菴)이다. 왕명을 받아 권신 윤원형(尹元衡)의 사건을 강직하게 조사하여 명성을 얻었다. 청백리로서 명망이 높았다. ○○○는 묘역 아래에 있는 혁림사(赫臨祠; 동래정씨 사당) 경내의 비각 안에 세워져 있다. 사각형의 받침돌에 비신(碑身; 글씨를 새기는 부분)을 세우고 이수(螭首; 용을 새겨 장식한 비석의 머릿돌)를 올린 방부이수(方趺螭首) 양식을 갖추고 있다.","a":"정대년신도비","c":"시도유형문화유산","nc":"","r":"경기도","s":"여주시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1637652.jpg"},{"q":"『○○○○○』은 범자(梵字) · 한자(漢字) 대조의 5가지 진언에 한글의 음역을 더한 책이다. ＜오대진언＞이란 사십이수진언(四十二手眞言) · 신묘장구대다라니(神妙章句大陀羅尼) · 수구즉득다라니(隨求卽得陀羅尼) · 대불정다라니(大佛頂陀羅尼) · 불정존승다라니(佛頂尊勝陀羅尼)를 말한다. 이 『○○○○○』은 두 가지 이유에서 간행하였는데, 첫째, 인수대비(仁粹大妃)*의 명(命)에 따라 일반 민중이 진언을 쉽게 익혀 암송하도록 하기 위해서, 둘째, 인수대비와 인혜왕대비(仁惠王大妃)가 세조 등 선왕(先王)의 뜻을 추모하기 위해서이다.","a":"오대진언집","c":"시도유형문화유산","nc":"","r":"충청북도","s":"단양군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1638888.jpg"},{"q":"거문고는 5세기 이전 고구려에서 만든 우리나라의 대표적인 현악기로, 3옥타브 정도를 오르내리는데 우리나라 악기 중 가장 넓은 음역을 자랑한다. 이 거문고는 유중교((柳重敎), 1821-1893)가 연주하던 칠현(七絃)의 거문고로서 그의 후손인 유성균이 소장하고 있던 것을 기증받아 제천의병전시관에서 전시 관리하고 있으며 1800년대 중반에 제작된 것으로 추정되며 현존하는 거문고중 가장 오래된 것으로 알려지고 있다.","a":"자양금","c":"시도민속문화유산","nc":"","r":"충청북도","s":"제천시","i":"http://www.khs.go.kr/unisearch/images/folklore_material/thumb/1658211.jpg"},{"q":"대전분지의 3대 하천인 대전천·유등천·갑천이 합류하여 갑천이 북쪽으로 흐르기 시작하는 지점의 동쪽에 위치하는 표고 140m(비고 70m)의 구릉에 위치하고 있다. 구릉의 정상부 및 그 남쪽의 계곡을 아울러 전체 모양이 삼태기와 같은 이른바 ‘포곡식(抱谷式)’ 토축성이다. 성벽의 둘레는 약 580m이며, 계곡부를 통과하는 남성벽의 가운데 부분이 문지로 추정된다. 유적에서 관찰되는 유물로는 통일신라 말~고려 초 무렵의 토기편이 많고, 일부 드러난 성벽 축조토에 그러한 토기편이 혼입되어 있어 축성 시점이 이르지 않음을 알 수 있다.","a":"우술성","c":"시도기념물","nc":"","r":"대전광역시","s":"대덕구","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1645785.jpg"},{"q":"높이 4.3ｍ로 ○○○ 마을 안에 모셔져 있는 석불상이다. 돌기둥 같은 신체에 머리에는 원형에 가까운 보개(寶蓋 ; 인도에서 귀인의 외출시에 사용하던 양산을 불상의 머리 위에 갓처럼 씌운 것)를 쓰고 있다. 발목 이하는 땅에 묻혀 있으며 불상 앞에는 자연석의 넓은 돌을 두어 불단으로 이용하고 있다. 민머리에 얕은 육계(肉髻; 상투 모양으로 솟은 붓다의 정수리, 붓다의 지혜를 상징)가 있고, 이마 중앙에는 백호(白毫; 흰 터럭이 말린 것으로 이곳에서 빛이 나온다고 함)가 표현되었다.","a":"용인미평리약사여래입상","c":"문화유산자료","nc":"","r":"경기도","s":"용인시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1659987.jpg"},{"q":"○○○는 횃불과 연기를 이용하여 급한 소식을 전하던 옛날의 통신수단을 말한다. 높은 산에 올라가서 불을 피워 낮에는 연기로 밤에는 불빛으로 신호를 보냈다. ○○○에 있는 이 ○○○○는 조선시대 봉수체제가 확립되었던 세종 24년(1438)에 ○○○ 동·서에 만든 ○○○ 가운데 동쪽 ○○○○이다. 평안북도 강계에서 시작하여 황해도, 경기도 내륙, 고양 해포나루, 무악동봉, 남산 훈도방으로 연결되는 봉수를 남산에 최종적으로 연락하는 곳이다. 터만 남아있던 것을 서울정도 600년 기념사업의 하나로 1994년에 복원하였다.","a":"무악산동봉수대터","c":"시도기념물","nc":"","r":"서울특별시","s":"서대문구","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1644788.jpg"},{"q":"화면 중앙에 ○○○여래가 결가부좌하고 있고, 앞쪽 전면에는 천부복식의 범천·제석천상이 합장형으로 시립하고 있다. 본존 좌우에는 보관에 화불이 있는 관음보살과 정병이 있는 대세지보살이 윤왕좌를 취하고 있고, 좌우 바깥에는 보살 2위씩 총4위의 보살이 합장한 모습으로 시립하고 있다. 화면 하단 전면에는 사천왕상이 배치되어 있고, 상단에는 아난과 가섭, 2위의 금강, 10위의 나한상 등이 대칭을 이루며 이룬다. ○○○여래는 육계가 뾰족하게 솟아올랐고, 황색과 주색을 번갈아 사용하여 정상계주와 중간계주를 각각 표현하였다.","a":"복천사 아미타극락회상도","c":"시도유형문화유산","nc":"","r":"부산광역시","s":"영도구","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/2020030609232400.png"},{"q":"○○○은 조덕린(1658∼1737) 선생이 말년에 수양하고자 경치 좋기로 이름난 곳을 찾아서 조선 영조 3년(1727)에 지은 정자이다. 계곡을 낀 경사진 곳에 자리잡고 있으며 앞면 3칸·옆면 2칸 규모에 마루를 중심으로 양쪽에는 온돌방을 두었다. 현판 ‘○○○’과 내현판 ‘마암’은 정조(재위 1776∼1800) 때 이름난 정승 채제공이 직접 썼다고 전하고 있다.","a":"봉화 사미정","c":"시도유형문화유산","nc":"","r":"경상북도","s":"봉화군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1641318.jpg"},{"q":"이 작품은 가선대부 ○○○의 ○○화로 정면향의 전신교의좌상이다. 인물의 육신부는 살색을 바르고 주색으로 윤곽선을 처리하였으며, 육신선을 따라 주색을 바림하여 음영을 표현하였는데, 특히 넓게 펼쳐 바림한 이마와 눈썹이 돋보인다. 상검선은 농묵세선, 하검선은 주색세선으로 처리하고, 눈머리와 눈꼬리에는 담묵으로 바림하였으며, 갈색 눈동자 가운데 농묵을 찍어 동공을 표현하였다. 눈썹·수염의 모근표현은 먼저 담묵으로 펴 바른 뒤 세선의 농묵과 백세선으로 묘사하였고, 귀의 모근표현은 바림 없이 농묵세선으로 그려내어 안면부에 약간의 변화를 주고 있다.","a":"양산 통도사 김경호 초상","c":"시도유형문화유산","nc":"","r":"경상남도","s":"양산시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1643050.jpg"},{"q":"조선 개국공신인 춘곡(春谷) 정탁(鄭擢, 1363∼1423) 선생의 묘이다. 1392년 이성계를 도와 개국공신이 되어 성균대사성에 올랐으며, 1398년(정종 즉위년) 제1차 왕자의 난 때 이방원을 도와 정사공신 2등에 올랐다. 묘역은 사각형태의 커다란 봉분 앞에 ‘ㄷ’자 모양의 둘레석을 하단에 쌓은 독특한 형태이다. 이는 고려 말기의 묘제로 조선 초기까지 잔존한 것인데, 이와 유사한 형태가 같은 지역 파주의 황희 정승의 묘역에도 남아 있어 비교가 가능하다. 묘역은 계단식으로 3단으로 나누고 계체석(階砌石; 묘역을 구분하는 편평하고 긴 경계석)으로 구분하였다.","a":"춘곡정탁묘역","c":"시도기념물","nc":"","r":"경기도","s":"파주시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1647074.jpg"},{"q":"○○○은 승지 김양근(金瀁根, 1858∼1926)의 아들 김승희(金昇熙, 1892∼1958)가 부친의 유덕을 추모하기 위하여 1928년 당시 쌀3백석을 들여 지은 누정이다. 남쪽으로 완만한 경사면을 따라 축대를 쌓아 단을 만들고 단 위에 건축물을 배치하였다. 솟을 대문에 누마루를 갖춘 가정문(嘉貞門)을 통해 안으로 들어가 계단을 오르면 좌우로 동재와 서재를 배치하였고, 다시 축대를 쌓은 위에 ○○○이 세워져 있다.","a":"운서정","c":"시도유형문화유산","nc":"","r":"전북특별자치도","s":"임실군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1639594.jpg"},{"q":"이 영정(○○○○○영정)은 ○○○ 천유선사의 좌안 8분면 바닥가부좌상으로, 녹색벽면과 돗자리의 이단구도를 배경으로 격자문의 주색가사를 입고 왼손에는 주장자를 오른손에는 염주를 쥔 채 가부좌하고 있다. 선사의 우측에 경전이 놓여진 서안이 배치되었다. 화면향좌측에 주지묵서의 ‘양종도총섭구용○○○대선사진(兩宗都摠攝九龍堂天有大禪師眞)’의 화제가 있고, 향우측에 영찬이 있어 1825년에 제작되었음이 확인된다. 배면중앙에는 범자주서 3행이 있다. 화면크기는 가로 85.5cm, 세로 126.0cm이다.","a":"구룡당천유 진영","c":"시도유형문화유산","nc":"","r":"경상남도","s":"양산시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/0000000001642990.JPG"},{"q":"○○○○○의 나한도 앞에 모셔져 있는 돌로 만든 나한상으로, 전체 16구 중 현재 12구만 남아 전하며, 나머지 4구는 근래 다시 추가 조성된 상태이다. 나한은 ‘아라한(阿羅漢)’의 준말로, 온갖 번뇌를 끊고 깨달음을 얻어서 세상 사람들의 공양을 받을 만한 공덕을 갖춘 성자를 뜻한다. 나한상 12구 모두 화강석재 위에 백토와 기름을 발라 처리하였으며, 얼굴과 머리 부분에는 먹·붉은색·백색·녹색으로 얼굴 윤곽과 모근을 표현하였다. 자세는 주로 결가좌를 취하고 있으나 반가좌의 경우도 있으며, 옷차림은 장삼에 가사를 걸친 모습이다.","a":"마하사 응진전 석조나한상","c":"문화유산자료","nc":"","r":"부산광역시","s":"연제구","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1659366.jpg"},{"q":"<○○○○>은 선조 대의 문신이자 학자이며, 임진왜란 때 의병장으로 활동한 조헌(趙憲, 1544~1592)의 학문과 덕행을 추모하기 위해 인조 26년(1648) 조헌의 옛 집터에 창건하여 위패를 모신 곳이다. 숙종 1년(1675) 송준길(宋浚吉)의 청으로 ‘牛渚(우저)’라고 사액(賜額, 임금이 사당, 서원 등에 이름을 지어서 새긴 현판을 내리는 일)되었다. 순조 34년(1834) 중건 이후 고종 8년(1871) 흥선대원군(興宣大院君)의 서원철폐령에도 훼철되지 않고 남아 있다가 1973년부터 3년에 걸쳐 전면 보수가 이루어졌다.","a":"우저서원","c":"시도유형문화유산","nc":"","r":"경기도","s":"김포시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1637340.jpg"},{"q":"불신과 광배가 하나의 돌에 새겨진 불상으로 양 손이 없어진 것을 제외하면 원래의 형태가 거의 완전하게 유지되고 있다. 민머리 위에는 상투 모양의 머리묶음이 높게 표현되었으며 길고 가는 눈, 작은 입술 등에서 고려적인 특징이 보인다. 양 어깨를 감싸고 있는 옷은 둥글고 단아한 모습이지만, 엄격한 좌우대칭을 이룬 옷주름선은 상당히 형식화 되었다. 광배(光背)는 끝이 둥근 반원형으로 머리광배와 몸광배를 선으로 도드라지게 구분했을 뿐 아무런 무늬도 없다. 대좌(臺座)는 반원형으로 연꽃이 새겨진 상대와 일부가 땅속에 묻힌 4각형의 하대로 되어있다.","a":"정서리석조여래입상","c":"시도유형문화유산","nc":"","r":"경상남도","s":"하동군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1641443.jpg"},{"q":"삼척 ○○○ 마을의 국도 도로변에는 금옥각(金玉閣)이라는 비각이 마련되어 있는데, 그 안에 이 2기의 철비를 모시고 있다. 하나는 삼척부사 이규헌에 대한 고마움과 어진 정치를 영구히 기리기 위해 세워놓은 것이고, 다른 하나는 옆의 비를 세우는데 참여한 주민들의 공을 잊지 않고자 세워둔 것이다. 이규헌은 조선 헌종 원년(1835) 삼척부사로 부임해 와 1839년까지 지내면서 이 지역의 백성들을 위해 어진 정치를 폈다. 특히 조선 헌종 3년(1837) 가뭄과 홍수로 백성들이 굶주리게 되자 역둔창의 양곡을 나누어주어 많은 백성들을 구하기도 하였다.","a":"삼척역둔리철비(부사이규헌영세불망비및금옥첨원비)","c":"문화유산자료","nc":"","r":"강원특별자치도","s":"삼척시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1660560.jpg"},{"q":"○○○○○은 충청남도 천안시 직산면 해발 176m 성산의 계곡을 감싸고 둘러쌓은 성이다. 『동국여지승람』에 의하면 사산성은 흙으로 쌓은 성이며, 둘레는 2,947척이며 성안에 우물터가 1개 있다고 전하나 찾을 수 없다고 기록하고 있다. 이곳에서는 5∼6세기 전반의 백제나 고구려의 것으로 보이는 토기들과 6세기후반의 신라계 유물에 속하는 굽다리접시(고배), 그리고 줄무늬·격자무늬를 새긴 기와조각 등이 발견되었다. 학계에서는 마한의 목지국이 쌓은 것으로 추정하기도 한다. 문헌사 및 고고학상 매우 중요한 유적으로 평가되고 있다.","a":"직산사산성","c":"시도기념물","nc":"","r":"충청남도","s":"천안시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1652866.jpg"},{"q":"조선 중기의 문신이며 인조의 장인인 한준겸(韓浚謙, 1557∼1627) 선생과 후손들의 가족 묘역이다. 묘역은 한준겸 묘를 중심으로 좌측에 아들 한회일(韓會一) 묘역과 우측에 손자 한이성(韓以成) 묘역, 그리고 앞쪽에 증손 한두상(韓斗相) 묘역이 4대에 걸쳐 조성되어 있다. 한준겸 묘역은 부인 황씨(黃氏)와 합장한 단분(單墳 ; 하나의 봉분)의 형태이다. 17세기 전반기의 묘제를 잘 보여주는 곳으로 묘표에서부터 동자석인과 장명등까지 골고루 갖춘 표준이 되는 묘역이다. 묘표는 1628년(인조 5)에 제작한 것으로 대리석 재질의 정갈한 비석이다.","a":"청주한씨문익공파묘역","c":"시도기념물","nc":"","r":"경기도","s":"시흥시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/2018103113231300.jpg"},{"q":"선암사 뒷편에 서 있는 석탑으로, 일부만 남아 있는 기단부(基壇部) 위에 3층의 탑신(塔身)을 얹고 있다. 탑신의 몸돌에는 기둥 모양을 새겨 놓았고, 특히 1층 몸돌 4면에는 연꽃받침 위에 앉은 부처의 모습을 돋을새김으로 조각해 놓았다. 지붕돌은 밑면의 받침이 4단씩인데, 3층 지붕돌이 많이 훼손되어 있다. 꼭대기에는 머리장식이 모두 없어지고, 기단의 한 부분으로 보이는 돌 하나가 놓여 있다. 전체적으로 탑신의 1층 몸돌에 비해 2층 몸돌이 급격히 줄어들고, 1층 몸돌의 불상 조각이 많이 닳아있어 화려하거나 세련되어 보이지는 않는다.","a":"의성치선동석탑","c":"문화유산자료","nc":"","r":"경상북도","s":"의성군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1662392.jpg"},{"q":"2006년 10월 30일 충청남도 유형문화유산으로 지정 ○○○○○ 부도는 통일신라 말기 팔각원당형 부도를 계승한 고려 초기의 부도로 추정된다. ○○○○○ 부도는 고려시대의 팔각원당형(八角圓堂型) 부도(浮屠)로서, 통일신라 말기 도선국사(道詵國師)[827~898]의 것으로 전해져 도선의 부도라고도 불린다. ○○○○○ 부도는 높이가 2.4m이고, 화강암으로 이루어져 있다. 두 마리 용이 여의주를 물고 있는 그림이 양각되어 있으며 팔각원당형의 전형적인 부도 양식을 따르고 있다.","a":"예산 송림사부도","c":"시도유형문화유산","nc":"","r":"충청남도","s":"예산군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1639300.jpg"},{"q":"신라 혜공왕 때 진표율사가 화암사(華巖寺)라는 이름으로 세운 절이다. 조선 인조 1년(1623)에 소실되었다가 인조 3년(1625)에 고쳐 짓는 등 여러 차례 소실과 재건을 반복하였다. 고종 1년(1864)에는 지금 있는 자리인 수바위 밑에 옮겨 짓고 이름도 수암사(穗岩寺)라 하였다가 1912년에 다시 화암사(禾岩寺)로 이름을 바꾸었다. 한국전쟁 때 다시 한 번 불에 타 훗날 법당만 다시 지었다. 1991년 세계 잼버리대회 준비를 위해 기존 건물을 철거하고 새로 지어 오늘에 이르고 있다.","a":"고성화암사","c":"문화유산자료","nc":"","r":"강원특별자치도","s":"고성군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1660545.jpg"},{"q":"독립운동가인 ○○○ 선생의 ○○로, 선생은 충청북도 ○○ 출신이며 호는 보재이다. 선생은 이시영, 이규형 등과 신학문을 공부하였다. 을사보호조약이 체결된 후, 통분을 금치못해 길거리에서 연설한 후 집 밖에 나오지 않았다. 1907년 네덜란드 헤이그에서 열린 만국평화회의에 조선이 독립국임을 주장하는 고종의 밀서를 가지고 갔으나 뜻을 이루지 못했다. 조국의 국권회복을 위하여 노력하다가 1917년 연해주에서 생애를 마쳤다. 가옥은 앞면 3칸·옆면 1칸 규모로 흙벽돌로 쌓고 진흙으로 마감한 초가이다. 40여년 전에 무너졌던 것을 최근에 복원·수리하였다.","a":"진천 이상설 생가","c":"시도기념물","nc":"","r":"충청북도","s":"진천군","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1650054.jpg"},{"q":"조선 세종 때의 문신인 ○○○○○ 유물로, 계에 관한 사항을 정리한 첩(帖)이다. 그는 단종 때에 문과에 급제하여 권지정자가 되었고, 세조 때는 형 신숙주가 단종 폐위에 가담함에 따라 벼슬을 사양하고, 순창으로 낙향하였다. 이곳에서 귀래정이라는 정자를 짓고 산수를 즐기며 은둔생활을 하였다. 말년에는 70세가 넘은 노인 10명과 계회를 맺어 십노계(十老契)라 이름하고, 첩 10개를 만들어 각자 소유하였는데, 그 중에 하나만이 남은 것으로 추정된다. 이 첩은 총 420자로 되어 있는데, 여기에는 계를 맺은 연유, 목적, 성격, 행동 등이 기록되어 있다.","a":"신말주선생의십로계첩","c":"시도유형문화유산","nc":"","r":"전북특별자치도","s":"순창군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1639608.jpg"},{"q":"○○○○은 경상남도 ○○군 칠원읍에 있는 해발 250m의 산정상에 돌로 쌓은 성이다. 총 길이가 450m인데 동·서의 길이가 180m, 남북 길이가 57m인 타원형 산성이다. 산성을 쌓은 시기는 정확히 알 수 없으나 마을주민들의 말에 의하면, 임진왜란 때 사용한 성이라 하며, 1917년에 조사된 『조선고락조사보고』에는 칠원면 유원리와 칠서면 신산리에 돌로 쌓은 유원리 산성으로 기록되어 있다. 현재 성벽 일부는 허물어진 상태이나 문터가 남아있으며, 성 안에는 건물터가 남아있다.","a":"함안 칠원산성","c":"문화유산자료","nc":"","r":"경상남도","s":"함안군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1664327.jpg"},{"q":"1916년 초창된 ○○○는 3면에 누마루를 갖춘 정자 형식의 정자로서 전라도 지역에는 예가 많으나 경남지역에서는 비교적 드문 건축유형이다. 치목과 결구가 섬세하고 수장이 미려하여 근대기 전통건축의 특징이 강한 근대한옥1916년 초창된 ○○○는 3면에 누마루를 갖춘 정자 형식의 정자로서 전라도 지역에는 예가 많으나 경남지역에서는 비교적 드문 건축유형이다. 치목과 결구가 섬세하고 수장이 미려하여 근대기 전통건축의 특징이 강한 근대한옥","a":"진주 수졸재","c":"문화유산자료","nc":"","r":"경상남도","s":"진주시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/2023063022482200.JPG"},{"q":"향교는 훌륭한 유학자를 제사하고 지방민의 유학교육과 교화를 위하여 나라에서 지은 교육기관이다. ○○○○는 조선 태조(재위 1392∼1398) 때 지은 것으로 순조 4년(1804)에 명륜당과 동재·서재를 고치고 풍화루를 지었다. 1816년에는 대성전을 고쳤으며 그 후 여러 차례의 수리가 있었다. 현재 남아 있는 건물은 대성전·동무·서무·명륜당·풍화루 등과 부속건물들이 남아있다. 대성전은 공자를 비롯하여 여러 성현들의 위패를 모시고 제사 지내는 곳으로 동무·서무와 함께 제사공간을 형성한다. 명륜당은 학생들이 공부하던 강당으로 이것을 중심으로 배움의 공간이 이루어진다.","a":"진천향교","c":"시도유형문화유산","nc":"","r":"충청북도","s":"진천군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1638546.jpg"},{"q":"규장각 대제학을 지낸 민승세가 1820년경 고향으로 돌아와 지은 집이다. 이 가옥은 안채, 사랑채, 행랑채가 ㄱ자 형태로 되어 있다. 안채 지붕은 옆면에서 볼 때 여덟 팔(八)자 모양을 한 팔작지붕이다. 6대째 살아온 이 집 주인인 민익현은 민승세 공의 5대손이다.","a":"민익현가옥","c":"문화유산자료","nc":"","r":"충청남도","s":"천안시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1661357.jpg"},{"q":"경상남도 ○○군 설천면 진목리 ○○○의 정상에 지어진 산성으로, 산꼭대기를 빙둘러 돌로 쌓았다. 성의 둘레는 1.5㎞, 성벽의 높이는 5∼6m이고 윗부분의 폭은 2.4m인데, 성벽의 바깥쪽은 깬돌을 이용하여 겹으로 쌓아 올리고, 안쪽은 자갈과 흙을 섞어서 채워 성벽을 다졌다. 성벽의 둘레에는 네모꼴의 망대(적의 동정을 살피기 위하여 세운 높은 대)가 있었던 흔적이 있다. 성 안의 중앙에는 건물터와 연못터가 있으며, 천씨(千氏) 성을 가진 장군과 일곱 시녀 사이에 얽힌 전설이 있는 제사터가 있다.","a":"남해 대국산성","c":"시도기념물","nc":"","r":"경상남도","s":"남해군","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1654792.jpg"},{"q":"○○○ 극락보전에 모셔져 있는데, 구체적인 기록이 없어 만든 때와 만든 이는 알 수 없다. 단지 ○○○의 다른 현판에 ‘1745년(영조21)에 없어진 절을 다시 세우면서 ○○○라 하였다’고 기록되어 있는데, 이때 불상도 함께 만든 것으로 보인다. 불상은 신체에 비해 머리가 큰 편으로 얼굴을 앞으로 약간 내민 구부정한 자세에 근엄한 표정을 짓고 앉아 있다. 네모진 얼굴과 신체, 지나치게 두꺼워 몸의 양감이 드러나지 않는 옷자락 표현 등, 조선 후기 불상의 특징을 따랐다.","a":"쌍계사목조여래좌상","c":"시도유형문화유산","nc":"","r":"경기도","s":"안산시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1637744.jpg"},{"q":"○○○는 청동기시대의 대표적인 무덤으로 고인돌이라고도 부르며, 주로 경제력이 있거나 정치권력을 가진 지배층의 무덤으로 알려져 있다. 우리나라의 고인돌은 4개의 받침돌을 세워 돌방을 만들고 그 위에 거대하고 평평한 덮개돌을 올려 놓은 탁자식과, 땅 속에 돌방을 만들고 작은 받침돌을 세운 뒤 그 위에 덮개돌을 올린 바둑판식으로 구분된다. 경상남도 양산시 ○○○에 남아 있는 1기의 고인돌은 일반적인 바둑판식에 해당하며, 덮개돌은 길이 2.4m, 너비 1.55m이다. 고인돌의 하부구조는 조사가 되지 않아 정확하게 알 수 없지만 지하에 무덤방이 있을 것으로 추정된다.","a":"양산신기리지석묘","c":"시도기념물","nc":"","r":"경상남도","s":"양산시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1655467.jpg"},{"q":"안성 봉업사지 인근에 있는 높이 3.9m의 보살상이다. 볼륨감 없이 평평한 돌기둥 같은 신체에 전체적으로 세부를 정교하게 조각하지 않고 높은 원통형의 보관에 사각의 보개(寶蓋 ; 인도에서 귀인의 외출시에 사용하던 양산을 불상의 머리 위에 갓처럼 씌운 것)까지 얹은 표현은 고려 전기 불상의 양식적인 특징이다. 보개는 이후 변형을 이루면서 충청도와 경기 남부를 중심으로 한 불상에 많이 나타나는 고려 전기 불상의 특징이다. 방형의 넓적한 얼굴에는 가늘게 뜬 눈이 수평으로 표현되고 짧은 코에 작은 입을 표현하였다.","a":"매산리석불입상","c":"시도유형문화유산","nc":"","r":"경기도","s":"안성시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1637389.jpg"},{"q":"조선시대 초대 남원부사 김희를 추모하기 위해 세운 사당이다. 김희는 남원부사로 재임하면서 백성을 인자하게 다스리고 판결이 명백하고 공정하여 주민들의 칭송을 받았으나 불행히도 재임 중에 병으로 별세하였다. 선조 30년(1597)에 불에 타버려 영조 때 다시 지었는데, 앞면 3칸·옆면 2칸 규모로 지붕은 옆면에서 볼 때 사람 인(人)자 모양인 맞배지붕이다. 제사는 봄(4월)에는 사당에서 지내고, 가을(10월)에는 송정리 무덤에서 지낸다.","a":"유애묘","c":"문화유산자료","nc":"","r":"전북특별자치도","s":"남원시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1661675.jpg"},{"q":"원주 ○○○○○ 소장 ○○○○○은 선조 5년(1572) 충주 월악산 ○○○에서 간행한 목판본으로 표지는 개장되었으나 도판과 판의 양식이 고려판을 답습하고 있는 등 당시의 서예⋅판화사⋅미술사의 양식변천 연구에 중요한 자료적 가치를 지니고 있다.","a":"원주고판화박물관소장덕주사판불설아미타경","c":"시도유형문화유산","nc":"","r":"강원특별자치도","s":"원주시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1638311.jpg"},{"q":"평택시 안중읍 용성리의 해발 110.8m ○○○에 있다. ○○○의 해발고도는 높지 않지만, 주변에 높은 산이 없어 넓은 지역이 조망된다. 이곳은 경주에서 상주를 거쳐 남양만에 이르는 교통로 상의 요충지다. 산성은 ○○○의 능선을 따라 축조되었다. 평면 형태는 동서 방향이 약간 긴 장방형이다. 석성으로 구축되었으며 전체 둘레는 582m다. 성벽은 기초를 계단식으로 다듬고, 편암계의 석재를 장방형으로 가공하여 바른층쌓기 방식으로 정교하게 쌓아 올렸다. 내벽과 적심부도 모두 돌로 쌓았다. 외벽 기저부에는 일정한 높이까지 보축성벽을 쌓았다.","a":"평택자미산성지","c":"시도기념물","nc":"","r":"경기도","s":"평택시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1647303.jpg"},{"q":"광무 2년(1898)에 군수 권상문이 신라 제4대 임금인 탈해왕의 제사를 모시기 위해 세웠다. 1906년부터는 신라의 3성 시조 임금(박, 석, 김)을 같이 모셨고 이때부터 ‘○○○’이라고 불렀다. 처음 지을 때 월성 안에 있던 것을 1980년 월성 안의 민가 철거와 함께 지금 있는 자리로 옮겼으며 봄·가을과 춘분·추분에 걸쳐 제사를 지내고 있다. 신라 3대 왕의 성 가운데 최초의 석씨 왕인 탈해왕(57∼80)에 대해서는 아래와 같은 전설이 전한다. 왜국 동북쪽 멀리 떨어져 있는 타파나국 왕비가 잉태한지 7년만에 커다란 알 하나를 낳았다.","a":"숭신전","c":"문화유산자료","nc":"","r":"경상북도","s":"경주시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1662971.jpg"},{"q":"2층 기단(基壇) 위로 5층의 탑신(塔身)을 올린 모습의 석탑으로, 주변에 절터로 보이는 건물터와 석불의 대좌로 보이는 석물 등이 남아있다. 아래층 기단의 각 면에는 둥글넓적한 안상(眼象)을 얕게 새기고, 위층 기단에는 각 면의 모서리와 가운데에 기둥 모양을 새겼다. 탑신부는 몸돌과 지붕돌을 각각 하나의 돌로 쌓아 올렸는데, 1층 몸돌은 큰 편이며, 2층부터는 높이가 급격히 낮아졌다. 지붕돌은 밑면에 3단의 받침을 두고, 네 귀퉁이는 높이 치켜 올라갔는데, 각층이 비슷한 크기로 거의 변화가 없는 것이 특징이다.","a":"강릉관음리오층석탑","c":"시도유형문화유산","nc":"","r":"강원특별자치도","s":"강릉시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1638145.jpg"},{"q":"강학공간인 ○○○와 그 곳에 소장되어 있는 41건의 ○○○이다. ○○○는 강명재라로도 불리는데, 원래는 1628년에 밀양김씨 운계 김홍발이 노동에 정착하면서 건립의 계기가 마련되었다고 볼 수 있지만 당시 건조물의 연혁에 대해서는 문헌 자료가 자세하지 않다. 그 뒤 18세기 후반에 강학공간 등 공동체 공간으로 활용되었다. 현재의 건물은 1843년에 지어진 것으로 1936년에는 노동사를 지었고, 1982년에 새로이 고쳐 지어졌다.","a":"영암고반재및소장고문서일괄","c":"문화유산자료","nc":"","r":"전남광주통합특별시","s":"영암군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1662266.jpg"},{"q":"남악은 신라시대 지리산을 일컫는 것으로 ○○○는 삼국시대부터 국민의 평화 및 질서유지와 풍년을 기원하는 지리산 신제를 모신 곳이다. 삼국시대에는 천왕봉에서 제사를 지냈으며 고려 때에 천왕봉에서 노고단으로 옮겼다. 조선 세조 2년(1456)에는 갈뫼봉 북쪽 내산면 좌사리 당동이란 곳에서 제를 올렸다. 기록에 따르면 ‘해마다 봄과 가을, 설날에 왕명으로 제사를 올렸으며, 재난이 있을 경우에는 별도로 제를 올리기도 하였다.’고 한다.","a":"남악사","c":"문화유산자료","nc":"","r":"전남광주통합특별시","s":"구례군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1661960.jpg"},{"q":"남양 방씨의 선조 방응현(房應賢)이 조선 중기에 처음 세운 정자이다. 정자 옆에 흐르는 냇물은 모래내, 즉 ‘사계(沙溪)’라고 불리운다. 임진왜란(1592년) 때 건물이 불에 타, 이후 후손들이 여러 번 다시 지었다. 방응현은 벼슬에 뜻을 두지 않고 학문을 닦으면서 일생을 이곳에서 보냈다. 그는 이항, 노수신, 조식, 노진 등 유명인사와 가깝게 지냈으며, 정자 안에는 그들의 글이 여러 편 걸려 있다. 건물 가운데 한 칸의 방을 두고 사방에 마루를 둔 구조로서, 일반적인 호남지방 정자의 양식을 따랐다.","a":"사계정사","c":"문화유산자료","nc":"","r":"전북특별자치도","s":"남원시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1661835.jpg"},{"q":"○○○는 청동기 시대의 대표적인 무덤으로 주로 경제력이 있거나 정치권력을 가진 지배층의 무덤으로 알려져 있다. 거대한 덮개돌[上石]이 지상에 드러나 있고 그 밑에 고임돌[支石], 묘역시설(墓域施設), 무덤방 등이 있는 구조를 가지고 있다. 하지만 지역과 시기에 따라 그 형태는 매우 다양하다. 일반적으로는 무덤방이 지상에 위치한 탁자식(卓子式)과 지하에 위치한 바둑판식(碁盤式)으로 나누며, 지하의 무덤방 위에 고임돌 없이 바로 덮개돌을 덮은 개석식(蓋石式)도 있다.","a":"용인 주북리 지석묘","c":"문화유산자료","nc":"","r":"경기도","s":"용인시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1660005.jpg"},{"q":"조선 후기의 문신인 ○○○ 선생의 초상화이다. ○○○은 조선 경종 3년(1723)에 병과에 급제하고 병조판서를 거쳐 우의정까지 올랐으며 특히 글씨를 잘 썼다. 초상화는 살색의 대나무 발을 배경으로 두고 호랑이 가죽으로 만든 의자에 앉아 있는 전신상이다. 얼굴은 측면을 향하고 있으나 전체적으로 좌우가 대칭을 이룬다. 머리에는 사모를 쓰고 짙은 청색의 관복을 갖춰 입었으며, 가슴에는 문관을 상징하는 학과 구름을 수놓았다. 수용성 물감을 아교액과 혼합하여 진한 색채로 만들어 사실적으로 표현하고 있다. 현재 개인소유로 관리되고 있으며, 관람할 수 없다.","a":"정우량 영정","c":"시도유형문화유산","nc":"","r":"인천광역시","s":"미추홀구","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/2015122811344400.jpg"},{"q":"○○○○○에 소장되어 있는 유물로, 예수 성심기(106×173cm) 1점과 성모 성심기(106×177cm) 1점 등 총 2점이다. 예수 성심기와 성모 성심기는 1914년 제1회 성체거동행사와 매년 성모성심축일에 종교행사용으로 사용하고자 비단천에 동양자수를 놓아 제작하였다. 앞면에 부조(浮彫)로 수를 놓았는데, 성체 속에 예수 그리스도를 보호하고 성체에 대한 신앙심을 고양한 것으로 보존상태가 양호한 편은 아니다.","a":"음성 감곡성당 소장유물","c":"시도유형문화유산","nc":"","r":"충청북도","s":"음성군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1638791.jpg"}]);